// Manipulador delegado global para garantir que o botao de redefinicao dos fosseis sempre funcione
if(!window._fossilResetGlobalAttached){
    document.addEventListener('click', (ev)=>{
        const btn = ev.target && ev.target.closest && ev.target.closest('#fossil-reset-btn');
        if(!btn) return;
        ev.preventDefault();
        ev.stopImmediatePropagation();
        ev.stopPropagation();
        try{ fossilHardReset(); }catch(e){}
    }, true);
    window._fossilResetGlobalAttached = true;
}

function getRouteInfo(routeKey){
    return APP_ROUTE_ALIASES[String(routeKey || '').trim().toLowerCase()] || null;
}

function normalizeQuickAction(value){
    const normalized = String(value || '').trim().toLowerCase();
    return Object.prototype.hasOwnProperty.call(QUICK_ACTION_ROUTES, normalized) ? normalized : '';
}

function getQuickActionRoutePath(action){
    return QUICK_ACTION_ROUTES[normalizeQuickAction(action)]?.path || '';
}

function getRequestedQuickActionFromUrl(){
    const params = new URLSearchParams(location.search);
    const queryAction = normalizeQuickAction(params.get('quick'));
    if(queryAction) return queryAction;

    const tabAction = normalizeQuickAction(getRouteInfo(params.get('tab'))?.quickAction || '');
    if(tabAction) return tabAction;

    return normalizeQuickAction(getRouteInfoFromPathname()?.quickAction || '');
}

function getRouteInfoFromPathname(pathname = location.pathname){
    const normalizedPath = String(pathname || '')
        .toLowerCase()
        .replace(/\/index\.html?$/, '')
        .replace(/\/+$/, '');
    const segments = normalizedPath
        .split('/')
        .filter(Boolean)
        .map((segment) => segment.replace(/\.html?$/i, ''));
    if(!segments.length) return null;

    const candidates = [];
    const last = segments[segments.length - 1] || '';
    const first = segments[0] || '';
    if(last) candidates.push(last);
    if(first && first !== last) candidates.push(first);

    for(const slug of candidates){
        if(!slug || slug === 'app' || slug === 'index') continue;
        const routeInfo = getRouteInfo(slug);
        if(routeInfo) return routeInfo;
    }

    return null;
}

function isEffectivenessRouteActive(){
    if(tabEffectBtn && tabEffectBtn.classList.contains('active')) return true;
    const pathRouteInfo = getRouteInfoFromPathname();
    if(pathRouteInfo?.tab === 'effectiveness') return true;
    try{
        const params = new URLSearchParams(location.search);
        return getRouteInfo(params.get('tab'))?.tab === 'effectiveness' || params.has('types');
    }catch(error){
        return false;
    }
}

function normalizePokemonCatalogVariant(value){
    return String(value || '').trim().toLowerCase() === POKEMON_CATALOG_VARIANT_MEGA
        ? POKEMON_CATALOG_VARIANT_MEGA
        : POKEMON_CATALOG_VARIANT_DEFAULT;
}

function getPokemonCatalogVariantFromUrl(){
    return POKEMON_CATALOG_VARIANT_DEFAULT;
}

function getCurrentPokemonCatalogVariant(){
    return normalizePokemonCatalogVariant(document.body?.dataset?.pokemonVariant || '');
}

function getPokemonRoutePathForVariant(){
    return '/pokemons';
}

function setCurrentPokemonCatalogVariant(variant = POKEMON_CATALOG_VARIANT_DEFAULT){
    const normalizedVariant = normalizePokemonCatalogVariant(variant);
    if(document.body){
        if(normalizedVariant === POKEMON_CATALOG_VARIANT_MEGA){
            document.body.dataset.pokemonVariant = POKEMON_CATALOG_VARIANT_MEGA;
        } else {
            delete document.body.dataset.pokemonVariant;
        }
    }
    return normalizedVariant;
}

function getPokemonCatalogSubjectLabel(variant = getCurrentPokemonCatalogVariant()){
    return normalizePokemonCatalogVariant(variant) === POKEMON_CATALOG_VARIANT_MEGA
        ? 'pokemons Mega'
        : 'pokemons';
}

function isPokemonCatalogPathname(pathname = location.pathname){
    return /\/pokemon(?:s)?(?:\/|$)/i.test(String(pathname || ''));
}

function normalizePokemonDetailRouteToken(value){
    try{
        return decodeURIComponent(String(value || ''))
            .trim()
            .toLowerCase();
    }catch(error){
        return String(value || '')
            .trim()
            .toLowerCase();
    }
}

function getPokemonDetailRouteMatch(pathname = location.pathname){
    // Manter caminhos numericos curtos reservados para paginacao do catalogo, ex: /pokemon/2.
    const match = String(pathname || '').match(/\/pokemon(?:s)?\/((?:\d{3,}(?:-[a-z0-9]+)?)|(?:[a-z][a-z0-9]*(?:-[a-z0-9]+)*))\/?$/i);
    if(!match) return null;
    const routeToken = normalizePokemonDetailRouteToken(match[1]);
    if(!routeToken) return null;
    return {
        routeToken,
        dex: /^\d{3,}(?:-[a-z0-9]+)?$/.test(routeToken)
            ? Number.parseInt(routeToken, 10)
            : null
    };
}

function getPokemonCatalogPageRouteMatch(pathname = location.pathname){
    const normalizedPathname = String(pathname || '');
    if(getPokemonDetailRouteMatch(normalizedPathname)) return null;
    return normalizedPathname.match(/\/pokemon(?:s)?\/([1-9]\d*)\/?$/i);
}

function normalizePokemonCatalogPageNumber(value, fallback = 1){
    const parsed = Number.parseInt(value, 10);
    return parsed >= 1 ? parsed : fallback;
}

function getRequestedPokemonCatalogPageFromPath(pathname = location.pathname){
    const match = getPokemonCatalogPageRouteMatch(pathname);
    if(!match) return null;
    return normalizePokemonCatalogPageNumber(match[1], 1);
}

function normalizeCatchRouteToken(value){
    try{
        return decodeURIComponent(String(value || ''))
            .trim()
            .toLowerCase();
    }catch(error){
        return String(value || '')
            .trim()
            .toLowerCase();
    }
}

function getCatchRouteMatch(pathname = location.pathname){
    const match = String(pathname || '').match(/\/catch\/([a-z0-9][a-z0-9-]*)\/?$/i);
    if(!match) return null;
    const routeToken = normalizeCatchRouteToken(match[1]);
    return routeToken ? { routeToken } : null;
}

function normalizeManiacsLocationRouteSlug(value){
    try{
        return decodeURIComponent(String(value || ''))
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9-]+/g, '-')
            .replace(/-+/g, '-')
            .replace(/^-+|-+$/g, '');
    }catch(error){
        return String(value || '')
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9-]+/g, '-')
            .replace(/-+/g, '-')
            .replace(/^-+|-+$/g, '');
    }
}

function getManiacsMapRouteMatch(pathname = location.pathname){
    const match = String(pathname || '').match(/\/maniacs\/([a-z0-9][a-z0-9-]*)\/mapa\/?$/i);
    if(!match) return null;
    const locationSlug = normalizeManiacsLocationRouteSlug(match[1]);
    return locationSlug ? { locationSlug, mapView: true } : null;
}

function slugifyCatchRouteToken(value){
    return normalizePokemonSearchText(value)
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
}

function getPokemonCatalogRoutePath(page = pokemonCatalogCurrentPage, variant = getCurrentPokemonCatalogVariant()){
    const basePath = getPokemonRoutePathForVariant(variant);
    const normalizedPage = normalizePokemonCatalogPageNumber(page, 1);
    return normalizedPage > 1 ? `${basePath}/${normalizedPage}` : basePath;
}

function getPokemonDetailRouteToken(entry){
    if(!entry) return '';
    return String(entry.routeToken || entry.routeSlug || entry.id || '')
        .trim()
        .toLowerCase();
}

function getPokemonDetailRoutePath(entry, variant = getCurrentPokemonCatalogVariant()){
    const routeToken = getPokemonDetailRouteToken(entry);
    if(!routeToken) return '';
    return `${getPokemonRoutePathForVariant(variant)}/${encodeURIComponent(routeToken)}`;
}

function getPokemonCatalogEntriesForVariant(variant = getCurrentPokemonCatalogVariant()){
    const normalizedVariant = normalizePokemonCatalogVariant(variant);
    return Array.isArray(pokemonCatalogEntriesByVariant[normalizedVariant])
        ? pokemonCatalogEntriesByVariant[normalizedVariant]
        : [];
}

function getPokemonCatalogEntryByName(name){
    const normalizedName = normalizePokemonSearchText(name);
    if(!normalizedName) return null;

    const entries = [
        ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT),
        ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
    ];
    const exactMatch = entries.find(entry => entry?.searchName === normalizedName);
    if(exactMatch) return exactMatch;

    if(normalizedName.startsWith('shiny ')){
        const baseName = normalizePokemonSearchText(normalizedName.replace(/^shiny\s+/, ''));
        return entries.find(entry => entry?.searchName === baseName) || null;
    }

    return null;
}

function getPokemonCatalogEntryLevelByName(name){
    const entry = getPokemonCatalogEntryByName(name);
    return entry ? entry.level : null;
}

window.getPokemonCatalogEntryLevelByName = getPokemonCatalogEntryLevelByName;

function findPokemonCatalogEntryByRouteToken(routeToken, variant = getCurrentPokemonCatalogVariant()){
    const normalizedToken = normalizePokemonDetailRouteToken(routeToken);
    if(!normalizedToken) return null;

    const normalizedVariant = normalizePokemonCatalogVariant(variant);
    const entries = normalizedVariant === POKEMON_CATALOG_VARIANT_DEFAULT
        ? [
            ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT),
            ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
        ]
        : getPokemonCatalogEntriesForVariant(normalizedVariant);

    return entries.find((entry) => {
        if(!entry) return false;
        return String(entry.routeToken || '').trim().toLowerCase() === normalizedToken;
    }) || null;
}

function getBossRouteMatch(pathname = location.pathname){
    const segments = String(pathname || '')
        .replace(/\/index\.html?$/i, '')
        .replace(/\/+$/, '')
        .split('/')
        .filter(Boolean);
    if(!segments.length) return null;

    const bossMode = normalizeBossModeParam(segments[0]);
    if(!bossMode || !['hoopa', 'champion', 'mew2', 'special', 'mainquest', 'horizons'].includes(bossMode)) return null;
    const detailSuffix = String(segments[2] || '').trim().toLowerCase();
    if((detailSuffix && !['mapa', 'video', 'pokemon'].includes(detailSuffix)) || segments.length > 3) return null;

    return {
        bossMode,
        bossSlug: segments[1] ? decodeURIComponent(segments[1]) : '',
        mapView: detailSuffix === 'mapa',
        videoView: detailSuffix === 'video',
        searchView: detailSuffix === 'pokemon'
    };
}

function getRequestedBossSlugFromPath(pathname = location.pathname){
    return String(getBossRouteMatch(pathname)?.bossSlug || '').trim().toLowerCase();
}

function getRoutePathForTab(activeTab = '', bossMode = ''){
    const normalizedTab = String(activeTab || '').trim().toLowerCase();
    if(normalizedTab === 'pokemons'){
        return getPokemonRoutePathForVariant();
    }
    if(normalizedTab === 'bosses'){
        const normalizedBossMode = normalizeBossModeParam(bossMode) || 'hoopa';
        const bossRoute = getRouteInfo(normalizedBossMode);
        return bossRoute?.path || '/hoopa';
    }
    const routeInfo = getRouteInfo(normalizedTab);
    return routeInfo?.path || '/pokemons';
}

function getHomePageUrl(){
    return new URL(getRoutePathForTab('home').replace(/^\//, ''), document.baseURI).toString();
}

function navigateToHomePage(){
    window.location.assign(getHomePageUrl());
}

function loadDeferredScript(src, globalCheck){
    try{
        if(typeof globalCheck === 'function' && globalCheck()) return Promise.resolve();
    }catch(e){}

    const resolvedSrc = new URL(src, document.baseURI).href;
    const existing = Array.from(document.scripts).find(script => script.src === resolvedSrc);
    if(existing){
        if(existing.dataset.loaded === 'true') return Promise.resolve();
        return new Promise((resolve, reject) => {
            let settled = false;
            let pollTimer = 0;
            let timeoutTimer = 0;
            const cleanup = () => {
                if(pollTimer) window.clearInterval(pollTimer);
                if(timeoutTimer) window.clearTimeout(timeoutTimer);
            };
            const resolveLoaded = () => {
                if(settled) return;
                settled = true;
                cleanup();
                existing.dataset.loaded = 'true';
                resolve();
            };
            const rejectLoad = () => {
                if(settled) return;
                settled = true;
                cleanup();
                reject(new Error(`Falha ao carregar ${src}`));
            };
            const checkGlobal = () => {
                try{
                    if(typeof globalCheck === 'function' && globalCheck()) resolveLoaded();
                }catch(error){}
            };
            existing.addEventListener('load', resolveLoaded, { once: true });
            existing.addEventListener('error', rejectLoad, { once: true });
            pollTimer = window.setInterval(checkGlobal, 100);
            timeoutTimer = window.setTimeout(rejectLoad, 15000);
            checkGlobal();
        });
    }

    return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = src;
        script.async = false;
        script.addEventListener('load', () => {
            script.dataset.loaded = 'true';
            resolve();
        }, { once: true });
        script.addEventListener('error', () => reject(new Error(`Falha ao carregar ${src}`)), { once: true });
        document.body.appendChild(script);
    });
}

function createInlineStatusMessage(className, message){
    const status = document.createElement('div');
    status.className = className;
    status.textContent = message;
    status.style.padding = '1rem';
    status.style.color = '#eee';
    status.style.background = 'rgba(255,255,255,0.06)';
    status.style.border = '1px solid rgba(255,255,255,0.08)';
    status.style.borderRadius = '0.75rem';
    return status;
}

function showTypesLoadingState(){
    if(!chart || menuTypes.length) return;
    chart.replaceChildren(createInlineStatusMessage('load-pending-message', 'Carregando tabela de tipos...'));
    renderTypeInfoEmptyState('Os dados da tabela estão sendo carregados para a consulta.');
}

function renderBossesDeferredState(message, options = {}){
    const { error = false } = options;
    const speedsterGrid = document.getElementById('speedster-grid');
    if(!speedsterGrid) return;
    const card = createInlineStatusMessage(error ? 'bosses-load-error-message' : 'bosses-load-pending-message', message);
    if(error){
        card.style.background = 'rgba(255,0,0,0.08)';
        card.style.borderColor = 'rgba(255,0,0,0.18)';
    }
    speedsterGrid.replaceChildren(card);
}

