function setSidebarGroupExpanded(groupEl, expanded){
    if(!(groupEl instanceof HTMLElement)) return;

    const toggle = groupEl.querySelector('[data-sidebar-group-toggle]');
    const submenuId = toggle?.getAttribute('aria-controls');
    const submenu = submenuId ? document.getElementById(submenuId) : groupEl.querySelector('.sidebar-submenu');
    const nextExpanded = Boolean(expanded);

    groupEl.dataset.expanded = nextExpanded ? 'true' : 'false';
    if(toggle){
        toggle.setAttribute('aria-expanded', nextExpanded ? 'true' : 'false');
    }
    if(submenu){
        submenu.hidden = !nextExpanded;
    }
}

function setSidebarOpen(nextOpen){
    const shouldOpen = Boolean(nextOpen) && isMobileSidebarMode();
    document.body.classList.toggle('sidebar-open', shouldOpen);

    if(mobileNavToggle){
        mobileNavToggle.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
    }
    if(appSidebar){
        appSidebar.setAttribute('aria-hidden', isMobileSidebarMode() ? (shouldOpen ? 'false' : 'true') : 'false');
    }
    if(appShellBackdrop){
        appShellBackdrop.hidden = !shouldOpen;
        appShellBackdrop.setAttribute('aria-hidden', shouldOpen ? 'false' : 'true');
    }
}

function getActiveSiteTarget(){
    if(document.body.classList.contains('home-view')) return 'home';
    if(contentBoost && !contentBoost.hidden) return 'boost';
    if(contentPokemons && !contentPokemons.hidden) return 'pokemons';
    if(contentTimes && !contentTimes.hidden) return 'times';
    if(contentTeamBuilder && !contentTeamBuilder.hidden) return 'team-builder';
    if(contentHuntBuilder && !contentHuntBuilder.hidden) return 'hunt-builder';
    if(contentRotomPhone && !contentRotomPhone.hidden) return 'rotom-phone';
    if(contentInteractiveMap && !contentInteractiveMap.hidden) return 'mapa-interativo';
    if(contentPoliceOperation && !contentPoliceOperation.hidden) return 'police-operation';
    if(contentSlowpokeWell && !contentSlowpokeWell.hidden) return 'slowpoke-well';
    if(contentLigaPokemon && !contentLigaPokemon.hidden) return 'liga-pokemon';
    if(contentHeldFusion && !contentHeldFusion.hidden) return 'fusao-de-held';
    if(contentProfessions && !contentProfessions.hidden) return 'profissoes';
    if(contentManiacs && !contentManiacs.hidden) return 'maniacs';
    if(contentBossesInfo && !contentBossesInfo.hidden) return 'bosses-info';
    if(tabEffectBtn?.classList.contains('active')) return 'effectiveness';
    if(tabFossilsBtn?.classList.contains('active')) return 'fossils';
    if(tabCalcBtn?.classList.contains('active')) return 'calculator';
    if(tabCatchBtn?.classList.contains('active')) return 'catch';
    if(tabSpeedstersBtn?.classList.contains('active')) return 'bosses';
    if(tabStreamersBtn?.classList.contains('active')) return 'streamers';
    if(tabCommunityBtn?.classList.contains('active')) return 'youtube';
    return '';
}

function normalizeBossModeParam(value){
    const normalized = String(value || '').trim().toLowerCase();
    if(!normalized) return '';
    if(normalized === 'hoopa-portais') return 'hoopa';
    if(normalized === 'champion-path') return 'champion';
    if(normalized === 'champions') return 'champion';
    if(normalized === 'mewtwo') return 'mew2';
    if(normalized === 'bosses-especiais' || normalized === 'especiais' || normalized === 'ranger-bosses' || normalized === 'ranger') return 'special';
    if(normalized === 'mainquest' || normalized === 'main-quest' || normalized === 'main-quest-bosses') return 'mainquest';
    if(normalized === 'planejador') return 'planner';
    return ['hoopa', 'champion', 'mew2', 'special', 'mainquest', 'planner', 'horizons'].includes(normalized) ? normalized : '';
}

function isTeamCatalogPathname(pathname = location.pathname){
    return /\/times(?:\/|$)/i.test(String(pathname || ''));
}

function normalizeTeamRouteSlug(value){
    try{
        return decodeURIComponent(String(value || ''));
    }catch(error){
        return String(value || '');
    }
}

function createTeamRouteSlug(value, fallback = ''){
    const slug = normalizeTeamRouteSlug(value || fallback)
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
    return slug || 'time';
}

function getTeamRouteMatch(pathname = location.pathname){
    const match = String(pathname || '').match(/\/times\/([a-z0-9]+(?:-[a-z0-9]+)*)\/?$/i);
    if(!match) return null;
    const teamSlug = createTeamRouteSlug(match[1]);
    return teamSlug ? { teamSlug } : null;
}

function getTeamDetailRoutePath(entry){
    const routeSlug = String(entry?.routeSlug || '').trim().toLowerCase();
    return routeSlug ? `/times/${encodeURIComponent(routeSlug)}` : '';
}

function getBossModeQueryValue(value){
    const normalized = normalizeBossModeParam(value);
    if(normalized === 'mew2') return 'mewtwo';
    if(normalized === 'special') return 'ranger-bosses';
    if(normalized === 'mainquest') return 'main-quest';
    if(normalized === 'planner') return 'planejador';
    return normalized;
}

function getRequestedBossModeFromUrl(){
    const params = new URLSearchParams(location.search);
    const pathRouteInfo = getRouteInfoFromPathname();
    const bossRouteMatch = getBossRouteMatch();
    return normalizeBossModeParam(params.get('tab'))
        || normalizeBossModeParam(params.get('bossmode') || params.get('boss') || params.get('mode'))
        || normalizeBossModeParam(bossRouteMatch?.bossMode || '')
        || normalizeBossModeParam(pathRouteInfo?.bossMode || '');
}

function getCurrentBossMode(){
    return normalizeBossModeParam(document.body?.dataset?.bossMode) || 'hoopa';
}

function syncSidebarNavigationState(){
    if(!appSidebar) return;

    const activeTarget = getActiveSiteTarget();
    const activeBossMode = String(document.body?.dataset?.bossMode || 'hoopa').toLowerCase();

    sidebarActionButtons.forEach((button) => {
        if(!(button instanceof HTMLElement)) return;

        const target = String(button.dataset.navTarget || '').toLowerCase();
        const action = String(button.dataset.navAction || '').toLowerCase();
        const requestedBossMode = String(button.dataset.bossMode || '').toLowerCase();

        let isActive = false;
        if(action){
            isActive = false;
        } else if(target === 'home'){
            isActive = activeTarget === 'home';
        } else if(target === 'bosses'){
            isActive = activeTarget === 'bosses' && (!requestedBossMode || requestedBossMode === activeBossMode);
        } else {
            isActive = activeTarget === target;
        }

        button.classList.toggle('is-active', isActive);
        if(isActive){
            button.setAttribute('aria-current', 'page');
        } else {
            button.removeAttribute('aria-current');
        }
    });

    document.querySelectorAll('.sidebar-group').forEach((group) => {
        const hasActiveItem = Boolean(group.querySelector('.sidebar-sublink.is-active'));
        group.classList.toggle('is-active', hasActiveItem);
        if(hasActiveItem){
            setSidebarGroupExpanded(group, true);
        }
    });
}

function openFullMapVideo(){
    const routeRestoreState = consumePendingQuickActionRouteRestore();
    const modalOptions = {
        url: FULL_MAP_VIDEO_URL,
        title: 'Mapa Completo',
        note: 'Clique em "YouTube" para abrir o video e checar os comentarios.'
    };
    if(routeRestoreState){
        modalOptions.onAfterClose = () => restoreQuickActionRouteUrl(routeRestoreState);
    }
    const opened = typeof openSiteYouTubeModal === 'function'
        ? openSiteYouTubeModal(modalOptions)
        : false;
    if(!opened){
        restoreQuickActionRouteUrl(routeRestoreState);
        openExternalWindow(FULL_MAP_VIDEO_URL);
    }
}

function activateSidebarTarget(button){
    if(!(button instanceof HTMLElement)) return;

    const action = String(button.dataset.navAction || '').toLowerCase();
    const actionButtons = {
        commands: commandsBtn,
        'elemental-balls': elementalBallsBtn,
        'full-map': { click: openFullMapVideo },
        fishing: fishingBtn
    };
    if(action && actionButtons[action]){
        const routeRestoreState = beginQuickActionRoute(action, button.dataset.navUrl);
        actionButtons[action]?.click();
        if(routeRestoreState && pendingQuickActionRouteRestore === routeRestoreState){
            pendingQuickActionRouteRestore = null;
            restoreQuickActionRouteUrl(routeRestoreState);
        }
        setSidebarOpen(false);
        return;
    }

    const target = String(button.dataset.navTarget || '').toLowerCase();
    const requestedBossMode = normalizeBossModeParam(button.dataset.bossMode || '');
    const openers = {
        home: showPokemons,
        effectiveness: showEffectiveness,
        fossils: showFossils,
        maniacs: showManiacs,
        'bosses-info': showBossesInfo,
        calculator: showCalculator,
        boost: showBoostCalculator,
        pokemons: showPokemons,
        times: showTimes,
        'team-builder': showTeamBuilder,
        'hunt-builder': showHuntBuilder,
        'rotom-phone': showRotomPhone,
        'police-operation': showPoliceOperation,
        'slowpoke-well': showSlowpokeWell,
        'liga-pokemon': showLigaPokemon,
        'fusao-de-held': showHeldFusion,
        profissoes: showProfessions,
        catch: showCatch,
        'mapa-interativo': showInteractiveMap,
        bosses: () => showSpeedsters(requestedBossMode || 'hoopa'),
        streamers: showStreamers,
        youtube: showCommunity
    };

    const openTarget = openers[target] || showEffectiveness;
    openTarget();

    if(target === 'bosses' && requestedBossMode && typeof window.setBossMode === 'function'){
        window.setBossMode(requestedBossMode);
    }

    // Garantir que a URL reflita o destino aberto quando a navegacao acontece pela sidebar
    try{
        if(typeof updateUrl === 'function') updateUrl();
    }catch(e){}

    syncSidebarNavigationState();
    setSidebarOpen(false);
}

function bindSidebarActionButtons(root = document){
    const buttons = root && typeof root.querySelectorAll === 'function'
        ? root.querySelectorAll('[data-nav-target], [data-nav-action]')
        : [];
    buttons.forEach((button) => {
        if(boundSidebarActionButtons.has(button)) return;
        boundSidebarActionButtons.add(button);
        button.addEventListener('click', () => {
            activateSidebarTarget(button);
        });
    });
}

function initializeSidebarNavigation(){
    if(sidebarNavigationInitialized) return;
    sidebarNavigationInitialized = true;

    const sidebarNav = document.querySelector('.sidebar-nav');
    ['bosses', 'systems', 'utilities', 'quests', 'community'].forEach((groupKey) => {
        const group = sidebarNav?.querySelector(`[data-sidebar-group="${groupKey}"]`);
        if(group) sidebarNav.appendChild(group);
    });

    sidebarGroupToggles.forEach((toggle) => {
        const group = toggle.closest('.sidebar-group');
        setSidebarGroupExpanded(group, group?.dataset?.expanded !== 'false');

        toggle.addEventListener('click', () => {
            if(!group) return;
            const isExpanded = toggle.getAttribute('aria-expanded') === 'true';
            setSidebarGroupExpanded(group, !isExpanded);
        });
    });

    bindSidebarActionButtons(document);

    if(mobileNavToggle){
        mobileNavToggle.addEventListener('click', () => {
            const isOpen = document.body.classList.contains('sidebar-open');
            setSidebarOpen(!isOpen);
        });
    }

    if(appShellBackdrop){
        appShellBackdrop.addEventListener('click', () => {
            setSidebarOpen(false);
        });
    }

    if(mobileSidebarQuery){
        const handleSidebarMediaChange = () => {
            setSidebarOpen(false);
            syncSidebarNavigationState();
        };

        if(typeof mobileSidebarQuery.addEventListener === 'function'){
            mobileSidebarQuery.addEventListener('change', handleSidebarMediaChange);
        } else if(typeof mobileSidebarQuery.addListener === 'function'){
            mobileSidebarQuery.addListener(handleSidebarMediaChange);
        }
    }

    window.addEventListener('bossmodechange', () => {
        syncSidebarNavigationState();
        if(!getRequestedBossSlugFromPath()){
            updateUrl();
        }
    });

    document.addEventListener('keydown', (event) => {
        if(event.key === 'Escape' && document.body.classList.contains('sidebar-open')){
            setSidebarOpen(false);
        }
    });

    setSidebarOpen(false);
    syncSidebarNavigationState();
}

