function fuzzyMatch(type,filter){
    if(!filter) return true;
    filter = filter.toLowerCase();
    let idx = 0;
    for(let ch of type){
        if(ch===filter[idx]) idx++;
        if(idx===filter.length) return true;
    }
    return false;
}

function createButtons(filter=""){ 
    chart.innerHTML='';
    const normalizedFilter = filter.toLowerCase();
    menuTypes.forEach(type=>{
        if(!fuzzyMatch(type,filter)) return;
        const btn=document.createElement('div');
        btn.className=`type-button ${type}`;
        btn.dataset.type=type;
        btn.tabIndex=0;
        btn.setAttribute('role','button');
        btn.setAttribute('aria-pressed','false');
        const img=document.createElement('img');
        img.src=`icons-type/${type}.png`;
        img.alt=type;
        img.className='type-icon';
        btn.appendChild(img);
        const hidden=document.createElement('span');
        hidden.className='visually-hidden';
        hidden.textContent=type.charAt(0).toUpperCase()+type.slice(1);
        btn.appendChild(hidden);
        const label=document.createElement('span');
        label.className='type-label';

        let display = type.charAt(0).toUpperCase()+type.slice(1);
        if(normalizedFilter){
            let result = '';
            let idx = 0;
            for(let ch of display){
                if(ch.toLowerCase() === normalizedFilter[idx]){
                    result += `<mark>${ch}</mark>`;
                    idx++;
                    if(idx === normalizedFilter.length) idx = normalizedFilter.length;
                } else {
                    result += ch;
                }
            }
            display = result;
        }
        label.innerHTML = display;
        btn.appendChild(label);
        btn.addEventListener('click',()=>selectType(type));
        btn.addEventListener('keydown',handleKeyNav);
        if(useGsap){
            btn.addEventListener('mouseenter',()=>gsap.to(btn,{scale:1.1,duration:0.2,ease:'power1.out'}));
            btn.addEventListener('mouseleave',()=>gsap.to(btn,{scale:1,duration:0.2,ease:'power1.out'}));
        }
        chart.appendChild(btn);
    });
    updateColumns();
}

function combineLists(arrs){return [...new Set(arrs.flat())];}
function tally(arrs){
    const m={};
    arrs.flat().forEach(t=>{m[t]=(m[t]||0)+1;});
    return m;
}
const TYPE_EFFECTIVE_MULTIPLIER = 1.5;
const TYPE_SUPER_EFFECTIVE_MULTIPLIER = 2;
const TYPE_RESIST_MULTIPLIER = 0.75;
const TYPE_STRONG_RESIST_MULTIPLIER = 0.5;
const TYPE_SUPER_EFFECTIVE_OVERRIDES = Object.freeze({
    ice: ['dragon'],
    fairy: ['dragon']
});

function getTypeDisplayName(type){
    if(!type) return '';
    return type.charAt(0).toUpperCase() + type.slice(1);
}

// Mapa de cores dos tipos (usado para tingir elementos da UI)
const TYPE_UI_COLORS = Object.freeze({
    normal: '#A8A77A', fire: '#EE8130', water: '#6390F0', electric: '#F7D02C',
    grass: '#7AC74C', ice: '#96D9D6', fighting: '#C22E28', poison: '#A33EA1',
    ground: '#E2BF65', flying: '#A98FF3', psychic: '#F95587', bug: '#A6B91A',
    rock: '#B6A136', ghost: '#735797', dragon: '#6F35FC', dark: '#705746',
    steel: '#B7B7CE', fairy: '#D685AD'
});

function hexToRgb(hex){
    if(!hex) return '255,255,255';
    const h = String(hex).replace('#','');
    const bigint = h.length === 3
        ? parseInt(h.split('').map(c=>c+c).join(''),16)
        : parseInt(h,16);
    const r = (bigint >> 16) & 255;
    const g = (bigint >> 8) & 255;
    const b = bigint & 255;
    return `${r},${g},${b}`;
}

function getTypeColor(type){
    if(!type) return '#ffffff';
    return TYPE_UI_COLORS[String(type).toLowerCase()] || '#ffffff';
}

function setTypeToneVariables(node, type){
    if(!(node instanceof HTMLElement)) return;
    const normalizedType = normalizePokemonTypeKey(type);
    if(!normalizedType){
        node.style.removeProperty('--type-color');
        node.style.removeProperty('--type-color-rgb');
        return;
    }
    const color = getTypeColor(normalizedType);
    node.style.setProperty('--type-color', color);
    node.style.setProperty('--type-color-rgb', hexToRgb(color));
}

function formatTypeMultiplierValue(multiplier){
    if(!Number.isFinite(multiplier)) return '-';
    if(Number.isInteger(multiplier)) return `${multiplier}x`;
    return `${String(Number(multiplier.toFixed(2))).replace(/\.0+$/,'').replace(/(\.\d*[1-9])0+$/,'$1')}x`;
}

function computeTypeRawMultiplier(attackingType, defendingTypes = []){
    let multiplier = 1;
    for(const defendingType of defendingTypes){
        if(!defendingType) continue;
        if(immunities[defendingType] && immunities[defendingType].includes(attackingType)){
            return 0;
        }
        if(effectiveness[attackingType] && effectiveness[attackingType].includes(defendingType)){
            multiplier *= 2;
        } else if(resistances[defendingType] && resistances[defendingType].includes(attackingType)){
            multiplier *= 0.5;
        }
    }
    return multiplier;
}

function hasTypeSuperEffectiveOverride(attackingType, defendingTypes = []){
    const overrides = TYPE_SUPER_EFFECTIVE_OVERRIDES[String(attackingType || '').toLowerCase()];
    if(!Array.isArray(overrides) || !overrides.length) return false;
    return defendingTypes.some(type => overrides.includes(String(type || '').toLowerCase()));
}

function normalizeTypeMatchupMultiplier(raw, attackingType = '', defendingTypes = []){
    if(typeof raw !== 'number' || Number.isNaN(raw)) return 1;
    if(raw === 0) return 0;
    if(raw >= 4) return TYPE_SUPER_EFFECTIVE_MULTIPLIER;
    if(raw >= 2 && hasTypeSuperEffectiveOverride(attackingType, defendingTypes)) return TYPE_SUPER_EFFECTIVE_MULTIPLIER;
    if(raw >= 2) return TYPE_EFFECTIVE_MULTIPLIER;
    if(raw >= 1) return 1;
    if(raw <= 0.25) return TYPE_STRONG_RESIST_MULTIPLIER;
    if(raw === 0.5) return TYPE_RESIST_MULTIPLIER;
    return raw;
}

function renderTypeInfoEmptyState(message){
    const info = document.getElementById('info');
    if(!info) return;
    info.innerHTML = `
        <div class="types-empty-state">
            <div class="types-empty-state__copy">
                <span class="types-empty-state__eyebrow">${message ? 'Carregando' : 'Sem seleção'}</span>
                <h3>${message ? 'Preparando a tabela de tipos' : 'Escolha um ou dois tipos'}</h3>
                <p>${message || 'O painel vai separar ataque e defesa com destaque para efetivo, super efetivo, resistência e imunidade.'}</p>
            </div>
            <div class="types-empty-state__grid">
                <article class="types-empty-card">
                    <strong>Ataque</strong>
                    <span>Veja onde sua combinação bate com 1.5x ou 2x.</span>
                </article>
                <article class="types-empty-card">
                    <strong>Defesa</strong>
                    <span>Confira vulnerabilidades, resistências e imunidades sem poluição visual.</span>
                </article>
            </div>
        </div>
    `;
}
// Dados da calculadora de captura
const catchBallOrder = ['ultra', 'story', 'elemental', 'safari'];
const catchBallRequirementAliases = Object.freeze(
    Object.values(ELEMENTAL_BALL_TYPE_MAP).reduce((acc, ball) => {
        if(ball?.key){
            acc[ball.key] = 'elemental';
        }
        return acc;
    }, { safari: 'ultra' })
);
const catchBallPreviewImages = {
    ultra: 'ultra',
    story: 'story',
    elemental: 'elemental',
    safari: 'saffari'
};
const ballPrices = Object.freeze({ ultra:130, story:250, elemental:330, safari:130 });
const CATCH_ELEMENTAL_BALL_OPTIONS = Object.freeze(
    Object.entries(ELEMENTAL_BALL_TYPE_MAP).reduce((acc, [rawType, ball]) => {
        const type = normalizePokemonTypeKey(rawType);
        if(!ball?.key || !ball?.label || !type || acc.some(entry => entry.key === ball.key)) return acc;
        acc.push({ key: ball.key, label: ball.label, type });
        return acc;
    }, [])
);
const CATCH_TARGET_TYPE_OPTIONS = Object.freeze(
    CATCH_ELEMENTAL_BALL_OPTIONS.map(({ type }) => ({
        value: type,
        label: formatPokemonTypeLabel(type)
    }))
);
const CATCH_NORMAL_PRICE_VALUES = Object.freeze([
    5, 60, 80, 125, 200, 250, 300, 500,
    1000, 2000, 3000, 3800, 4000, 6000, 6500, 7000, 8000, 9000,
    10000, 13000, 15000, 15800, 22000, 25000, 26000, 28000,
    39000, 40000, 45000, 85500, 97500, 115500
]);
let catchNormalPriceOptions = [];
let catchPriceActiveGroupKey = '';
// Contagens por nivel diferem entre normal e shiny
// Para niveis com multiplas opcoes, guardamos um array de requisitos alternativos
const captureData = {
    normal: {
        5:  [{ultra:1}],
        20: [{ultra:8}],
        30: [{ultra:31}],
        50: [{ultra:54}],
        65: [{ultra:46}],
        80: [{ultra:169}],
        95: [{ultra:192}],
        pre:[{ultra:750},{story:390},{elemental:300},{safari:750}],
        ace:[{ultra:889}]
    },
    shiny: {
        5:  [{ultra:100},{story:50},{elemental:38}],
        20: [{ultra:200},{story:100},{elemental:77}],
        30: [{ultra:800},{story:400},{elemental:308}],
        50: [{ultra:1000},{story:500},{elemental:385}],
        65: [{ultra:1600},{story:800},{elemental:615}],
        80: [{ultra:1600},{story:800},{elemental:615}],
        95: [{ultra:3200},{story:1600},{elemental:1231}],
        pre:[{ultra:3200},{story:1600},{elemental:1231}],
        ace:[{ultra:10400},{story:5200},{elemental:4000}]
    }
};
function computeRequired(lvl, variant){
    variant = variant || 'normal';
    const data = captureData[variant] || captureData['normal'];
    // Retornar array de opcoes; padrao para requisito zero
    return data[lvl] || [{ultra:0,story:0,elemental:0}];
}
function parseLog(text){
    let totalCost = 0;
    const counts = createEmptyCatchBallCounts();
    const specificElementalCounts = createEmptyCatchSpecificElementalCounts();
    const moneyMatch = text.match(/spent\s+([\d.,]+)\s+dollars/i);
    if(moneyMatch) totalCost = parseFloat(moneyMatch[1].replace(',','.'));
    // Permitir multiplas entradas para o mesmo tipo de ball e somar
    catchBallOrder.forEach(b=>{
        const re = new RegExp('(\\d+)\\s+'+b+'\\s+balls?', 'gi');
        let m;
        while((m=re.exec(text)) !== null){
            counts[b] += parseInt(m[1],10);
        }
    });
    // Alguns logs listam balls elementais especificas por nome. Mante-las separadas para
    // decidir depois se continuam como elemental ou caem para story para o alvo.
    CATCH_ELEMENTAL_BALL_OPTIONS.forEach(({ key, label })=>{
        const ballName = String(label || '').replace(/\s*Ball$/i, '').trim();
        if(!ballName) return;
        const re = new RegExp('(\\d+)\\s+'+ballName+'\\s+balls?', 'gi');
        let m;
        while((m=re.exec(text)) !== null){
            specificElementalCounts[key] += parseInt(m[1],10);
        }
    });
    return {totalCost, counts, specificElementalCounts};
}

function createEmptyCatchBallCounts(){
    return { ultra: 0, story: 0, elemental: 0, safari: 0 };
}

function createEmptyCatchSpecificElementalCounts(){
    return CATCH_ELEMENTAL_BALL_OPTIONS.reduce((acc, ball) => {
        acc[ball.key] = 0;
        return acc;
    }, {});
}

function cloneCatchBallCounts(source = {}){
    const counts = createEmptyCatchBallCounts();
    catchBallOrder.forEach((ball) => {
        counts[ball] = Number(source?.[ball] || 0);
    });
    return counts;
}

function cloneCatchSpecificElementalCounts(source = {}){
    const counts = createEmptyCatchSpecificElementalCounts();
    Object.keys(counts).forEach((ballKey) => {
        counts[ballKey] = Number(source?.[ballKey] || 0);
    });
    return counts;
}

function getBallTranslationKey(ball){
    const keyMap = {
        ultra: 'ballUltra',
        story: 'ballStory',
        elemental: 'ballElemental',
        safari: 'ballSafari'
    };
    return keyMap[ball] || 'ballUltra';
}

function getBallLabel(ball){
    return t(getBallTranslationKey(ball)) || ball;
}

function getCatchRequirementBallKey(ball){
    return catchBallRequirementAliases[ball] || ball;
}

function getCatchRequiredAmount(option, chosen, variant){
    if(!option || !chosen) return 0;
    const requirementBall = getCatchRequirementBallKey(chosen);
    if(option[requirementBall] && option[requirementBall] > 0) return option[requirementBall];
    if(variant === 'normal' && option.ultra) return option.ultra;
    return 0;
}

function getBallPreviewImageSrc(ball){
    const imageName = catchBallPreviewImages[ball] || ball || 'pokebola';
    return `balls/${imageName}.png`;
}

function getCatchVariantLabel(variant){
    return variant === 'shiny' ? t('shiny') : t('normal');
}

function getCatchLevelLabel(lvl){
    if(lvl === 'pre') return t('preLabel');
    if(lvl === 'ace') return t('aceLabel');
    return `${t('lvlPrefix')}${lvl}`;
}

function formatCurrencyValue(value){
    return `$${(Number(value) || 0).toFixed(2)}`;
}

function formatPokemonPriceLabel(value){
    return `$${Math.round(Number(value) || 0)}`;
}

function formatCatchPriceOptionLabel(value){
    const numericValue = Math.max(0, Number(value) || 0);
    if(!numericValue) return '$0';
    if(numericValue < 1000) return `$${numericValue}`;
    const thousands = numericValue / 1000;
    const compactThousands = Number.isInteger(thousands)
        ? String(thousands)
        : thousands.toFixed(1).replace(/\.0$/, '');
    return `$${compactThousands}k`;
}

function formatCatchPriceOptionDetail(value){
    const numericValue = Math.max(0, Number(value) || 0);
    if(!numericValue) return '$0';
    return `$${numericValue.toLocaleString('pt-BR')}`;
}

function formatCatchPriceRangeBoundary(value){
    const numericValue = Math.max(0, Number(value) || 0);
    if(!numericValue) return '$0';
    return `$${numericValue.toLocaleString('pt-BR')}`;
}

function getCatchPriceGroupDefinitions(){
    return [
        {
            key: 'starter',
            title: 'Baixo custo',
            accent: 'Bronze',
            note: 'Valores rápidos para capturas iniciais.',
            rangeStart: 5,
            rangeEnd: 999,
            matches: (value) => value < 1000
        },
        {
            key: 'mid',
            title: 'Milhar',
            accent: 'Prata',
            note: 'Faixa comum de evolução e hunts intermediárias.',
            rangeStart: 1000,
            rangeEnd: 9999,
            matches: (value) => value >= 1000 && value < 10000
        },
        {
            key: 'high',
            title: 'Alto valor',
            accent: 'Ouro',
            note: 'Pokémon de progressão mais cara.',
            rangeStart: 10000,
            rangeEnd: 49999,
            matches: (value) => value >= 10000 && value < 50000
        },
        {
            key: 'rare',
            title: 'Raros',
            accent: 'Elite',
            note: 'Entradas premium e registros especiais.',
            rangeStart: 50000,
            matches: (value) => value >= 50000
        }
    ];
}

function getCatchPriceGroups(options = []){
    const definitions = getCatchPriceGroupDefinitions();
    const groups = definitions.map((group) => ({
        ...group,
        items: []
    }));

    options.forEach((option) => {
        const numericValue = Math.max(0, Number(option?.value) || 0);
        const targetGroup = groups.find((group) => group.matches(numericValue)) || groups[groups.length - 1];
        if(targetGroup){
            targetGroup.items.push({
                ...option,
                numericValue
            });
        }
    });

    return groups
        .filter((group) => group.items.length)
        .map((group) => {
            const numericValues = group.items
                .map((item) => item.numericValue)
                .filter((value) => Number.isFinite(value))
                .sort((left, right) => left - right);
            const rangeStart = Number.isFinite(group.rangeStart) ? group.rangeStart : numericValues[0];
            const rangeEnd = Number.isFinite(group.rangeEnd) ? group.rangeEnd : numericValues[numericValues.length - 1];
            return {
                ...group,
                rangeStart,
                rangeEnd,
                rangeLabel: `${formatCatchPriceRangeBoundary(rangeStart)} até ${formatCatchPriceRangeBoundary(rangeEnd)}`
            };
        });
}

function getActiveCatchPriceGroup(groups, selectedValue = ''){
    if(!Array.isArray(groups) || !groups.length){
        catchPriceActiveGroupKey = '';
        return null;
    }

    const currentGroup = groups.find((group) => group.key === catchPriceActiveGroupKey);
    if(currentGroup){
        return currentGroup;
    }

    const selectedGroup = selectedValue
        ? groups.find((group) => group.items.some((item) => item.value === selectedValue))
        : null;

    if(selectedGroup){
        catchPriceActiveGroupKey = selectedGroup.key;
        return selectedGroup;
    }

    catchPriceActiveGroupKey = groups[0].key;
    return groups[0];
}

function renderCatchPricePicker(){
    const wrapper = document.getElementById('catch-price-picker');
    const uiRoot = document.getElementById('catch-price-picker-ui');
    if(!(wrapper instanceof HTMLElement) || !(uiRoot instanceof HTMLElement) || !(catchPriceSelect instanceof HTMLSelectElement)) return;

    const optionEntries = Array.from(catchPriceSelect.options)
        .filter((option) => option.value)
        .map((option) => ({
            value: String(option.value || ''),
            label: String(option.textContent || '').trim()
        }));

    wrapper.classList.add('catch-price-picker--enhanced');
    uiRoot.setAttribute('aria-hidden', 'false');
    uiRoot.replaceChildren();

    const summary = document.createElement('div');
    summary.className = 'catch-price-picker__summary';

    const summaryLabel = document.createElement('span');
    summaryLabel.className = 'catch-price-picker__summary-label';
    summaryLabel.textContent = 'Preço selecionado';

    const selectedValue = String(catchPriceSelect.value || '').trim();
    const summaryValue = document.createElement('strong');
    summaryValue.className = 'catch-price-picker__summary-value';
    summaryValue.textContent = selectedValue
        ? formatCatchPriceOptionLabel(selectedValue)
        : 'Escolha um valor';

    const summaryHint = document.createElement('span');
    summaryHint.className = 'catch-price-picker__summary-hint';
    summaryHint.textContent = selectedValue
        ? `${formatCatchPriceOptionDetail(selectedValue)} registrado para a captura normal.`
        : 'Escolha uma faixa de preço e depois selecione o valor desejado.';

    summary.append(summaryLabel, summaryValue, summaryHint);
    uiRoot.appendChild(summary);

    const groups = getCatchPriceGroups(optionEntries);
    const activeGroup = getActiveCatchPriceGroup(groups, selectedValue);
    if(!activeGroup) return;

    const rangeTabs = document.createElement('div');
    rangeTabs.className = 'catch-price-picker__range-tabs';

    groups.forEach((group) => {
        const tabButton = document.createElement('button');
        tabButton.type = 'button';
        tabButton.className = 'catch-price-picker__range-tab';
        tabButton.dataset.group = group.key;
        tabButton.textContent = group.rangeLabel;
        tabButton.setAttribute('aria-pressed', String(group.key === activeGroup.key));
        tabButton.setAttribute('aria-label', `Faixa ${group.rangeLabel}`);
        if(group.key === activeGroup.key){
            tabButton.classList.add('catch-price-picker__range-tab--active');
        }
        tabButton.addEventListener('click', () => {
            catchPriceActiveGroupKey = group.key;
            renderCatchPricePicker();
        });
        rangeTabs.appendChild(tabButton);
    });

    uiRoot.appendChild(rangeTabs);

    const panel = document.createElement('section');
    panel.className = 'catch-price-picker__panel';
    panel.dataset.group = activeGroup.key;

    const panelHeader = document.createElement('div');
    panelHeader.className = 'catch-price-picker__panel-header';

    const panelTitle = document.createElement('strong');
    panelTitle.className = 'catch-price-picker__panel-title';
    panelTitle.textContent = activeGroup.title;

    const panelNote = document.createElement('span');
    panelNote.className = 'catch-price-picker__panel-note';
    panelNote.textContent = activeGroup.note;

    const panelBadges = document.createElement('div');
    panelBadges.className = 'catch-price-picker__panel-badges';

    const accentBadge = document.createElement('span');
    accentBadge.className = 'catch-price-picker__panel-badge catch-price-picker__panel-badge--accent';
    accentBadge.textContent = activeGroup.accent;

    const countBadge = document.createElement('span');
    countBadge.className = 'catch-price-picker__panel-badge';
    countBadge.textContent = `${activeGroup.items.length} preço${activeGroup.items.length > 1 ? 's' : ''}`;

    panelBadges.append(accentBadge, countBadge);
    panelHeader.append(panelTitle, panelNote, panelBadges);

    const grid = document.createElement('div');
    grid.className = 'catch-price-picker__options';

    activeGroup.items.forEach((item) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'catch-price-picker__option';
        button.dataset.value = item.value;
        button.title = `Selecionar preço ${formatCatchPriceOptionDetail(item.value)}`;
        button.setAttribute('aria-label', `Selecionar preço ${formatCatchPriceOptionDetail(item.value)}`);
        button.setAttribute('aria-pressed', item.value === selectedValue ? 'true' : 'false');
        if(item.value === selectedValue){
            button.classList.add('catch-price-picker__option--selected');
        }

        const chip = document.createElement('span');
        chip.className = 'catch-price-picker__option-chip';
        chip.textContent = formatCatchPriceOptionLabel(item.value);

        button.appendChild(chip);
        button.addEventListener('click', () => {
            const previousValue = String(catchPriceSelect.value || '');
            catchPriceSelect.value = item.value;
            catchPriceActiveGroupKey = activeGroup.key;
            renderCatchPricePicker();
            if(previousValue !== item.value){
                catchPriceSelect.dispatchEvent(new Event('change', { bubbles: true }));
            }
        });

        grid.appendChild(button);
    });

    panel.append(panelHeader, grid);
    uiRoot.appendChild(panel);
}

function getCatchPokemonCaptureValue(entry, variant){
    if(!entry) return '';
    if(variant === 'normal'){
        const price = Number(entry.price || 0);
        return price > 0 ? String(price) : '';
    }
    if(variant === 'shiny'){
        const levelKey = getPokemonShinyCaptureLevelKey(entry);
        return levelKey ? String(levelKey) : '';
    }
    return '';
}

function isCatchVariantUsable(entry, variant){
    if(!entry || !variant) return false;
    if(!isPokemonCaptureVariantAvailable(entry, variant)) return false;
    return Boolean(getCatchPokemonCaptureValue(entry, variant));
}

function getCatchAvailablePokemonEntries(){
    const entries = Array.isArray(pokemonCatalogEntriesByVariant.default)
        ? pokemonCatalogEntriesByVariant.default
        : [];
    const seen = new Set();

    return entries
        .filter(entry => (
            entry
            && entry.name
            && entry.type1
            && entry.registered !== false
            && !isMegaPokemonCatalogEntry(entry)
            && (isCatchVariantUsable(entry, 'normal') || isCatchVariantUsable(entry, 'shiny'))
        ))
        .filter(entry => {
            const key = `${entry.id || ''}:${entry.name}`;
            if(seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((left, right) => left.name.localeCompare(right.name, 'pt-BR'));
}

function getCatchPokemonEntrySearchKey(entry){
    return entry?.searchName || normalizePokemonSearchText(entry?.name || '');
}

function getCatchPokemonRouteToken(entry){
    if(!entry) return '';
    return String(entry.routeSlug || entry.id || slugifyCatchRouteToken(entry.name) || '')
        .trim()
        .toLowerCase();
}

function getCatchRoutePath(entry = catchSelectedPokemonEntry){
    const routeToken = getCatchPokemonRouteToken(entry);
    return routeToken ? `/catch/${encodeURIComponent(routeToken)}` : '/catch';
}

function findCatchPokemonEntryByRouteToken(routeToken){
    const normalizedToken = normalizeCatchRouteToken(routeToken);
    if(!normalizedToken) return null;
    return catchPokemonEntries.find((entry) => {
        if(!entry) return false;
        if(getCatchPokemonRouteToken(entry) === normalizedToken) return true;
        return getCatchPokemonEntrySearchKey(entry) === normalizedToken;
    }) || null;
}

function getCatchVariantFromUrl(search = location.search){
    const params = new URLSearchParams(search);
    const variant = String(params.get('variante') || params.get('variant') || '').trim().toLowerCase();
    return variant === 'normal' || variant === 'shiny' ? variant : '';
}

function getCatchBallFromUrl(search = location.search){
    const params = new URLSearchParams(search);
    const ball = String(params.get('ball') || params.get('pokebola') || '').trim().toLowerCase();
    return catchBallOrder.includes(ball) ? ball : '';
}

function shouldRenderCatchEstimateFromUrl(search = location.search){
    const params = new URLSearchParams(search);
    const value = String(params.get('estimativa') || params.get('calcular') || '').trim().toLowerCase();
    return ['1', 'true', 'sim', 'yes'].includes(value);
}

function setCatchEstimateRenderedState(rendered){
    if(catchResult){
        catchResult.dataset.estimateRendered = rendered ? 'true' : 'false';
    }
}

function isCatchEstimateRendered(){
    return catchResult?.dataset?.estimateRendered === 'true';
}

function refreshCatchPokemonSearchStore(){
    catchPokemonEntries = getCatchAvailablePokemonEntries();
    catchPokemonSearchIndex = new Map();
    catchPokemonEntries.forEach(entry => {
        const searchKey = getCatchPokemonEntrySearchKey(entry);
        if(searchKey && !catchPokemonSearchIndex.has(searchKey)){
            catchPokemonSearchIndex.set(searchKey, entry);
        }
    });
    return catchPokemonEntries;
}

function findCatchMatchingPokemonEntries(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || catchPokemonSearchInput?.value || '');
    if(!normalizedValue) return [];
    return catchPokemonEntries.filter(entry => {
        const searchKey = getCatchPokemonEntrySearchKey(entry);
        return searchKey === normalizedValue || searchKey.includes(normalizedValue);
    });
}

function getCatchPokemonSearchResultEntries(value = '', limit = 8){
    const normalizedValue = normalizePokemonSearchText(value || catchPokemonSearchInput?.value || '');
    return getLimitedPokemonSearchEntries(catchPokemonEntries, normalizedValue, getCatchPokemonEntrySearchKey, limit);
}

function resolveCatchPokemonEntry(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || catchPokemonSearchInput?.value || '');
    if(!normalizedValue) return null;
    const exactEntry = catchPokemonSearchIndex.get(normalizedValue) || null;
    if(exactEntry) return exactEntry;

    const matchingEntries = findCatchMatchingPokemonEntries(normalizedValue);
    return matchingEntries.length === 1 ? matchingEntries[0] : null;
}

function getCatchSelectedPokemonEntry(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || catchPokemonSearchInput?.value || '');
    if(!normalizedValue) return null;
    if(catchSelectedPokemonEntry && getCatchPokemonEntrySearchKey(catchSelectedPokemonEntry) === normalizedValue){
        return catchSelectedPokemonEntry;
    }
    return resolveCatchPokemonEntry(normalizedValue);
}

function clearCatchPokemonSearchHideTimer(){
    if(catchPokemonSearchHideTimer){
        clearTimeout(catchPokemonSearchHideTimer);
        catchPokemonSearchHideTimer = 0;
    }
}

function hideCatchPokemonSearchResults(){
    clearCatchPokemonSearchHideTimer();
    const searchField = catchPokemonSearchInput?.closest('.boost-search-panel__field');
    if(searchField){
        searchField.classList.remove('boost-search-panel__field--drop-up');
    }
    if(catchPokemonResults){
        catchPokemonResults.hidden = true;
        catchPokemonResults.replaceChildren();
    }
    if(catchPokemonNoResults){
        catchPokemonNoResults.hidden = true;
    }
}

function syncCatchPokemonSearchResultsDirection(){
    const searchField = catchPokemonSearchInput?.closest('.boost-search-panel__field');
    if(!searchField) return;

    searchField.classList.remove('boost-search-panel__field--drop-up');
    const activePanel = !catchPokemonResults?.hidden
        ? catchPokemonResults
        : (!catchPokemonNoResults?.hidden ? catchPokemonNoResults : null);
    if(!activePanel) return;

    const fieldRect = searchField.getBoundingClientRect();
    const panelRect = activePanel.getBoundingClientRect();
    const viewportHeight = window.innerHeight || document.documentElement?.clientHeight || 0;
    const availableBelow = viewportHeight - fieldRect.bottom;
    const availableAbove = fieldRect.top;
    const desiredHeight = Math.min(
        Math.max(panelRect.height, activePanel.scrollHeight || 0),
        viewportHeight * 0.7
    );

    if(availableBelow < desiredHeight && availableAbove > availableBelow){
        searchField.classList.add('boost-search-panel__field--drop-up');
    }
}

function createCatchSearchResultContent(entry){
    const sprite = document.createElement('img');
    sprite.className = 'speedster-search-item-icon boost-search-item-icon boost-search-item-icon--pokemon';
    sprite.src = getPokemonImageSource(entry);
    sprite.alt = entry.name;
    sprite.title = entry.name;
    sprite.loading = 'lazy';
    sprite.decoding = 'async';
    setImageFallback(sprite, POKEMON_IMAGE_PLACEHOLDER);

    const typeIcons = [entry.type1, entry.type2]
        .filter(Boolean)
        .slice(0, 2)
        .map(typeKey => {
            const img = document.createElement('img');
            img.className = 'speedster-search-item-icon boost-search-item-icon';
            img.src = `icons-type/${typeKey}.png`;
            img.alt = typeKey;
            img.title = getTypeDisplayName(typeKey);
            img.loading = 'lazy';
            img.decoding = 'async';
            return img;
        });

    const name = document.createElement('span');
    name.className = 'boost-search-item-name';
    name.textContent = entry.name;

    const content = document.createElement('div');
    content.className = 'boost-search-item-content';
    content.appendChild(sprite);
    typeIcons.forEach(icon => content.appendChild(icon));
    content.appendChild(name);
    return content;
}

function renderCatchPokemonSearchResults(value = '', options = {}){
    const { keepClosed = false } = options;
    if(!catchPokemonResults || !catchPokemonNoResults) return;
    if(keepClosed){
        hideCatchPokemonSearchResults();
        return;
    }

    const normalizedValue = normalizePokemonSearchText(value || catchPokemonSearchInput?.value || '');
    const entries = getCatchPokemonSearchResultEntries(value);

    if(!entries.length){
        catchPokemonResults.hidden = true;
        catchPokemonResults.replaceChildren();
        catchPokemonNoResults.hidden = !normalizedValue;
        window.requestAnimationFrame(syncCatchPokemonSearchResultsDirection);
        return;
    }

    catchPokemonNoResults.hidden = true;
    catchPokemonResults.hidden = false;
    catchPokemonResults.replaceChildren();

    const currentEntry = getCatchSelectedPokemonEntry(value);
    const fragment = document.createDocumentFragment();
    entries.forEach(entry => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'speedster-search-item boost-search-item';
        item.dataset.pokemonName = entry.name;
        item.setAttribute('aria-label', `Selecionar ${entry.name} para calcular captura.`);
        if(currentEntry && currentEntry.id === entry.id){
            item.dataset.selected = 'true';
        }
        item.appendChild(createCatchSearchResultContent(entry));
        item.addEventListener('click', () => {
            applyCatchPokemonSearchSelection(entry);
        });
        fragment.appendChild(item);
    });

    catchPokemonResults.appendChild(fragment);
    window.requestAnimationFrame(syncCatchPokemonSearchResultsDirection);
}

function syncCatchTargetTypesFromPokemon(entry = catchSelectedPokemonEntry){
    if(catchTargetTypePrimarySelect){
        catchTargetTypePrimarySelect.value = entry?.type1 || '';
        syncCatchTypeSelectUi(catchTargetTypePrimarySelect);
    }
    if(catchTargetTypeSecondarySelect){
        catchTargetTypeSecondarySelect.value = entry?.type2 || '';
        syncCatchTypeSelectUi(catchTargetTypeSecondarySelect);
    }
    updateCatchElementalRuleStatus();
}

function syncCatchVariantOptionAvailability(){
    catchVariantInputs.forEach(input => {
        const enabled = catchSelectedPokemonEntry
            ? isCatchVariantUsable(catchSelectedPokemonEntry, input.value)
            : true;
        input.disabled = !enabled;
        const card = input.closest('.catch-variant-card');
        if(card){
            card.classList.toggle('catch-variant-card--disabled', !enabled);
            card.setAttribute('aria-disabled', String(!enabled));
        }
        if(!enabled && input.checked){
            input.checked = false;
        }
    });
}

function renderCatchPokemonMeta(){
    if(!catchPokemonMeta) return;
    catchPokemonMeta.replaceChildren();
    const entry = catchSelectedPokemonEntry;
    if(!entry) return;

    const preview = document.createElement('article');
    preview.className = 'boost-selected-preview catch-selected-preview';

    const header = document.createElement('div');
    header.className = 'boost-selected-preview__header';

    const media = document.createElement('span');
    media.className = 'boost-selected-preview__media';
    const image = document.createElement('img');
    image.src = getPokemonImageSource(entry);
    image.alt = entry.name;
    image.loading = 'lazy';
    image.decoding = 'async';
    image.addEventListener('error', () => {
        media.replaceChildren(createBoostMediaFallback(entry.name));
    }, { once: true });
    media.appendChild(image);

    const identity = document.createElement('div');
    identity.className = 'boost-selected-preview__identity';

    const kicker = document.createElement('span');
    kicker.className = 'boost-selected-preview__kicker';
    kicker.textContent = 'Alvo selecionado';

    const title = document.createElement('strong');
    title.className = 'boost-selected-preview__title';
    title.textContent = entry.name;

    identity.append(kicker, title);
    header.append(media, identity);

    const groups = document.createElement('div');
    groups.className = 'boost-selected-preview__groups';

    const typeGroup = document.createElement('div');
    typeGroup.className = 'boost-selected-preview__group';
    const typeLabel = document.createElement('span');
    typeLabel.className = 'boost-selected-preview__group-label';
    typeLabel.textContent = 'Tipos';
    const typeChips = document.createElement('div');
    typeChips.className = 'boost-selected-preview__chips';
    [entry.type1, entry.type2].filter(Boolean).forEach(type => {
        typeChips.appendChild(createBoostTypeChip(type));
    });
    typeGroup.append(typeLabel, typeChips);

    const dataGroup = document.createElement('div');
    dataGroup.className = 'boost-selected-preview__group';
    const dataLabel = document.createElement('span');
    dataLabel.className = 'boost-selected-preview__group-label';
    dataLabel.textContent = 'Dados';
    const dataChips = document.createElement('div');
    dataChips.className = 'boost-selected-preview__chips';
    dataChips.appendChild(createBoostTextChip(getPokemonEntryPriceLabel(entry) || 'Preco nao informado'));
    dataChips.appendChild(createBoostTextChip(getPokemonEntryLevelLabel(entry)));
    dataGroup.append(dataLabel, dataChips);

    groups.append(typeGroup, dataGroup);
    preview.append(header, groups);
    catchPokemonMeta.appendChild(preview);
}

function applyCatchPokemonSearchSelection(entry){
    if(!entry) return;
    catchSelectedPokemonEntry = entry;
    if(catchPokemonSearchInput){
        catchPokemonSearchInput.value = entry.name;
    }
    hideCatchPokemonSearchResults();
    syncCatchTargetTypesFromPokemon(entry);
    syncCatchVariantOptionAvailability();
    renderCatchPokemonMeta();
    syncCatchSelectionUi();
    updateUrl({ historyMode: 'push' });
}

function hydrateCatchPokemonOptions(){
    if(!catchPokemonSearchInput) return;
    const entries = refreshCatchPokemonSearchStore();
    catchPokemonSearchInput.placeholder = 'Digite para buscar';
    catchSelectedPokemonEntry = resolveCatchPokemonEntry(catchPokemonSearchInput.value || '');
    syncCatchTargetTypesFromPokemon(catchSelectedPokemonEntry);
    syncCatchVariantOptionAvailability();
    renderCatchPokemonMeta();
    hideCatchPokemonSearchResults();
}

function applyCatchUrlState(options = {}){
    const { updateHistory = false } = options || {};
    const routeMatch = getCatchRouteMatch();
    const params = new URLSearchParams(location.search);
    const queryTarget = params.get('pokemon') || params.get('alvo') || '';
    const hasTargetRequest = Boolean(routeMatch?.routeToken || queryTarget);
    const requestedEntry = routeMatch?.routeToken
        ? findCatchPokemonEntryByRouteToken(routeMatch.routeToken)
        : (queryTarget ? resolveCatchPokemonEntry(queryTarget) : null);

    if(requestedEntry){
        catchSelectedPokemonEntry = requestedEntry;
        if(catchPokemonSearchInput){
            catchPokemonSearchInput.value = requestedEntry.name;
        }
        syncCatchTargetTypesFromPokemon(requestedEntry);
    } else if(!hasTargetRequest){
        catchSelectedPokemonEntry = null;
        if(catchPokemonSearchInput){
            catchPokemonSearchInput.value = '';
        }
        catchVariantInputs.forEach((input) => {
            input.checked = false;
        });
        syncCatchTargetTypesFromPokemon(null);
    }
    syncCatchVariantOptionAvailability();

    const requestedVariant = getCatchVariantFromUrl();
    if(requestedVariant){
        catchVariantInputs.forEach((input) => {
            input.checked = input.value === requestedVariant && !input.disabled;
        });
    }

    const requestedBall = getCatchBallFromUrl();
    if(requestedBall && ballSelect){
        ballSelect.value = requestedBall;
        updateBallPreview();
    }

    renderCatchPokemonMeta();
    syncCatchSelectionUi();
    if(shouldRenderCatchEstimateFromUrl()){
        renderCatchCalculation({ updateHistory: false });
    } else {
        setCatchEstimateRenderedState(false);
    }
    if(updateHistory){
        updateUrl({ historyMode: 'replace' });
    }
}

function getSelectedCatchVariant(){
    return Array.from(catchVariantInputs || []).find((input) => input.checked)?.value || '';
}

function getCatchSelectionValue(variant = getSelectedCatchVariant()){
    const entry = catchSelectedPokemonEntry || getCatchSelectedPokemonEntry();
    if(variant === 'shiny'){
        return getCatchPokemonCaptureValue(entry, 'shiny');
    }
    if(variant === 'normal'){
        return getCatchPokemonCaptureValue(entry, 'normal');
    }
    return '';
}

function isCatchSelectionReady(variant = getSelectedCatchVariant()){
    const entry = catchSelectedPokemonEntry || getCatchSelectedPokemonEntry();
    if(!entry || !variant) return false;
    if(!isCatchVariantUsable(entry, variant)) return false;
    return Boolean(getCatchSelectionValue(variant));
}

function buildCatchNormalPriceOptions(){
    return Array.from(new Set(CATCH_NORMAL_PRICE_VALUES))
        .filter((value) => Number.isFinite(value) && value > 0)
        .sort((left, right) => left - right)
        .map((value) => ({
            value: String(value),
            label: formatCatchPriceOptionLabel(value)
        }));
}

function getCatchAvailablePriceOptions(){
    if(Array.isArray(catchNormalPriceOptions) && catchNormalPriceOptions.length){
        return catchNormalPriceOptions;
    }
    return buildCatchNormalPriceOptions();
}

function setCatchPriceSelectPlaceholder(label, disabled = true){
    if(!catchPriceSelect) return;
    setCatchSelectOptions(catchPriceSelect, [], {
        includeEmpty: true,
        emptyLabel: label,
        selectedValue: ''
    });
    catchPriceSelect.disabled = disabled;
    renderCatchPricePicker();
}

function syncCatchNormalPriceSelect(selectedValue = catchPriceSelect?.value || ''){
    if(!catchPriceSelect) return false;
    const options = getCatchAvailablePriceOptions();
    if(!options.length) return false;
    catchNormalPriceOptions = options;
    setCatchSelectOptions(catchPriceSelect, options, {
        includeEmpty: true,
        emptyLabel: t('catchPricePlaceholder'),
        selectedValue
    });
    catchPriceSelect.disabled = false;
    renderCatchPricePicker();
    return true;
}

function ensureCatchNormalPriceOptionsLoaded(){
    if(syncCatchNormalPriceSelect()){
        return Promise.resolve(catchNormalPriceOptions);
    }
    catchNormalPriceOptions = buildCatchNormalPriceOptions();
    if(!syncCatchNormalPriceSelect()){
        setCatchPriceSelectPlaceholder(t('catchPriceUnavailable'));
    }
    updateCatchActionState();
    return Promise.resolve(catchNormalPriceOptions);
}

function getCatchSelectionSummary(selectionValue, variant){
    if(variant === 'normal'){
        return {
            label: t('catchResultPriceLabel'),
            value: formatCatchPriceOptionLabel(selectionValue)
        };
    }
    return {
        label: t('catchResultLevelLabel'),
        value: getCatchLevelLabel(selectionValue)
    };
}

function formatBallAmount(count, ball){
    return `${count}x ${getBallLabel(ball)}`;
}

function formatBallAmountWithLabel(count, label){
    return `${count}x ${label}`;
}

function setCatchSelectOptions(select, items = [], config = {}){
    if(!select) return;
    const includeEmpty = Boolean(config.includeEmpty);
    const emptyLabel = config.emptyLabel || '';
    const preferredValue = config.selectedValue !== undefined ? config.selectedValue : select.value;
    select.innerHTML = '';

    if(includeEmpty){
        const emptyOption = document.createElement('option');
        emptyOption.value = '';
        emptyOption.textContent = emptyLabel;
        select.appendChild(emptyOption);
    }

    items.forEach((item) => {
        const option = document.createElement('option');
        option.value = item.value;
        option.textContent = item.label;
        select.appendChild(option);
    });

    const hasPreferredValue = items.some(item => item.value === preferredValue);
    if(hasPreferredValue){
        select.value = preferredValue;
    } else if(includeEmpty){
        select.value = '';
    } else if(items[0]){
        select.value = items[0].value;
    }
}

const catchTypeSelectControllers = new Map();
let catchTypeSelectHandlersBound = false;

function setCatchTypeSelectTone(node, type){
    setTypeToneVariables(node, type);
}

function createCatchTypeSelectThumb(type, label, className = 'catch-type-select__thumb'){
    const thumb = document.createElement('span');
    thumb.className = className;

    if(type){
        const img = document.createElement('img');
        img.src = `icons-type/${type}.png`;
        img.alt = label || formatPokemonTypeLabel(type);
        img.loading = 'lazy';
        img.decoding = 'async';
        thumb.appendChild(img);
    } else {
        thumb.textContent = '+';
    }

    return thumb;
}

function createCatchTypeSelectText(label, hint){
    const text = document.createElement('span');
    text.className = 'catch-type-select__text';

    const strong = document.createElement('strong');
    strong.textContent = label;

    const helper = document.createElement('span');
    helper.textContent = hint;

    text.append(strong, helper);
    return text;
}

function getCatchTypeSelectController(selectOrId){
    const id = typeof selectOrId === 'string'
        ? selectOrId
        : selectOrId instanceof HTMLSelectElement
            ? selectOrId.id
            : '';
    return id ? catchTypeSelectControllers.get(id) || null : null;
}

function closeCatchTypeSelectMenus(exceptId = ''){
    catchTypeSelectControllers.forEach((controller, selectId) => {
        if(exceptId && selectId === exceptId) return;
        controller.wrapper.classList.remove('catch-type-select--open');
        controller.trigger.setAttribute('aria-expanded', 'false');
        controller.menu.hidden = true;
    });
    syncCatchTypeSelectPanelStates();
}

function focusCatchTypeSelectOption(controller, direction = 1){
    if(!controller?.optionButtons?.length) return;
    const buttons = controller.optionButtons;
    const activeIndex = buttons.findIndex((button) => button === document.activeElement);
    const selectedIndex = Math.max(0, buttons.findIndex((button) => button.dataset.value === controller.select.value));
    const startIndex = activeIndex >= 0 ? activeIndex : selectedIndex;
    const nextIndex = (startIndex + direction + buttons.length) % buttons.length;
    buttons[nextIndex]?.focus();
}

function syncCatchTypeSelectPanelStates(){
    const panels = new Set();
    catchTypeSelectControllers.forEach((controller) => {
        const panel = controller?.wrapper?.closest('.catch-panel');
        if(panel instanceof HTMLElement){
            panels.add(panel);
        }
    });
    panels.forEach((panel) => {
        panel.classList.toggle(
            'catch-panel--type-select-active',
            Boolean(panel.querySelector('.catch-type-select--open'))
        );
    });
}

function resetCatchTypeSelectMenuPlacement(controller){
    if(!controller?.wrapper || !controller?.menu) return;
    controller.wrapper.classList.remove('catch-type-select--open-upward');
    controller.menu.style.maxHeight = '';
}

function updateCatchTypeSelectMenuPlacement(controller){
    if(!controller?.wrapper || !controller?.trigger || !controller?.menu) return;

    const viewportMargin = 14;
    const menuGap = 8;
    const minMenuHeight = 140;
    const triggerRect = controller.trigger.getBoundingClientRect();
    const availableBelow = Math.max(0, Math.floor(window.innerHeight - viewportMargin - triggerRect.bottom - menuGap));
    const nextMaxHeight = Math.max(minMenuHeight, availableBelow);

    controller.wrapper.classList.remove('catch-type-select--open-upward');
    controller.menu.style.maxHeight = `${nextMaxHeight}px`;
}

function setCatchTypeSelectMenuOpen(controller, shouldOpen, focusSelected = false){
    if(!controller) return;

    if(shouldOpen){
        closeCatchTypeSelectMenus(controller.select.id);
        controller.wrapper.classList.add('catch-type-select--open');
        controller.trigger.setAttribute('aria-expanded', 'true');
        controller.menu.hidden = false;
        updateCatchTypeSelectMenuPlacement(controller);
        syncCatchTypeSelectPanelStates();
        if(focusSelected){
            requestAnimationFrame(() => {
                const selectedButton = controller.optionButtons.find((button) => button.dataset.value === String(controller.select.value || ''));
                (selectedButton || controller.optionButtons[0])?.focus();
            });
        }
        return;
    }

    controller.wrapper.classList.remove('catch-type-select--open');
    controller.trigger.setAttribute('aria-expanded', 'false');
    controller.menu.hidden = true;
    resetCatchTypeSelectMenuPlacement(controller);
    syncCatchTypeSelectPanelStates();
}

function syncCatchTypeSelectUi(select){
    const controller = getCatchTypeSelectController(select);
    if(!controller) return;

    const value = String(select?.value || '');
    const normalizedType = normalizePokemonTypeKey(value);
    const selectedOption = Array.from(select.options).find((option) => option.value === value) || select.options[0] || null;
    const selectedLabel = String(selectedOption?.textContent || controller.placeholder || '').trim();

    controller.triggerCopy.replaceChildren();
    if(normalizedType){
        controller.triggerCopy.append(
            createCatchTypeSelectThumb(normalizedType, selectedLabel),
            createCatchTypeSelectText(selectedLabel, controller.selectedHint)
        );
    } else {
        controller.triggerCopy.classList.add('catch-type-select__trigger-copy--placeholder');
        controller.triggerCopy.append(
            createCatchTypeSelectThumb('', '', 'catch-type-select__placeholder-mark'),
            createCatchTypeSelectText(selectedLabel || controller.placeholder, controller.emptyHint)
        );
    }
    if(normalizedType){
        controller.triggerCopy.classList.remove('catch-type-select__trigger-copy--placeholder');
    }

    controller.trigger.setAttribute('aria-label', `${controller.label}: ${selectedLabel || controller.placeholder}`);
    setCatchTypeSelectTone(controller.wrapper, normalizedType);
    setCatchTypeSelectTone(controller.trigger, normalizedType);

    controller.optionButtons.forEach((button) => {
        const isSelected = button.dataset.value === value;
        button.classList.toggle('catch-type-select__option--selected', isSelected);
        button.setAttribute('aria-selected', isSelected ? 'true' : 'false');
    });
}

function ensureCatchTypeSelectHandlers(){
    if(catchTypeSelectHandlersBound) return;

    document.addEventListener('pointerdown', (event) => {
        const target = event.target;
        if(!(target instanceof Node)) return;
        const clickedInside = Array.from(catchTypeSelectControllers.values())
            .some((controller) => controller.wrapper.contains(target));
        if(!clickedInside){
            closeCatchTypeSelectMenus();
        }
    });

    document.addEventListener('keydown', (event) => {
        if(event.key !== 'Escape') return;
        const openController = Array.from(catchTypeSelectControllers.values())
            .find((controller) => controller.wrapper.classList.contains('catch-type-select--open'));
        if(!openController) return;
        event.preventDefault();
        setCatchTypeSelectMenuOpen(openController, false);
        openController.trigger.focus();
    });

    catchTypeSelectHandlersBound = true;
}

function renderCatchTypeSelect(select){
    if(!(select instanceof HTMLSelectElement)) return;

    const wrapper = select.closest('.catch-type-select');
    const uiRoot = wrapper?.querySelector('.catch-type-select__ui');
    if(!(wrapper instanceof HTMLElement) || !(uiRoot instanceof HTMLElement)) return;

    const labelEl = wrapper.closest('.catch-elemental-config__field')?.querySelector(`label[for="${select.id}"]`);
    const isSecondary = select.id === 'catch-target-type-secondary';
    const placeholder = String(select.options[0]?.textContent || '').trim();

    uiRoot.replaceChildren();
    wrapper.classList.add('catch-type-select--enhanced');
    uiRoot.setAttribute('aria-hidden', 'false');

    const trigger = document.createElement('button');
    trigger.type = 'button';
    trigger.id = `${select.id}-trigger`;
    trigger.className = 'catch-type-select__trigger';
    trigger.setAttribute('aria-haspopup', 'listbox');
    trigger.setAttribute('aria-expanded', 'false');
    trigger.setAttribute('aria-controls', `${select.id}-menu`);

    const triggerCopy = document.createElement('span');
    triggerCopy.className = 'catch-type-select__trigger-copy';

    const chevron = document.createElement('span');
    chevron.className = 'catch-type-select__chevron';
    chevron.setAttribute('aria-hidden', 'true');
    chevron.textContent = 'v';

    trigger.append(triggerCopy, chevron);

    const menu = document.createElement('div');
    menu.id = `${select.id}-menu`;
    menu.className = 'catch-type-select__menu';
    menu.setAttribute('role', 'listbox');
    menu.setAttribute('aria-labelledby', trigger.id);
    menu.hidden = true;

    const optionButtons = Array.from(select.options).map((option) => {
        const value = String(option.value || '');
        const normalizedType = normalizePokemonTypeKey(value);
        const label = String(option.textContent || '').trim();

        const button = document.createElement('button');
        button.type = 'button';
        button.className = `catch-type-select__option${normalizedType ? '' : ' catch-type-select__option--empty'}`;
        button.dataset.value = value;
        button.setAttribute('role', 'option');
        button.setAttribute('aria-selected', 'false');
        setCatchTypeSelectTone(button, normalizedType);

        if(normalizedType){
            button.append(
                createCatchTypeSelectThumb(normalizedType, label),
                createCatchTypeSelectText(label, isSecondary ? 'Elemento opcional' : 'Elemento principal')
            );
        } else {
            button.append(
                createCatchTypeSelectThumb('', '', 'catch-type-select__placeholder-mark'),
                createCatchTypeSelectText(label, isSecondary ? 'Sem segundo tipo' : 'Escolha um elemento')
            );
        }

        button.addEventListener('click', () => {
            const previousValue = String(select.value || '');
            select.value = value;
            syncCatchTypeSelectUi(select);
            setCatchTypeSelectMenuOpen(getCatchTypeSelectController(select), false);
            trigger.focus();
            if(previousValue !== value){
                select.dispatchEvent(new Event('change', { bubbles: true }));
            }
        });

        button.addEventListener('keydown', (event) => {
            if(event.key === 'ArrowDown'){
                event.preventDefault();
                focusCatchTypeSelectOption(getCatchTypeSelectController(select), 1);
                return;
            }
            if(event.key === 'ArrowUp'){
                event.preventDefault();
                focusCatchTypeSelectOption(getCatchTypeSelectController(select), -1);
                return;
            }
            if(event.key === 'Home'){
                event.preventDefault();
                getCatchTypeSelectController(select)?.optionButtons[0]?.focus();
                return;
            }
            if(event.key === 'End'){
                event.preventDefault();
                const buttons = getCatchTypeSelectController(select)?.optionButtons || [];
                buttons[buttons.length - 1]?.focus();
                return;
            }
            if(event.key === 'Escape'){
                event.preventDefault();
                setCatchTypeSelectMenuOpen(getCatchTypeSelectController(select), false);
                trigger.focus();
            }
        });

        menu.appendChild(button);
        return button;
    });

    uiRoot.append(trigger, menu);

    const controller = {
        select,
        wrapper,
        uiRoot,
        trigger,
        triggerCopy,
        menu,
        optionButtons,
        label: isSecondary ? 'Segundo tipo do alvo' : 'Tipo principal do alvo',
        placeholder,
        emptyHint: isSecondary ? 'Opcional' : 'Escolha na lista',
        selectedHint: isSecondary ? 'Segundo tipo do alvo' : 'Tipo principal do alvo'
    };

    catchTypeSelectControllers.set(select.id, controller);

    trigger.addEventListener('click', () => {
        const shouldOpen = menu.hidden;
        setCatchTypeSelectMenuOpen(controller, shouldOpen, shouldOpen);
    });

    trigger.addEventListener('keydown', (event) => {
        if(event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' '){
            event.preventDefault();
            setCatchTypeSelectMenuOpen(controller, true, true);
            return;
        }
        if(event.key === 'ArrowUp'){
            event.preventDefault();
            setCatchTypeSelectMenuOpen(controller, true, true);
            requestAnimationFrame(() => {
                const buttons = controller.optionButtons;
                buttons[buttons.length - 1]?.focus();
            });
        }
    });

    wrapper.addEventListener('focusout', () => {
        requestAnimationFrame(() => {
            if(!wrapper.contains(document.activeElement)){
                setCatchTypeSelectMenuOpen(controller, false);
            }
        });
    });

    if(labelEl instanceof HTMLElement && !labelEl.dataset.catchTypeTriggerBound){
        labelEl.dataset.catchTypeTriggerBound = 'true';
        labelEl.addEventListener('click', (event) => {
            const currentController = getCatchTypeSelectController(select);
            if(!currentController?.wrapper.classList.contains('catch-type-select--enhanced')) return;
            event.preventDefault();
            currentController.trigger.focus();
        });
    }

    if(!select.dataset.catchTypeUiBound){
        select.dataset.catchTypeUiBound = 'true';
        select.addEventListener('change', () => {
            syncCatchTypeSelectUi(select);
        });
    }

    syncCatchTypeSelectUi(select);
    resetCatchTypeSelectMenuPlacement(controller);
    syncCatchTypeSelectPanelStates();
    ensureCatchTypeSelectHandlers();
}

function getCatchSelectedTargetTypes(){
    const seen = new Set();
    const selectedTypes = [
        normalizePokemonTypeKey(catchTargetTypePrimarySelect?.value),
        normalizePokemonTypeKey(catchTargetTypeSecondarySelect?.value)
    ].filter(Boolean);
    const sourceTypes = selectedTypes.length ? selectedTypes : [
        normalizePokemonTypeKey(catchSelectedPokemonEntry?.type1),
        normalizePokemonTypeKey(catchSelectedPokemonEntry?.type2)
    ];

    return sourceTypes.filter((type) => {
        if(!type || seen.has(type)) return false;
        seen.add(type);
        return true;
    });
}

function getCatchTargetElementalBallOptions(targetTypes = getCatchSelectedTargetTypes()){
    const seen = new Set();
    return targetTypes
        .map(type => ELEMENTAL_BALL_TYPE_MAP[normalizePokemonTypeKey(type)] || null)
        .filter((ball) => {
            if(!ball?.key || seen.has(ball.key)) return false;
            seen.add(ball.key);
            return true;
        });
}

function getCatchElementalResolution(){
    const targetTypes = getCatchSelectedTargetTypes();
    const matchingBalls = getCatchTargetElementalBallOptions(targetTypes);
    return {
        targetTypes,
        matchingBalls,
        matchingBallKeys: new Set(matchingBalls.map(ball => ball.key)),
        hasTarget: targetTypes.length > 0
    };
}

function getCatchEffectiveRequirementBallKey(chosen){
    return getCatchRequirementBallKey(chosen);
}

function getCatchBallDisplayLabel(ball){
    return getBallLabel(ball);
}

function getCatchBallUnitPrice(ball){
    return Number(ballPrices[ball] || 0);
}

function getCatchSpecificElementalBucket(ballKey, resolution = getCatchElementalResolution()){
    if(!ballKey || !resolution?.hasTarget) return 'elemental';
    return resolution.matchingBallKeys.has(ballKey) ? 'elemental' : 'story';
}

function initializeCatchElementalSelectors(){
    setCatchSelectOptions(
        catchTargetTypePrimarySelect,
        CATCH_TARGET_TYPE_OPTIONS,
        { includeEmpty: true, emptyLabel: 'Selecione o tipo principal', selectedValue: catchTargetTypePrimarySelect?.value || '' }
    );
    setCatchSelectOptions(
        catchTargetTypeSecondarySelect,
        CATCH_TARGET_TYPE_OPTIONS,
        { includeEmpty: true, emptyLabel: 'Sem 2o tipo', selectedValue: catchTargetTypeSecondarySelect?.value || '' }
    );
    renderCatchTypeSelect(catchTargetTypePrimarySelect);
    renderCatchTypeSelect(catchTargetTypeSecondarySelect);
}

function updateCatchElementalRuleStatus(){
    if(!catchElementalRuleStatus) return;
    const { targetTypes, matchingBalls, hasTarget } = getCatchElementalResolution();
    const targetLabel = targetTypes.map(formatPokemonTypeLabel).join(' / ');
    const matchingBallLabel = matchingBalls.map(ball => ball.label).join(', ');

    let tone = 'idle';
    let message = '';

    if(hasTarget){
        tone = 'elemental';
        message = `Para ${targetLabel}, contam como ${getBallLabel('elemental')}: ${matchingBallLabel}. As outras elementais do log entram como ${getBallLabel('story')}.`;
    }

    catchElementalRuleStatus.dataset.tone = tone;
    catchElementalRuleStatus.textContent = message;
    catchElementalRuleStatus.hidden = !message;
}

function renderCatchChips(items){
    return items
        .filter(Boolean)
        .map(item=>`<span class="catch-result-chip">${item}</span>`)
        .join('');
}

function renderCatchMetrics(items){
    return items
        .filter(item=>item && item.value !== undefined && item.value !== null && item.value !== '')
        .map(item=>`
            <div class="catch-result-metric">
                <span class="catch-result-metric__label">${item.label}</span>
                <strong class="catch-result-metric__value">${item.value}</strong>
            </div>
        `)
        .join('');
}

function renderCatchPills(items, accent = false){
    const pillClass = accent ? 'catch-result-pill catch-result-pill--accent' : 'catch-result-pill';
    return items
        .filter(Boolean)
        .map(item=>`<span class="${pillClass}">${item}</span>`)
        .join('');
}

function createCatchLogState(text){
    const normalizedText = String(text || '');
    const { totalCost, counts, specificElementalCounts } = parseLog(normalizedText);
    return {
        sourceText: normalizedText,
        parsedTotalCost: Number(totalCost) || 0,
        parsedCounts: cloneCatchBallCounts(counts),
        parsedSpecificElementalCounts: cloneCatchSpecificElementalCounts(specificElementalCounts),
        manualCounts: createEmptyCatchBallCounts()
    };
}

function getCatchLogCombinedCounts(state){
    const counts = cloneCatchBallCounts(state?.parsedCounts);
    const specificElementalCounts = cloneCatchSpecificElementalCounts(state?.parsedSpecificElementalCounts);
    const resolution = getCatchElementalResolution();
    Object.entries(specificElementalCounts).forEach(([ballKey, count]) => {
        const bucket = getCatchSpecificElementalBucket(ballKey, resolution);
        counts[bucket] = Number(counts[bucket] || 0) + Number(count || 0);
    });
    catchBallOrder.forEach((ball) => {
        counts[ball] = Math.max(0, counts[ball] + Number(state?.manualCounts?.[ball] || 0));
    });
    return counts;
}

function getCatchLogManualCostDelta(state){
    return catchBallOrder.reduce((sum, ball) => {
        return sum + (Number(state?.manualCounts?.[ball] || 0) * getCatchBallUnitPrice(ball));
    }, 0);
}

function formatCatchQuickAdjustment(ball, manualCount){
    if(!manualCount){
        return t('catchQuickAdjustEmpty');
    }
    return t('catchQuickAdjustSummary')
        .replace('{sign}', manualCount > 0 ? '+' : '-')
        .replace('{count}', Math.abs(manualCount))
        .replace('{ball}', getCatchBallDisplayLabel(ball));
}

function updateBallPreview(){
    const selectedBall = document.getElementById('ball-select')?.value || 'elemental';
    const selectedBallLabel = getCatchBallDisplayLabel(selectedBall);
    const previewImage = document.getElementById('ball-img');
    if(previewImage){
        previewImage.src = getBallPreviewImageSrc(selectedBall);
        previewImage.alt = selectedBallLabel;
    }
    const previewName = document.getElementById('ball-preview-name');
    if(previewName) previewName.textContent = selectedBallLabel;
    const previewPrice = document.getElementById('ball-preview-price');
    if(previewPrice) previewPrice.textContent = `${formatCurrencyValue(getCatchBallUnitPrice(selectedBall))} cada`;
    updateCatchElementalRuleStatus();
}

function renderCatchPendingState(target, message){
    if(!target) return;
    if(target === catchResult){
        setCatchEstimateRenderedState(false);
    }
    target.innerHTML = `<div class="calc-result-highlight catch-result-empty">${message}</div>`;
}

function renderCatchEstimateResult(target, chosen, selectionValue, variant, optionItems){
    if(!target) return;
    if(!optionItems.length){
        if(target === catchResult){
            setCatchEstimateRenderedState(false);
        }
        target.innerHTML = `<div class="calc-result-highlight catch-result-empty">${t('noBallsParsed')}</div>`;
        return;
    }
    if(target === catchResult){
        setCatchEstimateRenderedState(true);
    }
    const selectedBallLabel = getCatchBallDisplayLabel(chosen);
    const selectionSummary = getCatchSelectionSummary(selectionValue, variant);
    const headline = formatBallAmountWithLabel(optionItems[0].needed, selectedBallLabel);
    const chips = renderCatchChips([
        `${selectionSummary.label}: ${selectionSummary.value}`,
        `${t('catchResultVariantLabel')}: ${getCatchVariantLabel(variant)}`,
        `${t('catchResultBallLabel')}: ${selectedBallLabel}`
    ]);
    const metrics = renderCatchMetrics(optionItems.map((item, index)=>({
        label: optionItems.length > 1 ? `${t('catchOptionLabel')} ${index + 1}` : t('catchResultCountLabel'),
        value: formatBallAmountWithLabel(item.needed, selectedBallLabel)
    })));
    target.innerHTML = `
        <div class="calc-result-highlight catch-result-shell">
            <div class="catch-result-shell__header">
                <div>
                    <span class="catch-result-shell__eyebrow">${t('catchResultTitle')}</span>
                    <div class="catch-result-shell__title">${headline}</div>
                </div>
                <div class="catch-result-shell__meta">${chips}</div>
            </div>
            <div class="catch-result-shell__grid">${metrics}</div>
        </div>
    `;
}

function renderCatchLogResult(target, chosen, totalCost, counts, effectiveUsed, remainingItems, avgNeeded, over, manualState = {}){
    if(!target) return;
    const totalBalls = catchBallOrder.reduce((sum, ball) => sum + (counts[ball] || 0), 0);
    if(totalCost === 0 && totalBalls === 0){
        target.innerHTML = `
            <div class="calc-result-highlight catch-result-shell">
                <div class="catch-result-shell__header">
                    <div>
                        <span class="catch-result-shell__eyebrow">${t('catchLogResultTitle')}</span>
                        <div class="catch-result-shell__title">${t('noBallsParsed')}</div>
                    </div>
                </div>
                <div class="catch-result-empty">${t('catchLogHint')}</div>
            </div>
        `;
        return;
    }
    const selectedBallLabel = getCatchBallDisplayLabel(chosen);
    const metrics = renderCatchMetrics([
        {label: t('catchLogSpentLabel'), value: formatCurrencyValue(totalCost)},
        {label: t('catchLogEquivalentLabel').replace('{ball}', selectedBallLabel), value: formatBallAmountWithLabel(effectiveUsed, selectedBallLabel)},
        {label: t('catchLogBallsLabel'), value: `${totalBalls}`}
    ]);
    const breakdown = renderCatchPills(
        catchBallOrder.map((ball) => `${getCatchBallDisplayLabel(ball)}: ${counts[ball] || 0}`)
    );
    const hasSelection = manualState?.hasSelection !== false;
    const statusLines = hasSelection
        ? (
            remainingItems.length
                ? remainingItems.map(item=>formatBallAmountWithLabel(item.needed, selectedBallLabel))
                : [
                    t('avgReached').replace('{avg}', avgNeeded).replace('{ball}', selectedBallLabel),
                    over > 0 ? t('overAvg').replace('{over}', over).replace('{ball}', selectedBallLabel) : '',
                    t('encouragement')
                ]
        )
        : ['Escolha o alvo e a variante para calcular quanto falta.'];
    const statusTitle = hasSelection
        ? (remainingItems.length ? t('catchRemainingTitle') : t('catchAchievedTitle'))
        : 'Estimativa bloqueada';
    const statusMarkup = renderCatchPills(statusLines, hasSelection && remainingItems.length);
    const manualCount = Number(manualState?.manualCount || 0);
    const adjustableBallCount = Number(manualState?.baseCount || 0);
    const quickAdjustSummary = formatCatchQuickAdjustment(chosen, manualCount);
    target.innerHTML = `
        <div class="calc-result-highlight catch-result-shell">
            <div class="catch-result-shell__header">
                <div>
                    <span class="catch-result-shell__eyebrow">${t('catchLogResultTitle')}</span>
                    <div class="catch-result-shell__title">${formatBallAmountWithLabel(effectiveUsed, selectedBallLabel)}</div>
                </div>
                <div class="catch-result-shell__meta">
                    ${renderCatchChips([`${t('catchResultBallLabel')}: ${selectedBallLabel}`])}
                </div>
            </div>
            <div class="catch-result-shell__grid">${metrics}</div>
            <div class="catch-log-adjuster">
                <div class="catch-log-adjuster__meta">
                    <span class="catch-log-adjuster__label">${t('catchQuickAdjustLabel')}</span>
                    <span class="catch-log-adjuster__hint">${t('catchQuickAdjustHint')}</span>
                </div>
                <div class="catch-log-adjuster__controls">
                    <button
                        type="button"
                        class="catch-log-adjuster__button catch-log-adjuster__button--ghost"
                        data-catch-adjust-ball="${chosen}"
                        data-catch-adjust-step="-1"
                        aria-label="${t('catchQuickAdjustDecrease').replace('{ball}', selectedBallLabel)}"
                        ${adjustableBallCount <= 0 ? 'disabled' : ''}
                    >-1</button>
                    <span class="catch-log-adjuster__value">${quickAdjustSummary}</span>
                    <button
                        type="button"
                        class="catch-log-adjuster__button"
                        data-catch-adjust-ball="${chosen}"
                        data-catch-adjust-step="1"
                        aria-label="${t('catchQuickAdjustIncrease').replace('{ball}', selectedBallLabel)}"
                    >+1</button>
                </div>
            </div>
            <div class="catch-result-shell__list">
                <span class="catch-result-shell__list-title">${t('catchLogBallsLabel')}</span>
                <div class="catch-result-shell__items">${breakdown}</div>
            </div>
            <div class="catch-result-shell__status">
                <span class="catch-result-shell__status-title">${statusTitle}</span>
                <div class="catch-result-shell__items">${statusMarkup}</div>
            </div>
        </div>
    `;
}

function drawConnections(type){
    const origin=document.querySelector(`.type-button[data-type="${type}"]`);
    if(!origin) return;
    const rect=origin.getBoundingClientRect();
    const svgRect=connectionsSvg.getBoundingClientRect();
    const ox=rect.left+rect.width/2-svgRect.left;
    const oy=rect.top+rect.height/2-svgRect.top;
    const related=[...(effectiveness[type]||[]),...(weaknesses[type]||[])];
    const otherSelected = currentSelection.length===2 ? currentSelection.find(t=>t!==type) : null;
    related.forEach(rt=>{
        const btn=document.querySelector(`.type-button[data-type="${rt}"]`);
        if(!btn) return;
        const rrect=btn.getBoundingClientRect();
        const rx=rrect.left+rrect.width/2-svgRect.left;
        const ry=rrect.top+rrect.height/2-svgRect.top;
        const line=document.createElementNS('http://www.w3.org/2000/svg','line');
        line.setAttribute('x1',ox);line.setAttribute('y1',oy);
        line.setAttribute('x2',ox);line.setAttribute('y2',oy);
        line.setAttribute('stroke','#fff');line.setAttribute('stroke-width','2');
        line.setAttribute('opacity','0.7');
        line.setAttribute('stroke-dasharray','5,5');
        line.style.strokeDashoffset='100';
        connectionsSvg.appendChild(line);
        if(useGsap){
            gsap.to(line, {attr: {x2: rx, y2: ry}, stroke: (otherSelected && rt===otherSelected) ? '#0f0' : '#ff0', strokeWidth: (otherSelected && rt===otherSelected)?3:2, duration: 0.5, ease: 'power1.out'});
            gsap.to(line.style, {strokeDashoffset:0, duration:0.5, ease:'linear'});
        } else {
            setTimeout(()=>{
                line.setAttribute('x2',rx);line.setAttribute('y2',ry);
                if(otherSelected && rt===otherSelected) {
                    line.setAttribute('stroke','#0f0');
                    line.setAttribute('stroke-width','3');
                } else {
                    line.setAttribute('stroke','#ff0');
                }
                line.style.transition='stroke-dashoffset 0.5s linear';
                line.style.strokeDashoffset='0';
            },10);
        }
        const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');
        circle.setAttribute('cx',ox);circle.setAttribute('cy',oy);
        circle.setAttribute('r','4');
        circle.setAttribute('fill', otherSelected && rt===otherSelected ? '#0f0' : '#ff0');
        circle.setAttribute('opacity','0.8');
        connectionsSvg.appendChild(circle);
        if(useGsap){
            gsap.to(circle, {attr: {cx: rx, cy: ry}, r:2, opacity:0, duration:0.5, ease:'power1.out'});
        } else {
            setTimeout(()=>{
                circle.setAttribute('cx',rx);circle.setAttribute('cy',ry);
                circle.setAttribute('r','2');circle.setAttribute('opacity','0');
                circle.style.transition='cx 0.5s, cy 0.5s, opacity 0.5s, r 0.5s';
            },10);
        }
    });
}

function renderSelection(){
    connectionsSvg.innerHTML='';
    document.querySelectorAll('.type-button').forEach(btn=>{
        btn.classList.remove('active','effectiveness','weakness','immune','mixed','neutral','resist','strength-from-selection');
        btn.setAttribute('aria-pressed','false');
    });
    const info=document.getElementById('info');
    info.textContent='';
    if(!currentSelection.length) return;
    currentSelection.forEach(type=>{
        const btn=document.querySelector(`.type-button[data-type="${type}"]`);
        if(btn){
            btn.classList.add('active');
            btn.setAttribute('aria-pressed','true');
            drawConnections(type);
        }
    });
    if(currentSelection.length===2){
        const [a,b]=currentSelection;
        const btnA=document.querySelector(`.type-button[data-type="${a}"]`);
        const btnB=document.querySelector(`.type-button[data-type="${b}"]`);
        if(btnA && btnB){
            const svgRect=connectionsSvg.getBoundingClientRect();
            const rectA=btnA.getBoundingClientRect();
            const rectB=btnB.getBoundingClientRect();
            const ax=rectA.left+rectA.width/2-svgRect.left;
            const ay=rectA.top+rectA.height/2-svgRect.top;
            const bx=rectB.left+rectB.width/2-svgRect.left;
            const by=rectB.top+rectB.height/2-svgRect.top;
            const link=document.createElementNS('http://www.w3.org/2000/svg','line');
            link.setAttribute('x1',ax); link.setAttribute('y1',ay);
            link.setAttribute('x2',bx); link.setAttribute('y2',by);
            link.setAttribute('stroke','#0ff');
            link.setAttribute('stroke-width','4');
            link.setAttribute('opacity','0.9');
            connectionsSvg.appendChild(link);
        }
    }
    // Multiplicadores defensivos: atacante vs currentSelection como defensores
    const multipliers = {};
    menuTypes.forEach(att=>{
        let m = 1;
        currentSelection.forEach(def=>{
            if(immunities[def] && immunities[def].includes(att)){
                m *= 0;          // defensor imune a este atacante
            } else if(effectiveness[att] && effectiveness[att].includes(def)){
                m *= 2;          // atacante forte contra defensor
            } else if(resistances[def] && resistances[def].includes(att)){
                m *= 0.5;        // defensor resiste ao atacante
            }
        });
        // Não permitir multiplicador zero — limite mínimo 0.5x
        m = Math.max(m, 0.5);
        multipliers[att] = m;
    });

    const strengths = combineLists(currentSelection.map(t=>effectiveness[t]||[]));
    const weakAgainst = Object.keys(multipliers).filter(t=> multipliers[t] > 1);
    const immuneList = Object.keys(multipliers).filter(t=> multipliers[t] === 0);
    const resistList = Object.keys(multipliers).filter(t=> multipliers[t] > 0 && multipliers[t] < 1);

    const strengthsCount = tally(currentSelection.map(t=>effectiveness[t]||[]));
    const weakCount = {};
    const resistCount = {};
    weakAgainst.forEach(t=>{ weakCount[t] = multipliers[t]; });
    // Contar quantos tipos selecionados cada alvo resiste
    currentSelection.forEach(ct=>{
        menuTypes.forEach(t=>{
            if(resistances[t] && resistances[t].includes(ct)){
                resistCount[t] = (resistCount[t]||0)+1;
            }
        });
    });

    // Estado visual: marcar tipos no grid conforme a relacao com a selecao atual
    // NOTA: no painel de tipos, consideramos 'effectiveness' como destaque visual para
    // tipos que sao "super efetivos" na relacao atual (atacantes que batem
    // na selecao com >1x). Isso garante que, por exemplo, Fairy e Ice aparecam como super efetivos
    // contra Dragon quando Dragon estiver selecionado.
    strengths.forEach(t2=>{
        const b=document.querySelector(`.type-button[data-type="${t2}"]`);
        if(b){
            // Tipos contra os quais a selecao atual e efetiva: manter marca sutil
            b.classList.add('strength-from-selection');
        }
    });
    // Tipos que causam >1x de dano na selecao (ou seja, sao super efetivos contra ela)
    weakAgainst.forEach(t2=>{
        const b=document.querySelector(`.type-button[data-type="${t2}"]`);
        if(b){
            b.classList.remove('weakness');
            b.classList.add('effectiveness');
        }
    });
    resistList.forEach(t2=>{const b=document.querySelector(`.type-button[data-type="${t2}"]`);if(b)b.classList.add('resist');});
    immuneList.forEach(t2=>{const b=document.querySelector(`.type-button[data-type="${t2}"]`);if(b)b.classList.add('immune');});

    const overlapped = strengths.filter(t2=>immuneList.includes(t2));
    overlapped.forEach(t2=>{
        const b = document.querySelector(`.type-button[data-type="${t2}"]`);
        if(b){
            b.classList.add('mixed');
            b.classList.remove('effectiveness');
            b.classList.remove('immune');
        }
    });

    if(currentSelection.length) {
        document.querySelectorAll('.type-button').forEach(btn=>{
            const type = btn.dataset.type;
            if(
                !btn.classList.contains('active') &&
                !btn.classList.contains('effectiveness') &&
                !btn.classList.contains('effective') &&
                !btn.classList.contains('weakness') &&
                !btn.classList.contains('resist') &&
                !btn.classList.contains('immune') &&
                !btn.classList.contains('mixed') &&
                !btn.classList.contains('strength-from-selection')
            ) {
                btn.classList.add('neutral');
            } else {
                btn.classList.remove('neutral');
            }
        });
    }
    // Montar um card de informacoes mais rico com secoes claras e icones clicaveis
    function makeIcons(list){
        return list.map(t2=>{
            const label = t2.charAt(0).toUpperCase()+t2.slice(1);
            return `
                <button class="info-type" data-type="${t2}" aria-label="Selecionar ${label}" title="${label}">
                    <img class="info-icon" src="icons-type/${t2}.png" alt="${label}" loading="lazy" decoding="async">
                    <span class="info-type-label">${label}</span>
                </button>
            `;
        }).join('');
    }

    // Separar forcas em 'efetivo' (count === 1) e 'super efetivo' (count > 1)
    const superEffectiveTargets = strengths.filter(t2 => (strengthsCount[t2] || 0) > 1);
    const effectiveTargets = strengths.filter(t2 => (strengthsCount[t2] || 0) === 1);

    let html = `<div class="types-info-shell">`;
    html += `
        <div class="types-info__summary">
            <span class="types-info__eyebrow">Análise atual</span>
            <div class="info-type-heading">${t('typeLabel')}: ${currentSelection.map(s=>s.charAt(0).toUpperCase()+s.slice(1)).join(' + ')}</div>
            <div class="types-selection-pills">
                ${currentSelection.map(type=>`<span class="types-selection-pill"><img src="icons-type/${type}.png" alt="" aria-hidden="true" loading="lazy" decoding="async"><span>${getTypeDisplayName(type)}</span></span>`).join('')}
            </div>
        </div>
        <div class="types-info__sections">
    `;
    if(superEffectiveTargets.length) html += `<section class="info-section info-super"><h4>${t('superEffective')}</h4><div class="info-icons">${makeIcons(superEffectiveTargets)}</div></section>`;
    if(effectiveTargets.length) html += `<section class="info-section info-effective"><h4>Efetivo</h4><div class="info-icons">${makeIcons(effectiveTargets)}</div></section>`;
    if(weakAgainst.length) html += `<section class="info-section info-vulnerable"><h4>${t('vulnerable')}</h4><div class="info-icons">${makeIcons(weakAgainst)}</div></section>`;
    if(resistList.length) html += `<section class="info-section info-resist"><h4>${t('resistLabel')}</h4><div class="info-icons">${makeIcons(resistList)}</div></section>`;
    if(immuneList.length) html += `<section class="info-section info-immune"><h4>${t('immune')}</h4><div class="info-icons">${makeIcons(immuneList)}</div></section>`;
    if(!superEffectiveTargets.length && !effectiveTargets.length && !weakAgainst.length && !resistList.length && !immuneList.length) html+=`<div class="info-empty-msg">${t('noRelation')}</div>`;
    html += `</div></div>`;
    info.innerHTML = html;

    // Conectar botoes clicaveis dentro do card
    info.querySelectorAll('.info-type').forEach(btn=>{
        btn.style.cursor = 'pointer';
        btn.addEventListener('click', ()=> selectType(btn.dataset.type));
        if(useGsap){
            gsap.fromTo(btn, {scale:0.9, opacity:0}, {scale:1, opacity:1, duration:0.32, ease:'back.out(1.4)'});
        }
    });
}

function renderSelection(){
    connectionsSvg.innerHTML='';
    document.querySelectorAll('.type-button').forEach(btn=>{
        btn.classList.remove('active','effective','effectiveness','weakness','immune','mixed','neutral','resist','strength-from-selection');
        btn.setAttribute('aria-pressed','false');
    });

    const info = document.getElementById('info');
    if(!currentSelection.length){
        renderTypeInfoEmptyState();
        return;
    }

    currentSelection.forEach(type=>{
        const btn=document.querySelector(`.type-button[data-type="${type}"]`);
        if(btn){
            btn.classList.add('active');
            btn.setAttribute('aria-pressed','true');
        }
    });

    const offenseEntries = menuTypes
        .map(targetType => {
            const activeMatches = currentSelection
                .map(attackingType => {
                    const rawMultiplier = computeTypeRawMultiplier(attackingType, [targetType]);
                    return normalizeTypeMatchupMultiplier(rawMultiplier, attackingType, [targetType]);
                })
                .filter(multiplier => multiplier > 1);
            if(!activeMatches.length) return null;
            const multiplier = activeMatches.some(value => value >= TYPE_SUPER_EFFECTIVE_MULTIPLIER) || activeMatches.length > 1
                ? TYPE_SUPER_EFFECTIVE_MULTIPLIER
                : TYPE_EFFECTIVE_MULTIPLIER;
            return { type: targetType, multiplier };
        })
        .filter(Boolean);

    const superEffectiveTargets = offenseEntries
        .filter(entry => entry.multiplier >= TYPE_SUPER_EFFECTIVE_MULTIPLIER)
        .sort((left, right) => left.type.localeCompare(right.type));
    const effectiveTargets = offenseEntries
        .filter(entry => entry.multiplier > 1 && entry.multiplier < TYPE_SUPER_EFFECTIVE_MULTIPLIER)
        .sort((left, right) => left.type.localeCompare(right.type));

    const defensiveEntries = menuTypes.map(type => {
        const rawMultiplier = computeTypeRawMultiplier(type, currentSelection);
        const multiplier = normalizeTypeMatchupMultiplier(rawMultiplier, type, currentSelection);
        return { type, rawMultiplier, multiplier };
    });

    const superWeakEntries = defensiveEntries
        .filter(entry => entry.multiplier >= TYPE_SUPER_EFFECTIVE_MULTIPLIER)
        .sort((left, right) => right.multiplier - left.multiplier || left.type.localeCompare(right.type));
    const weakEntries = defensiveEntries
        .filter(entry => entry.multiplier > 1 && entry.multiplier < TYPE_SUPER_EFFECTIVE_MULTIPLIER)
        .sort((left, right) => right.multiplier - left.multiplier || left.type.localeCompare(right.type));
    const resistEntries = defensiveEntries
        .filter(entry => entry.multiplier > 0 && entry.multiplier < 1)
        .sort((left, right) => left.multiplier - right.multiplier || left.type.localeCompare(right.type));
    const immuneEntries = defensiveEntries
        .filter(entry => entry.multiplier === 0)
        .sort((left, right) => left.type.localeCompare(right.type));

    superEffectiveTargets.forEach(entry=>{
        const btn=document.querySelector(`.type-button[data-type="${entry.type}"]`);
        if(btn && !btn.classList.contains('active')) btn.classList.add('effectiveness');
    });
    effectiveTargets.forEach(entry=>{
        const btn=document.querySelector(`.type-button[data-type="${entry.type}"]`);
        if(btn && !btn.classList.contains('active') && !btn.classList.contains('effectiveness')) btn.classList.add('effective');
    });
    // Relacoes defensivas ja foram calculadas antes nesta funcao.

    superWeakEntries.forEach(entry=>{
        const btn = document.querySelector(`.type-button[data-type="${entry.type}"]`);
        if(btn && !btn.classList.contains('active')) btn.classList.add('weakness');
    });
    weakEntries.forEach(entry=>{
        const btn = document.querySelector(`.type-button[data-type="${entry.type}"]`);
        if(btn && !btn.classList.contains('active') && !btn.classList.contains('weakness')) btn.classList.add('weakness');
    });
    resistEntries.forEach(entry=>{ const b=document.querySelector(`.type-button[data-type="${entry.type}"]`); if(b && !b.classList.contains('active')) b.classList.add('resist'); });
    immuneEntries.forEach(entry=>{ const b=document.querySelector(`.type-button[data-type="${entry.type}"]`); if(b && !b.classList.contains('active')) b.classList.add('immune'); });

    // Se um tipo e efetivo (pela selecao) e tambem ameaca/resistencia, marcar como misto
    const offenseTypes = [...new Set([...(superEffectiveTargets||[]).map(e=>e.type), ...(effectiveTargets||[]).map(e=>e.type)])];
    const defenseThreats = defensiveEntries.filter(e=>e.multiplier>1).map(e=>e.type);
    const overlapped = offenseTypes.filter(t=> defenseThreats.includes(t));
    overlapped.forEach(t2=>{
        const b = document.querySelector(`.type-button[data-type="${t2}"]`);
        if(b){
            b.classList.add('mixed');
            b.classList.remove('effectiveness');
            b.classList.remove('effective');
            b.classList.remove('weakness');
            b.classList.remove('resist');
            b.classList.remove('immune');
        }
    });

    document.querySelectorAll('.type-button').forEach(btn=>{
        if(
            !btn.classList.contains('active') &&
            !btn.classList.contains('effective') &&
            !btn.classList.contains('effectiveness') &&
            !btn.classList.contains('weakness') &&
            !btn.classList.contains('resist') &&
            !btn.classList.contains('immune') &&
            !btn.classList.contains('mixed') &&
            !btn.classList.contains('strength-from-selection')
        ) {
            btn.classList.add('neutral');
        } else {
            btn.classList.remove('neutral');
        }
    });

    function makeIcons(entries, tone){
        return entries.map(entry=>{
            const label = getTypeDisplayName(entry.type);
            return `
                <button class="info-type info-type--${tone}" data-type="${entry.type}" aria-label="Selecionar ${label}" title="${label}">
                    <img class="info-icon" src="icons-type/${entry.type}.png" alt="${label}" loading="lazy" decoding="async">
                    <span class="info-type-copy">
                        <span class="info-type-label">${label}</span>
                        <span class="info-type-mult">${formatTypeMultiplierValue(entry.multiplier)}</span>
                    </span>
                </button>
            `;
        }).join('');
    }

    function makeSection(title, subtitle, entries, tone){
        if(!entries.length) return '';
        return `
            <section class="info-section info-section--${tone}">
                <div class="info-section__header">
                    <h4>${title}</h4>
                    <span>${subtitle}</span>
                </div>
                <div class="info-icons">${makeIcons(entries, tone)}</div>
            </section>
        `;
    }

    let html = `<div class="types-info-shell">`;
    html += `
        <div class="types-info__summary">
            <span class="types-info__eyebrow">Análise atual</span>
            <div class="info-type-heading">${currentSelection.map(getTypeDisplayName).join(' + ')}</div>
            <div class="types-selection-pills">
                ${currentSelection.map(type=>`<span class="types-selection-pill"><img src="icons-type/${type}.png" alt="" aria-hidden="true" loading="lazy" decoding="async"><span>${getTypeDisplayName(type)}</span></span>`).join('')}
            </div>
            <div class="types-info__legend" aria-label="Legenda da análise atual">
                <span class="types-info__legend-item types-info__legend-item--super">2x</span>
                <span class="types-info__legend-item types-info__legend-item--effective">1.5x</span>
                <span class="types-info__legend-item types-info__legend-item--resist">Resiste</span>
                <span class="types-info__legend-item types-info__legend-item--vulnerable">Vulnerável</span>
                <span class="types-info__legend-item types-info__legend-item--super-vulnerable">2x defesa</span>
            </div>
        </div>
        <div class="types-info__sections">
    `;
    html += makeSection(t('superEffective'), 'Ataque 2x', superEffectiveTargets, 'super');
    html += makeSection('Efetivo', 'Ataque 1.5x', effectiveTargets, 'effective');
    html += makeSection(t('resistLabel'), 'Defesa 0.75x / 0.5x', resistEntries, 'resist');
    html += makeSection(t('vulnerable'), 'Defesa 1.5x', weakEntries, 'vulnerable');
    html += makeSection('Muito vulnerável', 'Defesa 2x', superWeakEntries, 'super-vulnerable');
    html += makeSection(t('immune'), 'Defesa 0x', immuneEntries, 'immune');
    if(!superEffectiveTargets.length && !effectiveTargets.length && !superWeakEntries.length && !weakEntries.length && !resistEntries.length && !immuneEntries.length){
        html += `<div class="info-empty-msg">${t('noRelation')}</div>`;
    }
    html += `</div></div>`;
    info.innerHTML = html;

    info.querySelectorAll('.info-type').forEach(btn=>{
        btn.style.cursor = 'pointer';
        btn.addEventListener('click', ()=> selectType(btn.dataset.type));
        if(useGsap){
            gsap.fromTo(btn, {scale:0.9, opacity:0}, {scale:1, opacity:1, duration:0.32, ease:'back.out(1.4)'});
        }
    });
}

function selectType(type){
    const idx=currentSelection.indexOf(type);
    if(idx!=-1){currentSelection.splice(idx,1);}else{if(currentSelection.length===2)currentSelection.shift();currentSelection.push(type);}renderSelection();updateUrl();}

function clearAll(options = {}){
    currentSelection = [];
    renderSelection();
    if(options.clearSearch){
        if(searchInput) searchInput.value = '';
        createButtons('');
    }
    updateUrl();
}

function handleKeyNav(e){
    const btns=Array.from(chart.querySelectorAll('.type-button'));
    const idx=btns.indexOf(e.currentTarget);
    if(idx===-1) return;
    switch(e.key){
        case'ArrowRight':if(idx<btns.length-1)btns[idx+1].focus();e.preventDefault();break;
        case'ArrowLeft':if(idx>0)btns[idx-1].focus();e.preventDefault();break;
        case'ArrowDown':if(idx+colCount<btns.length)btns[idx+colCount].focus();e.preventDefault();break;
        case'ArrowUp':if(idx-colCount>=0)btns[idx-colCount].focus();e.preventDefault();break;
        case'Enter':selectType(e.currentTarget.dataset.type);e.preventDefault();break;
    }
}

window.addEventListener('keydown',e=>{if(e.key==='Escape')clearAll();});
window.addEventListener('resize',()=>{updateColumns();if(currentSelection.length)renderSelection();});

