function showPokemons(requestedVariant = POKEMON_CATALOG_VARIANT_DEFAULT, options = {}){
    if(contentPokemons?.dataset.panelFragment && contentPokemons.dataset.panelLoaded !== 'true'){
        setVisiblePanel(contentPokemons);
        ensurePanelFragmentLoaded(contentPokemons)
            .then(() => showPokemons(requestedVariant, options))
            .catch(error => console.error('Pokemon panel load failed', error));
        return;
    }
    if(!pokemonCatalogStatus || !pokemonCatalogStatus.isConnected){
        refreshPokemonCatalogDomReferences();
    }
    const { requestedPage = null, requestedFilters = null } = options || {};
    const normalizedRequestedPage = requestedPage == null
        ? null
        : normalizePokemonCatalogPageNumber(requestedPage, 1);
    const hasRequestedFilters = requestedFilters !== null;
    const normalizedRequestedFilters = hasRequestedFilters
        ? normalizePokemonCatalogFiltersInput(requestedFilters)
        : null;
    initializePokemonCatalogFilters();
    initializePokemonCatalogPagination();
    clearTabHighlights();
    setActiveTabTheme('pokemons');
    setVisiblePanel(contentPokemons);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = t('pokemonsTitle');
    updateBrowserTitle();
    const normalizedVariant = setCurrentPokemonCatalogVariant(POKEMON_CATALOG_VARIANT_DEFAULT);
    const shouldResetFilters = activePokemonCatalogVariant !== normalizedVariant && !hasRequestedFilters;
    if(hasRequestedFilters){
        pendingPokemonCatalogRouteFilters = normalizedRequestedFilters;
        pokemonCatalogFilters = normalizedRequestedFilters;
    } else if(shouldResetFilters){
        pendingPokemonCatalogRouteFilters = null;
        pokemonCatalogFilters = { ...DEFAULT_POKEMON_CATALOG_FILTERS };
    }
    if(normalizedRequestedPage !== null){
        pokemonCatalogCurrentPage = normalizedRequestedPage;
    }
    if(pokemonCatalogLoaded){
        applyPokemonCatalogVariant(normalizedVariant, { resetFilters: shouldResetFilters });
        if(normalizedRequestedPage !== null){
            pokemonCatalogCurrentPage = normalizedRequestedPage;
        }
    }
    if(!pokemonCatalogLoaded){
        showPokemonCatalogLoadingState(normalizedVariant);
    }
    Promise.all([
        ensureTypesDataLoaded(),
        ensurePokemonCatalogLoaded()
    ]).then(() => {
        applyPokemonCatalogVariant(normalizedVariant, { resetFilters: shouldResetFilters });
        if(normalizedRequestedPage !== null){
            pokemonCatalogCurrentPage = normalizedRequestedPage;
        }
        renderPokemonCatalog({ animate: true });
        if(useGsap && contentPokemons){
            gsap.from(contentPokemons, { opacity: 0, y: -10, duration: 0.4 });
        }
    }).catch(error => {
        console.error('Pokemon catalog load failed', error);
    });
    updateUrl();
}

