function showTimes(options = {}){
    if(contentTimes?.dataset.panelFragment && contentTimes.dataset.panelLoaded !== 'true'){
        setVisiblePanel(contentTimes);
        ensurePanelFragmentLoaded(contentTimes)
            .then(() => showTimes(options))
            .catch(error => console.error('Times load failed', error));
        return;
    }
    refreshTimesDomReferences();
    const requestedTeamSlug = String(options?.requestedTeamSlug || getTeamRouteMatch()?.teamSlug || '').trim().toLowerCase();
    const requestedTeamFilters = options?.requestedFilters
        ? normalizeTeamFiltersInput(options.requestedFilters)
        : (isTeamCatalogPathname() ? getTeamFiltersFromUrl() : null);
    if(requestedTeamFilters){
        applyTeamFiltersInput(requestedTeamFilters);
    }
    initializeTimesPage();
    clearTabHighlights();
    setActiveTabTheme('times');
    setVisiblePanel(contentTimes);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = t('timesTitle');
    updateBrowserTitle();

    if(!teamsCatalogLoaded || !pokemonCatalogLoaded || !typesDataLoaded){
        showTimesLoadingState();
    } else {
        renderTeamsCatalog();
    }

    Promise.all([
        ensureTypesDataLoaded(),
        ensureTeamsCatalogLoaded(),
        ensurePokemonCatalogLoaded()
    ])
        .then(() => {
            renderTeamsCatalog({ animate: true });
            if(requestedTeamSlug){
                const opened = openTeamDetailsByRouteSlug(requestedTeamSlug, { pushState: false });
                if(!opened){
                    updateUrl({ historyMode: 'replace' });
                }
            }
            if(useGsap && contentTimes){
                gsap.from(contentTimes, {
                    opacity: 0,
                    y: -10,
                    duration: 0.4,
                    clearProps: 'opacity,transform'
                });
            }
        })
        .catch((error) => {
            console.error('Teams catalog load failed', error);
            teamsCatalogLoaded = false;
            teamsCatalog = [];
            updateTimesStatus(0, 0, teamFilters, { failed: true });
            setTimesEmptyState(
                'Nao foi possivel carregar os times.',
                'Tente novamente em instantes para consultar as composicoes.'
            );
        });

    if(!requestedTeamSlug){
        updateUrl();
    }
}

function initializeTimesPage(){
    if(timesPageInitialized) return;

    timesClanFilterButtons.forEach((button) => {
        button.addEventListener('click', () => {
            setTeamClanFilter(button.dataset.timesClanFilter || 'all');
        });
    });

    if(timesSearchInput){
        timesSearchInput.value = teamFilters.search;
        timesSearchInput.addEventListener('input', () => {
            applyTeamFiltersInput({
                ...teamFilters,
                search: timesSearchInput.value || ''
            });
            scheduleTeamsCatalogRender();
            if(contentTimes && !contentTimes.hidden){
                updateUrl();
            }
        });
    }

    if(timesTagFilterRow){
        timesTagFilterRow.addEventListener('click', (event) => {
            const button = event.target instanceof Element
                ? event.target.closest('[data-times-tag-filter]')
                : null;
            if(!(button instanceof HTMLButtonElement)) return;
            setTeamTagFilter(button.dataset.timesTagFilter || 'all');
        });
    }

    syncTeamClanFilterButtons(teamFilters.clan);
    syncTeamTagFilterButtons(teamFilters.tag);
    timesPageInitialized = true;
}

function normalizeTeamClanKey(value){
    const normalized = String(value || '').trim().toLowerCase();
    if(!normalized || normalized === 'todos') return 'all';
    return normalized;
}

function setTeamClanFilter(clanKey){
    applyTeamFiltersInput({
        ...teamFilters,
        clan: normalizeTeamClanKey(clanKey)
    });
    scheduleTeamsCatalogRender();
    if(contentTimes && !contentTimes.hidden){
        updateUrl();
    }
}

function normalizeTeamTagKey(value){
    const normalized = normalizePokemonSearchText(value).replace(/[\s/]+/g, '-');
    return normalized || 'all';
}

function normalizeTeamSearchFilter(value){
    return String(value || '').trim();
}

function normalizeTeamFiltersInput(filters = DEFAULT_TEAM_FILTERS){
    return {
        clan: normalizeTeamClanKey(filters?.clan),
        tag: normalizeTeamTagKey(filters?.tag),
        search: normalizeTeamSearchFilter(filters?.search)
    };
}

function getTeamFiltersFromUrl(search = location.search){
    try{
        const params = new URLSearchParams(search);
        return normalizeTeamFiltersInput({
            clan: params.get(TEAM_FILTER_QUERY_KEYS.clan) || '',
            tag: params.get(TEAM_FILTER_QUERY_KEYS.tag) || '',
            search: params.get(TEAM_FILTER_QUERY_KEYS.search)
                || params.get('search')
                || params.get('busca')
                || ''
        });
    }catch(error){
        return { ...DEFAULT_TEAM_FILTERS };
    }
}

function syncTeamFilterParams(params, filters = teamFilters){
    if(!(params instanceof URLSearchParams)) return params;

    const normalizedFilters = normalizeTeamFiltersInput(filters);
    if(normalizedFilters.clan && normalizedFilters.clan !== 'all'){
        params.set(TEAM_FILTER_QUERY_KEYS.clan, normalizedFilters.clan);
    } else {
        params.delete(TEAM_FILTER_QUERY_KEYS.clan);
    }

    if(normalizedFilters.tag && normalizedFilters.tag !== 'all'){
        params.set(TEAM_FILTER_QUERY_KEYS.tag, normalizedFilters.tag);
    } else {
        params.delete(TEAM_FILTER_QUERY_KEYS.tag);
    }

    if(normalizedFilters.search){
        params.set(TEAM_FILTER_QUERY_KEYS.search, normalizedFilters.search);
    } else {
        params.delete(TEAM_FILTER_QUERY_KEYS.search);
    }
    params.delete('search');
    params.delete('busca');

    return params;
}

function applyTeamFiltersInput(filters = DEFAULT_TEAM_FILTERS){
    teamFilters = normalizeTeamFiltersInput(filters);
    if(timesSearchInput && timesSearchInput.value !== teamFilters.search){
        timesSearchInput.value = teamFilters.search;
    }
    syncTeamClanFilterButtons(teamFilters.clan);
    syncTeamTagFilterButtons(teamFilters.tag);
    return teamFilters;
}

function collectTeamTagOptions(entries = teamsCatalog){
    const seen = new Set();
    const options = [];

    entries.forEach((entry) => {
        entry.tags.forEach((tagLabel) => {
            const key = normalizeTeamTagKey(tagLabel);
            if(!key || key === 'all' || seen.has(key)) return;
            seen.add(key);
            options.push({
                key,
                label: tagLabel
            });
        });
    });

    return options;
}

function renderTeamTagFilterButtons(entries = teamsCatalog){
    if(!(timesTagFilterRow instanceof HTMLElement)) return;

    const options = collectTeamTagOptions(entries);
    let shouldNormalizeUrl = false;
    if(!options.length){
        shouldNormalizeUrl = normalizeTeamTagKey(teamFilters.tag) !== 'all';
        timesTagFilterRow.hidden = true;
        timesTagFilterRow.replaceChildren();
        teamFilters = {
            ...teamFilters,
            tag: 'all'
        };
        if(shouldNormalizeUrl && contentTimes && !contentTimes.hidden){
            updateUrl({ historyMode: 'replace' });
        }
        return;
    }

    const availableTagKeys = new Set(['all', ...options.map((option) => option.key)]);
    const activeTagKey = normalizeTeamTagKey(teamFilters.tag);
    if(!availableTagKeys.has(activeTagKey)){
        shouldNormalizeUrl = true;
        teamFilters = {
            ...teamFilters,
            tag: 'all'
        };
    }

    const fragment = document.createDocumentFragment();
    const allButton = document.createElement('button');
    allButton.type = 'button';
    allButton.className = 'times-clan-filter-btn times-tag-filter-btn';
    allButton.dataset.timesTagFilter = 'all';
    allButton.textContent = 'Todas';
    fragment.appendChild(allButton);

    options.forEach((option) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'times-clan-filter-btn times-tag-filter-btn';
        button.dataset.timesTagFilter = option.key;
        button.textContent = option.label;
        fragment.appendChild(button);
    });

    timesTagFilterRow.replaceChildren(fragment);
    timesTagFilterRow.hidden = false;
    syncTeamTagFilterButtons(teamFilters.tag);
    if(shouldNormalizeUrl && contentTimes && !contentTimes.hidden){
        updateUrl({ historyMode: 'replace' });
    }
}

function setTeamTagFilter(tagKey){
    applyTeamFiltersInput({
        ...teamFilters,
        tag: normalizeTeamTagKey(tagKey)
    });
    scheduleTeamsCatalogRender();
    if(contentTimes && !contentTimes.hidden){
        updateUrl();
    }
}

function syncTeamClanFilterButtons(activeClan){
    const normalizedActiveClan = normalizeTeamClanKey(activeClan);
    timesClanFilterButtons.forEach((button) => {
        const buttonClan = normalizeTeamClanKey(button.dataset.timesClanFilter || 'all');
        const isActive = buttonClan === normalizedActiveClan;
        button.classList.toggle('is-active', isActive);
        button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
}

function syncTeamTagFilterButtons(activeTag){
    if(!(timesTagFilterRow instanceof HTMLElement)) return;

    const normalizedActiveTag = normalizeTeamTagKey(activeTag);
    timesTagFilterRow.querySelectorAll('[data-times-tag-filter]').forEach((button) => {
        if(!(button instanceof HTMLButtonElement)) return;
        const buttonTag = normalizeTeamTagKey(button.dataset.timesTagFilter || 'all');
        const isActive = buttonTag === normalizedActiveTag;
        button.classList.toggle('is-active', isActive);
        button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
}

function showTimesLoadingState(){
    if(timesStatus){
        timesStatus.textContent = 'Carregando times...';
    }
    if(timesCardGrid){
        timesCardGrid.replaceChildren();
    }
    hideTimesEmptyState();
}

function ensureTeamsCatalogLoaded(force = false){
    if(teamsCatalogLoaded && !force){
        return Promise.resolve(teamsCatalog);
    }

    if(teamsCatalogLoadPromise && !force){
        return teamsCatalogLoadPromise;
    }

    if(force){
        teamsCatalogLoaded = false;
        teamsCatalog = [];
        teamsCatalogLoadPromise = null;
        pokemonHuntPreAceStageByKey = null;
        pokemonHuntAceSourceKeys = null;
        huntBuilderTargetEntriesCache = null;
        teamEntryCompatibleHuntGroupsCache = new WeakMap();
    }

    showTimesLoadingState();
    teamsCatalogLoadPromise = loadTeamsCatalog()
        .then((entries) => {
            teamsCatalog = entries;
            renderTeamTagFilterButtons(teamsCatalog);
            teamsCatalogLoaded = true;
            pokemonHuntPreAceStageByKey = null;
            pokemonHuntAceSourceKeys = null;
            huntBuilderTargetEntriesCache = null;
            teamEntryCompatibleHuntGroupsCache = new WeakMap();
            return teamsCatalog;
        })
        .finally(() => {
            teamsCatalogLoadPromise = null;
        });

    return teamsCatalogLoadPromise;
}

function loadTeamsCatalog(){
    return Promise.all([
        fetch(TIMES_CATALOG_URL, { cache: 'no-store' })
            .then((response) => {
                if(!response.ok){
                    throw new Error(`Falha ao carregar ${TIMES_CATALOG_URL}: ${response.status}`);
                }
                return response.json();
            }),
        loadSharedPokemonGenerationMap()
    ])
        .then(([entries, generationMap]) => {
            if(!Array.isArray(entries)){
                throw new Error('O catalogo de times precisa ser uma lista.');
            }
            pokemonCatalogGenerationMap = generationMap;
            const normalizedEntries = entries
                .map((entry, index) => normalizeTeamEntry(entry, index))
                .filter(Boolean);
            return ensureUniqueTeamRouteSlugs(normalizedEntries);
        });
}

function ensureUniqueTeamRouteSlugs(entries = []){
    const usedSlugs = new Set();
    return entries.map((entry, index) => {
        const baseSlug = createTeamRouteSlug(entry?.routeSlug || entry?.id, `time-${index + 1}`);
        let routeSlug = baseSlug;
        let suffix = 2;
        while(usedSlugs.has(routeSlug)){
            routeSlug = `${baseSlug}-${suffix}`;
            suffix += 1;
        }
        usedSlugs.add(routeSlug);
        if(entry.routeSlug === routeSlug) return entry;
        return {
            ...entry,
            routeSlug,
            searchText: normalizePokemonSearchText(`${entry.searchText || ''} ${routeSlug}`)
        };
    });
}

function normalizeTeamEntry(entry, index){
    if(!entry || typeof entry !== 'object') return null;

    const clanKey = normalizeTeamClanKey(entry.clan);
    const clanInfo = getPokemonTeamInfo(clanKey);
    const rawElementLabel = String(entry.element || entry.className || entry.archetype || '').trim();
    const elementKeys = resolveTeamElementKeys(entry.elements, rawElementLabel);
    const elementLabel = rawElementLabel || elementKeys.map(formatPokemonTypeLabel).join('/') || 'Sem elemento';
    const tags = normalizeTeamTextList(entry.tags || entry.tag || entry.labels);
    const tagKeys = tags.map(normalizeTeamTagKey).filter(Boolean);
    const comment = String(entry.comment || entry.note || entry.description || '').trim();
    const tips = normalizeTeamTextList(entry.tips || entry.advice || entry.strategies);
    const pokemons = Array.isArray(entry.pokemons)
        ? entry.pokemons
            .map((member, memberIndex) => normalizeTeamMember(member, memberIndex))
            .filter(Boolean)
            .slice(0, 6)
        : [];
    const hunts = expandTeamHuntEntityListWithPreEvolutions(normalizeTeamEntityList(entry.hunts));
    const alternatives = entry.alternatives && typeof entry.alternatives === 'object'
        ? entry.alternatives
        : {};
    const alternativePokemons = normalizeTeamEntityList(
        alternatives.pokemons || alternatives.pokemon || entry.alternativePokemons || entry.alternativePokemon
    );
    const alternativeHunts = expandTeamHuntEntityListWithPreEvolutions(normalizeTeamEntityList(
        alternatives.hunts || alternatives.hunt || entry.alternativeHunts || entry.alternativeHunt
    ));
    const id = String(entry.id || `${clanKey || 'team'}-${index + 1}`).trim();
    const routeSlug = createTeamRouteSlug(id, `${clanKey || 'team'}-${index + 1}`);
    const searchTokens = [
        id,
        routeSlug,
        clanKey,
        clanInfo.label,
        elementLabel,
        ...tags,
        ...elementKeys,
        ...elementKeys.flatMap((typeKey) => TEAM_TYPE_SEARCH_ALIASES[typeKey] || [typeKey]),
        comment,
        ...tips,
        ...pokemons.flatMap((member) => [member.name, member.role, member.note]),
        ...hunts.flatMap((entity) => [entity.name, entity.note]),
        ...alternativePokemons.flatMap((entity) => [entity.name, entity.note]),
        ...alternativeHunts.flatMap((entity) => [entity.name, entity.note])
    ];

    return {
        id,
        routeSlug,
        clanKey,
        clanLabel: clanInfo.label,
        elementLabel,
        elementKeys,
        tags,
        tagKeys,
        comment,
        tips,
        pokemons,
        hunts,
        alternativePokemons,
        alternativeHunts,
        searchText: normalizePokemonSearchText(searchTokens.join(' '))
    };
}

function normalizeTeamTextList(values){
    const rawItems = Array.isArray(values)
        ? values
        : values == null
            ? []
            : [values];

    return rawItems
        .map((value) => {
            if(typeof value === 'string'){
                return value.trim();
            }
            if(value && typeof value === 'object'){
                return String(value.text || value.name || value.label || '').trim();
            }
            return '';
        })
        .filter(Boolean);
}

function normalizeTeamEntityList(values){
    const rawItems = Array.isArray(values)
        ? values
        : values == null
            ? []
            : [values];

    return rawItems
        .map((value) => {
            if(typeof value === 'string'){
                const name = value.trim();
                if(!name) return null;
                return {
                    name,
                    note: '',
                    image: buildTeamPokemonImageFileName(name)
                };
            }
            if(value && typeof value === 'object'){
                const name = String(value.name || value.label || value.text || value.pokemon || '').trim();
                if(!name) return null;
                return {
                    name,
                    note: String(value.note || value.comment || value.description || '').trim(),
                    image: String(value.image || buildTeamPokemonImageFileName(name)).trim()
                };
            }
            return null;
        })
        .filter(Boolean);
}

function getTeamHuntPreEvolutionSourceNames(huntName){
    return Array.from(new Set(
        String(huntName || '')
            .split(/[\/,|]+/)
            .map(name => name.trim())
            .filter(Boolean)
    ));
}

function getTeamHuntPreEvolutionEntries(huntName){
    const sourceNames = getTeamHuntPreEvolutionSourceNames(huntName);
    if(!sourceNames.length) return [];

    const graph = ensurePokemonEvolutionGraph();
    const seenKeys = new Set();
    const orderedKeys = [];
    const collectParents = (key) => {
        const node = graph.get(key);
        if(!node) return;
        Array.from(node.parents || []).forEach(parentKey => {
            if(!parentKey || seenKeys.has(parentKey)) return;
            seenKeys.add(parentKey);
            collectParents(parentKey);
            orderedKeys.push(parentKey);
        });
    };

    sourceNames.forEach(sourceName => {
        collectParents(getPokemonCatalogRegistryKey(sourceName));
    });

    return orderedKeys
        .map(key => {
            const catalogEntry = getPokemonEvolutionCatalogEntriesByKey(key)[0] || null;
            if(catalogEntry) return catalogEntry;
            const edge = POKEMON_EVOLUTION_EDGES.find(([parentName, childName]) => (
                getPokemonCatalogRegistryKey(parentName) === key
                || getPokemonCatalogRegistryKey(childName) === key
            ));
            const fallbackName = edge
                ? String(getPokemonCatalogRegistryKey(edge[0]) === key ? edge[0] : edge[1]).trim()
                : '';
            if(!fallbackName) return null;
            return {
                name: fallbackName,
                image: buildTeamPokemonImageFileName(fallbackName)
            };
        })
        .filter(Boolean);
}

function expandTeamHuntEntityListWithPreEvolutions(entities = []){
    const expanded = [];
    const seenKeys = new Set();
    const addEntity = (entity) => {
        const name = String(entity?.name || '').trim();
        const key = normalizePokemonSearchText(name);
        if(!name || !key || seenKeys.has(key)) return;
        seenKeys.add(key);
        expanded.push(entity);
    };

    (Array.isArray(entities) ? entities : []).forEach(entity => {
        addEntity(entity);
        getTeamHuntPreEvolutionEntries(entity?.name || '').forEach(preEvolution => {
            addEntity({
                name: preEvolution.name,
                note: '',
                image: preEvolution.image || buildTeamPokemonImageFileName(preEvolution.name),
                sourceHuntName: entity.name,
                combatHuntName: preEvolution.name
            });
        });
    });

    return expanded;
}

function getTeamHuntCombatName(hunt){
    const combatHuntName = String(hunt?.combatHuntName || '').trim();
    if(combatHuntName) return combatHuntName;
    const name = String(hunt?.name || hunt || '').trim();
    return name;
}

function normalizeTeamMember(member, index){
    if(!member || typeof member !== 'object') return null;

    const name = String(member.name || member.pokemon || '').trim();
    if(!name) return null;

    const role = String(member.role || member.function || `Slot ${index + 1}`).trim();
    const note = String(member.note || '').trim();
    const image = String(member.image || buildTeamPokemonImageFileName(name)).trim();

    return {
        name,
        role,
        note,
        image
    };
}

function resolveTeamElementKeys(elements, elementLabel){
    const rawEntries = Array.isArray(elements) && elements.length
        ? elements
        : String(elementLabel || '')
            .split(/[\/,]+/)
            .map((part) => part.trim())
            .filter(Boolean);

    const seen = new Set();
    return rawEntries
        .map(normalizePokemonTypeKey)
        .filter((value) => {
            if(!value || seen.has(value)) return false;
            seen.add(value);
            return true;
        });
}

function buildTeamPokemonImageFileName(name){
    const slug = String(name || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[♀]/g, 'f')
        .replace(/[♂]/g, 'm')
        .replace(/[’`]/g, "'")
        .toLowerCase()
        .replace(/\s+/g, '')
        .replace(/[.]/g, '')
        .replace(/[^a-z0-9'-]+/g, '')
        .replace(/-{2,}/g, '-')
        .replace(/'+/g, "'")
        .replace(/^[-']+|[-']+$/g, '');
    return slug ? resolvePokemonImageAssetPath(`${slug}.png`) : '';
}

function getTeamPokemonImageSource(member){
    const fileName = String(member?.image || '').trim();
    if(!fileName) return POKEMON_IMAGE_PLACEHOLDER;
    return appendTeamImageVersion(resolvePokemonImageAssetPath(fileName) || POKEMON_IMAGE_PLACEHOLDER);
}

function appendTeamImageVersion(source){
    const rawSource = String(source || '').trim();
    if(!rawSource || rawSource === POKEMON_IMAGE_PLACEHOLDER) return rawSource;
    if(/[?&]v=/.test(rawSource)) return rawSource;
    const separator = rawSource.includes('?') ? '&' : '?';
    return `${rawSource}${separator}v=${TEAM_POKEMON_IMAGE_VERSION}`;
}

function getTeamSearchTerms(value){
    return normalizePokemonSearchText(value)
        .split(/[,\s]+/)
        .filter(Boolean);
}

function hasActiveTeamFilters(filters = teamFilters){
    return normalizeTeamClanKey(filters?.clan) !== 'all'
        || normalizeTeamTagKey(filters?.tag) !== 'all'
        || Boolean(String(filters?.search || '').trim());
}

function getFilteredTeamEntries(filters = teamFilters){
    const normalizedClan = normalizeTeamClanKey(filters?.clan);
    const normalizedTag = normalizeTeamTagKey(filters?.tag);
    const searchTerms = getTeamSearchTerms(filters?.search || '');

    return teamsCatalog.filter((entry) => {
        if(normalizedClan !== 'all' && entry.clanKey !== normalizedClan) return false;
        if(normalizedTag !== 'all' && !entry.tagKeys.includes(normalizedTag)) return false;
        if(!searchTerms.length) return true;
        return searchTerms.every((term) => entry.searchText.includes(term));
    });
}

function findTeamEntryByRouteSlug(routeSlug){
    const normalizedSlug = createTeamRouteSlug(routeSlug);
    if(!normalizedSlug) return null;
    return teamsCatalog.find((entry) => {
        return String(entry?.routeSlug || '').trim().toLowerCase() === normalizedSlug;
    }) || null;
}

function openTeamDetailsByRouteSlug(routeSlug, options = {}){
    const entry = findTeamEntryByRouteSlug(routeSlug);
    if(!entry) return false;
    openTeamDetailsModal(entry, options);
    return true;
}

function scheduleTeamsCatalogRender(){
    if(!teamsCatalogLoaded) return;

    if(teamsCatalogRenderFrame){
        cancelAnimationFrame(teamsCatalogRenderFrame);
    }

    teamsCatalogRenderFrame = requestAnimationFrame(() => {
        teamsCatalogRenderFrame = null;
        renderTeamsCatalog();
    });
}

function updateTimesStatus(totalCount, visibleCount, filters = teamFilters, options = {}){
    if(!timesStatus) return;

    if(options.failed){
        timesStatus.textContent = 'Nao foi possivel carregar os times.';
        return;
    }

    if(!totalCount){
        timesStatus.textContent = 'Nenhum time cadastrado ainda.';
        return;
    }

    if(!hasActiveTeamFilters(filters)){
        timesStatus.textContent = totalCount === 1
            ? '1 time carregado.'
            : `${totalCount} times carregados.`;
        return;
    }

    if(!visibleCount){
        timesStatus.textContent = 'Nenhum time encontrado com os filtros atuais.';
        return;
    }

    timesStatus.textContent = `${visibleCount} de ${totalCount} times exibidos.`;
}

function setTimesEmptyState(title, text){
    if(timesEmptyTitle) timesEmptyTitle.textContent = title;
    if(timesEmptyText) timesEmptyText.textContent = text;
    if(timesEmptyState) timesEmptyState.hidden = false;
}

function hideTimesEmptyState(){
    if(timesEmptyState) timesEmptyState.hidden = true;
}

function renderTeamsCatalog(options = {}){
    const { animate = false } = options;
    if(!timesCardGrid) return;

    const filteredEntries = getFilteredTeamEntries();
    const totalCount = teamsCatalog.length;
    updateTimesStatus(totalCount, filteredEntries.length);
    timesCardGrid.replaceChildren();

    if(!totalCount){
        setTimesEmptyState(
            'Nenhum time cadastrado ainda.',
            'Adicione um novo time para preencher esta pagina.'
        );
        return;
    }

    if(!filteredEntries.length){
        setTimesEmptyState(
            'Nenhum time encontrado.',
            'Tente ajustar o cla ativo ou os termos da busca.'
        );
        return;
    }

    hideTimesEmptyState();

    const fragment = document.createDocumentFragment();
    filteredEntries.forEach((entry) => {
        fragment.appendChild(createTeamCard(entry));
    });
    timesCardGrid.appendChild(fragment);

    if(useGsap && animate && contentTimes && !contentTimes.hidden){
        gsap.from(timesCardGrid.querySelectorAll('.team-card'), {
            opacity: 0,
            y: 12,
            duration: 0.32,
            stagger: 0.04,
            overwrite: true
        });
    }
}

function createTeamCard(entry){
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'team-card';
    if(entry.routeSlug){
        card.dataset.teamRoute = entry.routeSlug;
    }
    card.setAttribute('role', 'listitem');
    card.setAttribute('aria-label', `${entry.clanLabel}. ${entry.elementLabel}. Abrir detalhes do time.`);

    const header = document.createElement('div');
    header.className = 'team-card__header';

    const clanBadge = createPokemonTeamBadge(entry.clanKey);
    const huntsCount = document.createElement('span');
    huntsCount.className = 'team-card__count';
    const compatibleHunts = getTeamEntryCompatibleHunts(entry);
    huntsCount.textContent = `${compatibleHunts.length} hunt${compatibleHunts.length === 1 ? '' : 's'}`;
    header.append(clanBadge, huntsCount);

    const hero = document.createElement('div');
    hero.className = 'team-card__hero';

    const crest = createTeamTypeCrest(entry.elementKeys, entry.elementLabel, { compact: true });
    const titleWrap = document.createElement('div');
    titleWrap.className = 'team-card__title-wrap';

    const eyebrow = document.createElement('span');
    eyebrow.className = 'team-card__eyebrow';
    eyebrow.textContent = entry.clanLabel;

    const title = document.createElement('strong');
    title.className = 'team-card__title';
    title.textContent = entry.elementLabel;

    titleWrap.append(eyebrow, title);
    hero.append(crest, titleWrap);

    const tagsRow = document.createElement('div');
    tagsRow.className = 'team-card__tags';
    entry.tags.forEach((tagLabel) => {
        tagsRow.appendChild(createTeamTagChip(tagLabel));
    });
    if(!tagsRow.childElementCount){
        tagsRow.classList.add('team-card__tags--empty');
        tagsRow.setAttribute('aria-hidden', 'true');
    }

    const roster = document.createElement('div');
    roster.className = 'team-card__roster';
    entry.pokemons.forEach((member, index) => {
        roster.appendChild(createTeamMemberRow(member, index));
    });

    const footer = document.createElement('div');
    footer.className = 'team-card__footer';
    footer.textContent = 'Abrir detalhes';

    card.append(header, hero, tagsRow, roster, footer);
    card.addEventListener('click', () => {
        openTeamDetailsModal(entry, { pushState: true });
    });

    return card;
}

function createTeamTagChip(tagLabel){
    const chip = document.createElement('span');
    chip.className = 'team-tag-chip';
    const dot = document.createElement('span');
    dot.className = 'team-tag-chip__dot';
    dot.setAttribute('aria-hidden', 'true');

    const label = document.createElement('span');
    label.className = 'team-tag-chip__label';
    label.textContent = tagLabel;

    chip.append(dot, label);
    return chip;
}

function createTeamTypeCrest(typeKeys = [], elementLabel = '', options = {}){
    const { compact = false } = options;
    const crest = document.createElement('div');
    crest.className = compact ? 'team-type-crest team-type-crest--compact' : 'team-type-crest';

    const normalizedKeys = Array.isArray(typeKeys) ? typeKeys.filter(Boolean) : [];
    normalizedKeys.slice(0, 3).forEach((typeKey) => {
        const token = document.createElement('span');
        token.className = 'team-type-crest__token';

        const icon = document.createElement('img');
        icon.src = `icons-type/${typeKey}.png`;
        icon.alt = formatPokemonTypeLabel(typeKey);
        icon.loading = 'lazy';
        icon.decoding = 'async';
        setImageFallback(icon, POKEMON_IMAGE_PLACEHOLDER);

        token.appendChild(icon);
        crest.appendChild(token);
    });

    if(!crest.childElementCount){
        const fallback = document.createElement('span');
        fallback.className = 'team-type-crest__fallback';
        fallback.textContent = String(elementLabel || 'TM').slice(0, 2).toUpperCase();
        crest.appendChild(fallback);
    }

    return crest;
}

function createTeamTypeTokenRow(entry){
    const fragment = document.createDocumentFragment();
    if(!entry.elementKeys.length){
        const empty = document.createElement('span');
        empty.className = 'team-empty-copy';
        empty.textContent = 'Sem elemento definido.';
        fragment.appendChild(empty);
        return fragment;
    }

    entry.elementKeys.forEach((typeKey) => {
        fragment.appendChild(createPokemonTypeToken(typeKey));
    });
    return fragment;
}

function getTeamMemberDisplayRoleKey(member, catalogEntry){
    if(isTeamMemberTankRole(member)) return 'all-rounder';
    const roleInfo = getPokemonRoleInfo(catalogEntry?.roleKey || catalogEntry?.role || '');
    if(roleInfo.key && roleInfo.key !== 'unknown') return roleInfo.key;
    return 'attacker';
}

function createTeamMemberRoleIcon(member, catalogEntry){
    const roleInfo = getPokemonRoleInfo(getTeamMemberDisplayRoleKey(member, catalogEntry));
    if(!roleInfo.key || roleInfo.key === 'unknown') return null;

    const badge = document.createElement('span');
    badge.className = 'team-roster-card__role-icon';
    badge.dataset.role = roleInfo.key;
    badge.title = formatPokemonRoleLabel(roleInfo.label || roleInfo.key);
    badge.setAttribute('aria-label', formatPokemonRoleLabel(roleInfo.label || roleInfo.key));

    const icon = document.createElement('img');
    icon.src = getPokemonRoleAssetSource(roleInfo.key);
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    icon.onerror = () => {
        icon.hidden = true;
    };

    badge.appendChild(icon);
    return badge;
}

function createTeamMemberRow(member, index, options = {}){
    const { modal = false, teamEntry = null } = options;
    const row = document.createElement('article');
    row.className = modal ? 'team-roster-card' : 'team-member-row';

    const media = document.createElement('span');
    media.className = modal ? 'team-roster-card__media' : 'team-member-row__media';

    const image = document.createElement('img');
    image.src = getTeamPokemonImageSource(member);
    image.alt = member.name;
    image.loading = 'lazy';
    image.decoding = 'async';
    setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
    media.appendChild(image);

    const content = document.createElement('div');
    content.className = modal ? 'team-roster-card__content' : 'team-member-row__content';

    const name = document.createElement('strong');
    name.className = modal ? 'team-roster-card__name' : 'team-member-row__name';
    name.textContent = member.name;

    const role = document.createElement('span');
    role.className = modal ? 'team-roster-card__role' : 'team-member-row__role';
    role.textContent = member.note ? `${member.role} • ${member.note}` : member.role;

    const catalogEntry = modal ? findTeamBuilderPokemonCatalogEntry(member?.name || '', {
        elementKeys: teamEntry?.elementKeys || [],
        clan: teamEntry?.clanKey || ''
    }) : null;
    const roleIcon = modal ? createTeamMemberRoleIcon(member, catalogEntry) : null;

    const movesetRow = document.createElement('span');
    movesetRow.className = 'team-roster-card__moveset';
    if(modal){
        const movesetTypes = normalizeTeamBuilderTypeList(catalogEntry?.moveset || []);
        if(movesetTypes.length){
            movesetRow.setAttribute('aria-label', `Moveset: ${movesetTypes.map(getTypeDisplayName).join(', ')}`);
            movesetTypes.forEach(typeKey => {
                movesetRow.appendChild(createPokemonTypeToken(typeKey, { compact: true }));
            });
        }
    }

    content.append(name, role);
    if(roleIcon){
        content.appendChild(roleIcon);
    }
    if(movesetRow.childElementCount){
        content.appendChild(movesetRow);
    }
    row.append(media, content);
    return row;
}

function createTeamEntityCard(entity, options = {}){
    const { showNote = false, showHuntMoveset = false } = options;
    const normalizedEntity = typeof entity === 'string'
        ? { name: entity, note: '', image: buildTeamPokemonImageFileName(entity) }
        : entity && typeof entity === 'object'
            ? {
                name: String(entity.name || entity.label || entity.text || entity.pokemon || '').trim(),
                note: String(entity.note || entity.comment || entity.description || '').trim(),
                image: String(entity.image || buildTeamPokemonImageFileName(entity.name || entity.label || entity.text || entity.pokemon || '')).trim(),
                sourceHuntName: String(entity.sourceHuntName || '').trim(),
                combatHuntName: String(entity.combatHuntName || '').trim(),
                huntLabel: String(entity.huntLabel || '').trim(),
                items: Array.isArray(entity.items) ? entity.items : []
            }
            : null;

    if(!normalizedEntity || !normalizedEntity.name){
        return document.createDocumentFragment();
    }

    const card = document.createElement('article');
    card.className = 'team-hunt-card';
    if(normalizedEntity.items.length > 1){
        card.classList.add('team-hunt-card--bundle');
    }
    if(showNote){
        card.classList.add('team-hunt-card--detailed');
    }

    if(showHuntMoveset){
        const levelBadge = createTeamHuntLevelBadge(normalizedEntity);
        if(levelBadge) card.appendChild(levelBadge);
    }

    const media = document.createElement('span');
    media.className = 'team-hunt-card__media';

    const mediaItems = normalizedEntity.items.length ? normalizedEntity.items : [normalizedEntity];
    mediaItems.slice(0, 3).forEach(item => {
        const image = document.createElement('img');
        image.src = getTeamPokemonImageSource(item);
        image.alt = item.name || normalizedEntity.name;
        image.loading = 'lazy';
        image.decoding = 'async';
        setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
        media.appendChild(image);
    });

    const copy = document.createElement('span');
    copy.className = 'team-hunt-card__copy';

    const label = document.createElement('span');
    label.className = 'team-hunt-card__label';
    label.textContent = normalizedEntity.name;
    copy.appendChild(label);

    card.append(media, copy);

    if(showHuntMoveset){
        const huntMeta = getTeamBuilderHuntCombatMeta(getTeamHuntCombatName(
            normalizedEntity.items[0] || normalizedEntity
        ));
        if(Array.isArray(huntMeta.moveset) && huntMeta.moveset.length){
            const movesetRow = document.createElement('span');
            movesetRow.className = 'team-hunt-card__moveset';
            movesetRow.setAttribute('aria-label', `Moveset: ${huntMeta.moveset.map(getTypeDisplayName).join(', ')}`);
            huntMeta.moveset.forEach(typeKey => {
                movesetRow.appendChild(createPokemonTypeToken(typeKey, { compact: true }));
            });
            card.appendChild(movesetRow);
        }
    }

    if(showNote && normalizedEntity.note){
        const note = document.createElement('span');
        note.className = 'team-hunt-card__note';
        note.textContent = normalizedEntity.note;
        card.append(note);
    }

    return card;
}

function createTeamHuntCard(hunt){
    return createTeamEntityCard(hunt);
}

function createTeamTipCard(tipText, index){
    const card = document.createElement('article');
    card.className = 'team-tip-card';

    const label = document.createElement('span');
    label.className = 'team-tip-card__label';
    label.textContent = `Dica ${index + 1}`;

    const text = document.createElement('p');
    text.className = 'team-tip-card__text';
    text.textContent = tipText;

    card.append(label, text);
    return card;
}

function renderTeamEntityCollection(container, values, options = {}){
    if(!(container instanceof HTMLElement)) return;
    container.classList.remove('times-details-hunt-groups');

    const { emptyText = '', showNote = false, showHuntMoveset = false } = options;
    if(!Array.isArray(values) || !values.length){
        if(emptyText){
            const empty = document.createElement('span');
            empty.className = 'team-empty-copy';
            empty.textContent = emptyText;
            container.replaceChildren(empty);
        } else {
            container.replaceChildren();
        }
        return;
    }

    const fragment = document.createDocumentFragment();
    values.forEach((value) => {
        fragment.appendChild(createTeamEntityCard(value, { showNote, showHuntMoveset }));
    });
    container.replaceChildren(fragment);
}

function getTeamHuntCatalogEntries(hunt){
    if(Array.isArray(hunt?.items) && hunt.items.length){
        return hunt.items
            .flatMap(item => getTeamHuntCatalogEntries(item))
            .filter(Boolean);
    }

    const huntName = String(hunt?.name || hunt || '').trim();
    const names = getTeamHuntPreEvolutionSourceNames(huntName);
    return names
        .map(name => {
            const exactEntry = getPokemonCatalogEntryByName(name);
            if(exactEntry) return exactEntry;
            const normalizedName = normalizePokemonSearchText(name);
            if(!normalizedName) return null;
            return [
                ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT),
                ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
            ].find(entry => entry?.searchName && entry.searchName.includes(normalizedName)) || null;
        })
        .filter(Boolean);
}

function getTeamHuntLevelGroupKey(hunt){
    const entries = getTeamHuntCatalogEntries(hunt);
    if(!entries.length) return '';

    let hasLevel300 = false;
    let hasLevel400 = false;
    entries.forEach(entry => {
        const specialTags = getPokemonEntrySpecialTags(entry);
        const numericLevel = getTeamBuilderEntryLevelNumber(entry);
        if(specialTags.includes('ace') || numericLevel === 100){
            hasLevel400 = true;
            return;
        }
        if(specialTags.includes('pre-ace') || (numericLevel !== null && numericLevel < 100)){
            hasLevel300 = true;
        }
    });

    if(hasLevel400) return '400';
    if(hasLevel300) return '300';
    return '';
}

function getTeamHuntLevelBadgeLabel(hunt){
    if(Array.isArray(hunt?.items) && hunt.items.length){
        const itemLabels = hunt.items
            .map(item => getTeamHuntLevelBadgeLabel(item))
            .filter(Boolean);
        if(itemLabels.includes('Lv 300')) return 'Lv 300';
        if(itemLabels.includes('Lv 400')) return 'Lv 400';
    }

    if(String(hunt?.sourceHuntName || '').trim()) return 'Lv 300';

    const combatName = getTeamHuntCombatName(hunt);
    const sourceNames = getTeamHuntPreEvolutionSourceNames(combatName);
    const graph = ensurePokemonEvolutionGraph();
    let hasChildren = false;
    let hasParents = false;
    sourceNames.forEach(name => {
        const node = graph.get(getPokemonCatalogRegistryKey(name));
        if(!node) return;
        if(node.children?.size) hasChildren = true;
        if(node.parents?.size) hasParents = true;
    });
    if(hasChildren) return 'Lv 300';
    if(hasParents) return 'Lv 400';

    const levelKey = getTeamHuntLevelGroupKey(hunt);
    if(levelKey === '300' || levelKey === '400') return `Lv ${levelKey}`;
    return '';
}

function getTeamHuntLevelSortValue(hunt){
    const label = getTeamHuntLevelBadgeLabel(hunt);
    if(label === 'Lv 300') return 300;
    if(label === 'Lv 400') return 400;
    return Number.MAX_SAFE_INTEGER;
}

function compareTeamBuilderHuntRecommendationsByLevel(left, right){
    const leftLevel = getTeamHuntLevelSortValue(left);
    const rightLevel = getTeamHuntLevelSortValue(right);
    if(leftLevel !== rightLevel) return leftLevel - rightLevel;

    const scoreDiff = Number(right?.score || 0) - Number(left?.score || 0);
    if(scoreDiff) return scoreDiff;

    return String(left?.name || '').localeCompare(String(right?.name || ''), 'pt-BR');
}

function createTeamHuntLevelBadge(hunt){
    const label = getTeamHuntLevelBadgeLabel(hunt);
    if(!label) return null;

    const badge = document.createElement('span');
    badge.className = 'team-hunt-card__level-badge';
    badge.textContent = label;
    badge.setAttribute('aria-label', label === 'Lv 300'
        ? 'Primeira ou segunda evolucao: level 300'
        : 'Ultima evolucao: level 400');
    return badge;
}

function getTeamHuntLevelGroups(hunts = []){
    const groups = {
        level300: [],
        level400: [],
        uncategorized: []
    };

    (Array.isArray(hunts) ? hunts : []).forEach(hunt => {
        const levelKey = getTeamHuntLevelGroupKey(hunt);
        if(levelKey === '300'){
            groups.level300.push(hunt);
        } else if(levelKey === '400'){
            groups.level400.push(hunt);
        } else {
            groups.uncategorized.push(hunt);
        }
    });

    return groups;
}

function formatTeamHuntBundleName(items = []){
    const names = (Array.isArray(items) ? items : [])
        .map(item => String(item?.name || item || '').trim())
        .filter(Boolean);
    if(names.length <= 1) return names[0] || '';
    if(names.length === 2) return `${names[0]} e ${names[1]}`;
    return `${names.slice(0, -1).join(', ')} e ${names[names.length - 1]}`;
}

function createTeamHuntDisplayEntity(entity, huntLabel = ''){
    if(!entity || typeof entity !== 'object') return entity;
    return {
        ...entity,
        huntLabel
    };
}

function createTeamHuntBundleDisplayEntity(items = [], sourceHuntName = '', huntLabel = ''){
    const safeItems = (Array.isArray(items) ? items : []).filter(Boolean);
    const name = formatTeamHuntBundleName(safeItems);
    return {
        name,
        note: '',
        image: safeItems[0]?.image || buildTeamPokemonImageFileName(name),
        sourceHuntName,
        huntLabel,
        items: safeItems
    };
}

function compactTeamHuntsForDisplay(hunts = []){
    const sourceGroups = new Map();
    (Array.isArray(hunts) ? hunts : []).forEach(hunt => {
        const name = String(hunt?.name || hunt || '').trim();
        if(!name) return;
        const sourceName = String(hunt?.sourceHuntName || name).trim();
        const key = normalizePokemonSearchText(sourceName || name);
        if(!key) return;
        if(!sourceGroups.has(key)){
            sourceGroups.set(key, {
                sourceName,
                final: null,
                preEvolutions: []
            });
        }
        const group = sourceGroups.get(key);
        const normalizedHunt = typeof hunt === 'string'
            ? { name, note: '', image: buildTeamPokemonImageFileName(name) }
            : hunt;
        if(hunt?.sourceHuntName){
            group.preEvolutions.push(normalizedHunt);
        } else {
            group.final = normalizedHunt;
        }
    });

    const compacted = [];
    sourceGroups.forEach(group => {
        let huntIndex = 1;
        if(group.preEvolutions.length){
            compacted.push(createTeamHuntBundleDisplayEntity(
                group.preEvolutions,
                group.sourceName,
                `Hunt ${huntIndex}`
            ));
            huntIndex += 1;
        }
        if(group.final){
            compacted.push(createTeamHuntDisplayEntity(group.final, `Hunt ${huntIndex}`));
        }
    });
    return compacted;
}

function compactTeamBuilderHuntRecommendations(recommendations = []){
    const sourceGroups = new Map();
    (Array.isArray(recommendations) ? recommendations : []).forEach(recommendation => {
        const name = String(recommendation?.name || '').trim();
        if(!name) return;
        const sourceName = String(recommendation?.sourceHuntName || name).trim();
        const key = normalizePokemonSearchText(sourceName || name);
        if(!key) return;
        if(!sourceGroups.has(key)){
            sourceGroups.set(key, {
                sourceName,
                final: null,
                preEvolutions: []
            });
        }
        const group = sourceGroups.get(key);
        if(recommendation?.sourceHuntName){
            group.preEvolutions.push(recommendation);
        } else {
            group.final = recommendation;
        }
    });

    const displayGroups = [];
    sourceGroups.forEach(group => {
        const cards = [];
        if(group.preEvolutions.length){
            const sourcePreEvolutionEntries = getTeamHuntPreEvolutionEntries(group.sourceName);
            const evolutionOrder = getTeamHuntPreEvolutionEntries(group.sourceName)
                .map(entry => normalizePokemonSearchText(entry?.name))
                .filter(Boolean);
            const recommendedPreEvolutionsByKey = new Map(
                group.preEvolutions.map(entry => [normalizePokemonSearchText(entry?.name), entry])
            );
            const completePreEvolutionItems = sourcePreEvolutionEntries
                .map(preEvolution => {
                    const preEvolutionName = String(preEvolution?.name || '').trim();
                    const key = normalizePokemonSearchText(preEvolutionName);
                    const recommended = recommendedPreEvolutionsByKey.get(key);
                    const fallback = group.preEvolutions[0] || {};
                    return {
                        ...fallback,
                        ...recommended,
                        name: preEvolutionName || String(recommended?.name || fallback?.name || '').trim(),
                        image: String(recommended?.image || preEvolution?.image || buildTeamPokemonImageFileName(preEvolutionName)).trim(),
                        sourceHuntName: group.sourceName,
                        combatHuntName: preEvolutionName || String(recommended?.combatHuntName || fallback?.combatHuntName || fallback?.name || '').trim()
                    };
                })
                .filter(item => item?.name);
            const orderedPreEvolutions = (completePreEvolutionItems.length ? completePreEvolutionItems : group.preEvolutions).sort((left, right) => {
                const leftIndex = evolutionOrder.indexOf(normalizePokemonSearchText(left?.name));
                const rightIndex = evolutionOrder.indexOf(normalizePokemonSearchText(right?.name));
                if(leftIndex !== -1 || rightIndex !== -1){
                    return (leftIndex === -1 ? Number.MAX_SAFE_INTEGER : leftIndex)
                        - (rightIndex === -1 ? Number.MAX_SAFE_INTEGER : rightIndex);
                }
                return left.name.localeCompare(right.name, 'pt-BR');
            });
            const bestPreEvolution = orderedPreEvolutions.reduce((best, current) => (
                !best || Number(current?.score || 0) > Number(best?.score || 0) ? current : best
            ), null);
            const bundle = createTeamHuntBundleDisplayEntity(orderedPreEvolutions, group.sourceName);
            cards.push({
                ...bundle,
                score: Number(bestPreEvolution?.score ?? group.final?.score ?? 0),
                typeKeys: Array.isArray(bestPreEvolution?.typeKeys) ? bestPreEvolution.typeKeys : [],
                note: String(bestPreEvolution?.note || '').trim()
            });
        }
        if(group.final){
            cards.push(group.final);
        }
        if(cards.length){
            displayGroups.push({
                name: String(group.final?.name || group.sourceName || cards[0]?.name || '').trim(),
                score: cards.reduce((score, card) => Math.max(score, Number(card?.score || 0)), 0),
                cards
            });
        }
    });

    const compacted = displayGroups
        .sort((left, right) => Number(right.score || 0) - Number(left.score || 0) || left.name.localeCompare(right.name, 'pt-BR'))
        .flatMap(group => group.cards);
    const deduped = new Map();
    compacted.forEach(card => {
        const key = normalizePokemonSearchText(card?.name || '');
        if(!key) return;
        const existing = deduped.get(key);
        if(!existing || Number(card?.score || 0) > Number(existing?.score || 0)){
            deduped.set(key, card);
        }
    });
    return Array.from(deduped.values()).sort(compareTeamBuilderHuntRecommendationsByLevel);
}

function createTeamHuntGroupSection(label, values, options = {}){
    const section = document.createElement('section');
    section.className = 'times-details-hunt-group';

    const heading = document.createElement('strong');
    heading.className = 'times-details-alt-label times-details-hunt-group__label';
    heading.textContent = label;

    const grid = document.createElement('div');
    grid.className = 'times-details-entity-grid';
    renderTeamEntityCollection(grid, values, options);

    section.append(heading, grid);
    return section;
}

function renderTeamHuntGroups(container, groups, options = {}){
    if(!(container instanceof HTMLElement)) return;

    const normalHunts = Array.isArray(groups?.normal) ? groups.normal : [];
    const shinyHunts = Array.isArray(groups?.shiny) ? groups.shiny : [];
    const allHunts = Array.isArray(groups?.all) ? groups.all : [...normalHunts, ...shinyHunts];
    const { emptyText = 'Nenhuma hunt cadastrada para este time.', showHuntMoveset = true } = options;

    container.classList.add('times-details-hunt-groups');
    if(!allHunts.length){
        const empty = document.createElement('span');
        empty.className = 'team-empty-copy';
        empty.textContent = emptyText;
        container.replaceChildren(empty);
        return;
    }

    const fragment = document.createDocumentFragment();
    const displayHunts = compactTeamHuntsForDisplay(allHunts);
    const levelGroups = getTeamHuntLevelGroups(displayHunts);
    if(levelGroups.level300.length){
        fragment.appendChild(createTeamHuntGroupSection('Hunt level 300', levelGroups.level300, { showHuntMoveset }));
    }
    if(levelGroups.level400.length){
        fragment.appendChild(createTeamHuntGroupSection('Hunt level 400', levelGroups.level400, { showHuntMoveset }));
    }
    if(levelGroups.uncategorized.length){
        fragment.appendChild(createTeamHuntGroupSection('Hunts recomendadas', levelGroups.uncategorized, { showHuntMoveset }));
    }
    container.replaceChildren(fragment);
}

function renderTeamDetailsModal(entry){
    if(!entry) return;

    const compatibleHuntGroups = getTeamEntryCompatibleHuntGroups(entry);
    const compatibleAlternativeHuntGroups = getTeamEntryCompatibleHuntGroups(entry, entry.alternativeHunts);
    const compatibleHunts = compatibleHuntGroups.all;
    const compatibleAlternativeHunts = compatibleAlternativeHuntGroups.all;

    activeTeamEntry = entry;
    if(timesDetailsClan){
        timesDetailsClan.replaceChildren(createPokemonTeamBadge(entry.clanKey));
    }
    if(timesDetailsTitle){
        timesDetailsTitle.textContent = entry.elementLabel;
    }
    if(timesDetailsSubtitle){
        timesDetailsSubtitle.textContent = `${entry.clanLabel} • ${entry.pokemons.length} Pokemons • ${compatibleHunts.length} hunts`;
    }
    if(timesDetailsTypes){
        timesDetailsTypes.replaceChildren(createTeamTypeTokenRow(entry));
    }
    if(timesDetailsCommentPanel && timesDetailsCommentText){
        const hasComment = Boolean(String(entry.comment || '').trim());
        timesDetailsCommentPanel.hidden = !hasComment;
        timesDetailsCommentText.textContent = hasComment ? entry.comment : '';
    }
    if(timesDetailsTipsPanel && timesDetailsTips){
        const hasTips = Array.isArray(entry.tips) && entry.tips.length > 0;
        timesDetailsTipsPanel.hidden = !hasTips;
        if(hasTips){
            const tipsFragment = document.createDocumentFragment();
            entry.tips.forEach((tipText, index) => {
                tipsFragment.appendChild(createTeamTipCard(tipText, index));
            });
            timesDetailsTips.replaceChildren(tipsFragment);
        } else {
            timesDetailsTips.replaceChildren();
        }
    }
    if(timesDetailsRoster){
        const rosterFragment = document.createDocumentFragment();
        entry.pokemons.forEach((member, index) => {
            rosterFragment.appendChild(createTeamMemberRow(member, index, { modal: true, teamEntry: entry }));
        });
        timesDetailsRoster.replaceChildren(rosterFragment);
    }
    if(timesDetailsHunts){
        renderTeamHuntGroups(timesDetailsHunts, compatibleHuntGroups, {
            emptyText: 'Nenhuma hunt cadastrada para este time.',
            showHuntMoveset: true
        });
    }
    if(timesDetailsAlternativesPanel){
        const hasAlternativePokemons = Array.isArray(entry.alternativePokemons) && entry.alternativePokemons.length > 0;
        const hasAlternativeHunts = compatibleAlternativeHunts.length > 0;
        const hasAlternatives = hasAlternativePokemons || hasAlternativeHunts;
        timesDetailsAlternativesPanel.hidden = !hasAlternatives;

        if(timesDetailsAltPokemonsGroup && timesDetailsAltPokemons){
            timesDetailsAltPokemonsGroup.hidden = !hasAlternativePokemons;
            renderTeamEntityCollection(timesDetailsAltPokemons, hasAlternativePokemons ? entry.alternativePokemons : [], {
                showNote: true
            });
        }
        if(timesDetailsAltHuntsGroup && timesDetailsAltHunts){
            timesDetailsAltHuntsGroup.hidden = !hasAlternativeHunts;
            renderTeamHuntGroups(timesDetailsAltHunts, hasAlternativeHunts ? compatibleAlternativeHuntGroups : {}, {
                showHuntMoveset: true
            });
        }
    }
}

function getTeamModalRestoreFallbackUrl(){
    const params = syncTeamFilterParams(new URLSearchParams(), teamFilters);
    const query = params.toString();
    return `/times${query ? `?${query}` : ''}`;
}

function hideTeamDetailsModalUi(){
    if(!timesDetailsModal) return;
    timesDetailsModal.setAttribute('aria-hidden', 'true');
    syncBasicModalPageState();

    if(timesDetailsKeyHandler){
        document.removeEventListener('keydown', timesDetailsKeyHandler);
        timesDetailsKeyHandler = null;
    }

    if(timesDetailsLastFocus instanceof HTMLElement && timesDetailsLastFocus.isConnected){
        try { timesDetailsLastFocus.focus({ preventScroll: true }); } catch(error) {}
    }

    timesDetailsLastFocus = null;
    activeTeamEntry = null;
}

function openTeamDetailsModal(entry, options = {}){
    const { pushState = true } = options || {};
    if(!timesDetailsModal || !entry) return;
    const previousUrl = getCurrentHistoryUrl();

    renderTeamDetailsModal(entry);
    timesDetailsLastFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    timesDetailsModal.setAttribute('aria-hidden', 'false');
    syncBasicModalPageState();

    const closeBtn = timesDetailsModal.querySelector('.modal-close');
    if(closeBtn instanceof HTMLElement){
        try { closeBtn.focus({ preventScroll: true }); } catch(error) {}
    }

    if(timesDetailsKeyHandler){
        document.removeEventListener('keydown', timesDetailsKeyHandler);
    }
    timesDetailsKeyHandler = (event) => {
        if(event.key === 'Escape') closeTeamDetailsModal();
    };
    document.addEventListener('keydown', timesDetailsKeyHandler);

    const detailRoutePath = getTeamDetailRoutePath(entry);
    if(pushState && detailRoutePath){
        try{
            teamModalRestoreUrl = getTeamRouteMatch(location.pathname)
                ? getTeamModalRestoreFallbackUrl()
                : previousUrl;
            const params = syncTeamFilterParams(new URLSearchParams(location.search), teamFilters);
            const query = params.toString();
            const detailUrl = detailRoutePath + (query ? `?${query}` : '');
            history.pushState({ tab: 'times', teamRouteSlug: entry.routeSlug }, '', detailUrl);
            teamModalHistoryPushed = true;
        }catch(error){
            teamModalHistoryPushed = false;
            teamModalRestoreUrl = getTeamModalRestoreFallbackUrl();
        }
    } else {
        teamModalHistoryPushed = false;
        teamModalRestoreUrl = getTeamModalRestoreFallbackUrl();
    }
}

function closeTeamDetailsModal(options = {}){
    const { viaPopstate = false } = options || {};
    if(!timesDetailsModal) return;

    if(viaPopstate){
        hideTeamDetailsModalUi();
        teamModalHistoryPushed = false;
        teamModalRestoreUrl = '';
        return;
    }

    const restoreUrl = teamModalRestoreUrl || getTeamModalRestoreFallbackUrl();
    hideTeamDetailsModalUi();
    teamModalHistoryPushed = false;
    teamModalRestoreUrl = '';
    if(getTeamRouteMatch()){
        try{
            history.replaceState({ tab: 'times' }, '', restoreUrl);
        }catch(error){
            updateUrl({ historyMode: 'replace' });
        }
    }
}

function getTeamBuilderSlotConfig(slotId = teamBuilderActiveSlotId){
    return TEAM_BUILDER_SLOT_CONFIGS.find(slot => slot.id === slotId) || TEAM_BUILDER_SLOT_CONFIGS[0] || null;
}

function isTeamBuilderDpsSlot(slotConfig){
    return Boolean(slotConfig && (slotConfig.kind === 'dps' || slotConfig.kind === 'finisher'));
}

function normalizeTimesPassiveText(value){
    return normalizePokemonSearchText(value)
        .replace(/[^a-z0-9]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

function timesPassiveTextMentionsType(text, typeKey){
    const aliases = TIMES_PASSIVE_TYPE_TEXT_ALIASES[typeKey] || [typeKey];
    const normalizedText = ` ${normalizeTimesPassiveText(text)} `;
    return aliases.some(alias => {
        const normalizedAlias = normalizeTimesPassiveText(alias);
        return normalizedAlias && normalizedText.includes(` ${normalizedAlias} `);
    });
}

function isTimesAllRounderPassiveAllowed(entry, text){
    const normalizedText = normalizeTimesPassiveText(text);
    if(!normalizedText.includes('caso') || !normalizedText.includes('all rounder')) return true;
    return entry?.roleKey === 'all-rounder'
        || normalizePokemonSearchText(entry?.role || '').includes('all rounder');
}

function getTimesDefensivePassiveTextCandidates(entry, source = 'normal'){
    const texts = [];
    const pushText = value => {
        const text = String(value || '').trim();
        if(text && !texts.includes(text)) texts.push(text);
    };

    if(source === 'shiny'){
        pushText(entry?.shinyPassiveDescription || entry?.shinyPassiveName || '');
    } else {
        pushText(entry?.passiveDescription || entry?.passiveText || entry?.passiveName || '');
    }

    getTeamBuilderPassiveInfo(entry).forEach(text => {
        const normalizedText = normalizeTimesPassiveText(text);
        const isShinyText = normalizedText.includes('shiny');
        if(source === 'shiny' ? isShinyText : !isShinyText){
            pushText(text);
        }
    });

    return texts;
}

function getTimesDefensiveTypesFromPassiveText(entry, text){
    if(!isTimesAllRounderPassiveAllowed(entry, text)) return [];

    const defensiveText = String(text || '')
        .replace(/em contrapartida[^.]+/gi, ' ')
        .replace(/mas leva[^.]+/gi, ' ')
        .replace(/mas recebe[^.]+/gi, ' ')
        .replace(/recebe super efetivo[^.]+/gi, ' ')
        .replace(/apenas no pokemon normal/gi, ' ');
    const normalizedText = normalizeTimesPassiveText(defensiveText);

    const hasDefensiveCue = /\b(resistencia|resistente|imune|inefetivo|inafetivo|defesa|dano reduzido|menos dano|reduz o dano|metade do dano|recebe metade)\b/.test(normalizedText);
    const hasTypeContext = /\b(tipo|tipos|ataque|ataques|attack|moves|golpes|dano|danos)\b/.test(normalizedText);
    const hasOffensiveCue = /\b(causa dano|causam dano|ataques deste pokemon|ataques do usuario|dano super efetivo contra|super efetividade contra)\b/.test(normalizedText);
    if(!hasDefensiveCue || !hasTypeContext || hasOffensiveCue) return [];

    return Object.keys(TIMES_PASSIVE_TYPE_TEXT_ALIASES)
        .filter(typeKey => timesPassiveTextMentionsType(normalizedText, typeKey));
}

function getTimesDefensivePassiveTypes(entry, source = 'normal'){
    const store = source === 'shiny'
        ? TIMES_SHINY_EXTRA_DEFENSIVE_PASSIVE_TYPES
        : TIMES_NORMAL_DEFENSIVE_PASSIVE_TYPES;
    const passiveTypes = [];
    const addType = type => {
        const normalizedType = normalizePokemonTypeKey(type);
        if(normalizedType && !passiveTypes.includes(normalizedType)){
            passiveTypes.push(normalizedType);
        }
    };

    getTeamBuilderPassiveLookupKeys(entry).forEach(key => {
        const types = store[key];
        if(Array.isArray(types)){
            types.forEach(addType);
        }
    });
    getTimesDefensivePassiveTextCandidates(entry, source).forEach(text => {
        getTimesDefensiveTypesFromPassiveText(entry, text).forEach(addType);
    });
    return passiveTypes;
}

function getTimesOffensivePassiveTextCandidates(entry, source = 'normal'){
    const texts = [];
    const pushText = value => {
        const text = String(value || '').trim();
        if(text && !texts.includes(text)) texts.push(text);
    };

    if(source === 'shiny'){
        pushText(entry?.shinyPassiveDescription || entry?.shinyPassiveName || '');
    } else {
        pushText(entry?.passiveDescription || entry?.passiveText || entry?.passiveName || '');
    }

    getTeamBuilderPassiveInfo(entry).forEach(text => {
        const normalizedText = normalizeTimesPassiveText(text);
        const isShinyText = normalizedText.includes('shiny');
        if(source === 'shiny' ? isShinyText : !isShinyText){
            pushText(text);
        }
    });

    return texts;
}

function getTimesOffensiveTypesFromPassiveText(entry, text){
    const normalizedText = normalizeTimesPassiveText(text);
    const hasOffensiveCue = /\b(causa|causam|causar|capaz de causar|ataques deste pokemon|ataques do usuario|todos os ataques|todo ataque|super efetividade contra|dano super efetivo contra)\b/.test(normalizedText);
    if(!hasOffensiveCue) return { types: [], all: false };

    const types = Object.keys(TIMES_PASSIVE_TYPE_TEXT_ALIASES)
        .filter(typeKey => timesPassiveTextMentionsType(normalizedText, typeKey));

    if(/\bmesma tipagem que a sua\b/.test(normalizedText)){
        normalizeTeamBuilderTypeList(entry?.naturalElements || []).forEach(type => {
            if(type && !types.includes(type)) types.push(type);
        });
    }

    const all = !types.length && /\b(todos os ataques|todo ataque)\b/.test(normalizedText);
    return { types, all };
}

function getTimesOffensivePassiveMeta(entry, source = 'all'){
    const types = [];
    let all = false;
    const addType = type => {
        const normalizedType = normalizePokemonTypeKey(type);
        if(normalizedType && !types.includes(normalizedType)){
            types.push(normalizedType);
        }
    };

    const sources = source === 'all'
        ? ['normal', 'shiny']
        : [source === 'shiny' ? 'shiny' : 'normal'];

    sources.forEach(passiveSource => {
        const explicitPassiveTypes = passiveSource === 'shiny'
            ? entry?.shinyPassiveSuperEffectiveTypes
            : entry?.passiveSuperEffectiveTypes;
        (Array.isArray(explicitPassiveTypes) ? explicitPassiveTypes : [])
            .forEach(addType);

        getTimesOffensivePassiveTextCandidates(entry, passiveSource).forEach(text => {
            const meta = getTimesOffensiveTypesFromPassiveText(entry, text);
            meta.types.forEach(addType);
            if(meta.all) all = true;
        });
    });

    return { types, all };
}

function getTimesTankDefenseTierAgainstType(entry, attackType){
    const normalizedType = normalizePokemonTypeKey(attackType);
    if(!entry || !normalizedType) return '';

    const naturalTypes = normalizeTeamBuilderTypeList(entry.naturalElements || []);
    if(naturalTypes.length && getPokemonTypeMultiplier(normalizedType, naturalTypes) < 1){
        return 'normal';
    }

    if(getTimesDefensivePassiveTypes(entry, 'normal').includes(normalizedType)){
        return 'normal';
    }

    if(getTimesDefensivePassiveTypes(entry, 'shiny').includes(normalizedType)){
        return 'shiny';
    }

    if(
        teamBuilderEntryReducesSuperEffectiveDamage(entry)
        && naturalTypes.length
        && getPokemonTypeMultiplier(normalizedType, naturalTypes) > 1
    ){
        return 'normal';
    }

    return '';
}

function getTimesTankHuntDefenseTier(tankEntry, huntMeta, fallbackAttackTypes = []){
    const attackTypes = huntMeta?.hasMoveset
        ? huntMeta.moveset
        : normalizeTeamBuilderTypeList(fallbackAttackTypes);
    if(!attackTypes.length) return '';

    let shinyOnly = false;
    for(const type of attackTypes){
        const tier = getTimesTankDefenseTierAgainstType(tankEntry, type);
        if(tier === 'normal') return 'normal';
        if(tier === 'shiny') shinyOnly = true;
    }

    return shinyOnly ? 'shiny' : '';
}

function getTeamEntryHuntCompatibilityInfo(entry, hunt, slotEntries){
    const huntName = String(hunt?.name || hunt || '').trim();
    if(!huntName) return null;

    const effectiveHuntName = getTeamHuntCombatName(hunt);
    const huntMeta = getTeamBuilderHuntCombatMeta(effectiveHuntName);
    const weaknessTypes = getTeamBuilderHuntWeaknessTypes(effectiveHuntName);
    const normalizedWeaknessTypes = normalizeTeamBuilderTypeList(weaknessTypes);
    if(!huntMeta.hasNaturalElements && !normalizedWeaknessTypes.length) return null;

    const tankEntry = slotEntries.find(item => item.slot.kind === 'tank')?.entry || null;
    const tankDefenseTier = getTimesTankHuntDefenseTier(tankEntry, huntMeta, normalizedWeaknessTypes);
    if(!tankEntry || !tankDefenseTier) return null;
    const tankCanDamage = huntMeta.hasNaturalElements
        ? teamBuilderDamageEntryHitsHunt(tankEntry, huntMeta)
        : teamBuilderDamageEntryHitsWeaknessTypes(tankEntry, normalizedWeaknessTypes);
    if(!tankCanDamage) return null;

    const effectiveDamageCount = getTeamBuilderEffectiveDamageCount(slotEntries, huntMeta, normalizedWeaknessTypes);
    if(effectiveDamageCount < 5) return null;

    return {
        hunt,
        huntName,
        tankDefenseTier,
        effectiveDamageCount
    };
}

function getTeamEntryCompatibleHuntGroups(entry, hunts = entry?.hunts){
    const safeHunts = Array.isArray(hunts) ? hunts : [];
    const groups = {
        normal: [],
        shiny: [],
        all: []
    };
    if(!entry || !safeHunts.length) return groups;

    if(hunts === entry?.hunts && teamEntryCompatibleHuntGroupsCache.has(entry)){
        return teamEntryCompatibleHuntGroupsCache.get(entry);
    }

    const slotEntries = getTeamEntrySlotEntries(entry);
    const expectedSlots = Array.isArray(entry.pokemons) ? entry.pokemons.length : 0;
    if((expectedSlots && slotEntries.length < expectedSlots) || !slotEntries.length){
        groups.normal = safeHunts.slice();
        groups.all = safeHunts.slice();
        if(hunts === entry?.hunts){
            teamEntryCompatibleHuntGroupsCache.set(entry, groups);
        }
        return groups;
    }

    safeHunts.forEach(hunt => {
        const compatibility = getTeamEntryHuntCompatibilityInfo(entry, hunt, slotEntries);
        if(!compatibility) return;
        if(compatibility.tankDefenseTier === 'shiny'){
            groups.shiny.push(hunt);
        } else {
            groups.normal.push(hunt);
        }
        groups.all.push(hunt);
    });
    if(hunts === entry?.hunts){
        teamEntryCompatibleHuntGroupsCache.set(entry, groups);
    }
    return groups;
}

function getTeamEntryCompatibleHunts(entry, hunts = entry?.hunts){
    return getTeamEntryCompatibleHuntGroups(entry, hunts).all;
}

function isTeamBuilderTankSlot(slotConfig){
    return Boolean(slotConfig && slotConfig.kind === 'tank');
}

function getTeamBuilderEntryKey(entry){
    if(!entry) return '';
    return `${normalizePokemonCatalogVariant(entry.variant)}:${entry.id || entry.routeSlug || entry.name}`;
}

function getTeamBuilderEntryDuplicateKey(entry){
    const normalizedName = entry?.searchName || normalizePokemonSearchText(entry?.name || '');
    return normalizedName.replace(/^mega\s+/, '').replace(/^shiny\s+/, '').trim();
}

function getTeamBuilderEeveelutionBaseKey(entry){
    const names = [entry?.baseName, entry?.name, entry?.id, entry?.routeSlug]
        .map(value => normalizePokemonSearchText(value).replace(/^shiny\s+/, ''))
        .filter(Boolean);
    return names.find(name => TEAM_BUILDER_EEVEE_EVOLUTION_KEYS.includes(name)) || '';
}

function isTeamBuilderNormalEeveelutionAllowed(entry){
    const baseKey = getTeamBuilderEeveelutionBaseKey(entry);
    return Boolean(baseKey && TEAM_BUILDER_NORMAL_EEVEE_EVOLUTION_KEYS.includes(baseKey));
}

function isTeamBuilderExplicitlyAllowedEntry(entry){
    if(!entry) return false;
    return [entry.searchName, entry.name, entry.routeSlug, entry.id]
        .map(normalizePokemonSearchText)
        .filter(Boolean)
        .some(key => TEAM_BUILDER_EXPLICITLY_ALLOWED_KEYS.includes(key));
}

function isTeamBuilderNormalEeveelutionBlocked(entry){
    if(isTeamBuilderExplicitlyAllowedEntry(entry)) return false;
    const baseKey = getTeamBuilderEeveelutionBaseKey(entry);
    if(!baseKey) return false;
    const isShinyEntry = normalizePokemonSearchText(entry?.name || '').startsWith('shiny ')
        || getPokemonEntrySpecialTags(entry).includes('shiny')
        || entry?.naturalShiny === true;
    return !isShinyEntry && !isTeamBuilderNormalEeveelutionAllowed(entry);
}

function applyTeamBuilderEeveelutionFunctionOverrides(entry){
    const baseKey = getTeamBuilderEeveelutionBaseKey(entry);
    const isShinyEntry = normalizePokemonSearchText(entry?.name || '').startsWith('shiny ')
        || getPokemonEntrySpecialTags(entry).includes('shiny')
        || entry?.naturalShiny === true;
    const subFunctionOverride = isShinyEntry
        ? (TEAM_BUILDER_SHINY_EEVEE_SUB_FUNCTION_OVERRIDES[baseKey] || TEAM_BUILDER_EEVEE_SUB_FUNCTION_OVERRIDES[baseKey])
        : TEAM_BUILDER_EEVEE_SUB_FUNCTION_OVERRIDES[baseKey];
    if(!baseKey || !Array.isArray(subFunctionOverride)) return entry;
    return {
        ...entry,
        subFunctions: normalizePokemonSubFunctions(subFunctionOverride)
    };
}

function createTeamBuilderShinyEeveelutionEntry(entry){
    const baseKey = getTeamBuilderEeveelutionBaseKey(entry);
    if(!baseKey || TEAM_BUILDER_NORMAL_EEVEE_EVOLUTION_KEYS.includes(baseKey)) return null;

    const specialTags = normalizePokemonSpecialTags([
        ...getPokemonEntrySpecialTags(entry),
        'shiny'
    ]);
    const routeSlug = `shiny-${entry.routeSlug || entry.id || baseKey}`;
    return applyTeamBuilderEeveelutionFunctionOverrides({
        ...entry,
        id: routeSlug,
        routeSlug,
        dex: null,
        name: `Shiny ${entry.name}`,
        baseName: entry.name,
        searchName: normalizePokemonSearchText(`Shiny ${entry.name}`),
        naturalShiny: true,
        normalCaptureAvailable: false,
        normalCaptureNote: 'Versao shiny disponivel apenas como variante especial nos builders.',
        shinyCaptureAvailable: false,
        shinyCaptureNote: 'Ja e shiny por natureza.',
        registered: true,
        catalogHidden: false,
        specialTags,
        builderLookupNames: baseKey === 'leafeon' ? ['Shiny Leafeon', 'Leafeon'] : []
    });
}

function isTeamBuilderVirtualShinyEeveelutionEntry(entry){
    return Boolean(
        getTeamBuilderEeveelutionBaseKey(entry)
        && (
            normalizePokemonSearchText(entry?.name || '').startsWith('shiny ')
            || getPokemonEntrySpecialTags(entry).includes('shiny')
        )
    );
}

function getTeamBuilderEntryLevelNumber(entry){
    const numericLevel = Number.parseFloat(String(entry?.level ?? '').trim());
    return Number.isFinite(numericLevel) ? numericLevel : null;
}

function teamBuilderEntryMeetsLevelRequirement(entry){
    const numericLevel = getTeamBuilderEntryLevelNumber(entry);
    return numericLevel === null || numericLevel >= 50;
}

function getTeamBuilderSelectedKeys(exceptSlotId = ''){
    return new Set(
        Object.entries(teamBuilderSelections || {})
            .filter(([slotId]) => slotId !== exceptSlotId)
            .map(([, entry]) => getTeamBuilderEntryKey(entry))
            .filter(Boolean)
    );
}

function getTeamBuilderSelectedDuplicateKeys(exceptSlotId = ''){
    return new Set(
        Object.entries(teamBuilderSelections || {})
            .filter(([slotId]) => slotId !== exceptSlotId)
            .map(([, entry]) => getTeamBuilderEntryDuplicateKey(entry))
            .filter(Boolean)
    );
}

function getTeamBuilderDuplicateSelectionEntry(entry, exceptSlotId = ''){
    const duplicateKey = getTeamBuilderEntryDuplicateKey(entry);
    if(!duplicateKey) return null;
    return Object.entries(teamBuilderSelections || {})
        .filter(([slotId]) => slotId !== exceptSlotId)
        .map(([, selectedEntry]) => selectedEntry)
        .find(selectedEntry => getTeamBuilderEntryDuplicateKey(selectedEntry) === duplicateKey) || null;
}

function isTeamBuilderAceEntry(entry){
    if(!entry) return false;
    const specialTags = getPokemonEntrySpecialTags(entry);
    if(specialTags.includes('ace')) return true;
    if(String(entry.level || '').trim().toLowerCase() === 'ace') return true;
    return isPokemonHuntAceSourceEntry(entry);
}

function getTeamBuilderAceRoleKey(entry){
    if(!isTeamBuilderAceEntry(entry)) return '';
    return normalizePokemonRoleKey(entry?.roleKey || entry?.role || '');
}

function getTeamBuilderAceSameRoleSelectionEntry(entry, exceptSlotId = ''){
    const roleKey = getTeamBuilderAceRoleKey(entry);
    if(!roleKey) return null;
    return Object.entries(teamBuilderSelections || {})
        .filter(([slotId]) => slotId !== exceptSlotId)
        .map(([, selectedEntry]) => selectedEntry)
        .find(selectedEntry => getTeamBuilderAceRoleKey(selectedEntry) === roleKey) || null;
}

function getTeamBuilderSelectedMegaEntry(exceptSlotId = ''){
    const selectedMega = Object.entries(teamBuilderSelections || {})
        .filter(([slotId]) => slotId !== exceptSlotId)
        .map(([, entry]) => entry)
        .find(entry => isMegaPokemonCatalogEntry(entry));
    return selectedMega || null;
}

function isTeamBuilderMegaSelectionBlocked(entry, slotId = teamBuilderActiveSlotId){
    return isMegaPokemonCatalogEntry(entry) && Boolean(getTeamBuilderSelectedMegaEntry(slotId));
}

function isTeamBuilderDuplicateSelectionBlocked(entry, slotId = teamBuilderActiveSlotId){
    const duplicateKey = getTeamBuilderEntryDuplicateKey(entry);
    return Boolean(duplicateKey && getTeamBuilderSelectedDuplicateKeys(slotId).has(duplicateKey));
}

function isTeamBuilderAceSameRoleSelectionBlocked(entry, slotId = teamBuilderActiveSlotId){
    return Boolean(getTeamBuilderAceSameRoleSelectionEntry(entry, slotId));
}

function isTeamBuilderRecommendedBossEntry(entry){
    const specialTags = getPokemonEntrySpecialTags(entry);
    if(!specialTags.includes('boss')) return false;
    const priceLabel = String(entry?.priceLabel || '').trim().toLowerCase();
    return priceLabel === '1x boss item'
        || (specialTags.includes('ranger') && priceLabel === 'ranger boss');
}

function isTeamBuilderNonCaptureAvailabilityExempt(entry){
    if(isMegaPokemonCatalogEntry(entry)) return true;
    const specialTags = getPokemonEntrySpecialTags(entry);
    return ['fossil', 'maniac', 'ranger', 'poke-gift'].some(tag => specialTags.includes(tag));
}

function getTeamBuilderBaseCatalogEntries(){
    const normalEntries = getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT);
    const permittedMegaEntries = getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
        .filter(entry => !TEAM_BUILDER_BLOCKED_MEGA_KEYS.includes(entry.searchName || normalizePokemonSearchText(entry.name)));

    return [...normalEntries, ...permittedMegaEntries].filter(entry => {
        if(!entry) return false;
        const explicitlyAllowed = isTeamBuilderExplicitlyAllowedEntry(entry);
        if(entry.catalogHidden && !explicitlyAllowed) return false;
        if(!explicitlyAllowed && isTeamBuilderNormalEeveelutionBlocked(entry)) return false;
        if(!explicitlyAllowed && !canOpenPokemonCatalogEntry(entry) && !isTeamBuilderRecommendedBossEntry(entry)) return false;
        if(
            !explicitlyAllowed
            && entry.normalCaptureAvailable === false
            && !isTeamBuilderRecommendedBossEntry(entry)
            && !isTeamBuilderNonCaptureAvailabilityExempt(entry)
        ) return false;
        if(!explicitlyAllowed && !hasPokemonVisibleRole({ key: entry.roleKey, label: entry.role })) return false;
        if(entry.roleKey === 'speedster' || entry.roleKey === 'supporter') return false;
        if(!explicitlyAllowed && !teamBuilderEntryMeetsLevelRequirement(entry)) return false;
        return true;
    }).map(applyTeamBuilderEeveelutionFunctionOverrides);
}

function getTeamBuilderCatalogEntries(){
    const baseEntries = getTeamBuilderBaseCatalogEntries();
    const baseKeys = new Set(baseEntries.map(entry => getTeamBuilderEeveelutionBaseKey(entry)).filter(Boolean));
    const shinyEeveelutionEntries = getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT)
        .filter(entry => {
            if(!entry || entry.catalogHidden || !teamBuilderEntryMeetsLevelRequirement(entry)) return false;
            const baseKey = getTeamBuilderEeveelutionBaseKey(entry);
            return Boolean(baseKey && !TEAM_BUILDER_NORMAL_EEVEE_EVOLUTION_KEYS.includes(baseKey) && !baseKeys.has(baseKey));
        })
        .map(createTeamBuilderShinyEeveelutionEntry)
        .filter(Boolean);
    return [...baseEntries, ...shinyEeveelutionEntries];
}

function teamBuilderEntryMatchesSlot(entry, slotConfig = getTeamBuilderSlotConfig()){
    if(!entry || !slotConfig) return false;
    const subFunctionKeys = getPokemonEntrySubFunctions(entry).map(subFunction => subFunction.key);
    if(isTeamBuilderTankSlot(slotConfig)){
        return entry.roleKey === 'defender' || entry.roleKey === 'all-rounder';
    }
    if(
        isTeamBuilderDpsSlot(slotConfig)
        && isTeamBuilderExplicitlyAllowedEntry(entry)
        && (!entry.roleKey || isTeamBuilderDpsRoleKey(entry))
    ) return true;
    if(isTeamBuilderDpsSlot(slotConfig) && entry.roleKey === 'all-rounder') return true;
    if(!isTeamBuilderDpsRoleKey(entry)) return false;
    if(entry.roleKey === 'striker') return true;
    if(isMegaPokemonCatalogEntry(entry)) return true;
    if(isTeamBuilderVirtualShinyEeveelutionEntry(entry)) return true;
    return subFunctionKeys.some(key => TEAM_BUILDER_DPS_SUB_FUNCTIONS.includes(key));
}

function getFilteredTeamBuilderEntries(){
    const slotConfig = getTeamBuilderSlotConfig();
    const normalizedSearch = normalizePokemonSearchText(teamBuilderFilters.search || '');
    const normalizedClan = String(teamBuilderFilters.clan || 'all').trim().toLowerCase();
    const normalizedType = normalizePokemonTypeKey(teamBuilderFilters.type || '');
    const activeSubFunctions = Array.isArray(teamBuilderFilters.subFunctions)
        ? teamBuilderFilters.subFunctions.map(normalizePokemonSubFunctionKey).filter(Boolean)
        : [];
    const activeRoles = Array.isArray(teamBuilderFilters.roles)
        ? teamBuilderFilters.roles.map(normalizePokemonRoleKey).filter(Boolean)
        : [];
    const selectedKeys = getTeamBuilderSelectedKeys(teamBuilderActiveSlotId);
    const selectedDuplicateKeys = getTeamBuilderSelectedDuplicateKeys(teamBuilderActiveSlotId);

    return getTeamBuilderCatalogEntries()
        .filter(entry => {
            if(selectedKeys.has(getTeamBuilderEntryKey(entry))) return false;
            if(selectedDuplicateKeys.has(getTeamBuilderEntryDuplicateKey(entry))) return false;
            if(isTeamBuilderAceSameRoleSelectionBlocked(entry, teamBuilderActiveSlotId)) return false;
            if(isTeamBuilderMegaSelectionBlocked(entry, teamBuilderActiveSlotId)) return false;
            if(!teamBuilderEntryMatchesSlot(entry, slotConfig)) return false;
            if(normalizedSearch && !entry.searchName.includes(normalizedSearch)) return false;
            if(normalizedClan !== 'all' && entry.team !== normalizedClan) return false;
            if(normalizedType && normalizedType !== 'all' && !teamBuilderEntryCoversType(entry, normalizedType)) return false;
            if(isTeamBuilderTankSlot(slotConfig) && activeRoles.length && !activeRoles.includes(entry.roleKey)) return false;
            const isDpsRoleFilterable = ['all-rounder', 'attacker', 'striker'].includes(entry.roleKey)
                || (isTeamBuilderExplicitlyAllowedEntry(entry) && entry.roleKey === 'supporter');
            if(isTeamBuilderDpsSlot(slotConfig) && activeRoles.length && isDpsRoleFilterable && !activeRoles.includes(entry.roleKey)) return false;
            if(isTeamBuilderDpsSlot(slotConfig) && activeSubFunctions.length){
                const entrySubFunctionKeys = getPokemonEntrySubFunctions(entry).map(subFunction => subFunction.key);
                if(!activeSubFunctions.some(key => entrySubFunctionKeys.includes(key))) return false;
            }
            return true;
        })
        .sort((left, right) => {
            const leftRoleIndex = POKEMON_ROLE_ORDER.indexOf(left.roleKey);
            const rightRoleIndex = POKEMON_ROLE_ORDER.indexOf(right.roleKey);
            if(leftRoleIndex !== rightRoleIndex) return leftRoleIndex - rightRoleIndex;
            return left.name.localeCompare(right.name);
        });
}

function getTeamBuilderEntryTypeKeys(entry){
    return [
        ...(Array.isArray(entry?.naturalElements) ? entry.naturalElements : []),
        ...(Array.isArray(entry?.moveset) ? entry.moveset : [])
    ].map(normalizePokemonTypeKey).filter(Boolean);
}

function getTeamBuilderPassiveLookupKeys(entry){
    const names = [entry?.name, entry?.baseName, entry?.id, entry?.routeSlug]
        .map(value => String(value || '').trim())
        .filter(Boolean);
    const keys = new Set();
    names.forEach(name => {
        const normalizedSearch = normalizePokemonSearchText(name);
        const normalizedLoose = name
            .toLowerCase()
            .replace(/['’]/g, '')
            .replace(/[^a-z0-9]+/g, ' ')
            .trim();
        if(normalizedSearch) keys.add(normalizedSearch);
        if(normalizedLoose) keys.add(normalizedLoose);
        if(normalizedSearch.startsWith('shiny ')) keys.add(normalizedSearch.replace(/^shiny\s+/, ''));
        if(normalizedLoose.startsWith('shiny ')) keys.add(normalizedLoose.replace(/^shiny\s+/, ''));
    });
    return Array.from(keys);
}

function addTeamBuilderPassiveInfo(passives, value, options = {}){
    const text = String(value || '').trim();
    if(!text) return;
    const labeledText = options.shiny && !/\(shiny\)\s*$/i.test(text)
        ? `${text} (shiny)`
        : text;
    if(labeledText && !passives.includes(labeledText)) passives.push(labeledText);
}

function formatTeamBuilderCatalogPassiveText(name, description){
    const passiveName = String(name || '').trim();
    const passiveDescription = String(description || '').trim();
    if(passiveName && passiveDescription){
        const normalizedName = normalizeTimesPassiveText(passiveName);
        const normalizedDescription = normalizeTimesPassiveText(passiveDescription);
        if(!normalizedDescription.startsWith(normalizedName)){
            return `${passiveName}: ${passiveDescription}`;
        }
    }
    return passiveDescription || passiveName;
}

function getTeamBuilderPassiveInfo(entry){
    const passives = [];
    getTeamBuilderPassiveLookupKeys(entry).forEach(key => {
        const values = TEAM_BUILDER_PASSIVE_META[key];
        if(Array.isArray(values) && values.length){
            values.forEach(value => {
                addTeamBuilderPassiveInfo(passives, value);
            });
        }
    });
    addTeamBuilderPassiveInfo(
        passives,
        formatTeamBuilderCatalogPassiveText(entry?.passiveName, entry?.passiveDescription)
    );
    addTeamBuilderPassiveInfo(
        passives,
        formatTeamBuilderCatalogPassiveText(entry?.shinyPassiveName, entry?.shinyPassiveDescription),
        { shiny: true }
    );
    return passives;
}

function ensureTeamBuilderPassiveTooltipSurface(){
    if(teamBuilderPassiveTooltipSurface instanceof HTMLElement) return teamBuilderPassiveTooltipSurface;

    const tooltip = document.createElement('div');
    tooltip.id = 'team-builder-passive-tooltip';
    tooltip.className = 'team-builder-passive-tooltip';
    tooltip.setAttribute('role', 'tooltip');
    tooltip.setAttribute('data-open', 'false');
    tooltip.setAttribute('data-placement', 'bottom');
    tooltip.addEventListener('mouseenter', cancelTeamBuilderPassiveTooltipHide);
    tooltip.addEventListener('mouseleave', scheduleTeamBuilderPassiveTooltipHide);
    document.body.appendChild(tooltip);
    teamBuilderPassiveTooltipSurface = tooltip;
    return tooltip;
}

function cancelTeamBuilderPassiveTooltipHide(){
    if(teamBuilderPassiveTooltipHideTimer){
        window.clearTimeout(teamBuilderPassiveTooltipHideTimer);
        teamBuilderPassiveTooltipHideTimer = 0;
    }
}

function scheduleTeamBuilderPassiveTooltipHide(){
    cancelTeamBuilderPassiveTooltipHide();
    teamBuilderPassiveTooltipHideTimer = window.setTimeout(() => {
        teamBuilderPassiveTooltipHideTimer = 0;
        hideTeamBuilderPassiveTooltip();
    }, 120);
}

function positionTeamBuilderPassiveTooltip(){
    const badge = teamBuilderPassiveTooltipActiveBadge;
    const tooltip = teamBuilderPassiveTooltipSurface;
    if(!(badge instanceof HTMLElement) || !(tooltip instanceof HTMLElement)) return;

    const viewportMargin = 12;
    const gap = 8;
    const badgeRect = badge.getBoundingClientRect();
    const tooltipRect = tooltip.getBoundingClientRect();
    const tooltipWidth = Math.min(tooltipRect.width || 0, window.innerWidth - (viewportMargin * 2));
    const tooltipHeight = tooltipRect.height || 0;
    const availableBelow = window.innerHeight - badgeRect.bottom - viewportMargin - gap;
    const availableAbove = badgeRect.top - viewportMargin - gap;
    const placeAbove = availableBelow < tooltipHeight && availableAbove > availableBelow;
    const maxLeft = Math.max(viewportMargin, window.innerWidth - viewportMargin - tooltipWidth);
    const preferredLeft = badgeRect.right - tooltipWidth;
    const left = Math.min(Math.max(preferredLeft, viewportMargin), maxLeft);
    const top = placeAbove
        ? Math.max(viewportMargin, badgeRect.top - tooltipHeight - gap)
        : Math.min(window.innerHeight - viewportMargin - tooltipHeight, badgeRect.bottom + gap);
    const arrowLeft = Math.min(
        Math.max((badgeRect.left + (badgeRect.width / 2)) - left, 16),
        Math.max(16, tooltipWidth - 16)
    );

    tooltip.dataset.placement = placeAbove ? 'top' : 'bottom';
    tooltip.style.left = `${Math.round(left)}px`;
    tooltip.style.top = `${Math.round(top)}px`;
    tooltip.style.setProperty('--team-builder-passive-tooltip-arrow-left', `${Math.round(arrowLeft)}px`);
}

function hideTeamBuilderPassiveTooltip(){
    cancelTeamBuilderPassiveTooltipHide();
    const tooltip = teamBuilderPassiveTooltipSurface;
    if(tooltip instanceof HTMLElement){
        tooltip.setAttribute('data-open', 'false');
    }
    if(teamBuilderPassiveTooltipActiveBadge instanceof HTMLElement){
        teamBuilderPassiveTooltipActiveBadge.removeAttribute('aria-describedby');
        teamBuilderPassiveTooltipActiveBadge.setAttribute('aria-expanded', 'false');
    }
    teamBuilderPassiveTooltipActiveBadge = null;
}

function showTeamBuilderPassiveTooltip(badge){
    if(!(badge instanceof HTMLElement)) return;
    cancelTeamBuilderPassiveTooltipHide();
    const passives = Array.isArray(badge._teamBuilderPassives)
        ? badge._teamBuilderPassives
        : [];
    if(!passives.length) return;

    const tooltip = ensureTeamBuilderPassiveTooltipSurface();
    const title = document.createElement('strong');
    title.textContent = 'Passiva';
    const list = document.createElement('span');
    list.className = 'team-builder-passive-tooltip__list';
    passives.forEach(passive => {
        const item = document.createElement('span');
        item.textContent = passive;
        list.appendChild(item);
    });

    tooltip.replaceChildren(title, list);
    tooltip.setAttribute('data-open', 'true');
    badge.setAttribute('aria-describedby', tooltip.id);
    badge.setAttribute('aria-expanded', 'true');
    teamBuilderPassiveTooltipActiveBadge = badge;
    positionTeamBuilderPassiveTooltip();
    requestAnimationFrame(positionTeamBuilderPassiveTooltip);
}

function bindTeamBuilderPassiveTooltipListeners(){
    if(teamBuilderPassiveTooltipListenersBound) return;

    window.addEventListener('scroll', () => {
        if(teamBuilderPassiveTooltipActiveBadge) positionTeamBuilderPassiveTooltip();
    }, true);
    window.addEventListener('resize', () => {
        if(teamBuilderPassiveTooltipActiveBadge) positionTeamBuilderPassiveTooltip();
    });
    document.addEventListener('keydown', event => {
        if(event.key === 'Escape') hideTeamBuilderPassiveTooltip();
    });
    document.addEventListener('pointerdown', event => {
        const target = event.target;
        if(
            teamBuilderPassiveTooltipActiveBadge
            && !teamBuilderPassiveTooltipActiveBadge.contains(target)
            && !(teamBuilderPassiveTooltipSurface instanceof HTMLElement && teamBuilderPassiveTooltipSurface.contains(target))
        ){
            hideTeamBuilderPassiveTooltip();
        }
    });

    teamBuilderPassiveTooltipListenersBound = true;
}

function createTeamBuilderPassiveBadge(entry){
    const passives = getTeamBuilderPassiveInfo(entry);
    if(!passives.length) return null;
    const badge = document.createElement('span');
    badge.className = 'team-builder-passive-badge';
    badge.tabIndex = 0;
    badge.setAttribute('aria-label', 'Pokemon com passiva registrada');
    badge.setAttribute('aria-expanded', 'false');
    badge._teamBuilderPassives = passives;

    const marker = document.createElement('span');
    marker.className = 'team-builder-passive-badge__mark';
    marker.textContent = '!';

    badge.addEventListener('mouseenter', () => showTeamBuilderPassiveTooltip(badge));
    badge.addEventListener('mouseleave', scheduleTeamBuilderPassiveTooltipHide);
    badge.addEventListener('focus', () => showTeamBuilderPassiveTooltip(badge));
    badge.addEventListener('blur', () => hideTeamBuilderPassiveTooltip());
    badge.addEventListener('click', event => {
        event.stopPropagation();
        if(teamBuilderPassiveTooltipActiveBadge === badge){
            hideTeamBuilderPassiveTooltip();
        } else {
            showTeamBuilderPassiveTooltip(badge);
        }
    });
    bindTeamBuilderPassiveTooltipListeners();

    badge.append(marker);
    return badge;
}

