function hideTeamBuilderHuntsTooltip(){
    const tooltip = teamBuilderHuntsTooltipSurface;
    if(tooltip instanceof HTMLElement){
        tooltip.setAttribute('data-open', 'false');
    }
    if(teamBuilderHuntsTooltipActiveBadge instanceof HTMLElement){
        teamBuilderHuntsTooltipActiveBadge.removeAttribute('aria-describedby');
        teamBuilderHuntsTooltipActiveBadge.setAttribute('aria-expanded', 'false');
    }
    teamBuilderHuntsTooltipActiveBadge = null;
}

function getTeamBuilderEntryHuntMatches(entry, slotConfig = getTeamBuilderSlotConfig()){
    if(!entry) return [];
    const resolvedSlot = slotConfig || getTeamBuilderSlotConfig();
    const isTankSlot = resolvedSlot?.kind === 'tank';
    const isDamageSlot = resolvedSlot?.kind === 'dps' || resolvedSlot?.kind === 'finisher';
    const matches = [];
    getTeamBuilderKnownHuntCandidates().forEach(candidate => {
        const huntName = String(candidate?.name || '').trim();
        if(!huntName) return;
        const effectiveHuntName = getTeamHuntCombatName(candidate);
        const huntMeta = getTeamBuilderHuntCombatMeta(effectiveHuntName);
        const weaknessTypeKeys = getTeamBuilderHuntWeaknessTypes(effectiveHuntName);
        const canHold = isTankSlot
            && isTeamBuilderTankEntry(entry)
            && teamBuilderTankCanHoldAndDamageHunt(entry, huntMeta, weaknessTypeKeys);
        const canDamage = isDamageSlot
            && teamBuilderEntryMatchesSlot(entry, resolvedSlot)
            && teamBuilderDamageEntryHitsAnyHuntWeakness(entry, huntMeta, weaknessTypeKeys);
        if(!canHold && !canDamage) return;
        matches.push({
            name: huntName,
            note: String(candidate.note || '').trim(),
            image: String(candidate.image || '').trim(),
            sourceHuntName: String(candidate.sourceHuntName || '').trim(),
            combatHuntName: String(candidate.combatHuntName || '').trim(),
            typeKeys: weaknessTypeKeys,
            roleLabel: canHold && canDamage ? 'Tank/Dano' : (canHold ? 'Tank' : 'Dano')
        });
    });

    return compactTeamBuilderHuntRecommendations(matches)
        .sort((left, right) => left.name.localeCompare(right.name));
}

function getTeamBuilderTooltipCombatNames(match){
    const items = Array.isArray(match?.items) && match.items.length
        ? match.items
        : [match];
    return Array.from(new Set(items
        .map(item => String(item?.combatHuntName || item?.name || '').trim())
        .filter(Boolean)
    ));
}

function getTeamBuilderTooltipHuntCombatTypes(match, key){
    const values = [];
    getTeamBuilderTooltipCombatNames(match).forEach(name => {
        const meta = getTeamBuilderHuntCombatMeta(name);
        const typeKeys = key === 'moveset' ? meta.moveset : meta.naturalElements;
        normalizeTeamBuilderTypeList(typeKeys).forEach(typeKey => {
            if(!values.includes(typeKey)) values.push(typeKey);
        });
    });
    return values;
}

function createTeamBuilderHuntsTooltipTypeList(typeKeys, className, label){
    const list = document.createElement('span');
    list.className = className;
    list.setAttribute('aria-label', label);
    normalizeTeamBuilderTypeList(typeKeys).forEach(typeKey => {
        list.appendChild(createPokemonTypeToken(typeKey, { compact: true }));
    });
    return list;
}

function renderTeamBuilderHuntsTooltipContent(tooltip, entry, slotConfig = getTeamBuilderSlotConfig()){
    const title = document.createElement('strong');
    title.textContent = `Hunts para ${entry?.name || 'Pokemon'}`;

    if(!teamsCatalogLoaded){
        const status = document.createElement('span');
        status.className = 'team-builder-hunts-tooltip__status';
        status.textContent = 'Carregando hunts...';
        tooltip.replaceChildren(title, status);
        return;
    }

    const matches = getTeamBuilderEntryHuntMatches(entry, slotConfig);
    if(!matches.length){
        const status = document.createElement('span');
        status.className = 'team-builder-hunts-tooltip__status';
        status.textContent = 'Nenhuma hunt compativel encontrada.';
        tooltip.replaceChildren(title, status);
        return;
    }

    const list = document.createElement('span');
    list.className = 'team-builder-hunts-tooltip__list';
    matches.forEach(match => {
        const item = document.createElement('span');
        item.className = 'team-builder-hunts-tooltip__item';
        const media = createTeamBuilderHuntMedia(match);
        media.classList.add('team-builder-hunts-tooltip__media');
        const copy = document.createElement('span');
        copy.className = 'team-builder-hunts-tooltip__copy';
        const top = document.createElement('span');
        top.className = 'team-builder-hunts-tooltip__top';
        const movesetKeys = getTeamBuilderTooltipHuntCombatTypes(match, 'moveset');
        if(movesetKeys.length){
            top.appendChild(createTeamBuilderHuntsTooltipTypeList(
                movesetKeys,
                'team-builder-hunts-tooltip__moveset',
                `Moveset: ${movesetKeys.map(formatPokemonTypeLabel).join(', ')}`
            ));
        }
        const name = document.createElement('span');
        name.className = 'team-builder-hunts-tooltip__name';
        name.textContent = match.name;
        top.appendChild(name);
        const naturalTypeKeys = getTeamBuilderTooltipHuntCombatTypes(match, 'naturalElements');
        if(naturalTypeKeys.length){
            top.appendChild(createTeamBuilderHuntsTooltipTypeList(
                naturalTypeKeys,
                'team-builder-hunts-tooltip__types',
                `Tipo: ${naturalTypeKeys.map(formatPokemonTypeLabel).join(', ')}`
            ));
        }
        const weaknessRow = document.createElement('span');
        weaknessRow.className = 'team-builder-hunts-tooltip__weaknesses';
        const typeKeys = getTeamBuilderHuntDisplayTypeKeys(match);
        if(typeKeys.length){
            const weaknessLabel = document.createElement('small');
            weaknessLabel.textContent = 'Fraquezas';
            weaknessRow.appendChild(weaknessLabel);
            weaknessRow.appendChild(createTeamBuilderHuntsTooltipTypeList(
                typeKeys,
                'team-builder-hunts-tooltip__weakness-list',
                `Fraquezas: ${typeKeys.map(formatPokemonTypeLabel).join(', ')}`
            ));
        } else {
            const compatible = document.createElement('small');
            compatible.textContent = 'Compatível';
            weaknessRow.appendChild(compatible);
        }
        copy.append(top, weaknessRow);
        item.append(media, copy);
        list.appendChild(item);
    });
    tooltip.replaceChildren(title, list);
}

function showTeamBuilderHuntsTooltip(badge){
    if(!(badge instanceof HTMLElement)) return;
    const entry = badge._teamBuilderEntry || null;
    const slotConfig = badge._teamBuilderSlotConfig || getTeamBuilderSlotConfig();
    if(!entry) return;

    hideTeamBuilderPassiveTooltip();
    const tooltip = ensureTeamBuilderHuntsTooltipSurface();
    renderTeamBuilderHuntsTooltipContent(tooltip, entry, slotConfig);
    tooltip.setAttribute('data-open', 'true');
    badge.setAttribute('aria-describedby', tooltip.id);
    badge.setAttribute('aria-expanded', 'true');
    teamBuilderHuntsTooltipActiveBadge = badge;
    positionTeamBuilderHuntsTooltip();
    requestAnimationFrame(positionTeamBuilderHuntsTooltip);

    if(!teamsCatalogLoaded){
        ensureTeamsCatalogLoaded()
            .then(() => {
                if(teamBuilderHuntsTooltipActiveBadge === badge){
                    renderTeamBuilderHuntsTooltipContent(tooltip, entry, slotConfig);
                    positionTeamBuilderHuntsTooltip();
                    requestAnimationFrame(positionTeamBuilderHuntsTooltip);
                }
            })
            .catch(error => {
                console.error('Team Builder hunt tooltip load failed', error);
                if(teamBuilderHuntsTooltipActiveBadge === badge){
                    const title = document.createElement('strong');
                    title.textContent = `Hunts para ${entry.name}`;
                    const status = document.createElement('span');
                    status.className = 'team-builder-hunts-tooltip__status';
                    status.textContent = 'Nao foi possivel carregar as hunts.';
                    tooltip.replaceChildren(title, status);
                    positionTeamBuilderHuntsTooltip();
                }
            });
    }
}

function bindTeamBuilderHuntsTooltipListeners(){
    if(teamBuilderHuntsTooltipListenersBound) return;

    window.addEventListener('scroll', () => {
        if(teamBuilderHuntsTooltipActiveBadge) positionTeamBuilderHuntsTooltip();
    }, true);
    window.addEventListener('resize', () => {
        if(teamBuilderHuntsTooltipActiveBadge) positionTeamBuilderHuntsTooltip();
    });
    document.addEventListener('keydown', event => {
        if(event.key === 'Escape') hideTeamBuilderHuntsTooltip();
    });
    document.addEventListener('pointerdown', event => {
        const target = event.target;
        if(
            teamBuilderHuntsTooltipActiveBadge
            && !teamBuilderHuntsTooltipActiveBadge.contains(target)
            && !(teamBuilderHuntsTooltipSurface instanceof HTMLElement && teamBuilderHuntsTooltipSurface.contains(target))
        ){
            hideTeamBuilderHuntsTooltip();
        }
    });

    teamBuilderHuntsTooltipListenersBound = true;
}

function createTeamBuilderHuntsBadge(entry, slotConfig = getTeamBuilderSlotConfig()){
    if(!entry) return null;
    const badge = document.createElement('span');
    badge.className = 'team-builder-hunts-badge';
    badge.tabIndex = 0;
    badge.setAttribute('role', 'button');
    badge.setAttribute('aria-label', `Ver hunts que ${entry.name} consegue cacar`);
    badge.setAttribute('aria-expanded', 'false');
    badge._teamBuilderEntry = entry;
    badge._teamBuilderSlotConfig = slotConfig || getTeamBuilderSlotConfig();

    const marker = document.createElement('img');
    marker.className = 'team-builder-hunts-badge__mark';
    marker.src = 'hunt-builder/hunt_symbol.png?v=20260627a';
    marker.alt = '';
    marker.loading = 'lazy';
    marker.decoding = 'async';
    setImageFallback(marker, POKEMON_IMAGE_PLACEHOLDER);

    const toggle = event => {
        event.preventDefault();
        event.stopPropagation();
        if(teamBuilderHuntsTooltipActiveBadge === badge){
            hideTeamBuilderHuntsTooltip();
        } else {
            showTeamBuilderHuntsTooltip(badge);
        }
    };
    badge.addEventListener('click', toggle);
    badge.addEventListener('keydown', event => {
        if(event.key === 'Enter' || event.key === ' '){
            toggle(event);
        }
    });
    bindTeamBuilderHuntsTooltipListeners();

    badge.append(marker);
    return badge;
}

function createTeamBuilderRoleIcon(entry){
    const roleInfo = getPokemonRoleInfo(entry?.roleKey || entry?.role);
    const badge = document.createElement('span');
    badge.className = 'team-builder-role-icon';
    badge.dataset.role = roleInfo.key || 'unknown';
    badge.title = formatPokemonRoleLabel(roleInfo.label || roleInfo.key);
    badge.setAttribute('aria-label', formatPokemonRoleLabel(roleInfo.label || roleInfo.key));

    const icon = document.createElement('img');
    icon.src = getPokemonRoleAssetSource(roleInfo.key);
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    icon.onerror = () => {
        icon.hidden = true;
    };

    badge.appendChild(icon);
    return badge;
}

function createTeamBuilderTypeSummaryRow(label, typeKeys = []){
    const normalizedTypes = Array.from(new Set(
        (Array.isArray(typeKeys) ? typeKeys : [])
            .map(normalizePokemonTypeKey)
            .filter(Boolean)
    ));
    if(!normalizedTypes.length) return null;

    const row = document.createElement('span');
    row.className = 'team-builder-type-row';

    const rowLabel = document.createElement('span');
    rowLabel.className = 'team-builder-type-row__label';
    rowLabel.textContent = label;

    const list = document.createElement('span');
    list.className = 'team-builder-type-row__list';
    normalizedTypes.forEach(typeKey => {
        list.appendChild(createPokemonTypeToken(typeKey, { compact: true }));
    });

    row.append(rowLabel, list);
    return row;
}

function createTeamBuilderTypeSummary(entry){
    const summary = document.createElement('span');
    summary.className = 'team-builder-type-summary';

    const movesetTypes = createTeamBuilderTypeSummaryRow('Moveset', entry?.moveset || []);
    if(movesetTypes) summary.appendChild(movesetTypes);
    const naturalTypes = createTeamBuilderTypeSummaryRow('Tipo', entry?.naturalElements || []);
    if(naturalTypes) summary.appendChild(naturalTypes);

    return summary.childElementCount ? summary : null;
}

function getTeamBuilderEntryMovesetKeys(entry){
    return (Array.isArray(entry?.moveset) ? entry.moveset : [])
        .map(normalizePokemonTypeKey)
        .filter(Boolean);
}

function teamBuilderEntryCoversType(entry, typeKey){
    const normalizedType = normalizePokemonTypeKey(typeKey);
    if(!entry || !normalizedType) return false;
    return getTeamBuilderEntryMovesetKeys(entry).includes(normalizedType);
}

function isTeamBuilderTankEntry(entry){
    return entry?.roleKey === 'defender' || entry?.roleKey === 'all-rounder';
}

function isTeamBuilderDpsRoleKey(entry){
    return entry?.roleKey === 'attacker'
        || entry?.roleKey === 'striker';
}

function createTeamBuilderRoleFunctionToken(entry){
    const token = document.createElement('span');
    token.className = 'pokemon-sub-function-token team-builder-role-function-token';
    token.textContent = formatPokemonRoleLabel(entry?.roleKey || entry?.role);
    return token;
}

function createTeamBuilderPokemonCard(entry){
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'team-builder-result-card';
    card.dataset.slotKind = getTeamBuilderSlotConfig()?.kind || 'dps';
    card.setAttribute('role', 'listitem');
    card.setAttribute('aria-label', `Selecionar ${entry.name}`);

    const media = document.createElement('span');
    media.className = 'team-builder-result-card__media';
    const imageFrame = document.createElement('span');
    imageFrame.className = 'team-builder-result-card__image-frame';
    const image = document.createElement('img');
    image.src = getPokemonImageSource(entry);
    image.alt = '';
    image.loading = 'lazy';
    image.decoding = 'async';
    setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
    imageFrame.appendChild(image);
    media.appendChild(imageFrame);

    const entrySubFunctions = getPokemonEntrySubFunctions(entry);
    if(isTeamBuilderTankEntry(entry)){
        const roleFunctionRow = createPokemonSubFunctionTokenRow([]);
        roleFunctionRow.classList.add('team-builder-result-card__sub-functions');
        roleFunctionRow.appendChild(createTeamBuilderRoleFunctionToken(entry));
        media.appendChild(roleFunctionRow);
    } else if(entrySubFunctions.length){
        const mediaSubFunctions = createPokemonSubFunctionTokenRow(entrySubFunctions);
        mediaSubFunctions.classList.add('team-builder-result-card__sub-functions');
        media.appendChild(mediaSubFunctions);
    }

    const body = document.createElement('span');
    body.className = 'team-builder-result-card__body';
    const name = document.createElement('strong');
    name.textContent = entry.name;
    const clanIcon = createPokemonTeamBadge(entry.team);
    clanIcon.classList.add('team-builder-clan-icon');
    clanIcon.title = entry.teamLabel || getPokemonTeamInfo(entry.team).label;
    clanIcon.setAttribute('aria-label', entry.teamLabel || getPokemonTeamInfo(entry.team).label);
    const roleIcon = createTeamBuilderRoleIcon(entry);
    const huntsBadge = createTeamBuilderHuntsBadge(entry, getTeamBuilderSlotConfig());
    const passiveBadge = createTeamBuilderPassiveBadge(entry);
    body.appendChild(name);
    const typeSummary = createTeamBuilderTypeSummary(entry);
    if(typeSummary) body.appendChild(typeSummary);

    card.append(media, body);
    card.appendChild(clanIcon);
    if(huntsBadge) card.appendChild(huntsBadge);
    card.appendChild(roleIcon);
    if(passiveBadge) card.appendChild(passiveBadge);
    card.addEventListener('click', () => {
        if(isTeamBuilderDuplicateSelectionBlocked(entry, teamBuilderActiveSlotId)){
            if(teamBuilderStatus){
                const selectedDuplicate = getTeamBuilderDuplicateSelectionEntry(entry, teamBuilderActiveSlotId);
                teamBuilderStatus.textContent = selectedDuplicate
                    ? `Seu time ja possui ${selectedDuplicate.name}, entao ${entry.name} nao pode entrar no mesmo time.`
                    : `${entry.name} ja possui uma variante equivalente no time.`;
            }
            return;
        }
        if(isTeamBuilderMegaSelectionBlocked(entry, teamBuilderActiveSlotId)){
            if(teamBuilderStatus){
                const selectedMega = getTeamBuilderSelectedMegaEntry(teamBuilderActiveSlotId);
                teamBuilderStatus.textContent = selectedMega
                    ? `Seu time ja possui um Mega selecionado: ${selectedMega.name}.`
                    : 'Seu time ja possui um Mega selecionado.';
            }
            return;
        }
        if(isTeamBuilderAceSameRoleSelectionBlocked(entry, teamBuilderActiveSlotId)){
            if(teamBuilderStatus){
                const selectedAceRole = getTeamBuilderAceSameRoleSelectionEntry(entry, teamBuilderActiveSlotId);
                teamBuilderStatus.textContent = selectedAceRole
                    ? `Seu time ja possui Ace ${formatPokemonRoleLabel(entry.roleKey || entry.role)}: ${selectedAceRole.name}.`
                    : `Seu time ja possui um Ace ${formatPokemonRoleLabel(entry.roleKey || entry.role)}.`;
            }
            return;
        }
        teamBuilderSelections = {
            ...teamBuilderSelections,
            [teamBuilderActiveSlotId]: entry
        };
        if(getTeamBuilderSlotConfig(teamBuilderActiveSlotId)?.kind === 'tank'){
            teamBuilderIgnoreTankForHunts = false;
        }
        teamBuilderFilters = {
            ...teamBuilderFilters,
            search: ''
        };
        if(teamBuilderSearchInput){
            teamBuilderSearchInput.value = '';
        }
        teamBuilderHuntsVisible = false;
        const nextEmptySlot = TEAM_BUILDER_SLOT_CONFIGS.find(slot => !teamBuilderSelections[slot.id]);
        if(nextEmptySlot){
            teamBuilderActiveSlotId = nextEmptySlot.id;
        }
        renderTeamBuilder();
    });
    return card;
}

function getTeamBuilderResultGroupKey(entry, slotConfig = getTeamBuilderSlotConfig()){
    if(slotConfig?.kind === 'tank' && isTeamBuilderTankEntry(entry)) return 'defender-ar';
    return entry?.roleKey || 'unknown';
}

function getTeamBuilderResultGroupLabel(roleKey){
    if(roleKey === 'defender-ar') return 'Defender/AR';
    return formatPokemonRoleLabel(roleKey);
}

function createTeamBuilderResultGroup(roleKey, entries = []){
    const group = document.createElement('section');
    group.className = 'team-builder-result-group';
    group.dataset.role = roleKey || 'unknown';

    const title = document.createElement('h4');
    title.className = 'team-builder-result-group__title';
    title.textContent = getTeamBuilderResultGroupLabel(roleKey);

    const grid = document.createElement('div');
    grid.className = 'team-builder-result-grid';
    entries.forEach(entry => grid.appendChild(createTeamBuilderPokemonCard(entry)));

    group.append(title, grid);
    return group;
}

function handleTeamBuilderSlotDrop(targetSlotId){
    const sourceSlotId = teamBuilderDragSlotId;
    teamBuilderDragSlotId = '';
    if(!sourceSlotId || sourceSlotId === targetSlotId) return;
    const sourceEntry = teamBuilderSelections[sourceSlotId];
    const targetEntry = teamBuilderSelections[targetSlotId];
    if(!sourceEntry) return;
    const sourceSlot = getTeamBuilderSlotConfig(sourceSlotId);
    const targetSlot = getTeamBuilderSlotConfig(targetSlotId);
    if(!teamBuilderEntryMatchesSlot(sourceEntry, targetSlot)){
        return;
    }
    if(targetEntry && !teamBuilderEntryMatchesSlot(targetEntry, sourceSlot)){
        return;
    }

    const nextSelections = { ...teamBuilderSelections, [targetSlotId]: sourceEntry };
    if(targetEntry){
        nextSelections[sourceSlotId] = targetEntry;
    } else {
        delete nextSelections[sourceSlotId];
    }
    teamBuilderSelections = nextSelections;
    teamBuilderActiveSlotId = targetSlotId;
    teamBuilderHuntsVisible = false;
    renderTeamBuilder();
}

function renderTeamBuilderSlots(){
    if(!teamBuilderSlots) return;
    const fragment = document.createDocumentFragment();
    TEAM_BUILDER_SLOT_CONFIGS.forEach((slotConfig, index) => {
        const selectedEntry = teamBuilderSelections[slotConfig.id] || null;
        const slot = document.createElement('article');
        slot.className = 'team-builder-slot';
        slot.dataset.slotKind = slotConfig.kind;
        slot.dataset.filled = selectedEntry ? 'true' : 'false';
        slot.dataset.slotId = slotConfig.id;
        if(slotConfig.id === teamBuilderActiveSlotId){
            slot.classList.add('is-active');
        }
        slot.setAttribute('role', 'listitem');
        if(selectedEntry){
            slot.draggable = true;
            slot.addEventListener('dragstart', (event) => {
                teamBuilderDragSlotId = slotConfig.id;
                event.dataTransfer.effectAllowed = 'move';
                event.dataTransfer.setData('text/plain', slotConfig.id);
                slot.classList.add('is-dragging');
            });
            slot.addEventListener('dragend', () => {
                teamBuilderDragSlotId = '';
                slot.classList.remove('is-dragging');
            });
        }
        slot.addEventListener('dragover', (event) => {
            if(teamBuilderDragSlotId && teamBuilderDragSlotId !== slotConfig.id){
                event.preventDefault();
                event.dataTransfer.dropEffect = 'move';
            }
        });
        slot.addEventListener('drop', (event) => {
            event.preventDefault();
            handleTeamBuilderSlotDrop(slotConfig.id);
        });

        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'team-builder-slot__select';
        button.setAttribute('aria-pressed', slotConfig.id === teamBuilderActiveSlotId ? 'true' : 'false');
        button.setAttribute('aria-label', selectedEntry ? `Editar ${slotConfig.label}: ${selectedEntry.name}` : `Preencher ${slotConfig.label}`);

        const indexEl = document.createElement('span');
        indexEl.className = 'team-builder-slot__index';
        indexEl.textContent = String(index + 1).padStart(2, '0');

        const copy = document.createElement('span');
        copy.className = 'team-builder-slot__copy';
        const label = document.createElement('strong');
        label.textContent = slotConfig.label;
        copy.appendChild(label);
        if(slotConfig.requirement){
            const requirement = document.createElement('span');
            requirement.textContent = slotConfig.requirement;
            copy.appendChild(requirement);
        }

        button.append(indexEl, copy);

        if(selectedEntry){
            const preview = document.createElement('span');
            preview.className = 'team-builder-slot__preview';
            const image = document.createElement('img');
            image.src = getPokemonImageSource(selectedEntry);
            image.alt = '';
            image.loading = 'lazy';
            image.decoding = 'async';
            setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
            const name = document.createElement('strong');
            name.textContent = selectedEntry.name;
            const typeSummary = createTeamBuilderTypeSummary(selectedEntry);
            const roleIcon = createTeamBuilderRoleIcon(selectedEntry);
            const passiveBadge = createTeamBuilderPassiveBadge(selectedEntry);
            preview.append(image, name);
            if(typeSummary) preview.appendChild(typeSummary);
            button.appendChild(preview);
            slot.appendChild(roleIcon);
            if(passiveBadge) slot.appendChild(passiveBadge);
        }

        button.addEventListener('click', () => {
            teamBuilderActiveSlotId = slotConfig.id;
            renderTeamBuilder();
        });
        slot.appendChild(button);

        if(selectedEntry){
            if(slotConfig.kind === 'tank'){
                const ignoreTankButton = document.createElement('button');
                ignoreTankButton.type = 'button';
                ignoreTankButton.className = 'team-builder-slot__tank-toggle';
                ignoreTankButton.classList.toggle('is-active', teamBuilderIgnoreTankForHunts);
                ignoreTankButton.setAttribute('aria-pressed', teamBuilderIgnoreTankForHunts ? 'true' : 'false');
                ignoreTankButton.setAttribute(
                    'aria-label',
                    teamBuilderIgnoreTankForHunts
                        ? 'Voltar a exigir que o AR ou Defender consiga tankar as hunts'
                        : 'Ignorar se o AR ou Defender consegue tankar as hunts'
                );
                ignoreTankButton.title = teamBuilderIgnoreTankForHunts
                    ? 'As hunts voltarao a considerar a resistencia do AR/Defender.'
                    : 'As hunts serao avaliadas somente pelas condicoes dos DPS e do Finisher.';
                ignoreTankButton.textContent = '🛡️';
                ignoreTankButton.addEventListener('dragstart', event => event.preventDefault());
                ignoreTankButton.addEventListener('click', () => {
                    teamBuilderIgnoreTankForHunts = !teamBuilderIgnoreTankForHunts;
                    renderTeamBuilder();
                });
                slot.appendChild(ignoreTankButton);
            }

            const clearButton = document.createElement('button');
            clearButton.type = 'button';
            clearButton.className = 'team-builder-slot__clear';
            clearButton.textContent = 'X';
            clearButton.title = 'Limpar';
            clearButton.setAttribute('aria-label', `Limpar ${slotConfig.label}`);
            clearButton.addEventListener('click', () => {
                const nextSelections = { ...teamBuilderSelections };
                delete nextSelections[slotConfig.id];
                teamBuilderSelections = nextSelections;
                if(slotConfig.kind === 'tank'){
                    teamBuilderIgnoreTankForHunts = false;
                }
                teamBuilderActiveSlotId = slotConfig.id;
                teamBuilderHuntsVisible = false;
                renderTeamBuilder();
            });
            slot.appendChild(clearButton);
        }

        fragment.appendChild(slot);
    });
    teamBuilderSlots.replaceChildren(fragment);
}

function isTeamBuilderComplete(){
    return TEAM_BUILDER_SLOT_CONFIGS.every(slot => Boolean(teamBuilderSelections[slot.id]));
}

function renderTeamBuilderResults(){
    if(!teamBuilderResults || !teamBuilderStatus) return;
    const slotConfig = getTeamBuilderSlotConfig();
    const entries = getFilteredTeamBuilderEntries();
    const totalAvailable = getTeamBuilderCatalogEntries().filter(entry => teamBuilderEntryMatchesSlot(entry, slotConfig)).length;
    const normalizedSearch = normalizePokemonSearchText(teamBuilderFilters.search || '');
    const renderLimit = normalizedSearch ? TEAM_BUILDER_RENDER_LIMIT_SEARCH : TEAM_BUILDER_RENDER_LIMIT_DEFAULT;
    const visibleEntries = entries.slice(0, renderLimit);

    teamBuilderStatus.textContent = entries.length
        ? `${entries.length} opcoes para ${slotConfig.label}.`
        : `Nenhuma opcao encontrada para ${slotConfig.label}.`;
    if(entries.length > visibleEntries.length){
        teamBuilderStatus.textContent += ` Mostrando ${visibleEntries.length}; refine a busca para ver os demais.`;
    }

    if(!entries.length){
        teamBuilderResults.replaceChildren(createInlineStatusMessage('team-builder-empty-message', 'Ajuste os filtros ou escolha outro slot.'));
        return;
    }

    const fragment = document.createDocumentFragment();
    const groups = new Map();
    visibleEntries.forEach(entry => {
        const groupKey = getTeamBuilderResultGroupKey(entry, slotConfig);
        if(!groups.has(groupKey)) groups.set(groupKey, []);
        groups.get(groupKey).push(entry);
    });
    const groupOrder = slotConfig.kind === 'tank'
        ? ['defender-ar']
        : [...POKEMON_ROLE_ORDER, 'unknown'];
    groupOrder.forEach(roleKey => {
        const groupEntries = groups.get(roleKey) || [];
        if(groupEntries.length){
            fragment.appendChild(createTeamBuilderResultGroup(roleKey, groupEntries));
        }
    });
    if(totalAvailable !== entries.length){
        teamBuilderStatus.textContent += ` ${totalAvailable - entries.length} oculto(s) por filtros ou ja selecionados.`;
    }
    teamBuilderResults.replaceChildren(fragment);
}

function setTeamBuilderFilterButtonState(container, activeValue, attributeName){
    if(!(container instanceof HTMLElement)) return;
    container.querySelectorAll('button').forEach(button => {
        const value = button.dataset[attributeName] || 'all';
        const isActive = value === activeValue;
        button.classList.toggle('is-active', isActive);
        button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
}

function renderTeamBuilderClanFilters(){
    if(!(teamBuilderClanFilterRow instanceof HTMLElement) || teamBuilderClanFilterRow.childElementCount) return;
    const options = [
        { value: 'all', label: 'Todos', image: '' },
        ...Object.entries(TEAM_ASSETS).map(([value, info]) => ({ value, label: info.label, image: info.image }))
    ];
    options.forEach(option => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'team-builder-filter-button';
        button.dataset.teamBuilderClan = option.value;
        button.setAttribute('aria-pressed', option.value === teamBuilderFilters.clan ? 'true' : 'false');
        if(option.image){
            const icon = document.createElement('img');
            icon.src = option.image;
            icon.alt = '';
            icon.loading = 'lazy';
            icon.decoding = 'async';
            button.appendChild(icon);
        }
        const label = document.createElement('span');
        label.textContent = option.label;
        button.appendChild(label);
        button.addEventListener('click', () => {
            teamBuilderFilters = {
                ...teamBuilderFilters,
                clan: option.value,
                subFunctions: [],
                roles: []
            };
            renderTeamBuilder();
        });
        teamBuilderClanFilterRow.appendChild(button);
    });
}

function getTeamBuilderFunctionFilterMode(slotConfig = getTeamBuilderSlotConfig()){
    if(isTeamBuilderTankSlot(slotConfig)) return 'role';
    if(isTeamBuilderDpsSlot(slotConfig)) return 'subFunction';
    return '';
}

function createTeamBuilderFunctionFilterButton({ value, label, mode, image = '' }){
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'team-builder-filter-button';
    button.setAttribute('aria-pressed', 'false');
    if(mode === 'role'){
        button.dataset.teamBuilderRole = value;
    } else {
        button.dataset.teamBuilderSubFunction = value;
    }

    if(image){
        const icon = document.createElement('img');
        icon.src = image;
        icon.alt = '';
        icon.loading = 'lazy';
        icon.decoding = 'async';
        button.appendChild(icon);
    } else {
        const dot = document.createElement('span');
        dot.className = 'team-builder-filter-button__dot';
        dot.dataset.subFunction = value;
        button.appendChild(dot);
    }

    const text = document.createElement('span');
    text.textContent = label;
    button.appendChild(text);
    return button;
}

function renderTeamBuilderSubFunctionFilters(){
    if(!(teamBuilderSubFunctionFilterRow instanceof HTMLElement)) return;
    const mode = getTeamBuilderFunctionFilterMode();
    if(teamBuilderSubFunctionFilterRow.dataset.filterMode === mode && teamBuilderSubFunctionFilterRow.childElementCount) return;

    teamBuilderSubFunctionFilterRow.dataset.filterMode = mode;
    teamBuilderSubFunctionFilterRow.replaceChildren();
    if(!mode) return;

    if(mode === 'role'){
        TEAM_BUILDER_TANK_ROLE_FILTERS.forEach(value => {
            const label = formatPokemonRoleLabel(value);
            const button = createTeamBuilderFunctionFilterButton({
                value,
                label,
                mode,
                image: getPokemonRoleAssetSource(value)
            });
            button.addEventListener('click', () => {
                const current = new Set(Array.isArray(teamBuilderFilters.roles) ? teamBuilderFilters.roles : []);
                if(current.has(value)){
                    current.delete(value);
                } else {
                    current.add(value);
                }
                teamBuilderFilters = { ...teamBuilderFilters, roles: Array.from(current) };
                renderTeamBuilder();
            });
            teamBuilderSubFunctionFilterRow.appendChild(button);
        });
        return;
    }

    TEAM_BUILDER_DPS_SUB_FUNCTIONS.forEach(value => {
        const meta = POKEMON_SUB_FUNCTION_META[value] || { key: value, label: value };
        const button = createTeamBuilderFunctionFilterButton({
            value,
            label: meta.label,
            mode,
            image: ''
        });
        button.addEventListener('click', () => {
            const current = new Set(Array.isArray(teamBuilderFilters.subFunctions) ? teamBuilderFilters.subFunctions : []);
            if(current.has(value)){
                current.delete(value);
            } else {
                current.add(value);
            }
            teamBuilderFilters = { ...teamBuilderFilters, subFunctions: Array.from(current) };
            renderTeamBuilder();
        });
        teamBuilderSubFunctionFilterRow.appendChild(button);
    });
    const allRounderButton = createTeamBuilderFunctionFilterButton({
        value: 'all-rounder',
        label: formatPokemonRoleLabel('all-rounder'),
        mode: 'role',
        image: getPokemonRoleAssetSource('all-rounder')
    });
    allRounderButton.addEventListener('click', () => {
        const current = new Set(Array.isArray(teamBuilderFilters.roles) ? teamBuilderFilters.roles : []);
        if(current.has('all-rounder')){
            current.delete('all-rounder');
        } else {
            current.add('all-rounder');
        }
        teamBuilderFilters = { ...teamBuilderFilters, roles: Array.from(current) };
        renderTeamBuilder();
    });
    teamBuilderSubFunctionFilterRow.appendChild(allRounderButton);
}

function renderTeamBuilderTypeFilters(){
    if(!(teamBuilderTypeFilterRow instanceof HTMLElement) || teamBuilderTypeFilterRow.childElementCount) return;
    const options = [{ value: 'all', label: 'Todos' }, ...(menuTypes || []).map(type => ({ value: type, label: getTypeDisplayName(type) }))];
    options.forEach(option => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'team-builder-filter-button team-builder-filter-button--type';
        button.dataset.teamBuilderType = option.value;
        button.setAttribute('aria-pressed', option.value === teamBuilderFilters.type ? 'true' : 'false');
        if(option.value !== 'all'){
            const icon = document.createElement('img');
            icon.src = `icons-type/${option.value}.png`;
            icon.alt = '';
            icon.loading = 'lazy';
            icon.decoding = 'async';
            button.appendChild(icon);
        }
        const label = document.createElement('span');
        label.textContent = option.label;
        button.appendChild(label);
        button.addEventListener('click', () => {
            teamBuilderFilters = {
                ...teamBuilderFilters,
                type: option.value,
                subFunctions: [],
                roles: []
            };
            renderTeamBuilder();
        });
        teamBuilderTypeFilterRow.appendChild(button);
    });
}

function renderTeamBuilderFilterControls(){
    const activeSlot = getTeamBuilderSlotConfig();
    const functionFilterMode = getTeamBuilderFunctionFilterMode(activeSlot);
    if(teamBuilderSubFunctionFilterField instanceof HTMLElement){
        teamBuilderSubFunctionFilterField.hidden = !functionFilterMode;
        const label = teamBuilderSubFunctionFilterField.querySelector(':scope > span');
        if(label){
            label.textContent = functionFilterMode === 'role' ? 'Função' : 'Sub-função';
        }
    }
    if(functionFilterMode !== 'subFunction' && Array.isArray(teamBuilderFilters.subFunctions) && teamBuilderFilters.subFunctions.length){
        teamBuilderFilters = { ...teamBuilderFilters, subFunctions: [] };
    }
    if(functionFilterMode === 'subFunction' && Array.isArray(teamBuilderFilters.roles) && teamBuilderFilters.roles.length){
        const dpsRoles = teamBuilderFilters.roles.filter(role => normalizePokemonRoleKey(role) === 'all-rounder');
        if(dpsRoles.length !== teamBuilderFilters.roles.length){
            teamBuilderFilters = { ...teamBuilderFilters, roles: dpsRoles };
        }
    } else if(functionFilterMode !== 'role' && Array.isArray(teamBuilderFilters.roles) && teamBuilderFilters.roles.length){
        teamBuilderFilters = { ...teamBuilderFilters, roles: [] };
    }
    setTeamBuilderFilterButtonState(teamBuilderClanFilterRow, teamBuilderFilters.clan || 'all', 'teamBuilderClan');
    setTeamBuilderFilterButtonState(teamBuilderTypeFilterRow, teamBuilderFilters.type || 'all', 'teamBuilderType');
    if(teamBuilderSubFunctionFilterRow instanceof HTMLElement){
        renderTeamBuilderSubFunctionFilters();
        const activeSubFunctions = new Set(Array.isArray(teamBuilderFilters.subFunctions) ? teamBuilderFilters.subFunctions : []);
        const activeRoles = new Set(Array.isArray(teamBuilderFilters.roles) ? teamBuilderFilters.roles : []);
        teamBuilderSubFunctionFilterRow.querySelectorAll('button').forEach(button => {
            const subFunctionValue = button.dataset.teamBuilderSubFunction || '';
            const roleValue = button.dataset.teamBuilderRole || '';
            const isActive = roleValue
                ? activeRoles.has(roleValue)
                : activeSubFunctions.has(subFunctionValue);
            button.classList.toggle('is-active', isActive);
            button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
        });
    }
}

function getTeamBuilderSelectedEntries(){
    return TEAM_BUILDER_SLOT_CONFIGS
        .map(slot => teamBuilderSelections[slot.id])
        .filter(Boolean);
}

function getTeamBuilderSelectedSlotEntries(){
    return TEAM_BUILDER_SLOT_CONFIGS
        .map(slot => ({
            slot,
            entry: teamBuilderSelections[slot.id] || null
        }))
        .filter(item => item.entry);
}

function getPreferredTeamBuilderCatalogEntry(candidates = [], options = {}){
    const entries = (Array.isArray(candidates) ? candidates : [])
        .filter(Boolean);
    if(!entries.length) return null;

    const preferredMovesets = normalizeTeamBuilderTypeList(
        options.preferredMovesets || options.elementKeys || []
    );
    if(preferredMovesets.length){
        const movesetMatch = entries.find(entry => {
            const movesetKeys = getTeamBuilderEntryMovesetKeys(entry);
            return preferredMovesets.some(typeKey => movesetKeys.includes(typeKey));
        });
        if(movesetMatch) return movesetMatch;
    }

    const preferredTeam = normalizeTeamClanKey(options.team || options.clan || '');
    if(preferredTeam){
        const teamMatch = entries.find(entry => String(entry?.team || '').trim().toLowerCase() === preferredTeam);
        if(teamMatch) return teamMatch;
    }

    return entries[0] || null;
}

function findTeamBuilderPokemonCatalogEntry(name, options = {}){
    const normalizedName = normalizePokemonSearchText(name);
    if(!normalizedName) return null;
    const entries = getTeamBuilderCatalogEntries();
    const exactMatches = entries.filter(entry => normalizePokemonSearchText(entry.name) === normalizedName);
    if(exactMatches.length) return getPreferredTeamBuilderCatalogEntry(exactMatches, options);

    const exactAliasMatches = entries.filter(entry => Array.isArray(entry.builderLookupNames)
        && entry.builderLookupNames.some(alias => normalizePokemonSearchText(alias) === normalizedName));
    if(exactAliasMatches.length) return getPreferredTeamBuilderCatalogEntry(exactAliasMatches, options);

    const partialMatches = entries.filter(entry => entry.searchName && entry.searchName.includes(normalizedName));
    if(partialMatches.length) return getPreferredTeamBuilderCatalogEntry(partialMatches, options);

    const partialAliasMatches = entries.filter(entry => Array.isArray(entry.builderLookupNames)
        && entry.builderLookupNames.some(alias => normalizePokemonSearchText(alias).includes(normalizedName)));
    return getPreferredTeamBuilderCatalogEntry(partialAliasMatches, options)
        || null;
}

function getTeamBuilderEntryRawNumericShareId(entry){
    if(!entry) return '';
    if(isMegaPokemonCatalogEntry(entry)){
        const baseKey = getPokemonMegaBaseRegistryKey(entry);
        const baseEntry = baseKey ? getPokemonEvolutionCatalogEntriesByKey(baseKey)[0] || null : null;
        const baseDex = Number(baseEntry?.dex);
        if(Number.isFinite(baseDex) && baseDex > 0) return `m${baseDex}`;
        return '';
    }

    const dex = Number(entry.dex);
    return Number.isFinite(dex) && dex > 0 ? String(dex) : '';
}

function isTeamBuilderNumericShareIdAmbiguous(entry, numericId){
    if(!entry || !numericId) return false;
    const isMegaEntry = isMegaPokemonCatalogEntry(entry);
    let matchCount = 0;
    getTeamBuilderCatalogEntries().forEach(candidate => {
        if(!candidate || isMegaPokemonCatalogEntry(candidate) !== isMegaEntry) return;
        if(getTeamBuilderEntryRawNumericShareId(candidate) === numericId){
            matchCount += 1;
        }
    });
    return matchCount > 1;
}

function getTeamBuilderEntryNumericShareId(entry){
    const numericId = getTeamBuilderEntryRawNumericShareId(entry);
    if(!isTeamBuilderNumericShareIdAmbiguous(entry, numericId)) return numericId;
    const routeToken = String(entry?.routeToken || '').trim().toLowerCase();
    return /^\d{3,}(?:-[a-z0-9]+)?$/.test(routeToken) ? routeToken : '';
}

function getTeamBuilderDefaultNumericTokenEntry(candidates = [], expectedToken = ''){
    const defaultKey = TEAM_BUILDER_NUMERIC_TOKEN_DEFAULT_KEYS[String(expectedToken || '')];
    if(!defaultKey) return null;
    return (Array.isArray(candidates) ? candidates : []).find(entry => (
        [entry?.routeSlug, entry?.id, entry?.name, entry?.searchName]
            .map(normalizePokemonSearchText)
            .filter(Boolean)
            .includes(normalizePokemonSearchText(defaultKey))
    )) || null;
}

function findTeamBuilderPokemonCatalogEntryByNumericToken(token, slotConfig = null){
    const rawToken = String(token || '').trim().toLowerCase();
    if(!rawToken) return null;

    const megaMatch = rawToken.match(/^m(?:ega)?-?(\d+)$/);
    const numericMatch = megaMatch || rawToken.match(/^(\d+)$/);
    if(!numericMatch) return null;

    const expectedToken = megaMatch ? `m${Number(numericMatch[1])}` : String(Number(numericMatch[1]));
    const candidates = getTeamBuilderCatalogEntries().filter(entry => {
        if(!entry) return false;
        if(slotConfig && !teamBuilderEntryMatchesSlot(entry, slotConfig)) return false;
        const entryToken = getTeamBuilderEntryRawNumericShareId(entry);
        if(entryToken !== expectedToken) return false;
        return megaMatch ? isMegaPokemonCatalogEntry(entry) : !isMegaPokemonCatalogEntry(entry);
    });

    return getTeamBuilderDefaultNumericTokenEntry(candidates, expectedToken)
        || getPreferredTeamBuilderCatalogEntry(candidates)
        || null;
}

function findTeamBuilderPokemonCatalogEntryByToken(token, slotConfig = null){
    const normalizedToken = normalizePokemonDetailRouteToken(token);
    if(!normalizedToken) return null;
    return findTeamBuilderPokemonCatalogEntryByNumericToken(normalizedToken, slotConfig)
        || findPokemonCatalogEntryByRouteToken(normalizedToken, POKEMON_CATALOG_VARIANT_DEFAULT)
        || findTeamBuilderPokemonCatalogEntry(normalizedToken);
}

function getTeamBuilderShareTokenCandidatesForSlot(slotConfig){
    const candidates = [];
    const seenTokens = new Set();
    getTeamBuilderCatalogEntries().forEach(entry => {
        if(!entry || !teamBuilderEntryMatchesSlot(entry, slotConfig)) return;
        const token = getTeamBuilderShareTokenForEntry(entry);
        if(!token || seenTokens.has(token)) return;
        seenTokens.add(token);
        candidates.push({ token, entry });
    });
    return candidates.sort((left, right) => (
        right.token.length - left.token.length
        || left.token.localeCompare(right.token, 'pt-BR')
    ));
}

function getTeamBuilderShareTokenForEntry(entry){
    const numericId = getTeamBuilderEntryNumericShareId(entry);
    if(numericId) return numericId;
    return String(entry?.routeSlug || entry?.id || '')
        .trim()
        .toLowerCase();
}

function getTeamBuilderShareValue(){
    const tokens = TEAM_BUILDER_SLOT_CONFIGS.map(slot => getTeamBuilderShareTokenForEntry(teamBuilderSelections[slot.id]));
    if(tokens.every(token => !token)) return '';
    if(tokens.some(token => !token)){
        return tokens.map(token => encodeURIComponent(token || '')).join('--');
    }
    return tokens.map(encodeURIComponent).join('');
}

function parseCompactTeamBuilderShareTokens(shareValue){
    const compactValue = String(shareValue || '').trim().toLowerCase();
    if(!compactValue || !/^[a-z0-9-]+$/.test(compactValue)) return [];

    const memo = new Set();
    const readSlot = (slotIndex, offset) => {
        const memoKey = `${slotIndex}:${offset}`;
        if(memo.has(memoKey)) return null;
        if(slotIndex >= TEAM_BUILDER_SLOT_CONFIGS.length){
            return offset === compactValue.length ? [] : null;
        }
        if(offset >= compactValue.length){
            memo.add(memoKey);
            return null;
        }

        const slot = TEAM_BUILDER_SLOT_CONFIGS[slotIndex];
        const candidates = getTeamBuilderShareTokenCandidatesForSlot(slot)
            .filter(candidate => compactValue.startsWith(candidate.token, offset));

        for(const candidate of candidates){
            const nextOffset = offset + candidate.token.length;
            const rest = readSlot(slotIndex + 1, nextOffset);
            if(rest){
                return [candidate.token, ...rest];
            }
        }

        memo.add(memoKey);
        return null;
    };

    return readSlot(0, 0) || [];
}

function parseTeamBuilderShareTokens(shareValue){
    const rawValue = String(shareValue || '').trim();
    if(!rawValue) return [];
    if(rawValue.includes('--')){
        return rawValue.split('--').map(token => decodeURIComponent(token || '').trim());
    }
    if(rawValue.includes('.')){
        return rawValue.split('.').map(token => decodeURIComponent(token || '').trim()).filter(Boolean);
    }
    return parseCompactTeamBuilderShareTokens(decodeURIComponent(rawValue));
}

function applyTeamBuilderShareValue(rawValue){
    const shareValue = String(rawValue || '').trim();
    if(!shareValue || shareValue === teamBuilderUrlHydratedValue) return false;
    const tokens = parseTeamBuilderShareTokens(shareValue);
    if(tokens.length !== TEAM_BUILDER_SLOT_CONFIGS.length) return false;

    const nextSelections = {};
    const usedDuplicateKeys = new Set();
    const usedAceRoleKeys = new Set();
    let selectedMegaKey = '';
    for(let index = 0; index < TEAM_BUILDER_SLOT_CONFIGS.length; index += 1){
        const slot = TEAM_BUILDER_SLOT_CONFIGS[index];
        if(!tokens[index]) continue;
        const entry = findTeamBuilderPokemonCatalogEntryByToken(tokens[index], slot);
        if(!entry || !teamBuilderEntryMatchesSlot(entry, slot) || !teamBuilderEntryMeetsLevelRequirement(entry)) return false;
        const duplicateKey = getTeamBuilderEntryDuplicateKey(entry);
        if(duplicateKey && usedDuplicateKeys.has(duplicateKey)) return false;
        if(duplicateKey) usedDuplicateKeys.add(duplicateKey);
        const aceRoleKey = getTeamBuilderAceRoleKey(entry);
        if(aceRoleKey && usedAceRoleKeys.has(aceRoleKey)) return false;
        if(aceRoleKey) usedAceRoleKeys.add(aceRoleKey);
        if(isMegaPokemonCatalogEntry(entry)){
            const megaKey = getTeamBuilderEntryKey(entry);
            if(selectedMegaKey && selectedMegaKey !== megaKey) return false;
            selectedMegaKey = megaKey;
        }
        nextSelections[slot.id] = entry;
    }

    teamBuilderSelections = nextSelections;
    teamBuilderIgnoreTankForHunts = false;
    teamBuilderActiveSlotId = TEAM_BUILDER_SLOT_CONFIGS.find(slot => !nextSelections[slot.id])?.id
        || TEAM_BUILDER_SLOT_CONFIGS[0]?.id
        || '';
    teamBuilderHuntsVisible = isTeamBuilderComplete();
    teamBuilderHuntsLoading = false;
    teamBuilderFilters = {
        search: '',
        clan: 'all',
        subFunctions: [],
        roles: [],
        type: 'all'
    };
    if(teamBuilderSearchInput) teamBuilderSearchInput.value = '';
    teamBuilderUrlHydratedValue = shareValue;
    return true;
}

function applyTeamBuilderShareValueFromUrl(){
    const params = new URLSearchParams(location.search);
    return applyTeamBuilderShareValue(params.get(TEAM_BUILDER_SHARE_PARAM) || '');
}

function isTeamMemberTankRole(member){
    const roleText = normalizePokemonSearchText(member?.role || '');
    if(!roleText) return false;
    const roleTokens = roleText.split(/\s+/).filter(Boolean);
    return roleTokens.includes('ar')
        || roleTokens.includes('tank')
        || roleTokens.includes('defender')
        || roleText.includes('all rounder');
}

function getTeamMemberSlotKind(member){
    if(isTeamMemberTankRole(member)) return 'tank';
    const roleText = normalizePokemonSearchText(member?.role || '');
    if(roleText.includes('finisher')) return 'finisher';
    return 'dps';
}

function getTeamEntrySlotEntries(teamEntry){
    let tankSlotAssigned = false;
    return (Array.isArray(teamEntry?.pokemons) ? teamEntry.pokemons : [])
        .map(member => {
            const entry = findTeamBuilderPokemonCatalogEntry(member?.name || '', {
                elementKeys: teamEntry?.elementKeys || [],
                clan: teamEntry?.clanKey || ''
            });
            if(!entry) return null;
            const rawSlotKind = getTeamMemberSlotKind(member);
            const slotKind = rawSlotKind === 'tank' && !tankSlotAssigned
                ? 'tank'
                : (rawSlotKind === 'finisher' ? 'finisher' : 'dps');
            if(slotKind === 'tank') tankSlotAssigned = true;
            return {
                slot: { kind: slotKind },
                entry,
                member
            };
        })
        .filter(Boolean);
}

function normalizeTeamBuilderTypeList(types = []){
    return Array.from(new Set(
        (Array.isArray(types) ? types : [types])
            .map(normalizePokemonTypeKey)
            .filter(Boolean)
    ));
}

function getTeamBuilderDefensivePassiveTypes(entry){
    const passiveTypes = [];
    const addType = type => {
        const normalizedType = normalizePokemonTypeKey(type);
        if(normalizedType && !passiveTypes.includes(normalizedType)){
            passiveTypes.push(normalizedType);
        }
    };
    getTeamBuilderPassiveLookupKeys(entry).forEach(key => {
        const types = TEAM_BUILDER_DEFENSIVE_PASSIVE_TYPES[key];
        if(Array.isArray(types)){
            types.forEach(addType);
        }
    });
    getTimesDefensivePassiveTypes(entry, 'normal').forEach(addType);
    getTimesDefensivePassiveTypes(entry, 'shiny').forEach(addType);
    Object.entries(entry?.defenseByBossType || {}).forEach(([type, factor]) => {
        if(Number(factor) < 1) addType(type);
    });
    Object.entries(entry?.defenseDamageFactorByBossType || {}).forEach(([type, factor]) => {
        if(Number(factor) < 1) addType(type);
    });
    return passiveTypes;
}

function teamBuilderEntryReducesSuperEffectiveDamage(entry){
    if(!entry) return false;
    const texts = [
        ...getTimesDefensivePassiveTextCandidates(entry, 'normal'),
        ...getTimesDefensivePassiveTextCandidates(entry, 'shiny')
    ];
    return texts.some(text => {
        const normalizedText = normalizeTimesPassiveText(text);
        const hasSuperEffectiveCue = /\b(super efetivo|super efetivos)\b/.test(normalizedText);
        const hasReductionCue = /\b(toma menos|sofre menos|menos dano|reduz|reduzido|metade|0 5x)\b/.test(normalizedText);
        const isNegativeCue = /\b(recebe super efetivo|leva dano super efetivo|mas leva|mas recebe|em contrapartida)\b/.test(normalizedText);
        return hasSuperEffectiveCue && hasReductionCue && !isNegativeCue;
    });
}

function getTeamBuilderHuntCombatMeta(huntName){
    const normalizedName = normalizePokemonSearchText(huntName);
    const override = TEAM_BUILDER_HUNT_META_OVERRIDES[normalizedName] || null;
    const entry = getPokemonCatalogEntryByName(huntName)
        || findTeamBuilderPokemonCatalogEntry(huntName);
    const naturalElements = normalizeTeamBuilderTypeList(
        override?.naturalElements || entry?.naturalElements || []
    );
    const moveset = normalizeTeamBuilderTypeList(
        override?.moveset || entry?.moveset || []
    );
    return {
        naturalElements,
        moveset,
        hasNaturalElements: naturalElements.length > 0,
        hasMoveset: moveset.length > 0
    };
}

function teamBuilderEntryDefendsAgainstType(entry, attackType){
    const normalizedType = normalizePokemonTypeKey(attackType);
    if(!entry || !normalizedType) return false;

    const passiveTypes = getTeamBuilderDefensivePassiveTypes(entry);
    if(passiveTypes.includes(normalizedType)) return true;

    const naturalTypes = normalizeTeamBuilderTypeList(entry.naturalElements || []);
    if(!naturalTypes.length) return false;

    if(
        teamBuilderEntryReducesSuperEffectiveDamage(entry)
        && getPokemonTypeMultiplier(normalizedType, naturalTypes) > 1
    ){
        return true;
    }

    return getPokemonTypeMultiplier(normalizedType, naturalTypes) < 1;
}

function teamBuilderEntryIsVulnerableToAttackType(entry, attackType){
    const normalizedType = normalizePokemonTypeKey(attackType);
    if(!entry || !normalizedType) return false;

    const passiveTypes = getTeamBuilderDefensivePassiveTypes(entry);
    if(passiveTypes.includes(normalizedType)) return false;

    const naturalTypes = normalizeTeamBuilderTypeList(entry.naturalElements || []);
    if(!naturalTypes.length) return false;

    const multiplier = getPokemonTypeMultiplier(normalizedType, naturalTypes);
    if(multiplier <= 1) return false;

    return !teamBuilderEntryReducesSuperEffectiveDamage(entry);
}

function teamBuilderTankCanHoldHunt(tankEntry, huntMeta, fallbackAttackTypes = []){
    const attackTypes = huntMeta?.hasMoveset
        ? huntMeta.moveset
        : normalizeTeamBuilderTypeList(fallbackAttackTypes);
    if(!attackTypes.length) return false;
    if(huntMeta?.hasMoveset && attackTypes.some(type => teamBuilderEntryIsVulnerableToAttackType(tankEntry, type))){
        return false;
    }
    return attackTypes.some(type => teamBuilderEntryDefendsAgainstType(tankEntry, type));
}

function teamBuilderTankCanHoldAndDamageHunt(tankEntry, huntMeta, fallbackAttackTypes = []){
    if(!teamBuilderTankCanHoldHunt(tankEntry, huntMeta, fallbackAttackTypes)) return false;
    return huntMeta?.hasNaturalElements
        ? teamBuilderDamageEntryHitsHunt(tankEntry, huntMeta)
        : teamBuilderDamageEntryHitsWeaknessTypes(tankEntry, fallbackAttackTypes);
}

function teamBuilderDamageEntryHitsHunt(entry, huntMeta){
    if(!huntMeta?.hasNaturalElements) return true;
    const moveset = normalizeTeamBuilderTypeList(entry?.moveset || []);
    const offensivePassive = getTimesOffensivePassiveMeta(entry);
    if(offensivePassive.all) return true;
    if(teamBuilderEntryOffensivePassiveHitsNaturalTypes(entry, huntMeta.naturalElements)) return true;
    if(!moveset.length) return false;
    // Dano efetivo: qualquer fraqueza da hunt (> 1x), nao exige multiplicador 4x.
    return moveset.some(type => getPokemonTypeMultiplier(type, huntMeta.naturalElements) > 1);
}

function teamBuilderEntryOffensivePassiveHitsNaturalTypes(entry, naturalTypes = []){
    const normalizedNaturalTypes = normalizeTeamBuilderTypeList(naturalTypes);
    if(!normalizedNaturalTypes.length) return false;
    const offensivePassive = getTimesOffensivePassiveMeta(entry);
    if(offensivePassive.all) return true;
    return offensivePassive.types.some(type => normalizedNaturalTypes.includes(type));
}

function teamBuilderDamageEntryHitsWeaknessTypes(entry, weaknessTypes = []){
    const moveset = normalizeTeamBuilderTypeList(entry?.moveset || []);
    const normalizedWeaknessTypes = normalizeTeamBuilderTypeList(weaknessTypes);
    const offensivePassive = getTimesOffensivePassiveMeta(entry);
    if(offensivePassive.all) return true;
    if(!moveset.length || !normalizedWeaknessTypes.length) return false;
    return moveset.some(type => normalizedWeaknessTypes.includes(type));
}

function teamBuilderDamageEntryHitsAnyHuntWeakness(entry, huntMeta, weaknessTypes = []){
    return huntMeta?.hasNaturalElements
        ? teamBuilderDamageEntryHitsHunt(entry, huntMeta)
        : teamBuilderDamageEntryHitsWeaknessTypes(entry, weaknessTypes);
}

function teamBuilderSelectedMovesetsHitWeaknessTypes(selectedSlotEntries = [], weaknessTypes = [], huntMeta = null, options = {}){
    const normalizedWeaknessTypes = normalizeTeamBuilderTypeList(weaknessTypes);
    const ignoreTankCondition = options.ignoreTankCondition === true;
    if(!normalizedWeaknessTypes.length && !huntMeta?.hasNaturalElements) return false;
    return (Array.isArray(selectedSlotEntries) ? selectedSlotEntries : [])
        .some(item => {
            if(item.slot.kind === 'tank'){
                if(ignoreTankCondition) return false;
                return teamBuilderTankCanHoldAndDamageHunt(item.entry, huntMeta, normalizedWeaknessTypes);
            }
            if(item.slot.kind !== 'dps' && item.slot.kind !== 'finisher') return false;
            return teamBuilderDamageEntryHitsAnyHuntWeakness(item.entry, huntMeta, normalizedWeaknessTypes);
        });
}

function getTeamBuilderEffectiveDamageCount(selectedSlotEntries = [], huntMeta, weaknessTypes = [], options = {}){
    const ignoreTankCondition = options.ignoreTankCondition === true;
    return selectedSlotEntries
        .filter(item => {
            if(item.slot.kind === 'tank'){
                if(ignoreTankCondition) return false;
                return teamBuilderTankCanHoldAndDamageHunt(item.entry, huntMeta, weaknessTypes);
            }
            if(item.slot.kind !== 'dps' && item.slot.kind !== 'finisher') return false;
            return teamBuilderDamageEntryHitsAnyHuntWeakness(item.entry, huntMeta, weaknessTypes);
        }).length;
}

function areTeamBuilderSlotEntriesCompatibleWithHunt(selectedSlotEntries = [], huntName, weaknessTypes = [], options = {}){
    const huntMeta = getTeamBuilderHuntCombatMeta(huntName);
    const normalizedWeaknessTypes = normalizeTeamBuilderTypeList(weaknessTypes);
    const ignoreTankCondition = options.ignoreTankCondition === true;
    if(!huntMeta.hasNaturalElements && !normalizedWeaknessTypes.length) return false;

    const tankEntry = selectedSlotEntries.find(item => item.slot.kind === 'tank')?.entry || null;
    if(!tankEntry || (
        !ignoreTankCondition
        && !teamBuilderTankCanHoldAndDamageHunt(tankEntry, huntMeta, normalizedWeaknessTypes)
    )){
        return false;
    }

    const effectiveDamageCount = getTeamBuilderEffectiveDamageCount(
        selectedSlotEntries,
        huntMeta,
        normalizedWeaknessTypes,
        options
    );

    return effectiveDamageCount >= 5
        && (
            !huntMeta.hasNaturalElements
            || !normalizedWeaknessTypes.length
            || teamBuilderSelectedMovesetsHitWeaknessTypes(selectedSlotEntries, normalizedWeaknessTypes, huntMeta, options)
        );
}

function loadDeferredStylesheet(src){
    const resolvedSrc = new URL(src, document.baseURI).href;
    const existing = Array.from(document.styleSheets)
        .map(sheet => sheet.ownerNode)
        .find(node => node?.href === resolvedSrc);
    if(existing) return Promise.resolve();

    return new Promise((resolve, reject) => {
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = src;
        link.addEventListener('load', resolve, { once: true });
        link.addEventListener('error', () => reject(new Error(`Falha ao carregar ${src}`)), { once: true });
        document.head.appendChild(link);
    });
}

function ensurePanelFragmentLoaded(panel){
    if(!panel) return Promise.reject(new Error('Painel indisponivel.'));
    const fragmentName = String(panel.dataset.panelFragment || '').trim();
    if(!fragmentName || panel.dataset.panelLoaded === 'true') return Promise.resolve(panel);
    if(panelFragmentLoadPromises.has(fragmentName)) return panelFragmentLoadPromises.get(fragmentName);

    panel.setAttribute('aria-busy', 'true');
    const fragmentUrl = `fragments/${fragmentName}.html?v=${PANEL_FRAGMENT_VERSION}`;
    const stylesheetUrl = `fragments/${fragmentName}.css?v=${PANEL_FRAGMENT_VERSION}`;
    const needsFragmentStylesheet = panel.dataset.panelFragmentStyles !== 'none';
    const htmlRequest = fetch(fragmentUrl).then(response => {
        if(!response.ok) throw new Error(`Falha ao carregar ${fragmentUrl}`);
        return response.text();
    });
    const promise = Promise.all([
        htmlRequest,
        needsFragmentStylesheet ? loadDeferredStylesheet(stylesheetUrl) : Promise.resolve()
    ])
        .then(([html]) => {
            // Alguns fragmentos antigos ainda incluem o próprio contêiner
            // role="tabpanel". O placeholder já é esse contêiner; inserir o
            // fragmento inteiro criaria IDs duplicados e um painel interno
            // oculto, deixando a página com altura zero. Aceitamos os dois
            // formatos e usamos somente o conteúdo do contêiner quando ele
            // estiver presente.
            const template = document.createElement('template');
            template.innerHTML = String(html || '').trim();
            const fragmentRoot = template.content.firstElementChild;
            if(
                fragmentRoot
                && fragmentRoot.id === panel.id
                && fragmentRoot.getAttribute('role') === 'tabpanel'
            ){
                panel.replaceChildren(...Array.from(fragmentRoot.childNodes));
            } else {
                panel.innerHTML = html;
            }
            panel.dataset.panelLoaded = 'true';
            panel.removeAttribute('aria-busy');
            bindSidebarActionButtons(panel);
            return panel;
        })
        .catch(error => {
            panel.removeAttribute('aria-busy');
            const loading = panel.querySelector('.panel-fragment-loading');
            if(loading){
                loading.classList.add('is-error');
                loading.textContent = 'Nao foi possivel carregar o conteudo. Atualize a pagina para tentar novamente.';
            }
            panelFragmentLoadPromises.delete(fragmentName);
            throw error;
        });
    panelFragmentLoadPromises.set(fragmentName, promise);
    return promise;
}

function ensureInteractiveMapAssetsReady(){
    if(typeof window.initInteractiveMapPage === 'function'){
        return loadDeferredStylesheet(INTERACTIVE_MAP_STYLESHEET_SRC);
    }
    if(interactiveMapAssetsLoadPromise) return interactiveMapAssetsLoadPromise;
    interactiveMapAssetsLoadPromise = Promise.all([
        loadDeferredStylesheet(INTERACTIVE_MAP_STYLESHEET_SRC),
        loadDeferredScript(INTERACTIVE_MAP_SCRIPT_SRC, () => typeof window.initInteractiveMapPage === 'function')
    ]).catch(error => {
        interactiveMapAssetsLoadPromise = null;
        throw error;
    });
    return interactiveMapAssetsLoadPromise;
}

function ensureInteractiveMapPanelReady(){
    if(!contentInteractiveMap) return Promise.reject(new Error('Painel do mapa interativo indisponivel.'));
    const fragmentReady = contentInteractiveMap.dataset.panelFragment
        && contentInteractiveMap.dataset.panelLoaded !== 'true'
        ? ensurePanelFragmentLoaded(contentInteractiveMap)
        : Promise.resolve(contentInteractiveMap);
    return fragmentReady
        .then(() => ensureInteractiveMapAssetsReady())
        .then(() => contentInteractiveMap);
}

window.ensureInteractiveMapPanelReady = ensureInteractiveMapPanelReady;

function ensureOptionalLocalConfigReady(){
    if(window.POKE_YT_API_KEY) return Promise.resolve();
    if(!/^(localhost|127\.0\.0\.1)$/i.test(location.hostname)) return Promise.resolve();
    if(optionalLocalConfigLoadPromise) return optionalLocalConfigLoadPromise;
    optionalLocalConfigLoadPromise = loadDeferredScript('js/config.local.js', () => Boolean(window.POKE_YT_API_KEY))
        .catch(() => false);
    return optionalLocalConfigLoadPromise;
}

function isTeamBuilderHuntCompatible(huntName, weaknessTypes = []){
    return areTeamBuilderSlotEntriesCompatibleWithHunt(
        getTeamBuilderSelectedSlotEntries(),
        huntName,
        weaknessTypes,
        { ignoreTankCondition: teamBuilderIgnoreTankForHunts }
    );
}

function getTeamBuilderHuntWeaknessTypes(huntName){
    const huntMeta = getTeamBuilderHuntCombatMeta(huntName);
    if(huntMeta.hasNaturalElements){
        return getPokemonWeaknesses(huntMeta.naturalElements).map(weakness => weakness.type);
    }
    return [];
}

function addTeamBuilderPreEvolutionHuntCandidates(huntCandidates){
    Array.from(huntCandidates.values()).forEach(candidate => {
        if(!candidate || candidate.sourceHuntName) return;
        const sourceName = String(candidate.name || '').trim();
        if(!sourceName) return;
        getTeamHuntPreEvolutionEntries(sourceName).forEach(preEvolution => {
            const preEvolutionName = String(preEvolution?.name || '').trim();
            const key = normalizePokemonSearchText(preEvolutionName);
            if(!preEvolutionName || !key || huntCandidates.has(key)) return;
            huntCandidates.set(key, {
                name: preEvolutionName,
                note: '',
                image: String(preEvolution.image || buildTeamPokemonImageFileName(preEvolutionName)).trim(),
                sourceHuntName: sourceName,
                combatHuntName: preEvolutionName,
                fallbackTypeKeys: Array.isArray(candidate.fallbackTypeKeys) ? [...candidate.fallbackTypeKeys] : [],
                sourceTeams: Array.isArray(candidate.sourceTeams) ? [...candidate.sourceTeams] : []
            });
        });
    });
}

function getTeamBuilderKnownHuntCandidates(){
    const huntCandidates = new Map();
    (teamsCatalog || []).forEach(team => {
        const fallbackTypeKeys = Array.from(new Set(
            (Array.isArray(team.elementKeys) ? team.elementKeys : [])
                .map(normalizePokemonTypeKey)
                .filter(Boolean)
        ));
        [...(team.hunts || []), ...(team.alternativeHunts || [])].forEach(hunt => {
            const huntObject = hunt && typeof hunt === 'object' ? hunt : null;
            const huntName = String(huntObject?.name || hunt || '').trim();
            if(!huntName) return;
            const key = normalizePokemonSearchText(huntName);
            if(isTeamBuilderExcludedHuntName(huntName)) return;
            const existing = huntCandidates.get(key);
            if(existing){
                existing.sourceTeams.push(team);
                fallbackTypeKeys.forEach(typeKey => {
                    if(!existing.fallbackTypeKeys.includes(typeKey)) existing.fallbackTypeKeys.push(typeKey);
                });
                if(!existing.image && huntObject?.image) existing.image = String(huntObject.image || '').trim();
                if(!existing.note && huntObject?.note) existing.note = String(huntObject.note || '').trim();
                if(!existing.sourceHuntName && huntObject?.sourceHuntName) existing.sourceHuntName = String(huntObject.sourceHuntName || '').trim();
                if(!existing.combatHuntName && huntObject?.combatHuntName) existing.combatHuntName = String(huntObject.combatHuntName || '').trim();
                return;
            }
            huntCandidates.set(key, {
                name: huntName,
                note: String(huntObject?.note || '').trim(),
                image: String(huntObject?.image || '').trim(),
                sourceHuntName: String(huntObject?.sourceHuntName || '').trim(),
                combatHuntName: String(huntObject?.combatHuntName || '').trim(),
                fallbackTypeKeys,
                sourceTeams: [team]
            });
        });
    });
    Object.keys(TEAM_BUILDER_HUNT_META_OVERRIDES || {}).forEach(key => {
        if(isTeamBuilderExcludedHuntName(key)) return;
        if(key === 'tsaarena' && huntCandidates.has('tsareena')) return;
        if(key === 'salamance' && huntCandidates.has('salamence')) return;
        if(!huntCandidates.has(key)){
            huntCandidates.set(key, {
                name: key.split(' ').map(part => part ? part[0].toUpperCase() + part.slice(1) : '').join(' '),
                note: '',
                image: '',
                fallbackTypeKeys: [],
                sourceTeams: []
            });
        }
    });
    addTeamBuilderPreEvolutionHuntCandidates(huntCandidates);
    return Array.from(huntCandidates.values());
}

function getTeamBuilderHuntRecommendations(){
    const selectedEntries = getTeamBuilderSelectedEntries();
    const selectedSlotEntries = getTeamBuilderSelectedSlotEntries();
    const selectedNames = new Set(selectedEntries.map(entry => normalizePokemonSearchText(entry.name)).filter(Boolean));
    const selectedTypes = new Set(selectedEntries.flatMap(getTeamBuilderEntryTypeKeys));
    const selectedMovesetTypes = new Set(selectedEntries.flatMap(getTeamBuilderEntryMovesetKeys));
    const selectedClan = selectedEntries.map(entry => entry.team).find(Boolean) || '';
    const compatibilityOptions = { ignoreTankCondition: teamBuilderIgnoreTankForHunts };
    const huntScores = new Map();

    getTeamBuilderKnownHuntCandidates().forEach(candidate => {
        const huntName = String(candidate?.name || '').trim();
        if(!huntName) return;
        const effectiveHuntName = getTeamHuntCombatName(candidate);
        const weaknessTypeKeys = getTeamBuilderHuntWeaknessTypes(effectiveHuntName);
        const huntMeta = getTeamBuilderHuntCombatMeta(effectiveHuntName);
        const fullyCompatible = areTeamBuilderSlotEntriesCompatibleWithHunt(
            selectedSlotEntries,
            effectiveHuntName,
            weaknessTypeKeys,
            compatibilityOptions
        );
        if(!fullyCompatible){
            const sourceHuntName = String(candidate.sourceHuntName || '').trim();
            if(!sourceHuntName) return;
            const sourceWeaknessTypes = getTeamBuilderHuntWeaknessTypes(sourceHuntName);
            const sourceCompatible = areTeamBuilderSlotEntriesCompatibleWithHunt(
                selectedSlotEntries,
                sourceHuntName,
                sourceWeaknessTypes,
                compatibilityOptions
            );
            if(!sourceCompatible) return;
            const preEvolutionDamageCount = getTeamBuilderEffectiveDamageCount(
                selectedSlotEntries,
                huntMeta,
                weaknessTypeKeys,
                compatibilityOptions
            );
            if(
                preEvolutionDamageCount < 5
                || !teamBuilderSelectedMovesetsHitWeaknessTypes(
                    selectedSlotEntries,
                    weaknessTypeKeys,
                    huntMeta,
                    compatibilityOptions
                )
            ) return;
        }
        const sourceScore = (Array.isArray(candidate.sourceTeams) ? candidate.sourceTeams : []).reduce((score, team) => {
            const teamMembers = Array.isArray(team.pokemons) ? team.pokemons : [];
            const memberScore = teamMembers.reduce((memberTotal, member) => {
                return memberTotal + (selectedNames.has(normalizePokemonSearchText(member.name)) ? 4 : 0);
            }, 0);
            const typeScore = (team.elementKeys || []).reduce((typeTotal, typeKey) => {
                return typeTotal + (selectedTypes.has(normalizePokemonTypeKey(typeKey)) ? 1 : 0);
            }, 0);
            const clanScore = selectedClan && selectedClan === team.clanKey ? 1 : 0;
            return Math.max(score, memberScore + typeScore + clanScore);
        }, 0);
        const effectiveDamageCount = getTeamBuilderEffectiveDamageCount(
            selectedSlotEntries,
            huntMeta,
            weaknessTypeKeys,
            compatibilityOptions
        );
        const selectedWeaknessTypeScore = weaknessTypeKeys.reduce((score, typeKey) => {
            return score + (selectedMovesetTypes.has(typeKey) ? 2 : 0);
        }, 0);
        const score = sourceScore + (effectiveDamageCount * 3) + selectedWeaknessTypeScore;
        const key = normalizePokemonSearchText(huntName);
        const existing = huntScores.get(key);
        const source = {
            name: huntName,
            note: String(candidate.note || '').trim(),
            image: String(candidate.image || '').trim(),
            sourceHuntName: String(candidate.sourceHuntName || '').trim(),
            combatHuntName: String(candidate.combatHuntName || '').trim(),
            score,
            typeKeys: weaknessTypeKeys
        };
        if(!existing || source.score > existing.score){
            huntScores.set(key, source);
        }
    });

    return compactTeamBuilderHuntRecommendations(Array.from(huntScores.values())
        .sort((left, right) => right.score - left.score || left.name.localeCompare(right.name)));
}

function findTeamBuilderPokemonImageEntry(name){
    return findTeamBuilderPokemonCatalogEntry(name);
}

function createTeamBuilderHuntImage(name, imagePath = ''){
    const entry = findTeamBuilderPokemonImageEntry(name);
    const imageOverride = TEAM_BUILDER_HUNT_IMAGE_OVERRIDES[normalizePokemonSearchText(name)] || '';
    const image = document.createElement('img');
    image.src = imagePath
        ? getTeamPokemonImageSource({ image: imagePath })
        : imageOverride
            ? getTeamPokemonImageSource({ image: imageOverride })
            : entry
                ? getPokemonImageSource(entry)
                : getTeamPokemonImageSource({ image: buildTeamPokemonImageFileName(name) });
    image.alt = name;
    image.loading = 'lazy';
    image.decoding = 'async';
    setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
    return image;
}

function createTeamBuilderHuntMedia(recommendation){
    const media = document.createElement('span');
    media.className = 'team-builder-hunt-card__media';
    const items = Array.isArray(recommendation?.items) && recommendation.items.length
        ? recommendation.items
        : [recommendation];
    if(items.length > 1) media.classList.add('team-builder-hunt-card__media--bundle');
    items.slice(0, 3).forEach(item => {
        media.appendChild(createTeamBuilderHuntImage(
            String(item?.name || recommendation?.name || '').trim(),
            String(item?.image || '').trim()
        ));
    });
    return media;
}

function areSameTeamBuilderTypeList(left = [], right = []){
    const normalizedLeft = normalizeTeamBuilderTypeList(left);
    const normalizedRight = normalizeTeamBuilderTypeList(right);
    return normalizedLeft.length === normalizedRight.length
        && normalizedLeft.every((typeKey, index) => typeKey === normalizedRight[index]);
}

function getTeamBuilderHuntDisplayTypeKeys(recommendation){
    if(!recommendation || typeof recommendation !== 'object') return [];

    const getItemTypeKeys = (item) => {
        const huntName = String(item?.combatHuntName || item?.name || '').trim();
        if(!huntName) return [];
        return normalizeTeamBuilderTypeList(getTeamBuilderHuntWeaknessTypes(huntName));
    };

    const items = Array.isArray(recommendation.items) && recommendation.items.length
        ? recommendation.items
        : [];

    if(items.length){
        const itemTypeLists = items
            .map(getItemTypeKeys)
            .filter(typeKeys => typeKeys.length);
        if(itemTypeLists.length){
            const firstTypeList = itemTypeLists[0];
            if(itemTypeLists.every(typeList => areSameTeamBuilderTypeList(typeList, firstTypeList))){
                return firstTypeList;
            }
            return Array.from(new Set(itemTypeLists.flat()));
        }
    }

    const directTypeKeys = getItemTypeKeys(recommendation);
    return directTypeKeys;
}

function renderTeamBuilderHunts(){
    if(!(teamBuilderHunts instanceof HTMLElement)) return;
    if(teamBuilderHuntsLoading){
        teamBuilderHunts.hidden = false;
        teamBuilderHunts.replaceChildren(createInlineStatusMessage('team-builder-hunts-loading', 'Carregando hunts recomendadas...'));
        return;
    }
    if(!teamBuilderHuntsVisible){
        teamBuilderHunts.hidden = true;
        teamBuilderHunts.replaceChildren();
        return;
    }
    const recommendations = getTeamBuilderHuntRecommendations();
    if(!recommendations.length){
        teamBuilderHunts.hidden = false;
        teamBuilderHunts.replaceChildren(createInlineStatusMessage('team-builder-hunts-empty', 'Nenhuma hunt compativel foi encontrada para esta composicao.'));
        return;
    }

    const list = document.createElement('div');
    list.className = 'team-builder-hunt-list';
    recommendations.forEach(recommendation => {
        const card = document.createElement('article');
        card.className = 'team-builder-hunt-card';
        const levelBadge = createTeamHuntLevelBadge(recommendation);
        if(levelBadge){
            levelBadge.classList.add('team-builder-hunt-card__level-badge');
            card.appendChild(levelBadge);
        }
        const media = createTeamBuilderHuntMedia(recommendation);
        const body = document.createElement('span');
        body.className = 'team-builder-hunt-card__body';
        const name = document.createElement('strong');
        name.textContent = recommendation.name;
        body.appendChild(name);
        const displayTypeKeys = getTeamBuilderHuntDisplayTypeKeys(recommendation);
        if(displayTypeKeys.length){
            const typeList = document.createElement('span');
            typeList.className = 'team-builder-hunt-card__types';
            typeList.setAttribute('aria-label', `Tipos: ${displayTypeKeys.map(getTypeDisplayName).join(', ')}`);
            displayTypeKeys.forEach(typeKey => {
                typeList.appendChild(createPokemonTypeToken(typeKey, { compact: true }));
            });
            body.appendChild(typeList);
        }
        if(recommendation.note){
            const note = document.createElement('p');
            note.textContent = recommendation.note;
            body.appendChild(note);
        }
        card.append(media, body);
        list.appendChild(card);
    });
    teamBuilderHunts.hidden = false;
    teamBuilderHunts.replaceChildren(list);
}

function loadTeamBuilderHuntsIfNeeded(){
    if(!isTeamBuilderComplete()) return;
    if(teamsCatalogLoaded){
        teamBuilderHuntsVisible = true;
        teamBuilderHuntsLoading = false;
        renderTeamBuilderHunts();
        return;
    }
    if(teamBuilderHuntsLoading) return;
    teamBuilderHuntsVisible = true;
    teamBuilderHuntsLoading = true;
    renderTeamBuilderHunts();
    ensureTeamsCatalogLoaded()
        .then(() => {
            teamBuilderHuntsVisible = true;
        })
        .catch(error => {
            console.error('Team Builder hunts load failed', error);
            if(teamBuilderHunts){
                teamBuilderHunts.hidden = false;
                teamBuilderHunts.replaceChildren(createInlineStatusMessage('team-builder-hunts-error', 'Nao foi possivel carregar as hunts de /times.'));
            }
        })
        .finally(() => {
            teamBuilderHuntsLoading = false;
            renderTeamBuilderHunts();
        });
}

function renderTeamBuilderCompletionState(){
    const complete = isTeamBuilderComplete();
    if(teamBuilderPicker instanceof HTMLElement){
        teamBuilderPicker.hidden = complete;
    }
    if(teamBuilderCompletePanel instanceof HTMLElement){
        teamBuilderCompletePanel.hidden = !complete;
    }
    if(!complete){
        teamBuilderHuntsVisible = false;
        teamBuilderHuntsLoading = false;
        renderTeamBuilderHunts();
        return;
    }
    teamBuilderHuntsVisible = true;
    loadTeamBuilderHuntsIfNeeded();
}

function renderTeamBuilder(){
    hideTeamBuilderHuntsTooltip();
    const filledCount = Object.values(teamBuilderSelections || {}).filter(Boolean).length;
    if(teamBuilderFilledCount) teamBuilderFilledCount.textContent = `${filledCount}/6`;
    const activeSlot = getTeamBuilderSlotConfig();
    if(teamBuilderActiveSlotLabel){
        teamBuilderActiveSlotLabel.textContent = activeSlot ? `Selecionando ${activeSlot.label}` : 'Selecao';
    }
    renderTeamBuilderFilterControls();
    renderTeamBuilderSlots();
    renderTeamBuilderCompletionState();
    if(!isTeamBuilderComplete()){
        renderTeamBuilderResults();
    }
    if(teamBuilderInitialized && contentTeamBuilder && !contentTeamBuilder.hidden){
        updateUrl();
    }
}

function scheduleTeamBuilderSearchRender(){
    if(teamBuilderSearchRenderFrame){
        window.cancelAnimationFrame(teamBuilderSearchRenderFrame);
    }
    teamBuilderSearchRenderFrame = window.requestAnimationFrame(() => {
        teamBuilderSearchRenderFrame = 0;
        renderTeamBuilder();
    });
}

function initializeTeamBuilderPage(){
    if(teamBuilderInitialized) return;

    if(teamBuilderSearchInput){
        teamBuilderSearchInput.addEventListener('input', () => {
            teamBuilderFilters = {
                ...teamBuilderFilters,
                search: teamBuilderSearchInput.value || ''
            };
            scheduleTeamBuilderSearchRender();
        });
    }
    teamBuilderInitialized = true;
}

function showTeamBuilder(){
    if(contentTeamBuilder?.dataset.panelFragment && contentTeamBuilder.dataset.panelLoaded !== 'true'){
        setVisiblePanel(contentTeamBuilder);
        ensurePanelFragmentLoaded(contentTeamBuilder)
            .then(() => showTeamBuilder())
            .catch(error => console.error('Team Builder panel load failed', error));
        return;
    }
    if(!teamBuilderStatus || !teamBuilderStatus.isConnected){
        refreshTeamBuilderDomReferences();
    }
    initializeTeamBuilderPage();
    clearTabHighlights();
    setActiveTabTheme('team-builder');
    setVisiblePanel(contentTeamBuilder);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = 'Team Builder';
    updateBrowserTitle();

    if(teamBuilderStatus && !pokemonCatalogLoaded){
        teamBuilderStatus.textContent = 'Carregando catalogo...';
    }
    Promise.all([
        ensureTypesDataLoaded(),
        ensurePokemonCatalogLoaded()
    ]).then(() => {
        renderTeamBuilderClanFilters();
        renderTeamBuilderSubFunctionFilters();
        renderTeamBuilderTypeFilters();
        applyTeamBuilderShareValueFromUrl();
        renderTeamBuilder();
        if(useGsap && contentTeamBuilder){
            gsap.from(contentTeamBuilder, { opacity: 0, y: -10, duration: 0.4 });
        }
    }).catch(error => {
        console.error('Team Builder load failed', error);
        if(teamBuilderStatus) teamBuilderStatus.textContent = 'Nao foi possivel carregar o Team Builder.';
    });
}

function getHuntBuilderTargetDefinitionNames(definition){
    return Array.from(new Set([
        definition?.name,
        definition?.metaName,
        ...(Array.isArray(definition?.lookupNames) ? definition.lookupNames : []),
        ...(Array.isArray(definition?.preEvolutions) ? definition.preEvolutions.map(entry => entry?.name) : [])
    ].map(value => String(value || '').trim()).filter(Boolean)));
}

function getExpandedHuntBuilderTargetDefinitions(){
    const definitions = [];
    const seenKeys = new Set();
    const addDefinition = (definition) => {
        const name = String(definition?.name || '').trim();
        const key = normalizePokemonSearchText(name);
        if(!name || !key || seenKeys.has(key)) return;
        seenKeys.add(key);
        definitions.push(definition);
    };

    HUNT_BUILDER_TARGET_DEFINITIONS.forEach(definition => {
        addDefinition(definition);
        const preEvolutions = [];
        const seenPreEvolutionKeys = new Set();
        getHuntBuilderTargetDefinitionNames(definition).forEach(sourceName => {
            getTeamHuntPreEvolutionEntries(sourceName).forEach(preEvolution => {
                const preEvolutionName = String(preEvolution?.name || '').trim();
                const preEvolutionKey = normalizePokemonSearchText(preEvolutionName);
                if(!preEvolutionName || !preEvolutionKey || seenPreEvolutionKeys.has(preEvolutionKey)) return;
                seenPreEvolutionKeys.add(preEvolutionKey);
                preEvolutions.push({
                    name: preEvolutionName,
                    image: preEvolution.image || buildTeamPokemonImageFileName(preEvolutionName)
                });
            });
        });
        if(preEvolutions.length){
            const preEvolutionGroups = new Map();
            preEvolutions.forEach(preEvolution => {
                const combatMeta = getTeamBuilderHuntCombatMeta(preEvolution.name);
                const signature = combatMeta.naturalElements.join('/');
                if(!preEvolutionGroups.has(signature)){
                    preEvolutionGroups.set(signature, []);
                }
                preEvolutionGroups.get(signature).push(preEvolution);
            });

            preEvolutionGroups.forEach(groupedPreEvolutions => {
                addDefinition({
                    name: formatTeamHuntBundleName(groupedPreEvolutions),
                    metaName: groupedPreEvolutions[0]?.name || definition?.metaName || definition?.name,
                    image: groupedPreEvolutions[0]?.image || '',
                    lookupNames: groupedPreEvolutions.map(entry => entry.name),
                    preEvolutions: groupedPreEvolutions
                });
            });
        }
    });

    return definitions;
}

function findHuntBuilderTargetCatalogEntry(definition){
    const names = getHuntBuilderTargetDefinitionNames(definition);
    for(const name of names){
        const entry = getPokemonCatalogEntryByName(name)
            || findTeamBuilderPokemonCatalogEntry(name);
        if(entry) return entry;
    }
    return null;
}

function createHuntBuilderTargetEntry(definition){
    const catalogEntry = findHuntBuilderTargetCatalogEntry(definition);
    const combatMeta = getTeamBuilderHuntCombatMeta(definition?.metaName || definition?.name || '');
    const names = getHuntBuilderTargetDefinitionNames(definition);
    const displayName = String(definition?.name || catalogEntry?.name || '').trim();
    if(!displayName) return null;
    const preEvolutionItems = (Array.isArray(definition?.preEvolutions) ? definition.preEvolutions : [])
        .map(item => ({
            name: String(item?.name || '').trim(),
            image: String(item?.image || buildTeamPokemonImageFileName(item?.name || '')).trim()
        }))
        .filter(item => item.name);
    const entry = {
        ...(catalogEntry || {}),
        id: `hunt:${normalizePokemonSearchText(displayName)}`,
        name: displayName,
        searchName: normalizePokemonSearchText(displayName),
        huntSearchBase: normalizePokemonSearchText(names.join(' ')),
        huntLookupNames: names,
        naturalElements: combatMeta.naturalElements,
        moveset: combatMeta.moveset,
        catalogHidden: false
    };
    if(preEvolutionItems.length) entry.huntDisplayItems = preEvolutionItems;
    if(definition?.image) entry.image = definition.image;
    else if(catalogEntry?.image && !entry.image) entry.image = catalogEntry.image;
    return entry;
}

function createHuntBuilderEntryMedia(entry, baseClassName, altText = ''){
    const media = document.createElement('span');
    media.className = baseClassName;
    const items = Array.isArray(entry?.huntDisplayItems) && entry.huntDisplayItems.length
        ? entry.huntDisplayItems
        : [entry];
    if(items.length > 1) media.classList.add(`${baseClassName}--bundle`);
    items.slice(0, 3).forEach(item => {
        const image = document.createElement('img');
        const itemName = String(item?.name || entry?.name || '').trim();
        image.src = getPokemonImageSource(item);
        image.alt = altText ? `${altText} ${itemName}` : '';
        image.loading = 'lazy';
        image.decoding = 'async';
        setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
        media.appendChild(image);
    });
    return media;
}

function getHuntBuilderTargetEntries(){
    if(Array.isArray(huntBuilderTargetEntriesCache)) return huntBuilderTargetEntriesCache;
    const entries = getExpandedHuntBuilderTargetDefinitions()
        .map(createHuntBuilderTargetEntry)
        .filter(Boolean)
        .sort((left, right) => left.name.localeCompare(right.name, 'pt-BR'));
    if(!pokemonCatalogLoaded) return entries;
    huntBuilderTargetEntriesCache = entries;
    return huntBuilderTargetEntriesCache;
}

function getHuntBuilderSearchEntries(query = ''){
    const normalizedQuery = normalizePokemonSearchText(query);
    const entries = getHuntBuilderTargetEntries();
    if(!normalizedQuery) return entries.slice(0, 12);
    const matches = [];
    for(const entry of entries){
        const searchBase = entry.huntSearchBase || entry.searchName || normalizePokemonSearchText(entry.name);
        if(!searchBase.includes(normalizedQuery)) continue;
        matches.push(entry);
        if(matches.length >= 12) break;
    }
    return matches;
}

function hideHuntBuilderSearchResults(){
    if(huntBuilderSearchResults){
        huntBuilderSearchResults.hidden = true;
        huntBuilderSearchResults.replaceChildren();
    }
    if(huntBuilderSearchInput){
        huntBuilderSearchInput.setAttribute('aria-expanded', 'false');
    }
}

function clearHuntBuilderSearchHideTimer(){
    if(!huntBuilderSearchHideTimer) return;
    window.clearTimeout(huntBuilderSearchHideTimer);
    huntBuilderSearchHideTimer = 0;
}

function createHuntBuilderSearchResult(entry){
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'hunt-builder-search-result';
    button.setAttribute('role', 'option');

    const media = createHuntBuilderEntryMedia(entry, 'hunt-builder-search-result__media');

    const copy = document.createElement('span');
    copy.className = 'hunt-builder-search-result__copy';
    const name = document.createElement('strong');
    name.textContent = entry.name;
    const meta = document.createElement('span');
    meta.className = 'hunt-builder-search-result__meta';
    const types = createTeamBuilderTypeSummaryRow('Tipo', entry.naturalElements || []);
    const moveset = createTeamBuilderTypeSummaryRow('Moveset', entry.moveset || []);
    if(moveset) moveset.classList.add('hunt-builder-search-result__moveset');
    if(moveset) meta.appendChild(moveset);
    if(types) meta.appendChild(types);
    copy.append(name, meta);

    button.append(media, copy);
    button.addEventListener('mousedown', event => event.preventDefault());
    button.addEventListener('click', () => {
        huntBuilderSelectedTarget = entry;
        huntBuilderSelectedTypes = [];
        huntBuilderSelectedClan = '';
        resetHuntBuilderRegenerationState();
        if(huntBuilderSearchInput) huntBuilderSearchInput.value = entry.name;
        hideHuntBuilderSearchResults();
        renderHuntBuilder();
    });
    return button;
}

function renderHuntBuilderSearchResults(query = huntBuilderSearchInput?.value || ''){
    if(!huntBuilderSearchResults || !huntBuilderSearchInput) return;
    const entries = getHuntBuilderSearchEntries(query);
    if(!entries.length){
        const empty = document.createElement('p');
        empty.className = 'hunt-builder-search-empty';
        empty.textContent = 'Nenhum Pokemon encontrado.';
        huntBuilderSearchResults.replaceChildren(empty);
    } else {
        const fragment = document.createDocumentFragment();
        entries.forEach(entry => fragment.appendChild(createHuntBuilderSearchResult(entry)));
        huntBuilderSearchResults.replaceChildren(fragment);
    }
    huntBuilderSearchResults.hidden = false;
    huntBuilderSearchInput.setAttribute('aria-expanded', 'true');
}

function renderHuntBuilderTarget(){
    if(!huntBuilderTarget) return;
    const entry = huntBuilderSelectedTarget;
    if(!entry){
        huntBuilderTarget.hidden = true;
        huntBuilderTarget.replaceChildren();
        return;
    }

    const media = createHuntBuilderEntryMedia(entry, 'hunt-builder-target__media', 'Imagem de');

    const copy = document.createElement('div');
    const eyebrow = document.createElement('span');
    eyebrow.className = 'hunt-builder-eyebrow';
    eyebrow.textContent = 'Hunt selecionada';
    const name = document.createElement('strong');
    name.textContent = entry.name;
    const types = createPokemonTokenRow(entry.naturalElements);
    const moveset = createTeamBuilderTypeSummaryRow('Moveset', entry.moveset || []);
    if(moveset) moveset.classList.add('hunt-builder-target__moveset');
    copy.append(eyebrow, name, types);
    if(moveset) copy.appendChild(moveset);

    huntBuilderTarget.replaceChildren(media, copy);
    huntBuilderTarget.hidden = false;
}

function renderHuntBuilderTypeOptions(){
    if(!huntBuilderTypeOptions || !huntBuilderTypesPanel) return;
    const entry = huntBuilderSelectedTarget;
    if(!entry || !huntBuilderSelectedClan){
        huntBuilderTypesPanel.hidden = true;
        huntBuilderTypeOptions.replaceChildren();
        return;
    }

    const weaknessesList = getPokemonWeaknesses(entry.naturalElements);
    const fragment = document.createDocumentFragment();
    weaknessesList.forEach(weakness => {
        const typeKey = normalizePokemonTypeKey(weakness.type);
        const selected = huntBuilderSelectedTypes.includes(typeKey);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'hunt-builder-option hunt-builder-option--type';
        button.dataset.type = typeKey;
        button.classList.toggle('is-active', selected);
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
        button.setAttribute('aria-label', `${formatPokemonTypeLabel(typeKey)} ${formatTypeMultiplierValue(weakness.multiplier)}`);
        button.title = formatPokemonTypeLabel(typeKey);

        const icon = document.createElement('img');
        icon.src = `icons-type/${typeKey}.png`;
        icon.alt = '';
        icon.loading = 'lazy';
        icon.decoding = 'async';
        setImageFallback(icon, POKEMON_IMAGE_PLACEHOLDER);

        const multiplier = document.createElement('span');
        multiplier.textContent = formatTypeMultiplierValue(weakness.multiplier);
        button.append(icon, multiplier);
        button.addEventListener('click', () => {
            const current = new Set(huntBuilderSelectedTypes);
            if(current.has(typeKey)) current.delete(typeKey);
            else current.add(typeKey);
            huntBuilderSelectedTypes = Array.from(current);
            resetHuntBuilderRegenerationState();
            renderHuntBuilder();
        });
        fragment.appendChild(button);
    });

    huntBuilderTypeOptions.replaceChildren(fragment);
    huntBuilderTypesPanel.hidden = false;
}

function renderHuntBuilderClanOptions(){
    if(!huntBuilderClanOptions || !huntBuilderClanPanel) return;
    if(!huntBuilderSelectedTarget){
        huntBuilderClanPanel.hidden = true;
        huntBuilderClanOptions.replaceChildren();
        return;
    }

    const fragment = document.createDocumentFragment();
    ['instinct', 'mystic', 'valor'].forEach(clanKey => {
        const teamInfo = getPokemonTeamInfo(clanKey);
        const selected = huntBuilderSelectedClan === clanKey;
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'hunt-builder-option hunt-builder-option--clan';
        button.dataset.clan = clanKey;
        button.classList.toggle('is-active', selected);
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
        button.setAttribute('aria-label', teamInfo.label);
        button.title = teamInfo.label;

        const image = document.createElement('img');
        image.src = teamInfo.image;
        image.alt = '';
        image.loading = 'lazy';
        image.decoding = 'async';
        button.appendChild(image);
        button.addEventListener('click', () => {
            huntBuilderSelectedClan = clanKey;
            resetHuntBuilderRegenerationState();
            renderHuntBuilder();
        });
        fragment.appendChild(button);
    });

    huntBuilderClanOptions.replaceChildren(fragment);
    huntBuilderClanPanel.hidden = false;
}

function getHuntBuilderCandidateLevel(entry){
    const numericLevel = Number(entry?.level);
    if(Number.isFinite(numericLevel)) return numericLevel;
    return String(entry?.level || '').trim().toLowerCase() === 'ace' ? 100 : 0;
}

function getHuntBuilderEntrySubFunctionKeys(entry){
    return getPokemonEntrySubFunctions(entry).map(subFunction => subFunction.key);
}

function getHuntBuilderSelectedTargetKeys(){
    return new Set(
        [huntBuilderSelectedTarget?.name, ...(Array.isArray(huntBuilderSelectedTarget?.huntLookupNames) ? huntBuilderSelectedTarget.huntLookupNames : [])]
            .map(normalizePokemonSearchText)
            .filter(Boolean)
    );
}

function huntBuilderEntryCoversSelectedTarget(entry, selectedTypes = [], targetNaturalTypes = []){
    const selectedTypeKeys = normalizeTeamBuilderTypeList(selectedTypes);
    const movesetKeys = getTeamBuilderEntryMovesetKeys(entry);
    if(selectedTypeKeys.some(typeKey => movesetKeys.includes(typeKey))) return true;

    const offensivePassive = getTimesOffensivePassiveMeta(entry);
    if(offensivePassive.all) return true;

    return teamBuilderEntryOffensivePassiveHitsNaturalTypes(entry, targetNaturalTypes);
}

function getHuntBuilderCompatibleEntries(){
    const selectedTypes = normalizeTeamBuilderTypeList(huntBuilderSelectedTypes);
    const targetNaturalTypes = normalizeTeamBuilderTypeList(huntBuilderSelectedTarget?.naturalElements || []);

    return getTeamBuilderCatalogEntries()
        .filter(entry => {
            const explicitlyAllowed = isTeamBuilderExplicitlyAllowedEntry(entry);
            if(!entry || entry.catalogHidden) return false;
            if(entry.team !== huntBuilderSelectedClan) return false;
            if(!explicitlyAllowed && !hasPokemonVisibleRole({ key: entry.roleKey, label: entry.role })) return false;
            if(!explicitlyAllowed && !teamBuilderEntryMeetsLevelRequirement(entry)) return false;
            if(!huntBuilderEntryCoversSelectedTarget(entry, selectedTypes, targetNaturalTypes)) return false;
            return true;
        });
}

function getHuntBuilderSelectedTargetCombatMeta(){
    const naturalElements = normalizeTeamBuilderTypeList(huntBuilderSelectedTarget?.naturalElements || []);
    const moveset = normalizeTeamBuilderTypeList(huntBuilderSelectedTarget?.moveset || []);
    return {
        naturalElements,
        moveset,
        hasNaturalElements: naturalElements.length > 0,
        hasMoveset: moveset.length > 0
    };
}

function huntBuilderAllRounderCanTankSelectedTarget(entry){
    if(!entry || entry.roleKey !== 'all-rounder') return false;
    return teamBuilderTankCanHoldAndDamageHunt(
        entry,
        getHuntBuilderSelectedTargetCombatMeta(),
        huntBuilderSelectedTypes
    );
}

function sortHuntBuilderEntries(entries, kind){
    return [...entries].sort((left, right) => {
        const leftFunctions = getHuntBuilderEntrySubFunctionKeys(left);
        const rightFunctions = getHuntBuilderEntrySubFunctionKeys(right);
        if(kind === 'dps'){
            const leftStunner = leftFunctions.includes('stunner') ? 1 : 0;
            const rightStunner = rightFunctions.includes('stunner') ? 1 : 0;
            if(leftStunner !== rightStunner) return rightStunner - leftStunner;
        }
        const levelDifference = getHuntBuilderCandidateLevel(right) - getHuntBuilderCandidateLevel(left);
        if(levelDifference) return levelDifference;
        return left.name.localeCompare(right.name);
    });
}

function rotateHuntBuilderEntries(entries, offset){
    if(!entries.length) return [];
    const safeOffset = Math.abs(Number(offset) || 0) % entries.length;
    return [...entries.slice(safeOffset), ...entries.slice(0, safeOffset)];
}

function resetHuntBuilderRegenerationState(){
    huntBuilderGeneration = 0;
    huntBuilderLastTeamKeys = [];
    huntBuilderPreviousTeamKeys = [];
}

function getHuntBuilderTeamEntryKeys(slots = []){
    return (Array.isArray(slots) ? slots : [])
        .map(slot => getTeamBuilderEntryKey(slot?.entry))
        .filter(Boolean);
}

function buildHuntBuilderTeam(){
    const compatibleEntries = getHuntBuilderCompatibleEntries();
    const targetCombatMeta = getHuntBuilderSelectedTargetCombatMeta();
    const targetWeaknessTypes = normalizeTeamBuilderTypeList(huntBuilderSelectedTypes);
    const huntBuilderDpsSlotConfig = { id: 'hunt-builder-dps', kind: 'dps' };
    const usedKeys = new Set();
    const usedDuplicateKeys = new Set();
    const usedAceRoleKeys = new Set();
    const previousKeys = new Set(huntBuilderPreviousTeamKeys);
    const selectedBySlot = {};
    const pickEntry = (pool, slotId, offset = 0) => {
        const availableEntries = rotateHuntBuilderEntries(sortHuntBuilderEntries(pool, slotId.startsWith('dps') ? 'dps' : slotId), offset)
            .filter(entry => (
                !usedKeys.has(getTeamBuilderEntryKey(entry))
                && !usedDuplicateKeys.has(getTeamBuilderEntryDuplicateKey(entry))
                && !usedAceRoleKeys.has(getTeamBuilderAceRoleKey(entry))
            ));
        const available = availableEntries.find(entry => !previousKeys.has(getTeamBuilderEntryKey(entry)))
            || availableEntries[0]
            || null;
        if(!available) return null;
        usedKeys.add(getTeamBuilderEntryKey(available));
        usedDuplicateKeys.add(getTeamBuilderEntryDuplicateKey(available));
        const aceRoleKey = getTeamBuilderAceRoleKey(available);
        if(aceRoleKey) usedAceRoleKeys.add(aceRoleKey);
        selectedBySlot[slotId] = available;
        return available;
    };

    const finisherPool = compatibleEntries.filter(entry => (
        getHuntBuilderEntrySubFunctionKeys(entry).includes('finisher')
        && teamBuilderDamageEntryHitsAnyHuntWeakness(entry, targetCombatMeta, targetWeaknessTypes)
    ));
    const allRounderPool = compatibleEntries.filter(huntBuilderAllRounderCanTankSelectedTarget);
    const dpsPool = compatibleEntries.filter(entry => (
        teamBuilderEntryMatchesSlot(entry, huntBuilderDpsSlotConfig)
        && teamBuilderDamageEntryHitsAnyHuntWeakness(entry, targetCombatMeta, targetWeaknessTypes)
    ));

    pickEntry(allRounderPool, 'ar', huntBuilderGeneration);
    pickEntry(finisherPool, 'finisher', huntBuilderGeneration);
    HUNT_BUILDER_SLOT_CONFIGS
        .filter(slot => slot.kind === 'dps')
        .forEach((slot, index) => pickEntry(dpsPool, slot.id, huntBuilderGeneration + index));

    return HUNT_BUILDER_SLOT_CONFIGS.map(slot => ({
        ...slot,
        entry: selectedBySlot[slot.id] || null
    }));
}

function createHuntBuilderHeldIcon(item){
    const wrapper = document.createElement('span');
    wrapper.className = 'hunt-builder-team-card__held-item';
    wrapper.tabIndex = 0;
    wrapper.setAttribute('aria-label', item.name);

    const icon = document.createElement('img');
    icon.src = `helds/${item.file}`;
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    icon.onerror = () => {
        wrapper.hidden = true;
    };

    const tooltip = document.createElement('span');
    tooltip.className = 'hunt-builder-team-card__held-tooltip';
    tooltip.textContent = item.name;

    wrapper.append(icon, tooltip);
    return wrapper;
}

function getHuntBuilderHeldMovesetKeys(entry){
    const movesetKeys = getTeamBuilderEntryMovesetKeys(entry);
    if(movesetKeys.length <= 1) return movesetKeys;

    const selectedTypes = new Set(
        (Array.isArray(huntBuilderSelectedTypes) ? huntBuilderSelectedTypes : [])
            .map(normalizePokemonTypeKey)
            .filter(Boolean)
    );
    const selectedMovesets = movesetKeys.filter(typeKey => selectedTypes.has(typeKey));
    return selectedMovesets.length ? selectedMovesets : movesetKeys;
}

function getHuntBuilderHeldSuggestions(slot){
    if(slot?.kind === 'ar'){
        return [
            HUNT_BUILDER_HELD_ITEMS.assaultVest,
            HUNT_BUILDER_HELD_ITEMS.berryJuice,
            HUNT_BUILDER_HELD_ITEMS.leftovers
        ];
    }
    const movesetItems = getHuntBuilderHeldMovesetKeys(slot?.entry)
        .flatMap(typeKey => HUNT_BUILDER_HELD_ITEMS_BY_MOVESET[typeKey] || []);
    return [
        HUNT_BUILDER_HELD_ITEMS.choiceBand,
        ...movesetItems,
        HUNT_BUILDER_HELD_ITEMS.laggingTail
    ];
}

function createHuntBuilderHeldSuggestions(slot){
    const items = getHuntBuilderHeldSuggestions(slot);
    const menu = document.createElement('span');
    menu.className = 'hunt-builder-team-card__held-menu';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'hunt-builder-team-card__held-toggle';
    button.title = 'Itens sugeridos';
    button.setAttribute('aria-label', 'Abrir itens sugeridos');
    button.setAttribute('aria-expanded', 'false');

    const buttonImage = document.createElement('img');
    buttonImage.src = 'helds/Held-Button.png?v=20260614b';
    buttonImage.alt = '';
    buttonImage.setAttribute('aria-hidden', 'true');
    buttonImage.loading = 'lazy';
    buttonImage.decoding = 'async';
    setImageFallback(buttonImage, 'helds/Held-Button.png?v=20260614b');
    button.appendChild(buttonImage);

    const helds = document.createElement('span');
    helds.className = 'hunt-builder-team-card__helds';
    helds.setAttribute('aria-label', 'Sugestoes de held');
    helds.hidden = true;
    items.forEach(item => helds.appendChild(createHuntBuilderHeldIcon(item)));

    button.addEventListener('click', event => {
        event.stopPropagation();
        const isOpen = !helds.hidden;
        helds.hidden = isOpen;
        button.setAttribute('aria-expanded', isOpen ? 'false' : 'true');
    });

    menu.append(button, helds);
    return menu;
}

function createHuntBuilderTeamCard(slot){
    const card = document.createElement('article');
    card.className = 'hunt-builder-team-card';
    card.dataset.slot = slot.id;
    card.setAttribute('role', 'listitem');

    const header = document.createElement('div');
    header.className = 'hunt-builder-team-card__header';
    const slotLabel = document.createElement('strong');
    slotLabel.textContent = slot.label;
    header.appendChild(slotLabel);

    if(!slot.entry){
        card.classList.add('is-empty');
        const empty = document.createElement('p');
        empty.textContent = 'Nenhuma opcao compativel.';
        card.append(header, empty);
        return card;
    }

    const entry = slot.entry;
    const heldMenu = createHuntBuilderHeldSuggestions(slot);
    const roleIcon = createTeamBuilderRoleIcon(entry);
    header.appendChild(heldMenu);
    header.appendChild(roleIcon);

    const image = document.createElement('img');
    image.className = 'hunt-builder-team-card__pokemon';
    image.src = getPokemonImageSource(entry);
    image.alt = `Imagem de ${entry.name}`;
    image.loading = 'lazy';
    image.decoding = 'async';
    setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);

    const name = document.createElement('h4');
    name.textContent = entry.name;

    const moveset = document.createElement('div');
    moveset.className = 'hunt-builder-team-card__moveset';
    getTeamBuilderEntryMovesetKeys(entry).forEach(typeKey => {
        moveset.appendChild(createPokemonTypeToken(typeKey, { compact: true }));
    });

    const footer = document.createElement('div');
    footer.className = 'hunt-builder-team-card__footer';
    const subFunctions = getPokemonEntrySubFunctions(entry);
    if(subFunctions.length){
        footer.appendChild(createPokemonSubFunctionTokenRow(subFunctions));
    }

    card.append(header, image, name, moveset, footer);
    return card;
}

function renderHuntBuilderTeam(){
    if(!huntBuilderResultPanel || !huntBuilderTeam || !huntBuilderStatus) return;
    const ready = Boolean(
        huntBuilderSelectedTarget
        && huntBuilderSelectedTypes.length
        && huntBuilderSelectedClan
    );
    huntBuilderResultPanel.hidden = !ready;
    if(!ready){
        huntBuilderTeam.replaceChildren();
        huntBuilderStatus.textContent = '';
        huntBuilderLastTeamKeys = [];
        huntBuilderPreviousTeamKeys = [];
        if(huntBuilderMoveTeamBtn){
            huntBuilderMoveTeamBtn.disabled = true;
            huntBuilderMoveTeamBtn.title = 'Complete os 6 slots para mover ao Team Builder';
        }
        return;
    }

    const slots = buildHuntBuilderTeam();
    const fragment = document.createDocumentFragment();
    slots.forEach(slot => fragment.appendChild(createHuntBuilderTeamCard(slot)));
    huntBuilderTeam.replaceChildren(fragment);
    huntBuilderLastTeamKeys = getHuntBuilderTeamEntryKeys(slots);

    const filledCount = slots.filter(slot => slot.entry).length;
    const isComplete = filledCount === HUNT_BUILDER_SLOT_CONFIGS.length;
    if(huntBuilderMoveTeamBtn){
        huntBuilderMoveTeamBtn.disabled = !isComplete;
        huntBuilderMoveTeamBtn.title = isComplete
            ? 'Copiar o time sugerido para o Team Builder'
            : 'Complete os 6 slots para mover ao Team Builder';
    }
    const selectedTypeLabels = huntBuilderSelectedTypes.map(formatPokemonTypeLabel).join(', ');
    huntBuilderStatus.textContent = isComplete
        ? `Time completo para ${huntBuilderSelectedTarget.name} usando ${selectedTypeLabels}.`
        : `${filledCount}/6 slots encontrados. Selecione mais tipos ou outro cla para ampliar as opcoes.`;
}

function renderHuntBuilder(){
    renderHuntBuilderTarget();
    renderHuntBuilderTypeOptions();
    renderHuntBuilderClanOptions();
    renderHuntBuilderTeam();
}

function initializeHuntBuilderPage(){
    if(huntBuilderInitialized) return;
    huntBuilderInitialized = true;

    if(huntBuilderSearchInput){
        huntBuilderSearchInput.addEventListener('input', () => {
            if(
                huntBuilderSelectedTarget
                && normalizePokemonSearchText(huntBuilderSearchInput.value) !== huntBuilderSelectedTarget.searchName
            ){
                huntBuilderSelectedTarget = null;
                huntBuilderSelectedTypes = [];
                huntBuilderSelectedClan = '';
                resetHuntBuilderRegenerationState();
                renderHuntBuilder();
            }
            renderHuntBuilderSearchResults();
        });
        huntBuilderSearchInput.addEventListener('focus', () => {
            clearHuntBuilderSearchHideTimer();
            renderHuntBuilderSearchResults();
        });
        huntBuilderSearchInput.addEventListener('blur', () => {
            clearHuntBuilderSearchHideTimer();
            huntBuilderSearchHideTimer = window.setTimeout(hideHuntBuilderSearchResults, 140);
        });
        huntBuilderSearchInput.addEventListener('keydown', event => {
            if(event.key === 'Escape'){
                hideHuntBuilderSearchResults();
                return;
            }
            if(event.key !== 'Enter') return;
            const firstEntry = getHuntBuilderSearchEntries(huntBuilderSearchInput.value)[0];
            if(!firstEntry) return;
            event.preventDefault();
            huntBuilderSelectedTarget = firstEntry;
            huntBuilderSelectedTypes = [];
            huntBuilderSelectedClan = '';
            resetHuntBuilderRegenerationState();
            huntBuilderSearchInput.value = firstEntry.name;
            hideHuntBuilderSearchResults();
            renderHuntBuilder();
        });
    }

    if(huntBuilderRegenerateBtn){
        huntBuilderRegenerateBtn.addEventListener('click', () => {
            huntBuilderPreviousTeamKeys = huntBuilderLastTeamKeys.slice();
            huntBuilderGeneration += 1;
            renderHuntBuilderTeam();
        });
    }

    if(huntBuilderClearBtn){
        huntBuilderClearBtn.addEventListener('click', () => {
            huntBuilderSelectedTarget = null;
            huntBuilderSelectedTypes = [];
            huntBuilderSelectedClan = '';
            resetHuntBuilderRegenerationState();
            if(huntBuilderSearchInput) huntBuilderSearchInput.value = '';
            hideHuntBuilderSearchResults();
            renderHuntBuilder();
        });
    }

    if(huntBuilderMoveTeamBtn){
        huntBuilderMoveTeamBtn.addEventListener('click', () => {
            const slots = buildHuntBuilderTeam();
            const slotMap = {
                ar: 'tank-ar',
                'dps-1': 'dps-1',
                'dps-2': 'dps-2',
                'dps-3': 'dps-3',
                'dps-4': 'dps-4',
                finisher: 'finisher'
            };
            const nextSelections = {};
            slots.forEach(slot => {
                const targetSlotId = slotMap[slot.id];
                if(targetSlotId && slot.entry) nextSelections[targetSlotId] = slot.entry;
            });
            if(Object.keys(nextSelections).length !== HUNT_BUILDER_SLOT_CONFIGS.length) return;
            teamBuilderSelections = nextSelections;
            teamBuilderIgnoreTankForHunts = false;
            teamBuilderActiveSlotId = TEAM_BUILDER_SLOT_CONFIGS.find(slot => !teamBuilderSelections[slot.id])?.id
                || TEAM_BUILDER_SLOT_CONFIGS[0]?.id
                || '';
            teamBuilderFilters = {
                search: '',
                clan: 'all',
                subFunctions: [],
                roles: [],
                type: 'all'
            };
            if(teamBuilderSearchInput) teamBuilderSearchInput.value = '';
            teamBuilderHuntsVisible = true;
            teamBuilderHuntsLoading = false;
            localStorage.setItem('selectedTab', 'team-builder');
            showTeamBuilder();
        });
    }
}

function normalizeProfessionRouteKey(value){
    const normalized = String(value || '').trim().toLowerCase().replace(/^#/, '');
    return ['designer', 'breeder', 'photographer', 'researcher'].includes(normalized) ? normalized : '';
}

function setProfessionDetailView(professionKey = '', options = {}){
    const normalizedProfessionKey = normalizeProfessionRouteKey(professionKey);
    const hero = contentProfessions?.querySelector('.professions-hero') || null;
    const selector = document.getElementById('professions-selector');
    const details = Array.from(contentProfessions?.querySelectorAll('.profession-detail') || []);
    const activeDetail = normalizedProfessionKey
        ? document.getElementById(`profession-${normalizedProfessionKey}-detail`)
        : null;
    const showDetail = Boolean(activeDetail);
    const shouldUpdateUrl = options.updateUrl !== false;

    activeProfessionKey = showDetail ? normalizedProfessionKey : '';
    if(hero) hero.hidden = showDetail;
    if(selector) selector.hidden = showDetail;
    details.forEach(detail => {
        detail.hidden = detail !== activeDetail;
    });

    if(shouldUpdateUrl && contentProfessions && !contentProfessions.hidden){
        updateUrl({ historyMode: options.historyMode || 'push' });
    }

    if(showDetail && activeDetail){
        requestAnimationFrame(() => {
            activeDetail.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
    }
}

function initializeProfessionsPage(){
    if(professionsPageInitialized) return;

    initializeProfessionsImageModal();

    document.querySelectorAll('[data-profession-select]').forEach(button => {
        button.addEventListener('click', () => {
            const professionKey = button.getAttribute('data-profession-select') || '';
            setProfessionDetailView(professionKey, { historyMode: 'push' });
        });
    });

    document.querySelectorAll('[data-profession-back]').forEach(button => {
        button.addEventListener('click', () => {
            setProfessionDetailView('', { historyMode: 'push' });
            const selector = document.getElementById('professions-selector');
            if(selector){
                requestAnimationFrame(() => {
                    selector.scrollIntoView({ behavior: 'smooth', block: 'start' });
                });
            }
        });
    });

    professionsPageInitialized = true;
}

function initializeProfessionsImageModal(){
    if(professionsImageModalInitialized) return;

    const modal = document.getElementById('profession-image-modal');
    const viewport = document.getElementById('profession-image-modal-viewport');
    const canvas = document.getElementById('profession-image-modal-canvas');
    const image = document.getElementById('profession-image-modal-image');
    const title = document.getElementById('profession-image-modal-title');
    const closeBtn = modal?.querySelector('.modal-close') || null;
    const prevBtn = modal?.querySelector('[data-profession-image-nav="prev"]') || null;
    const nextBtn = modal?.querySelector('[data-profession-image-nav="next"]') || null;
    if(!modal || !viewport || !canvas || !image) return;

    setupZoomableImageModal(modal, viewport, canvas, image);
    let currentImageGroup = [];
    let currentImageIndex = -1;

    const getProfessionImageCaption = (sourceImage) => sourceImage.closest('figure')?.querySelector('figcaption')?.textContent?.trim()
        || sourceImage.getAttribute('alt')
        || 'Imagem';

    const getProfessionImageGroupContainer = (sourceImage) => {
        const selectors = [
            '.profession-rank-gallery article',
            '.profession-image-stack',
            '.profession-craft-grid',
            '.profession-resource-preview',
            '.profession-inline-figure',
            'figure'
        ];
        for(const selector of selectors){
            const container = sourceImage.closest(selector);
            if(container) return container;
        }
        return sourceImage.parentElement || contentProfessions;
    };

    const getProfessionImageGroup = (sourceImage) => {
        const container = getProfessionImageGroupContainer(sourceImage);
        if(!container) return [sourceImage];
        return Array.from(container.querySelectorAll('img')).filter(candidate => {
            if(candidate.id === 'profession-image-modal-image') return false;
            if(candidate.closest('[data-profession-select]')) return false;
            return candidate instanceof HTMLImageElement;
        });
    };

    const updateProfessionImageNav = () => {
        const hasNavigation = currentImageGroup.length > 1;
        if(prevBtn) prevBtn.hidden = !hasNavigation;
        if(nextBtn) nextBtn.hidden = !hasNavigation;
        if(prevBtn) prevBtn.disabled = !hasNavigation;
        if(nextBtn) nextBtn.disabled = !hasNavigation;
    };

    const setModalImageFromSource = (sourceImage) => {
        if(!(sourceImage instanceof HTMLImageElement)) return false;
        const src = sourceImage.currentSrc || sourceImage.getAttribute('src') || '';
        if(!src) return false;
        const caption = getProfessionImageCaption(sourceImage);
        image.src = src;
        image.alt = sourceImage.getAttribute('alt') || caption;
        if(title) title.textContent = caption;
        updateProfessionImageNav();
        if(modal.getAttribute('aria-hidden') === 'false' && typeof modal._onOpen === 'function'){
            modal._onOpen();
        }
        return true;
    };

    const navigateProfessionImage = (direction) => {
        if(currentImageGroup.length <= 1) return;
        const step = direction === 'prev' ? -1 : 1;
        const nextIndex = (currentImageIndex + step + currentImageGroup.length) % currentImageGroup.length;
        const nextImage = currentImageGroup[nextIndex];
        if(setModalImageFromSource(nextImage)){
            currentImageIndex = nextIndex;
        }
    };

    const closeModal = () => {
        if(modal.getAttribute('aria-hidden') === 'true') return;
        modal.setAttribute('aria-hidden', 'true');
        currentImageGroup = [];
        currentImageIndex = -1;
        updateProfessionImageNav();
        if(typeof modal._onClose === 'function') modal._onClose();
        syncBasicModalPageState();
    };

    const openImage = (sourceImage) => {
        if(!(sourceImage instanceof HTMLImageElement)) return;
        currentImageGroup = getProfessionImageGroup(sourceImage);
        currentImageIndex = Math.max(0, currentImageGroup.indexOf(sourceImage));
        if(!setModalImageFromSource(sourceImage)) return;
        modal.setAttribute('aria-hidden', 'false');
        syncBasicModalPageState();
        if(typeof modal._onOpen === 'function') modal._onOpen();
    };

    contentProfessions?.addEventListener('click', (event) => {
        const sourceImage = event.target.closest('img');
        if(!sourceImage || sourceImage.id === 'profession-image-modal-image') return;
        if(sourceImage.closest('[data-profession-select]')) return;
        openImage(sourceImage);
    });

    contentProfessions?.addEventListener('keydown', (event) => {
        if(event.key !== 'Enter' && event.key !== ' ') return;
        const sourceImage = event.target.closest('img');
        if(!sourceImage || sourceImage.id === 'profession-image-modal-image') return;
        if(sourceImage.closest('[data-profession-select]')) return;
        event.preventDefault();
        openImage(sourceImage);
    });

    contentProfessions?.querySelectorAll('img').forEach(img => {
        if(img.id === 'profession-image-modal-image') return;
        if(img.closest('[data-profession-select]')) return;
        img.tabIndex = 0;
        img.setAttribute('role', 'button');
        const label = img.closest('figure')?.querySelector('figcaption')?.textContent?.trim()
            || img.getAttribute('alt')
            || 'imagem';
        img.setAttribute('aria-label', `Abrir imagem: ${label}`);
    });

    if(closeBtn) closeBtn.addEventListener('click', closeModal);
    if(prevBtn) prevBtn.addEventListener('click', () => navigateProfessionImage('prev'));
    if(nextBtn) nextBtn.addEventListener('click', () => navigateProfessionImage('next'));
    modal.addEventListener('click', (event) => {
        if(event.target === modal) closeModal();
    });
    window.addEventListener('keydown', (event) => {
        if(modal.getAttribute('aria-hidden') === 'true') return;
        if(event.key === 'Escape'){
            closeModal();
        } else if(event.key === 'ArrowLeft'){
            event.preventDefault();
            navigateProfessionImage('prev');
        } else if(event.key === 'ArrowRight'){
            event.preventDefault();
            navigateProfessionImage('next');
        }
    });
    updateProfessionImageNav();

    professionsImageModalInitialized = true;
}

let rotomPhoneChecklistInitialized = false;

function initializeRotomPhoneChecklist(){
    if(!contentRotomPhone || rotomPhoneChecklistInitialized) return;
    const storageKey = 'pokeEffectiveness.rotomPhone.completedTasks';
    const stepStorageKey = 'pokeEffectiveness.rotomPhone.taskSteps';
    const checklist = contentRotomPhone.querySelector('[data-rotom-checklist]');
    const resetButton = contentRotomPhone.querySelector('[data-rotom-reset]');
    const searchInput = contentRotomPhone.querySelector('[data-rotom-search-input]');
    const searchClearButton = contentRotomPhone.querySelector('[data-rotom-search-clear]');
    const searchSummary = contentRotomPhone.querySelector('[data-rotom-search-summary]');
    const searchResults = contentRotomPhone.querySelector('[data-rotom-search-results]');
    if(!checklist) return;
    const steppedTasks = {
        'primeiros-passos-combate': [
            '1 Etapa: Derrote 10 Pidgey.',
            '2 Etapa: Derrote 10 Spearow.',
            '3 Etapa: Derrote 10 Caterpie.',
            '4 Etapa: Derrote 10 Geodude.',
            '5 Etapa: Derrote 10 Oddish.'
        ],
        'coletando-info-pidgey': [
            '1 Etapa: Colete informa\u00e7\u00f5es dos seguintes pok\u00e9mon utilizando a Pok\u00e9dex: Pidgey.',
            '2 Etapa: Colete informa\u00e7\u00f5es dos seguintes pok\u00e9mon utilizando a Pok\u00e9dex: Oddish.',
            '3 Etapa: Colete informa\u00e7\u00f5es dos seguintes pok\u00e9mon utilizando a Pok\u00e9dex: Geodude.',
            '4 Etapa: Colete informa\u00e7\u00f5es dos seguintes pok\u00e9mon utilizando a Pok\u00e9dex: Spearow.',
            '5 Etapa: Colete informa\u00e7\u00f5es dos seguintes pok\u00e9mon utilizando a Pok\u00e9dex: Caterpie.'
        ]
    };
    let searchEntries = [];
    let searchHighlightTimeout = 0;

    const normalizeSearchValue = (value) => normalizePokemonSearchText(value).replace(/[^a-z0-9]+/g, ' ').trim();
    const getTrimmedText = (element) => String(element?.textContent || '').replace(/\s+/g, ' ').trim();

    const getRotomPhoneTaskById = (taskId) => (
        Array.from(checklist.querySelectorAll('[data-rotom-task]'))
            .find(taskButton => taskButton.getAttribute('data-rotom-task') === taskId) || null
    );

    const buildSearchEntries = () => {
        searchEntries = [];
        checklist.querySelectorAll('[data-rotom-city]').forEach((cityPanel, cityIndex) => {
            const cityName = getTrimmedText(cityPanel.querySelector('.rotom-phone-city-panel__title strong'));
            cityPanel.querySelectorAll('[data-rotom-task]').forEach((taskButton, taskIndex) => {
                const taskId = taskButton.getAttribute('data-rotom-task') || '';
                const title = getTrimmedText(taskButton.querySelector('.rotom-phone-task__title-row strong'));
                const baseDescription = getTrimmedText(taskButton.querySelector('.rotom-phone-task__description'));
                const level = getTrimmedText(taskButton.querySelector('.rotom-phone-task__level'));
                const rewards = getTrimmedText(taskButton.querySelector('.rotom-phone-task__rewards'))
                    .replace(/^Recompensas:\s*/i, '');
                const steps = steppedTasks[taskId] || [baseDescription];
                steps.forEach((stepText, stepIndex) => {
                    const entry = {
                        taskId,
                        title,
                        cityName,
                        level,
                        rewards,
                        stepText,
                        stepIndex,
                        stepTotal: steps.length,
                        order: (cityIndex * 1000) + (taskIndex * 10) + stepIndex
                    };
                    entry.searchKey = normalizeSearchValue([
                        cityName,
                        title,
                        level,
                        rewards,
                        stepText
                    ].join(' '));
                    searchEntries.push(entry);
                });
            });
        });
    };

    const createSearchResultCard = (entry) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'rotom-phone-search__result';
        button.dataset.rotomSearchTask = entry.taskId;

        const head = document.createElement('span');
        head.className = 'rotom-phone-search__result-head';

        const titleWrap = document.createElement('span');
        titleWrap.className = 'rotom-phone-search__result-title';

        const city = document.createElement('span');
        city.className = 'rotom-phone-search__city';
        city.textContent = entry.cityName || 'Cidade';

        const title = document.createElement('strong');
        title.textContent = entry.title || 'Task';
        titleWrap.append(city, title);

        const step = document.createElement('span');
        step.className = 'rotom-phone-search__step';
        step.textContent = entry.stepTotal > 1 ? `Etapa ${entry.stepIndex + 1}/${entry.stepTotal}` : 'Etapa 1/1';
        head.append(titleWrap, step);

        const description = document.createElement('span');
        description.className = 'rotom-phone-search__description';
        description.textContent = entry.stepText || '';

        const meta = document.createElement('span');
        meta.className = 'rotom-phone-search__meta';

        if(entry.level){
            const level = document.createElement('span');
            level.className = 'rotom-phone-search__pill';
            level.textContent = entry.level;
            meta.appendChild(level);
        }

        if(entry.rewards){
            const rewards = document.createElement('span');
            rewards.className = 'rotom-phone-search__pill';
            rewards.textContent = `Recompensas: ${entry.rewards}`;
            meta.appendChild(rewards);
        }

        button.append(head, description, meta);
        return button;
    };

    const renderSearchResults = () => {
        if(!searchInput || !searchSummary || !searchResults) return;
        const rawQuery = String(searchInput.value || '').trim();
        const normalizedQuery = normalizeSearchValue(rawQuery);
        if(searchClearButton) searchClearButton.hidden = !rawQuery;
        searchResults.replaceChildren();

        if(normalizedQuery.length < 2){
            searchSummary.textContent = 'Digite pelo menos 2 caracteres para pesquisar.';
            searchResults.hidden = true;
            return;
        }

        const tokens = normalizedQuery.split(/\s+/).filter(Boolean);
        const matches = searchEntries
            .filter(entry => tokens.every(token => entry.searchKey.includes(token)))
            .sort((left, right) => left.order - right.order);

        if(!matches.length){
            searchSummary.textContent = `Nenhuma task encontrada para "${rawQuery}".`;
            searchResults.hidden = true;
            return;
        }

        searchSummary.textContent = `${matches.length} ocorrencia${matches.length === 1 ? '' : 's'} encontrada${matches.length === 1 ? '' : 's'} para "${rawQuery}".`;
        const fragment = document.createDocumentFragment();
        matches.forEach(entry => fragment.appendChild(createSearchResultCard(entry)));
        searchResults.appendChild(fragment);
        searchResults.hidden = false;
    };

    const focusSearchResultTask = (taskId) => {
        const taskButton = getRotomPhoneTaskById(taskId);
        if(!taskButton) return;
        const cityPanel = taskButton.closest('[data-rotom-city]');
        if(cityPanel instanceof HTMLDetailsElement){
            cityPanel.open = true;
        }
        window.clearTimeout(searchHighlightTimeout);
        checklist.querySelectorAll('.is-search-target').forEach(element => {
            element.classList.remove('is-search-target');
        });
        taskButton.classList.add('is-search-target');
        taskButton.scrollIntoView({ behavior: 'smooth', block: 'center' });
        taskButton.focus({ preventScroll: true });
        searchHighlightTimeout = window.setTimeout(() => {
            taskButton.classList.remove('is-search-target');
        }, 2400);
    };

    const readCompleted = () => {
        try {
            const parsed = JSON.parse(localStorage.getItem(storageKey) || '[]');
            return new Set(Array.isArray(parsed) ? parsed : []);
        } catch {
            return new Set();
        }
    };

    const readStepProgress = () => {
        try {
            const parsed = JSON.parse(localStorage.getItem(stepStorageKey) || '{}');
            return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
        } catch {
            return {};
        }
    };

    const writeCompleted = (completed) => {
        try {
            localStorage.setItem(storageKey, JSON.stringify(Array.from(completed)));
        } catch {}
    };

    const writeStepProgress = (progress) => {
        try {
            localStorage.setItem(stepStorageKey, JSON.stringify(progress));
        } catch {}
    };

    let completedTasks = readCompleted();
    let stepProgress = readStepProgress();

    const updateProgress = () => {
        checklist.querySelectorAll('[data-rotom-city]').forEach((cityPanel) => {
            const tasks = Array.from(cityPanel.querySelectorAll('[data-rotom-task]'));
            const done = tasks.filter((task) => task.classList.contains('is-complete')).length;
            const progress = cityPanel.querySelector('[data-rotom-city-progress]');
            if(!progress) return;
            const isComplete = done === tasks.length;
            progress.classList.toggle('is-complete', isComplete);
            progress.textContent = isComplete
                ? `${done}/${tasks.length} feitas`
                : `${tasks.length - done} restantes`;
        });
    };

    const applyCompletedState = () => {
        checklist.querySelectorAll('[data-rotom-task]').forEach((taskButton) => {
            const taskId = taskButton.getAttribute('data-rotom-task');
            const steps = steppedTasks[taskId];
            const isComplete = completedTasks.has(taskId);
            if(steps){
                const rawIndex = Number(stepProgress[taskId] || 0);
                const stepIndex = isComplete ? steps.length - 1 : Math.min(Math.max(rawIndex, 0), steps.length - 1);
                const description = taskButton.querySelector('.rotom-phone-task__description');
                const count = taskButton.querySelector('.rotom-phone-task__count');
                if(description) description.textContent = steps[stepIndex];
                if(count) count.textContent = `${stepIndex + 1}/${steps.length}`;
            }
            taskButton.classList.toggle('is-complete', isComplete);
            taskButton.setAttribute('aria-pressed', isComplete ? 'true' : 'false');
        });
        updateProgress();
    };

    checklist.addEventListener('click', (event) => {
        const taskButton = event.target.closest('[data-rotom-task]');
        if(!taskButton || !checklist.contains(taskButton)) return;
        const taskId = taskButton.getAttribute('data-rotom-task');
        if(!taskId) return;
        const steps = steppedTasks[taskId];
        if(steps){
            if(completedTasks.has(taskId)){
                completedTasks.delete(taskId);
                stepProgress[taskId] = 0;
            } else {
                const currentStep = Math.min(Math.max(Number(stepProgress[taskId] || 0), 0), steps.length - 1);
                if(currentStep < steps.length - 1){
                    stepProgress[taskId] = currentStep + 1;
                } else {
                    completedTasks.add(taskId);
                    stepProgress[taskId] = steps.length - 1;
                }
            }
        } else if(completedTasks.has(taskId)){
            completedTasks.delete(taskId);
        } else {
            completedTasks.add(taskId);
        }
        writeCompleted(completedTasks);
        writeStepProgress(stepProgress);
        applyCompletedState();
    });

    if(resetButton){
        resetButton.addEventListener('click', () => {
            completedTasks = new Set();
            stepProgress = {};
            writeCompleted(completedTasks);
            writeStepProgress(stepProgress);
            applyCompletedState();
        });
    }

    if(searchInput){
        buildSearchEntries();
        searchInput.addEventListener('input', renderSearchResults);
    }

    if(searchClearButton){
        searchClearButton.addEventListener('click', () => {
            if(searchInput) searchInput.value = '';
            renderSearchResults();
            searchInput?.focus();
        });
    }

    if(searchResults){
        searchResults.addEventListener('click', (event) => {
            const resultButton = event.target.closest('[data-rotom-search-task]');
            if(!resultButton || !searchResults.contains(resultButton)) return;
            focusSearchResultTask(resultButton.getAttribute('data-rotom-search-task') || '');
        });
    }

    applyCompletedState();
    renderSearchResults();
    rotomPhoneChecklistInitialized = true;
}

function showRotomPhone(){
    clearTabHighlights();
    setActiveTabTheme('rotom-phone');
    setVisiblePanel(contentRotomPhone);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = 'Rotom Phone';
    updateBrowserTitle();
    ensurePanelFragmentLoaded(contentRotomPhone).then(() => {
        initializeRotomPhoneChecklist();
        if(useGsap && contentRotomPhone && !contentRotomPhone.hidden){
            gsap.from(contentRotomPhone, { opacity: 0, y: -10, duration: 0.4 });
            gsap.from(contentRotomPhone.querySelectorAll('.rotom-phone-section'), { opacity: 0, y: 18, duration: 0.45, stagger: 0.06 });
        }
    }).catch(error => console.error('Rotom Phone load failed', error));
    updateUrl();
}

function showInteractiveMap(){
    if(contentInteractiveMap?.dataset.panelFragment && contentInteractiveMap.dataset.panelLoaded !== 'true'){
        setVisiblePanel(contentInteractiveMap);
        ensurePanelFragmentLoaded(contentInteractiveMap)
            .then(() => showInteractiveMap())
            .catch(error => console.error('Interactive map panel load failed', error));
        return;
    }
    const requestedMarkerRoute = String(location.pathname || '').match(/\/mapa-interativo\/([a-z0-9][a-z0-9-]*)\/?$/i);
    const requestedMarkerSlug = requestedMarkerRoute?.[1] || INITIAL_INTERACTIVE_MAP_MARKER_SLUG;
    const requestedMarkerPath = requestedMarkerSlug ? `/mapa-interativo/${requestedMarkerSlug}` : '';
    if(contentInteractiveMap){
        contentInteractiveMap.dataset.requestedMarkerSlug = requestedMarkerSlug;
    }
    clearTabHighlights();
    setActiveTabTheme('mapa-interativo');
    setVisiblePanel(contentInteractiveMap);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = 'Mapa Interativo';
    updateBrowserTitle();
    ensureInteractiveMapAssetsReady().then(() => {
        const initializeMap = typeof window.refreshInteractiveMapPage === 'function'
            ? window.refreshInteractiveMapPage
            : window.initInteractiveMapPage;
        if(typeof initializeMap !== 'function') throw new Error('Inicializador do mapa indisponivel.');
        return initializeMap()
            .then(() => {
                if(requestedMarkerPath && location.pathname !== requestedMarkerPath){
                    history.replaceState(history.state, '', `${requestedMarkerPath}${location.search}${location.hash}`);
                }
                window.setTimeout(() => {
                    requestAnimationFrame(() => {
                        if(typeof window.focusInteractiveMapRoute === 'function'){
                            window.focusInteractiveMapRoute();
                        }
                    });
                }, 250);
            });
    }).catch(error => console.error('Interactive map load failed', error));
    updateUrl();
}

