function getLigaPokemonGymPokemonImage(name){
    const fileName = String(name || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-');
    const aliases = {
        'mr-mime': 'mrmime'
    };
    return `pokemons/1gen/${aliases[fileName] || fileName}.png`;
}

let ligaPokemonPageInitialized = false;

function bindLigaPokemonMapButton(button, options = {}){
    if(!button || button.dataset.ligaMapBound === 'true') return;
    const markerId = String(options.markerId || button.dataset.ligaMapMarker || '').trim();
    const title = String(options.title || button.dataset.ligaMapTitle || 'Liga Pokémon').trim();
    const image = String(options.image || button.dataset.ligaMapImage || '').trim();
    if(!markerId) return;
    button.dataset.ligaMapBound = 'true';
    button.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        openInteractiveMapMarker(markerId, {
            name: title,
            image,
            trigger: button
        });
    });
}

function createLigaPokemonMapButton(options = {}){
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'liga-pokemon-map-btn liga-pokemon-gym-card__map-btn';
    button.setAttribute('aria-label', `Abrir localização de ${options.title || 'Liga Pokémon'} no mapa interativo`);
    button.title = 'Localização';
    button.textContent = '🗺️';
    bindLigaPokemonMapButton(button, options);
    return button;
}

function initializeLigaPokemonPage(){
    if(!contentLigaPokemon || ligaPokemonPageInitialized) return;
    const storageKey = 'pokeEffectiveness.ligaPokemon.kantoCaptured';
    const kantoGrid = contentLigaPokemon.querySelector('#liga-pokemon-kanto-grid');
    const kantoSummary = contentLigaPokemon.querySelector('#liga-pokemon-kanto-summary');
    const kantoProgress = contentLigaPokemon.querySelector('.liga-pokemon-kanto-progress');
    const kantoProgressFill = contentLigaPokemon.querySelector('[data-liga-kanto-progress]');
    const resetButton = contentLigaPokemon.querySelector('[data-liga-kanto-reset]');

    const readCaptured = () => {
        try {
            const parsed = JSON.parse(localStorage.getItem(storageKey) || '[]');
            return new Set((Array.isArray(parsed) ? parsed : []).map(Number).filter(Number.isFinite));
        } catch {
            return new Set();
        }
    };

    const writeCaptured = captured => {
        try {
            localStorage.setItem(storageKey, JSON.stringify(Array.from(captured).sort((a, b) => a - b)));
        } catch {}
    };

    let captured = readCaptured();

    const updateKantoProgress = () => {
        const capturedCount = LIGA_POKEMON_KANTO.filter(entry => captured.has(entry.dex)).length;
        const total = LIGA_POKEMON_KANTO.length;
        const percentage = total ? (capturedCount / total) * 100 : 0;
        if(kantoSummary) kantoSummary.textContent = `${capturedCount} de ${total} capturados`;
        if(kantoProgress){
            kantoProgress.setAttribute('aria-valuemax', String(total));
            kantoProgress.setAttribute('aria-valuenow', String(capturedCount));
        }
        if(kantoProgressFill) kantoProgressFill.style.width = `${percentage}%`;
        kantoGrid?.querySelectorAll('[data-liga-kanto-dex]').forEach(card => {
            const dex = Number(card.getAttribute('data-liga-kanto-dex'));
            const isCaptured = captured.has(dex);
            card.classList.toggle('is-captured', isCaptured);
            card.setAttribute('aria-pressed', isCaptured ? 'true' : 'false');
            const name = card.getAttribute('data-liga-kanto-name') || 'Pokémon';
            card.setAttribute('aria-label', `${name}: ${isCaptured ? 'capturado' : 'não capturado'}`);
        });
    };

    contentLigaPokemon.querySelectorAll('[data-liga-gym-grid]').forEach(grid => {
        const mode = grid.getAttribute('data-liga-gym-grid') === 'hard' ? 'Hard' : 'Easy';
        const fragment = document.createDocumentFragment();
        LIGA_POKEMON_GYMS.forEach((gym, index) => {
            const article = document.createElement('article');
            article.className = 'liga-pokemon-gym-card';
            setTypeToneVariables(article, gym.specialty);
            const specialtyLabel = gym.specialtyLabel || `Especialidade ${gym.specialty}`;
            const teamMarkup = gym.team.map(name => {
                const isBoss = name === gym.boss;
                const weaknessTypes = LIGA_POKEMON_GYM_WEAKNESSES[name] || [];
                const weaknessMarkup = weaknessTypes.map(type => {
                    const label = formatPokemonTypeLabel(type);
                    return `<span title="${label}" aria-label="Fraqueza ${label}"><img src="icons-type/${type}.png" alt=""></span>`;
                }).join('');
                return `<div class="liga-pokemon-gym-pokemon${isBoss ? ' is-boss' : ''}" role="listitem">
                    <img src="${getLigaPokemonGymPokemonImage(name)}" alt="${name}" loading="lazy" decoding="async">
                    <strong>${name}</strong>
                    ${isBoss ? '<img class="liga-pokemon-boss-emblem" src="hunt-builder/hunt_symbol.png?v=20260627a" alt="Boss" title="Boss" loading="lazy" decoding="async">' : ''}
                    <div class="liga-pokemon-gym-pokemon__weaknesses" aria-label="Fraquezas de ${name}"><small>Fraquezas</small>${weaknessMarkup}</div>
                </div>`;
            }).join('');
            article.innerHTML = `
                <div class="liga-pokemon-gym-card__head">
                    <span>Ginásio ${index + 1} · ${mode}</span>
                    <img class="liga-pokemon-gym-card__trainer" src="liga-pokemon/assets/${gym.sprite}-gen3.png" alt="${gym.leader}" loading="lazy" decoding="async">
                    <strong>${gym.leader}</strong>
                    <small>${gym.city} · ${specialtyLabel}</small>
                </div>
                <div class="liga-pokemon-gym-card__block"><span>Mecânica</span><p>${gym.mechanic}</p></div>
                <div class="liga-pokemon-gym-card__block liga-pokemon-gym-card__block--team"><span>Pokémon</span><div class="liga-pokemon-gym-team" role="list" aria-label="Equipe de ${gym.leader} no modo ${mode}">${teamMarkup}</div></div>
                `;
            article.appendChild(createLigaPokemonMapButton({
                markerId: gym.mapMarkerId,
                title: `Ginásio de ${gym.leader}`,
                image: `liga-pokemon/assets/${gym.sprite}-gen3.png`
            }));
            fragment.appendChild(article);
        });
        grid.replaceChildren(fragment);
    });

    contentLigaPokemon.querySelectorAll('[data-liga-map-marker]').forEach(button => {
        bindLigaPokemonMapButton(button);
    });

    if(kantoGrid){
        const fragment = document.createDocumentFragment();
        LIGA_POKEMON_KANTO.forEach(entry => {
            const card = document.createElement('button');
            card.type = 'button';
            card.className = 'liga-pokemon-kanto-card';
            card.setAttribute('role', 'listitem');
            card.dataset.ligaKantoDex = String(entry.dex);
            card.dataset.ligaKantoName = entry.name;

            const image = document.createElement('img');
            image.src = `pokemons/1gen/${entry.sprite}.png`;
            image.alt = '';
            image.loading = 'lazy';
            image.decoding = 'async';

            const name = document.createElement('strong');
            name.textContent = entry.name;
            const dex = document.createElement('small');
            dex.textContent = `#${String(entry.dex).padStart(3, '0')}`;
            card.append(image, name, dex);
            fragment.appendChild(card);
        });
        kantoGrid.replaceChildren(fragment);
        kantoGrid.addEventListener('click', event => {
            const card = event.target.closest('[data-liga-kanto-dex]');
            if(!card || !kantoGrid.contains(card)) return;
            const dex = Number(card.getAttribute('data-liga-kanto-dex'));
            if(captured.has(dex)) captured.delete(dex);
            else captured.add(dex);
            writeCaptured(captured);
            updateKantoProgress();
        });
    }

    resetButton?.addEventListener('click', () => {
        captured = new Set();
        writeCaptured(captured);
        updateKantoProgress();
    });

    updateKantoProgress();
    ligaPokemonPageInitialized = true;
}

function showLigaPokemon(){
    clearTabHighlights();
    setActiveTabTheme('liga-pokemon');
    setVisiblePanel(contentLigaPokemon);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = 'Liga Pokémon';
    updateBrowserTitle();
    ensurePanelFragmentLoaded(contentLigaPokemon).then(() => {
        initializeLigaPokemonPage();
        if(useGsap && contentLigaPokemon && !contentLigaPokemon.hidden){
            gsap.from(contentLigaPokemon, { opacity: 0, y: -10, duration: 0.4 });
            gsap.from(contentLigaPokemon.querySelectorAll('.liga-pokemon-section, .liga-pokemon-collapsible'), { opacity: 0, y: 18, duration: 0.45, stagger: 0.05 });
        }
    }).catch(error => console.error('Liga Pokemon load failed', error));
    updateUrl();
}

const HELD_FUSION_HELDS = [
    { key: 'choiceband', name: 'Choice Band', file: 'helds/choiceband.png', effect: 'Dano', description: 'Aumenta o dano em', values: [2, 4, 6, 9, 12, 16, 20] },
    { key: 'choicespecs', name: 'Choice Specs', file: 'helds/choicespecs.png', effect: 'Chance crit.', description: 'Aumenta chance de crítico em', values: [8, 10, 12, 14, 16, 20, 24] },
    { key: 'assaultvest', name: 'Assault Vest', file: 'helds/assaultvest.png', effect: 'Defesa', description: 'Aumenta a defesa do Pokémon em', values: [2, 4, 6, 9, 12, 16, 20] },
    { key: 'lifeorb', name: 'Life Orb', file: 'helds/lifeorb.png', effect: 'Vida', description: 'Aumenta a vida do Pokémon em', values: [2, 4, 6, 9, 12, 16, 20] },
    { key: 'choicescarf', name: 'Choice Scarf', file: 'helds/choicescarf.png', effect: 'Defesa critica', description: 'Aumenta a chance de defesa crítica em', values: [8, 10, 12, 14, 16, 20, 24] },
    { key: 'luckyegg', name: 'Lucky Egg', file: 'helds/luckyegg.png', effect: 'Experiência bônus', description: 'Aumenta a experiência ganha em', values: [10, 15, 20, 25, 30, 35, 40] },
    { key: 'amuletcoin', name: 'Amulet Coin', file: 'helds/amuletcoin.png', effect: 'Chance de item', description: 'Aumenta a chance de conseguir um drop bônus em', values: [5, 20, 35, 50, 65, 80, 100] }
];

const HELD_FUSION_STEPS = {
    1: { cost: 10000, costLabel: '10.000 (10K)', baseChance: 5, boosterChance: 90, coins: 1 },
    2: { cost: 25000, costLabel: '25.000 (25K)', baseChance: 8, boosterChance: 84, coins: 2 },
    3: { cost: 50000, costLabel: '50.000 (50K)', baseChance: 10, boosterChance: 80, coins: 3 },
    4: { cost: 200000, costLabel: '200.000 (200K)', baseChance: 15, boosterChance: 70, coins: 9 },
    5: { cost: 500000, costLabel: '500.000 (500K)', baseChance: 25, boosterChance: 50, coins: 45 },
    6: { cost: 1000000, costLabel: '1.000.000 (1KK)', baseChance: 30, boosterChance: 40, coins: 90 }
};

const HELD_FUSION_AMULET_OVERRIDES = {
    5: { cost: 5000000, costLabel: '5.000.000 (5KK)', baseChance: 23, matchingMaterialBonus: 2, boosterChance: 36, coins: 150 },
    6: { cost: 10000000, costLabel: '10.000.000 (10KK)', baseChance: 2, boosterChance: 96, coins: 900 }
};

let heldFusionSimulatorInitialized = false;

function getHeldFusionHeld(key){
    return HELD_FUSION_HELDS.find(held => held.key === key) || HELD_FUSION_HELDS[0];
}

function getHeldFusionStep(heldKey, tier){
    const numericTier = Number(tier) || 1;
    if(heldKey === 'amuletcoin' && HELD_FUSION_AMULET_OVERRIDES[numericTier]){
        return HELD_FUSION_AMULET_OVERRIDES[numericTier];
    }
    return HELD_FUSION_STEPS[numericTier] || HELD_FUSION_STEPS[1];
}

function getHeldFusionMaterialChance(sourceKey, step, materialKey){
    const baseChance = step.baseChance;
    const isMatchingAmuletCoin = sourceKey === 'amuletcoin' && materialKey === 'amuletcoin';
    return baseChance + (isMatchingAmuletCoin ? (step.matchingMaterialBonus || 0) : 0);
}

function getHeldFusionMaterialOptions(sourceKey){
    return sourceKey === 'amuletcoin'
        ? HELD_FUSION_HELDS.filter(held => held.key === 'amuletcoin')
        : HELD_FUSION_HELDS;
}

function setHeldFusionSlot(slot, held, tierLabel = ''){
    if(!slot) return;
    const img = slot.querySelector('img');
    const label = slot.querySelector('span');
    if(held){
        if(img){
            img.src = held.file;
            img.alt = held.name;
            img.hidden = false;
        }
        if(label) label.textContent = tierLabel;
        slot.classList.add('is-filled');
        
        // Criar informação detalhada do held
        const tier = tierLabel.match(/\d+/) ? parseInt(tierLabel.match(/\d+/)[0]) : 0;
        const tierIndex = Math.max(0, tier - 1);
        const value = held.values && held.values[tierIndex] ? held.values[tierIndex] : '-';
        const description = held.description ? `${held.description} ${value}%.` : '';
        const fullInfo = `${held.name} ${tierLabel}\n${description}`;
        
        slot.setAttribute('data-held-info', fullInfo);
    } else {
        if(img){
            img.removeAttribute('src');
            img.alt = '';
            img.hidden = true;
        }
        if(label) label.textContent = '';
        slot.classList.remove('is-filled');
        slot.removeAttribute('data-held-info');
    }
}

function formatHeldFusionMoney(step){
    return step?.costLabel ? `$${step.costLabel}` : '$0';
}

function getHeldFusionEffectText(held, tier){
    const current = held.values[tier - 1];
    const next = held.values[tier] || current;
    return `${held.effect}: T${tier} ${current}% -> T${tier + 1} ${next}%`;
}

function getHeldFusionResultEffectText(held, tier){
    const current = held.values[tier - 1];
    const next = held.values[tier] || current;
    const effect = String(held.effect || '').toLowerCase();
    return {
        current: `T${tier} ${current}% de ${effect}`,
        next: `T${tier + 1} ${next}% de ${effect}`
    };
}

function calculateHeldFusionState(){
    const sourceSelect = document.getElementById('held-fusion-sim-source');
    const tierSelect = document.getElementById('held-fusion-sim-tier');
    const materialOneSelect = document.getElementById('held-fusion-sim-material-1');
    const materialTwoSelect = document.getElementById('held-fusion-sim-material-2');
    const boosterInput = document.getElementById('held-fusion-sim-booster');
    const source = getHeldFusionHeld(sourceSelect?.value);
    const tier = Number(tierSelect?.value) || 1;
    const step = getHeldFusionStep(source.key, tier);
    const materialKeys = [materialOneSelect?.value || '', materialTwoSelect?.value || ''].filter(Boolean);
    const validMaterials = source.key === 'amuletcoin'
        ? materialKeys.filter(key => key === 'amuletcoin')
        : materialKeys;
    const materialCount = validMaterials.length;
    const amuletMaterialCount = validMaterials.filter(key => key === 'amuletcoin').length;
    const usesBooster = Boolean(boosterInput?.checked);
    const hasKnownChance = typeof step.baseChance === 'number';
    
    let chance = null;
    if(hasKnownChance){
        // Sem helds não pode fazer fusão, mesmo com moeda especial
        if(materialCount === 0){
            chance = 0;
        } else if(source.key === 'amuletcoin'){
            // O Amulet Coin aceita qualquer Held primário. Em toda a sua
            // progressão, somente outro Amulet Coin como descarte recebe os
            // +2 pontos percentuais extras; os demais usam a chance-base.
            const materialChance = validMaterials.reduce(
                (total, materialKey) => total + getHeldFusionMaterialChance(source.key, step, materialKey),
                0
            );
            chance = Math.min(
                100,
                materialChance + (usesBooster ? step.boosterChance : 0)
            );
        } else {
            // Lógica normal para outros helds
            chance = Math.min(100, (step.baseChance * materialCount) + (usesBooster ? step.boosterChance : 0));
        }
    }
    
    const canFuse = materialCount > 0 && hasKnownChance;
    return { source, tier, step, materialKeys, validMaterials, materialCount, amuletMaterialCount, usesBooster, chance, canFuse, hasKnownChance };
}

function renderHeldFusionSimulator(resultText = ''){
    const state = calculateHeldFusionState();
    const sourceSlot = document.getElementById('held-fusion-source-slot');
    const materialOneSlot = document.getElementById('held-fusion-material-slot-1');
    const materialTwoSlot = document.getElementById('held-fusion-material-slot-2');
    const previewSlot = document.getElementById('held-fusion-preview-slot');
    const boosterSlot = document.getElementById('held-fusion-booster-slot');
    const costEl = document.getElementById('held-fusion-sim-cost');
    const chanceEl = document.getElementById('held-fusion-sim-chance');
    const coinsEl = document.getElementById('held-fusion-sim-coins');
    const effectEl = document.getElementById('held-fusion-sim-effect');
    const messageEl = document.getElementById('held-fusion-sim-message');
    const resultEl = document.getElementById('held-fusion-sim-result');
    const fuseBtn = document.getElementById('held-fusion-sim-fuse');

    setHeldFusionSlot(sourceSlot, state.source, `T${state.tier}`);
    setHeldFusionSlot(materialOneSlot, state.materialKeys[0] ? getHeldFusionHeld(state.materialKeys[0]) : null, state.materialKeys[0] ? `T${state.tier}` : '');
    setHeldFusionSlot(materialTwoSlot, state.materialKeys[1] ? getHeldFusionHeld(state.materialKeys[1]) : null, state.materialKeys[1] ? `T${state.tier}` : '');
    setHeldFusionSlot(previewSlot, state.source, `T${state.tier + 1}`);

    if(boosterSlot){
        boosterSlot.classList.toggle('is-filled', state.usesBooster);
        const boosterImage = boosterSlot.querySelector('img');
        if(boosterImage) boosterImage.hidden = !state.usesBooster;
        const boosterLabel = boosterSlot.querySelector('span');
        if(boosterLabel) boosterLabel.textContent = state.usesBooster ? 'Moeda' : '';
    }

    if(costEl) costEl.textContent = formatHeldFusionMoney(state.step);
    if(chanceEl) chanceEl.textContent = state.chance === null ? 'Nao informada' : `${state.chance}%`;
    if(coinsEl) coinsEl.textContent = state.usesBooster ? `${state.step.coins} Moeda${state.step.coins === 1 ? '' : 's'}` : '0';
    if(effectEl) effectEl.textContent = getHeldFusionEffectText(state.source, state.tier);

    let message = 'Adicione um ou dois Helds de descarte.';
    if(!state.hasKnownChance){
        message = 'A chance de Amulet Coin T5 -> T6 nao foi informada; confira no jogo antes de tentar.';
    } else if(state.materialKeys.length && !state.materialCount){
        message = 'Amulet Coin só aceita outro Amulet Coin como material de fusão.';
    } else if(state.materialCount){
        const boosterText = state.usesBooster ? ` com bonus de ${state.step.boosterChance}% da Moeda Especial` : '';
        const matchingMaterialBonus = state.source.key === 'amuletcoin' && state.step.matchingMaterialBonus
            ? ` +${state.step.matchingMaterialBonus}% por Amulet Coin de descarte`
            : '';
        message = `${state.materialCount} material(is): +${state.step.baseChance}% por held${matchingMaterialBonus}${boosterText}.`;
    }
    if(messageEl) messageEl.textContent = message;
    if(resultEl && resultText) resultEl.textContent = resultText;
    if(fuseBtn) fuseBtn.disabled = !state.canFuse;

    return state;
}

function populateHeldFusionSelect(select, includeEmpty = false, heldOptions = HELD_FUSION_HELDS){
    if(!select) return;
    const currentValue = select.value;
    select.replaceChildren();
    if(includeEmpty){
        const empty = document.createElement('option');
        empty.value = '';
        empty.textContent = 'Vazio';
        select.appendChild(empty);
    }
    heldOptions.forEach((held) => {
        const option = document.createElement('option');
        option.value = held.key;
        option.textContent = held.name;
        select.appendChild(option);
    });
    if(currentValue && Array.from(select.options).some(option => option.value === currentValue)){
        select.value = currentValue;
    }
}

function syncHeldFusionMaterialSelects(sourceSelect, materialOneSelect, materialTwoSelect){
    const materialOptions = getHeldFusionMaterialOptions(sourceSelect?.value);
    populateHeldFusionSelect(materialOneSelect, true, materialOptions);
    populateHeldFusionSelect(materialTwoSelect, true, materialOptions);
}

function initializeHeldFusionSimulator(){
    if(heldFusionSimulatorInitialized) return;
    const sourceSelect = document.getElementById('held-fusion-sim-source');
    const tierSelect = document.getElementById('held-fusion-sim-tier');
    const materialOneSelect = document.getElementById('held-fusion-sim-material-1');
    const materialTwoSelect = document.getElementById('held-fusion-sim-material-2');
    const boosterInput = document.getElementById('held-fusion-sim-booster');
    const fuseBtn = document.getElementById('held-fusion-sim-fuse');
    const resetBtn = document.getElementById('held-fusion-sim-reset');
    const closeBtn = document.querySelector('.held-fusion-sim__close');
    if(!sourceSelect || !tierSelect || !materialOneSelect || !materialTwoSelect) return;

    populateHeldFusionSelect(sourceSelect);
    syncHeldFusionMaterialSelects(sourceSelect, materialOneSelect, materialTwoSelect);
    tierSelect.replaceChildren();
    for(let tier = 1; tier <= 6; tier += 1){
        const option = document.createElement('option');
        option.value = String(tier);
        option.textContent = `T${tier} -> T${tier + 1}`;
        tierSelect.appendChild(option);
    }

    sourceSelect.value = 'choiceband';
    tierSelect.value = '1';
    materialOneSelect.value = '';
    materialTwoSelect.value = '';

    sourceSelect.addEventListener('change', () => {
        syncHeldFusionMaterialSelects(sourceSelect, materialOneSelect, materialTwoSelect);
        renderHeldFusionSimulator('Resultado: aguardando simulacao.');
    });
    [tierSelect, materialOneSelect, materialTwoSelect, boosterInput].forEach((control) => {
        control?.addEventListener('change', () => renderHeldFusionSimulator('Resultado: aguardando simulacao.'));
    });

    fuseBtn?.addEventListener('click', () => {
        const state = renderHeldFusionSimulator();
        if(!state.canFuse) return;
        const success = Math.random() * 100 < state.chance;
        const effectText = getHeldFusionResultEffectText(state.source, state.tier);
        const resultText = success
            ? `Resultado: sucesso. ${state.source.name} sobe de ${effectText.current} para ${effectText.next}; materiais e taxa foram consumidos.`
            : `Resultado: falha. ${state.source.name} permanece em ${effectText.current}; materiais e taxa foram consumidos.`;
        renderHeldFusionSimulator(resultText);
    });

    const resetHeldFusion = () => {
        sourceSelect.value = 'choiceband';
        tierSelect.value = '1';
        materialOneSelect.value = '';
        materialTwoSelect.value = '';
        if(boosterInput) boosterInput.checked = false;
        renderHeldFusionSimulator('Resultado: aguardando simulacao.');
    };

    resetBtn?.addEventListener('click', resetHeldFusion);
    closeBtn?.addEventListener('click', resetHeldFusion);

    heldFusionSimulatorInitialized = true;
    renderHeldFusionSimulator('Resultado: aguardando simulacao.');
}

