function showSpeedsters(requestedBossMode=''){
    if(contentSpeedsters?.dataset.panelFragment && contentSpeedsters.dataset.panelLoaded !== 'true'){
        setVisiblePanel(contentSpeedsters);
        ensurePanelFragmentLoaded(contentSpeedsters)
            .then(() => showSpeedsters(requestedBossMode))
            .catch(error => console.error('Bosses panel load failed', error));
        return;
    }
    clearTabHighlights();
    setActiveTabTheme('bosses');
    if(tabSpeedstersBtn) {
        tabSpeedstersBtn.classList.add('active');
        tabSpeedstersBtn.setAttribute('aria-selected','true');
    }
    setVisiblePanel(contentSpeedsters);
    document.body.classList.remove('show-instructions');
    const legend = document.getElementById('legend');
    if(legend) legend.style.display = 'none';
    const titleEl = document.getElementById('page-title');
    if(titleEl) titleEl.textContent = t('tabSpeedsters');
    updateBrowserTitle();

    const requestedBossRoute = getBossRouteMatch();
    const targetBossMode = normalizeBossModeParam(requestedBossMode)
        || normalizeBossModeParam(requestedBossRoute?.bossMode || '')
        || getRequestedBossModeFromUrl()
        || getCurrentBossMode()
        || 'hoopa';
    const requestedBossSlug = requestedBossRoute && normalizeBossModeParam(requestedBossRoute.bossMode) === targetBossMode
        ? String(requestedBossRoute.bossSlug || '').trim().toLowerCase()
        : '';

    if(document.body){
        document.body.dataset.bossMode = targetBossMode;
    }

    if(typeof window.setBossMode !== 'function' || typeof renderGrid !== 'function'){
        renderBossesDeferredState('Carregando catálogo de bosses...');
        if(!requestedBossSlug){
            updateUrl();
        }
        ensureBossesPageReady().then(() => {
            if(!contentSpeedsters?.hidden){
                showSpeedsters(targetBossMode);
            }
        }).catch(error => {
            console.error('Bosses load failed', error);
        });
        return;
    }

    if(typeof window.setBossMode === 'function') {
        window.setBossMode(targetBossMode);
    }

    // Garantir que o grid seja montado ao abrir a aba (rerenderizar se necessario)
    if(typeof renderGrid === 'function') {
        renderGrid();
        const speedsterGrid = document.getElementById('speedster-grid');
        if(speedsterGrid && speedsterGrid.children.length === 0){
            const warning = document.createElement('div');
            warning.style.padding = '1rem';
            warning.style.color = '#eee';
            warning.style.background = 'rgba(255,0,0,0.08)';
            warning.textContent = 'Não foi possível carregar os bosses, tente atualizar a página.';
            speedsterGrid.appendChild(warning);
            console.warn('Bosses grid está vazio após renderização. Possível problema no bosses.js.');
        }
    }

    if(requestedBossSlug){
        let openedFromRoute = false;
        if(!requestedBossRoute?.searchView && typeof window.openBossModalByRouteSlug === 'function'){
            openedFromRoute = window.openBossModalByRouteSlug(targetBossMode, requestedBossSlug, { pushState: false });
        }
        if(openedFromRoute && requestedBossRoute?.mapView && typeof window.openBossLocationByRouteSlug === 'function'){
            window.openBossLocationByRouteSlug(targetBossMode, requestedBossSlug, { pushState: false });
        } else if(typeof window.closeBossLocationOverlay === 'function'){
            window.closeBossLocationOverlay({ skipHistory: true, skipRouteRestore: true });
        }
        if(openedFromRoute && requestedBossRoute?.videoView && typeof window.openBossTutorialByRouteSlug === 'function'){
            window.openBossTutorialByRouteSlug(targetBossMode, requestedBossSlug, { pushState: false });
        } else if(typeof window.closeBossTutorialModal === 'function'){
            window.closeBossTutorialModal({ skipRouteRestore: true, skipFocusRestore: true });
        }
        if(!openedFromRoute && !requestedBossRoute?.mapView && !requestedBossRoute?.videoView && typeof window.openSpeedsterSearchResultByRouteSlug === 'function'){
            openedFromRoute = window.openSpeedsterSearchResultByRouteSlug(targetBossMode, requestedBossSlug, { pushState: false });
        }
        if(!openedFromRoute && typeof window.closeBossModal === 'function'){
            window.closeBossModal({ skipHistory: true });
        }
    } else {
        if(typeof window.closeBossLocationOverlay === 'function'){
            window.closeBossLocationOverlay({ skipHistory: true, skipRouteRestore: true });
        }
        if(typeof window.closeBossTutorialModal === 'function'){
            window.closeBossTutorialModal({ skipRouteRestore: true, skipFocusRestore: true });
        }
        const bossModalOpen = typeof window.isBossModalOpen === 'function' && window.isBossModalOpen();
        const bossSearchModalOpen = typeof window.isBossSearchResultModalOpen === 'function' && window.isBossSearchResultModalOpen();
        if((bossModalOpen || bossSearchModalOpen) && typeof window.closeBossModal === 'function'){
            window.closeBossModal({ skipHistory: true });
        }
    }

    if(useGsap && contentSpeedsters){
        gsap.from(contentSpeedsters, {opacity:0, y:-10, duration:0.4});
    }
    updateUrl();
}

