const dropHints = {
    Drake: ['dracozolt.png','dracovish.png'],
    Bird: ['dracozolt.png','arctozolt.png'],
    Dino: ['arctozolt.png','arctovish.png'],
    Fish: ['arctovish.png','dracovish.png'],
    Amber: ['aerodactyl.png','aerodactyl.png']
};

function getFossilDisplayLabel(type){
    return t(String(type || '').toLowerCase()) || String(type || '');
}

function getDirectFossilResult(type){
    if(Object.prototype.hasOwnProperty.call(directFossilRevivals, type)){
        return directFossilRevivals[type];
    }
    const selfPairKey = `${type},${type}`;
    if(Object.prototype.hasOwnProperty.call(fossilCombos, selfPairKey)){
        return fossilCombos[selfPairKey];
    }
    return null;
}

function getFossilSelectionConfigByPokemon(pokemon){
    for(const [type, data] of Object.entries(directFossilRevivals)){
        if(data.pokemon === pokemon){
            return { selectionKey: type, fossilTypes: [type] };
        }
    }
    for(const [pairKey, data] of Object.entries(fossilCombos)){
        if(data.pokemon !== pokemon) continue;
        const parts = pairKey.split(',');
        if(parts[0] === parts[1]){
            return { selectionKey: parts[0], fossilTypes: [parts[0]] };
        }
        return { selectionKey: pairKey, fossilTypes: parts };
    }
    return null;
}

function highlightFossilTypes(fossilTypes){
    const uniqueTypes = [...new Set((Array.isArray(fossilTypes) ? fossilTypes : []).filter(Boolean))];
    uniqueTypes.forEach(type => {
        const img = document.querySelector(`.fossil-img[data-type="${type}"]`);
        if(img){
            img.classList.add('selected', 'active');
        }
    });
}

function showDropHints(type, elem){
    const hints = dropHints[type];
    const container = document.getElementById('drop-hints');
    if(!container) return;
    container.innerHTML = '';
    if(hints && hints.length === 2){
        // Adicionar uma linha descritiva acima das setas
        const desc = document.createElement('div');
        desc.className = 'drop-text';
        desc.textContent = 'Pode dropar:';
        container.appendChild(desc);
        // Montar layout de duas linhas: setas na primeira, imagens dos Pokemon na segunda.
        const arrowRow = document.createElement('div');
        arrowRow.className = 'arrow-row';
        // Se as duas dicas apontam para o mesmo Pokemon, mostrar uma unica seta para baixo
        if(hints[0] === hints[1]){
            const downArrow = document.createElement('span');
            downArrow.className = 'arrow';
            downArrow.textContent = '↓';
            arrowRow.appendChild(downArrow);
        } else {
            const leftArrow = document.createElement('span');
            leftArrow.className = 'arrow';
            leftArrow.textContent = '↙';
            leftArrow.style.transform = 'rotate(-15deg)';
            const rightArrow = document.createElement('span');
            rightArrow.className = 'arrow';
            rightArrow.textContent = '↘';
            rightArrow.style.transform = 'rotate(15deg)';
            arrowRow.appendChild(leftArrow);
            arrowRow.appendChild(rightArrow);
        }
        const imageRow = document.createElement('div');
        imageRow.className = 'image-row';
        // Criar cada imagem de Pokemon com rotulo abaixo
        const unique = hints[0] === hints[1] ? [hints[0]] : [hints[0], hints[1]];
        unique.forEach(fname=>{
            const wrapper = document.createElement('div');
            wrapper.className = 'drop-item';
            const img = document.createElement('img');
            img.src = 'fosseis/' + fname;
            img.alt = fname;
            const label = document.createElement('div');
            label.className = 'drop-name';
            // Usar nome do arquivo sem extensao como nome
            const name = fname.split('.')[0];
            label.textContent = name.charAt(0).toUpperCase() + name.slice(1);
            wrapper.appendChild(img);
            wrapper.appendChild(label);
            imageRow.appendChild(wrapper);
        });
        container.appendChild(arrowRow);
        container.appendChild(imageRow);
        // Em vez de alinhar relativo ao grid inteiro, mover o container
        // diretamente abaixo da celula de fossil clicada para as dicas acompanharem esse item
        container.style.marginTop = '0.5rem';
        container.style.marginLeft = '';
        if(elem){
            const cell = elem.closest('.fossil-cell');
            if(cell){
                cell.appendChild(container); // isso move automaticamente o elemento no DOM
            }
        }
        if(useGsap){
            gsap.from(container.children, {opacity:0, y:10, stagger:0.1, duration:0.4});
        }
    }
}

// Retornar um Set de tipos de fossil parceiros que combinam com `type` conforme `fossilCombos`
function getPartners(type){
    const result = new Set();
    if(!type || typeof type !== 'string') return result;
    if(!fossilCombos) return result;
    for(const k in fossilCombos){
        if(!Object.prototype.hasOwnProperty.call(fossilCombos, k)) continue;
        const parts = k.split(',');
        if(parts.length !== 2) continue;
        const a = parts[0];
        const b = parts[1];
        if(a === type) result.add(b);
        if(b === type) result.add(a);
    }
    return result;
}

function restoreDropHintsContainer(){
    const drop = document.getElementById('drop-hints');
    const resultDiv = document.getElementById('result');
    if(!drop || !resultDiv) return;
    const parent = resultDiv.parentElement;
    if(parent && drop.parentElement !== parent){
        parent.insertBefore(drop, resultDiv);
    }
}

function fossilClearSelection(){
    fossilSelections.length = 0;
    // Remover classes visuais de selecao/transitorias de todas as imagens de fossil
    document.querySelectorAll('.fossil-img').forEach(img=>{
        img.classList.remove('selected','active','compatible','incompatible');
        if(useGsap) gsap.to(img, {scale:1, duration:0.2});
    });
    const drop = document.getElementById('drop-hints');
    if(drop) drop.innerHTML = '';
    restoreDropHintsContainer();
}

// Finalizar selecao apos mostrar um resultado, mas manter o destaque visual "selected"
function fossilFinalizeSelection(){
    // Limpar estado interno de selecao para o usuario poder escolher um novo par
    fossilSelections.length = 0;
    // Remover estados visuais transitorios, mas manter o destaque `selected`
    document.querySelectorAll('.fossil-img').forEach(img=>{
        img.classList.remove('active','compatible','incompatible');
        if(useGsap) gsap.to(img, {scale:1, duration:0.15});
    });
    const drop = document.getElementById('drop-hints');
    if(drop) drop.innerHTML = '';
    restoreDropHintsContainer();
}

function animateSelectedFossils(onComplete){
    const finalize = typeof onComplete === 'function'
        ? onComplete
        : () => {
            fossilFinalizeSelection();
            hintEl.textContent = '';
        };
    if(useGsap){
        const selectedImgs = document.querySelectorAll('.fossil-img.selected');
        gsap.to(selectedImgs, {
            scale: 1.2,
            duration: 0.18,
            yoyo: true,
            repeat: 1,
            ease: 'power1.inOut',
            onComplete: finalize
        });
    } else {
        finalize();
    }
}

function renderFossilResultCard({ pokemon, dna, dnaAmount, price, detailLabel, detailValue, helperText }){
    const resultDiv = document.getElementById('result');
    if(!resultDiv || !pokemon) return;

    const pokemonName = pokemon.split('.')[0];
    const normalizedName = pokemonName.charAt(0).toUpperCase() + pokemonName.slice(1);

    let dnaHtml = '';
    if(dna){
        const dnaAmountHtml = Number.isFinite(Number(dnaAmount)) && Number(dnaAmount) > 0
            ? `<span style="margin-right:0.4rem;">${Number(dnaAmount)}</span>`
            : '';
        dnaHtml = `<p style="margin-top:0.5rem;">${t('dnaRequired') || 'DNA necessário'}: ${dnaAmountHtml}<img src="fosseis/${dna}" alt="${t('dnaRequired') || 'DNA necessário'}" style="display:inline-block; vertical-align:middle; max-width:48px; max-height:48px;" /></p>`;
    }

    const priceHtml = price
        ? `<p>${t('costLabel') || 'Custo'}: ${price}</p>`
        : '';
    const detailHtml = detailLabel && detailValue
        ? `<p style="margin-top:0.5rem;">${detailLabel}: ${detailValue}</p>`
        : '';

    resultDiv.innerHTML = `
        <div class="fossil-result" style="text-align:center; color:#fff;">
            <h3>${normalizedName}</h3>
            <img src="fosseis/${pokemon}" alt="${normalizedName}" style="max-width:160px; max-height:160px; border:1px solid rgba(255,255,255,0.25); border-radius:0.5rem;" />
            ${detailHtml}
            <p>${helperText}</p>
            ${dnaHtml}
            ${priceHtml}
        </div>
    `;

}

function fossilShowResult(selectionKey){
    lastFossilPair = selectionKey;
    if(!selectionKey) return;

    if(!String(selectionKey).includes(',')){
        const directResult = getDirectFossilResult(selectionKey);
        if(!directResult) return;
        renderFossilResultCard({
            pokemon: directResult.pokemon,
            dna: directResult.dna,
            dnaAmount: directResult.dnaAmount,
            price: directResult.price,
            detailLabel: t('fossilSourceLabel') || 'Fóssil',
            detailValue: getFossilDisplayLabel(selectionKey),
            helperText: t('fossilSingleResultText') || 'Este fóssil revive o Pokémon diretamente.'
        });
        return;
    }

    const combo = fossilCombos[selectionKey];
    if(!combo) return;
    const [a,b] = selectionKey.split(',');

    renderFossilResultCard({
        pokemon: combo.pokemon,
        dna: combo.dna,
        dnaAmount: combo.dnaAmount,
        price: combo.price,
        detailLabel: t('fossilComboLabel') || 'Combinação',
        detailValue: `${getFossilDisplayLabel(a)} + ${getFossilDisplayLabel(b)}`,
        helperText: t('fossilResultText') || 'Use esta combinação para ver o Pokémon resultante.'
    });
}

function renderFossilEmptyState(){
    const resultDiv = document.getElementById('result');
    if(!resultDiv) return;

    resultDiv.innerHTML = `
        <div class="fossil-empty-state">
            <strong>${t('fossilEmptyTitle') || 'Escolha um fóssil direto ou combine dois fósseis.'}</strong>
            <span>${t('fossilEmptyText') || 'O resultado aparece na hora para fósseis únicos e após o segundo clique para combinações.'}</span>
        </div>
    `;
}

// Redefinicao robusta para a aba de fosseis; idempotente e segura para chamar repetidamente
function fossilHardReset(){
    try{
        // Limpar estado interno
        lastFossilPair = null;
        fossilSelections.length = 0;

        // Limpar estados visuais nas imagens de fossil
        document.querySelectorAll('.fossil-img').forEach(i=>{
            i.classList.remove('selected','active','compatible','incompatible');
            if(useGsap) gsap.to(i, {scale:1, duration:0.15});
        });

        // Limpar destaques dos cards da galeria
        document.querySelectorAll('.pokemon-card.selected').forEach(c=>c.classList.remove('selected'));

        // Limpar dicas de drop e area de resultado
        const drop = document.getElementById('drop-hints'); if(drop) drop.innerHTML = '';
        restoreDropHintsContainer();
        if(hintEl) hintEl.textContent = '';
        renderFossilEmptyState();

        // Reconstruir galeria apenas se estiver ausente para evitar flicker quando ja existe
        const gallery = document.getElementById('pokemon-gallery');
        if(gallery && gallery.children.length === 0){
            try{ buildPokemonGallery(); }catch(e){}
        }
    }catch(e){
        // Engolir erro; a redefinicao deve ser resiliente
    }
}



function showByPokemon(pokemon){
    showComboForPokemon(pokemon);
}

let hintEl = document.getElementById('fossil-hint');

function refreshFossilDomReferences(){
    fossilResultDiv = document.getElementById('result');
    hintEl = document.getElementById('fossil-hint');
}

function buildPokemonGallery(){
    const gallery = document.getElementById('pokemon-gallery');
    if(!gallery) return;
    gallery.innerHTML = '';
    const seen = new Set();
    // Usar ordem fixa na galeria para inserir novos Pokemon com precisao
    const desiredOrder = [
        'dracozolt.png',
        'dracovish.png',
        'arctovish.png',
        'arctozolt.png',
        'aerodactyl.png',
        'omanyte.png',
        'kabuto.png',
        'lileep.png',
        'anorith.png',
        'cranidos.png',
        'shieldon.png',
        'tirtouga.png',
        'archen.png',
        'tyrunt.png',
        'amaura.png'
    ];
    const entries = [];
    Object.keys(fossilCombos).forEach(k=>{
        const data = fossilCombos[k];
        if(seen.has(data.pokemon)) return;
        seen.add(data.pokemon);
        entries.push(data.pokemon);
    });
    Object.values(directFossilRevivals).forEach(data=>{
        if(seen.has(data.pokemon)) return;
        seen.add(data.pokemon);
        entries.push(data.pokemon);
    });
    // Ordenar conforme a ordem desejada; itens desconhecidos vao ao fim em ordem alfabetica
    entries.sort((a,b)=>{
        const iA = desiredOrder.indexOf(a);
        const iB = desiredOrder.indexOf(b);
        if(iA !== -1 && iB !== -1) return iA - iB;
        if(iA !== -1) return -1;
        if(iB !== -1) return 1;
        return a.localeCompare(b);
    });
    entries.forEach(poke=>{
        const card = document.createElement('div');
        card.className = 'pokemon-card';
        card.dataset.pokemon = poke;
        const base = poke.split('.')[0];
        const display = base.charAt(0).toUpperCase() + base.slice(1);
        const img = document.createElement('img');
        img.src = 'fosseis/' + poke;
        img.alt = display;
        card.appendChild(img);
        const label = document.createElement('div');
        const sideKey = huntSide[base];
        // Omitir rotulo de lado para Aerodactyl porque e aleatorio
        const sideText = sideKey && base !== 'aerodactyl' ? ` (${t(sideKey)})` : '';
        label.textContent = display + sideText;
        card.appendChild(label);
        card.addEventListener('click', ()=>{
            // Marcar card clicado da galeria como selecionado (persistente)
            document.querySelectorAll('.pokemon-card.selected').forEach(c=>c.classList.remove('selected'));
            card.classList.add('selected');
            showComboForPokemon(poke);
        });
        if(useGsap){
            card.addEventListener('mouseenter', ()=>{
                gsap.to(card, {scale:1.1, duration:0.2});
            });
            card.addEventListener('mouseleave', ()=>{
                gsap.to(card, {scale:1, duration:0.2});
            });
        }
        gallery.appendChild(card);
    });
}

function showComboForPokemon(pokemon){
    // Limpar dicas de drop ao vir da galeria
    const drop = document.getElementById('drop-hints');
    if(drop) drop.innerHTML = '';
    const config = getFossilSelectionConfigByPokemon(pokemon);
    if(!config) return;

    fossilClearSelection();
    document.querySelectorAll('.fossil-img').forEach(i=>{
        i.classList.remove('active','compatible','incompatible');
    });
    highlightFossilTypes(config.fossilTypes);

    // Destacar o card clicado da galeria (usar atributo data)
    document.querySelectorAll('.pokemon-card.selected').forEach(c=>c.classList.remove('selected'));
    const matched = document.querySelector(`.pokemon-card[data-pokemon="${pokemon}"]`);
    if(matched) matched.classList.add('selected');

    fossilShowResult(config.selectionKey);
    animateSelectedFossils();
}

function initializeDirectFossilSelection(type){
    const dropEl = document.getElementById('drop-hints');
    if(dropEl) dropEl.innerHTML = '';
    fossilShowResult(type);
    animateSelectedFossils();
}

function hasDirectFossilResult(type){
    return !!getDirectFossilResult(type);
}

function isPairCombinableFossil(type){
    return type === 'Drake' || type === 'Bird' || type === 'Dino' || type === 'Fish';
}

function isSelfPairFossil(type){
    return Object.prototype.hasOwnProperty.call(fossilCombos, `${type},${type}`);
}

function canReuseSelectedFossil(type){
    return isSelfPairFossil(type) || hasDirectFossilResult(type);
}

function buildFossilPairKey(selections){
    if(!Array.isArray(selections) || selections.length === 0) return '';
    if(selections.length === 1) return selections[0];
    return `${selections[0]},${selections[1]}`;
}

function showFossilPairSelection(selections){
    const key = buildFossilPairKey(selections);
    if(!key) return;
    fossilShowResult(key);
    animateSelectedFossils();
}

function playFossilPairPop(){
    if(!useGsap) return;
    const selectedImgs = document.querySelectorAll('.fossil-img.selected');
    gsap.to(selectedImgs, {scale:1.3, duration:0.2, yoyo:true, repeat:1, ease:'power1.inOut'});
}

function updateFossilPairHint(type){
    if(!isPairCombinableFossil(type)){
        document.querySelectorAll('.fossil-img').forEach(i=>{
            if(i.dataset.type === type) return;
            i.classList.remove('compatible', 'incompatible');
        });
        hintEl.textContent = '';
        return;
    }
    const partners = getPartners(type);
    document.querySelectorAll('.fossil-img').forEach(i=>{
        const targetType = i.dataset.type;
        if(targetType === type) return;
        if(partners.has(targetType)){
            i.classList.add('compatible');
            i.classList.remove('incompatible');
        } else {
            i.classList.add('incompatible');
            i.classList.remove('compatible');
        }
    });
    if(partners.size > 0){
        const names = [...partners].map(partnerType => getFossilDisplayLabel(partnerType));
        hintEl.textContent = t('fossilHintCombines') + names.join(', ');
    } else {
        hintEl.textContent = t('fossilHintNone');
    }
}

function initializeFossilsPage(){
    if(fossilsPageInitialized) return;

    document.querySelectorAll('.fossil-label').forEach(span=>{
        const type = span.previousElementSibling?.dataset.type;
        if(type && strings[lang] && strings[lang][type.toLowerCase()]){
            span.textContent = strings[lang][type.toLowerCase()];
        }
    });

    // Montar a galeria do rodape mostrando os Pokemon resultantes
    buildPokemonGallery();

    Array.from(document.querySelectorAll('.fossil-img')).forEach(img=>{
        img.addEventListener('click', ()=>{
            const type = img.dataset.type;
            if(hasDirectFossilResult(type)){
                fossilClearSelection();
                fossilSelections.push(type);
                img.classList.add('selected');
                img.classList.add('active');
                initializeDirectFossilSelection(type);
                return;
            }

            if(fossilSelections.includes(type) && !canReuseSelectedFossil(type)) return;
            fossilSelections.push(type);
            img.classList.add('selected');
            img.classList.add('active');

            if(fossilSelections.length===1){
                // Mostrar dicas de drop para clique solo, posicionadas abaixo do item clicado
                showDropHints(type, img);
                updateFossilPairHint(type);
            }
            if(fossilSelections.length === 2){
                // Limpar dicas de drop ao formar par
                const dropEl = document.getElementById('drop-hints');
                if(dropEl) dropEl.innerHTML = '';

                playFossilPairPop();
                showFossilPairSelection(fossilSelections);
            }
        });
    });

    fossilsPageInitialized = true;
}

function clampTrainingLevel(value){
    const parsed = Number.parseInt(value, 10);
    if(!Number.isFinite(parsed)) return 5;
    return Math.max(5, Math.min(99, parsed));
}

function getTrainingEntryLevel(entry){
    const parsed = Number.parseInt(entry?.level, 10);
    return clampTrainingLevel(Number.isFinite(parsed) ? parsed : 5);
}

function canShowEntryInTrainingSearch(entry){
    const parsedLevel = Number.parseInt(entry?.level, 10);
    return !Number.isFinite(parsedLevel) || parsedLevel < 100;
}

function getTrainingAvailablePokemonEntries(){
    const entries = [
        ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT),
        ...getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
    ].filter(entry => (
        entry
        && entry.name
        && entry.type1
        && canShowEntryInTrainingSearch(entry)
        && entry.catalogHidden !== true
        && canOpenPokemonCatalogEntry(entry)
    ));
    const seen = new Set();
    return entries
        .filter(entry => {
            const key = `${entry.variant || 'default'}:${entry.id || entry.routeSlug || entry.name}`;
            if(seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((left, right) => left.name.localeCompare(right.name, 'pt-BR'));
}

function getTrainingPokemonSearchKey(entry){
    return entry?.searchName || normalizePokemonSearchText(entry?.name || '');
}

function hydrateTrainingPokemonOptions(){
    trainingPokemonEntries = getTrainingAvailablePokemonEntries();
    trainingPokemonSearchIndex = new Map();
    trainingPokemonEntries.forEach(entry => {
        const key = getTrainingPokemonSearchKey(entry);
        if(key && !trainingPokemonSearchIndex.has(key)){
            trainingPokemonSearchIndex.set(key, entry);
        }
    });
    if(trainingPokemonSearchInput){
        trainingPokemonSearchInput.placeholder = trainingPokemonEntries.length
            ? 'Busque um Pokemon...'
            : 'Catalogo indisponivel no momento';
    }
}

function getTrainingPokemonSearchResultEntries(value = '', limit = 8){
    const normalizedValue = normalizePokemonSearchText(value || trainingPokemonSearchInput?.value || '');
    return getLimitedPokemonSearchEntries(trainingPokemonEntries, normalizedValue, getTrainingPokemonSearchKey, limit);
}

function createTrainingSearchResultContent(entry){
    const sprite = document.createElement('img');
    sprite.className = 'speedster-search-item-icon boost-search-item-icon boost-search-item-icon--pokemon';
    sprite.src = getPokemonImageSource(entry);
    sprite.alt = entry.name;
    sprite.loading = 'lazy';
    sprite.decoding = 'async';
    setImageFallback(sprite, POKEMON_IMAGE_PLACEHOLDER);

    const name = document.createElement('span');
    name.className = 'boost-search-item-name';
    name.textContent = entry.name;

    const meta = document.createElement('span');
    meta.className = 'training-search-item-meta';
    meta.textContent = `Nivel ${getTrainingEntryLevel(entry)} • ${formatPokemonTypeLabel(entry.type1)}${entry.type2 ? ` / ${formatPokemonTypeLabel(entry.type2)}` : ''}`;

    const text = document.createElement('span');
    text.className = 'training-search-item-copy';
    text.append(name, meta);

    const content = document.createElement('div');
    content.className = 'boost-search-item-content training-search-item-content';
    content.append(sprite);
    [entry.type1, entry.type2].filter(Boolean).slice(0, 2).forEach(typeKey => {
        const icon = document.createElement('img');
        icon.className = 'speedster-search-item-icon boost-search-item-icon';
        icon.src = `icons-type/${typeKey}.png`;
        icon.alt = formatPokemonTypeLabel(typeKey);
        icon.loading = 'lazy';
        icon.decoding = 'async';
        content.appendChild(icon);
    });
    content.appendChild(text);
    return content;
}

function hideTrainingPokemonSearchResults(){
    if(trainingPokemonSearchHideTimer){
        clearTimeout(trainingPokemonSearchHideTimer);
        trainingPokemonSearchHideTimer = 0;
    }
    if(trainingPokemonResults){
        trainingPokemonResults.hidden = true;
        trainingPokemonResults.replaceChildren();
    }
    if(trainingPokemonNoResults){
        trainingPokemonNoResults.hidden = true;
    }
}

function renderTrainingPokemonSearchResults(value = ''){
    if(!trainingPokemonResults || !trainingPokemonNoResults) return;
    const normalizedValue = normalizePokemonSearchText(value || trainingPokemonSearchInput?.value || '');
    const entries = getTrainingPokemonSearchResultEntries(value);
    if(!entries.length){
        trainingPokemonResults.hidden = true;
        trainingPokemonResults.replaceChildren();
        trainingPokemonNoResults.hidden = !normalizedValue;
        return;
    }

    trainingPokemonNoResults.hidden = true;
    trainingPokemonResults.hidden = false;
    trainingPokemonResults.replaceChildren();
    const currentKey = getTrainingPokemonSearchKey(trainingSelectedPokemonEntry);
    const fragment = document.createDocumentFragment();
    entries.forEach(entry => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'speedster-search-item boost-search-item';
        item.dataset.pokemonName = entry.name;
        if(currentKey && currentKey === getTrainingPokemonSearchKey(entry)){
            item.dataset.selected = 'true';
        }
        item.setAttribute('aria-label', `Selecionar ${entry.name} para calcular treinamento.`);
        item.appendChild(createTrainingSearchResultContent(entry));
        item.addEventListener('click', () => applyTrainingPokemonSelection(entry));
        fragment.appendChild(item);
    });
    trainingPokemonResults.appendChild(fragment);
}

function getSelectedTrainingVariant(){
    return document.querySelector('input[name="training-variant"]:checked')?.value === 'shiny'
        ? 'shiny'
        : 'normal';
}

function getTrainingPlateCostForLevel(level){
    return Math.max(1, Math.floor(Number(level) / 10));
}

function getTrainingExperienceRatesForLevel(level){
    const from = clampTrainingLevel(level);
    return TRAINING_EXPERIENCE_RATES.find(entry => from >= entry.minLevel) || TRAINING_EXPERIENCE_RATES[TRAINING_EXPERIENCE_RATES.length - 1];
}

function getTrainingBaseLevelForCalculation(currentLevel){
    return getTrainingEntryLevel(trainingSelectedPokemonEntry) || clampTrainingLevel(currentLevel);
}

function getTrainingProgressRows(startLevel, baseLevel, resultType = 'success'){
    const rows = [];
    const rates = getTrainingExperienceRatesForLevel(baseLevel);
    const expPerTraining = resultType === 'fail' ? rates.fail : rates.success;
    if(expPerTraining <= 0) return rows;
    let level = clampTrainingLevel(startLevel);
    while(level < 100){
        const from = level;
        const to = Math.min(100, level + (expPerTraining / 100));
        rows.push({
            from,
            to,
            plates: getTrainingPlateCostForLevel(from)
        });
        level = to;
    }
    return rows;
}

function getTrainingRows(startLevel, baseLevel = getTrainingBaseLevelForCalculation(startLevel)){
    const from = clampTrainingLevel(startLevel);
    const base = clampTrainingLevel(baseLevel);
    const successRows = getTrainingProgressRows(from, base, 'success');
    const failRows = getTrainingProgressRows(from, base, 'fail');
    const totalRows = Math.max(successRows.length, failRows.length);
    return Array.from({ length: totalRows }, (_, index) => {
        const successRow = successRows[index] || null;
        const failRow = failRows[index] || null;
        const rowFrom = successRow?.from ?? failRow?.from ?? from;
        const rowTo = successRow?.to ?? failRow?.to ?? 100;
        return {
            from: rowFrom,
            to: rowTo,
            trainingIndex: index + 1,
            label: `Treino ${index + 1}`,
            coins: successRow ? 1 : 0,
            failCoins: 0,
            successPlates: successRow?.plates || 0,
            failPlates: failRow?.plates || 0
        };
    });
}

function calculateTrainingTotals(startLevel, variant = getSelectedTrainingVariant(), baseLevel = getTrainingBaseLevelForCalculation(startLevel)){
    const rows = getTrainingRows(startLevel, baseLevel);
    const coins = rows.reduce((sum, row) => sum + row.coins, 0);
    const failCoins = rows.reduce((sum, row) => sum + (row.failCoins || 0), 0);
    const successPlates = rows.reduce((sum, row) => sum + row.successPlates, 0);
    const failPlates = rows.reduce((sum, row) => sum + row.failPlates, 0);
    const shiningPlates = variant === 'shiny' ? successPlates : 0;
    const shiningStoneBlocks = variant === 'shiny'
        ? Math.ceil(shiningPlates / SHINING_PLATE_BLOCK_SIZE)
        : 0;
    const craftCommonPlates = variant === 'shiny'
        ? Math.max(successPlates, shiningStoneBlocks * SHINING_PLATE_BLOCK_SIZE)
        : successPlates;
    return {
        rows,
        coins,
        failCoins,
        successPlates,
        failPlates,
        shiningPlates,
        shiningStoneBlocks,
        craftCommonPlates,
        elementItems: craftCommonPlates * COMMON_PLATE_COST.elementItems,
        charItems: craftCommonPlates * COMMON_PLATE_COST.charItems,
        stones: craftCommonPlates * COMMON_PLATE_COST.stones
    };
}

function createTrainingMaterialCard(options = {}){
    const {
        label = '',
        value = 0,
        detail = '',
        image = '',
        tone = '',
        info = '',
        badge = ''
    } = options;
    const card = document.createElement('article');
    card.className = `training-material-card${tone ? ` training-material-card--${tone}` : ''}`;
    if(info){
        const help = document.createElement('button');
        help.type = 'button';
        help.className = 'training-material-card__help';
        help.textContent = '?';
        help.dataset.tooltip = info;
        help.setAttribute('aria-label', info);
        card.appendChild(help);
    }
    const media = document.createElement('span');
    media.className = 'training-material-card__media';
    if(image){
        const img = document.createElement('img');
        img.src = image;
        img.alt = '';
        img.loading = 'lazy';
        img.decoding = 'async';
        media.appendChild(img);
    }
    if(badge){
        const badgeEl = document.createElement('span');
        badgeEl.className = 'training-material-card__media-badge';
        badgeEl.textContent = badge;
        badgeEl.setAttribute('aria-hidden', 'true');
        media.appendChild(badgeEl);
    }
    const body = document.createElement('span');
    body.className = 'training-material-card__body';
    const title = document.createElement('strong');
    title.textContent = label;
    const amount = document.createElement('span');
    amount.className = 'training-material-card__value';
    amount.textContent = Number(value || 0).toLocaleString('pt-BR');
    const note = document.createElement('small');
    note.textContent = detail;
    body.append(title, amount, note);
    card.append(media, body);
    return card;
}

function renderTrainingSelectedPokemon(){
    if(!trainingSelectedPokemon) return;
    if(!trainingSelectedPokemonEntry){
        trainingSelectedPokemon.hidden = true;
        trainingSelectedPokemon.replaceChildren();
        return;
    }
    const entry = trainingSelectedPokemonEntry;
    const sprite = document.createElement('img');
    sprite.src = getPokemonImageSource(entry);
    sprite.alt = entry.name;
    sprite.loading = 'lazy';
    sprite.decoding = 'async';
    setImageFallback(sprite, POKEMON_IMAGE_PLACEHOLDER);

    const title = document.createElement('strong');
    title.textContent = entry.name;
    const meta = document.createElement('span');
    meta.textContent = [
        `Nivel base ${getTrainingEntryLevel(entry)}`,
        formatPokemonTypeLabel(entry.type1),
        entry.type2 ? formatPokemonTypeLabel(entry.type2) : '',
        entry.role ? formatPokemonRoleLabel(entry.role) : ''
    ].filter(Boolean).join(' • ');
    const copy = document.createElement('span');
    copy.append(title, meta);
    trainingSelectedPokemon.replaceChildren(sprite, copy);
    trainingSelectedPokemon.hidden = false;
}

function setTrainingStepUnlocked(stepEl, unlocked){
    if(!stepEl) return;
    stepEl.classList.toggle('training-step--locked', !unlocked);
    stepEl.classList.toggle('training-step--active', unlocked);
}

function updateTrainingStepState(){
    const hasPokemon = Boolean(trainingSelectedPokemonEntry);
    const level = clampTrainingLevel(trainingCurrentLevelInput?.value || 5);
    const hasLevel = hasPokemon && level >= 5 && level < 100;
    setTrainingStepUnlocked(trainingStepLevel, hasPokemon);
    setTrainingStepUnlocked(trainingStepVariant, hasLevel);

    if(trainingCurrentLevelInput) trainingCurrentLevelInput.disabled = !hasPokemon;
    if(trainingLevelDecreaseBtn) trainingLevelDecreaseBtn.disabled = !hasPokemon || level <= 5;
    if(trainingLevelIncreaseBtn) trainingLevelIncreaseBtn.disabled = !hasPokemon || level >= 99;
    trainingVariantInputs.forEach(input => {
        input.disabled = !hasLevel;
    });
    if(trainingLevelPreview){
        const previewTotals = hasPokemon ? calculateTrainingTotals(level) : null;
        trainingLevelPreview.textContent = hasPokemon
            ? `${previewTotals.coins} treino(s) ate o level 100.`
            : '';
    }
}

function renderTrainingResults(){
    if(!trainingResults) return;
    if(!trainingSelectedPokemonEntry){
        trainingResults.replaceChildren(trainingSelectionStatus || document.createTextNode('Selecione um Pokemon para liberar as proximas etapas.'));
        if(trainingSelectionStatus) trainingSelectionStatus.textContent = 'Selecione um Pokemon para liberar as proximas etapas.';
        return;
    }

    const level = clampTrainingLevel(trainingCurrentLevelInput?.value || getTrainingEntryLevel(trainingSelectedPokemonEntry));
    const variant = getSelectedTrainingVariant();
    const totals = calculateTrainingTotals(level, variant);
    const typeMeta = BOOST_TYPE_STONE_META[trainingSelectedPokemonEntry.type1] || null;
    const elementName = typeMeta?.name || 'Stone do tipo';
    const elementImage = typeMeta?.image || '';
    const elementItemImage = `icons-type/${trainingSelectedPokemonEntry.type1}.png`;

    const shell = document.createElement('div');
    shell.className = 'training-results-shell';

    const summary = document.createElement('div');
    summary.className = 'training-summary-grid';
    summary.append(
        createTrainingMaterialCard({ label: 'Golden Coins', value: totals.coins, detail: `${level} -> 100`, image: 'calculadora/golden_coin.gif', tone: 'coin' }),
        createTrainingMaterialCard({ label: 'Plates (S)', value: totals.successPlates, detail: 'Treinos com sucesso', image: 'calculadora/plate.gif', tone: 'success' })
    );
    if(totals.failCoins > 0){
        summary.append(createTrainingMaterialCard({ label: 'Golden Coins (F)', value: totals.failCoins, detail: 'Estimativa de falhas', image: 'calculadora/golden_coin.gif', tone: 'coin' }));
    }
    if(totals.failPlates > 0){
        summary.append(createTrainingMaterialCard({ label: 'Plates (F)', value: totals.failPlates, detail: 'Estimativa de falhas', image: 'calculadora/plate.gif', tone: 'fail' }));
    }
    if(variant === 'shiny'){
        summary.append(createTrainingMaterialCard({
            label: 'Shining Plates',
            value: totals.shiningPlates,
            detail: 'Usadas junto das Plates normais',
            image: 'calculadora/shiny_plate.gif',
            tone: 'shiny'
        }));
    }

    const materialsTitle = document.createElement('h3');
    materialsTitle.textContent = 'Materiais para craft';
    const materials = document.createElement('div');
    materials.className = 'training-material-grid';
    materials.append(
        createTrainingMaterialCard({
            label: 'Itens do elemento',
            value: totals.elementItems,
            detail: `${COMMON_PLATE_COST.elementItems} por Plate`,
            image: elementItemImage,
            tone: 'item',
            info: 'Esses itens específicos são dropados por qualquer Pokémon desse elemento.'
        }),
        createTrainingMaterialCard({
            label: 'Itens característicos',
            value: totals.charItems,
            detail: `${COMMON_PLATE_COST.charItems} por Plate`,
            image: 'calculadora/lotitems.png',
            tone: 'item',
            info: 'Esses itens específicos são dropados por um Pokémon específico. Procure no jogo, na área de treinamento, para saber exatamente qual item é necessário.'
        }),
        createTrainingMaterialCard({ label: elementName, value: totals.stones, detail: `${COMMON_PLATE_COST.stones} por Plate`, image: elementImage, tone: 'item' })
    );
    if(variant === 'shiny'){
        materials.append(createTrainingMaterialCard({
            label: 'Shining Stones',
            value: totals.shiningStoneBlocks,
            detail: `1 bloco a cada ${SHINING_PLATE_BLOCK_SIZE} Shining Plates`,
            image: elementImage,
            tone: 'shiny',
            badge: '\u2728'
        }));
    }

    const detail = document.createElement('details');
    detail.className = 'training-detail-table';
    const detailSummary = document.createElement('summary');
    detailSummary.innerHTML = `<span>Tabela Detalhada</span><small>${totals.coins} treino(s)</small>`;
    const tableWrap = document.createElement('div');
    tableWrap.className = 'training-detail-table__wrap';
    const table = document.createElement('table');
    const hasFailCoins = totals.failCoins > 0;
    const hasFailPlates = totals.failPlates > 0;
    table.innerHTML = hasFailCoins
        ? '<thead><tr><th>Treino</th><th>Coins (S)</th><th>Coins (F)</th><th>Plates (S)</th><th>Plates (F)</th></tr></thead>'
        : hasFailPlates
            ? '<thead><tr><th>Treino</th><th>Coins</th><th>Plates (S)</th><th>Plates (F)</th></tr></thead>'
            : '<thead><tr><th>Treino</th><th>Coins</th><th>Plates</th></tr></thead>';
    const body = document.createElement('tbody');
    totals.rows.forEach(row => {
        const tr = document.createElement('tr');
        if(row.trainingIndex % 10 === 0) tr.className = 'training-detail-table__decade';
        tr.innerHTML = hasFailCoins
            ? `<td>${row.label || `${row.from} -> ${row.to}`}</td><td>${row.coins}</td><td>${row.failCoins || 0}</td><td>${row.successPlates}</td><td>${row.failPlates}</td>`
            : hasFailPlates
                ? `<td>${row.label || `${row.from} -> ${row.to}`}</td><td>${row.coins}</td><td>${row.successPlates}</td><td>${row.failPlates}</td>`
                : `<td>${row.label || `${row.from} -> ${row.to}`}</td><td>${row.coins}</td><td>${row.successPlates}</td>`;
        body.appendChild(tr);
    });
    const footer = document.createElement('tfoot');
    footer.innerHTML = hasFailCoins
        ? `<tr><th>Total</th><th>${totals.coins.toLocaleString('pt-BR')}</th><th>${totals.failCoins.toLocaleString('pt-BR')}</th><th>${totals.successPlates.toLocaleString('pt-BR')}</th><th>${totals.failPlates.toLocaleString('pt-BR')}</th></tr>`
        : hasFailPlates
            ? `<tr><th>Total</th><th>${totals.coins.toLocaleString('pt-BR')}</th><th>${totals.successPlates.toLocaleString('pt-BR')}</th><th>${totals.failPlates.toLocaleString('pt-BR')}</th></tr>`
            : `<tr><th>Total</th><th>${totals.coins.toLocaleString('pt-BR')}</th><th>${totals.successPlates.toLocaleString('pt-BR')}</th></tr>`;
    table.append(body, footer);
    tableWrap.appendChild(table);
    detail.append(detailSummary, tableWrap);

    const context = document.createElement('div');
    context.className = 'training-result-context';
    context.textContent = `${trainingSelectedPokemonEntry.name} • Level ${level} • ${variant === 'shiny' ? 'Shiny' : 'Normal'} • Tipo ${formatPokemonTypeLabel(trainingSelectedPokemonEntry.type1)}`;

    shell.append(context, summary, materialsTitle, materials, detail);
    trainingResults.replaceChildren(shell);
    animateCalcResult(trainingResults);
}

function syncTrainingCalculator(){
    updateTrainingStepState();
    renderTrainingSelectedPokemon();
    renderTrainingResults();
}

function applyTrainingPokemonSelection(entry){
    trainingSelectedPokemonEntry = entry || null;
    if(trainingPokemonSearchInput && entry){
        trainingPokemonSearchInput.value = entry.name;
    }
    if(trainingCurrentLevelInput && entry){
        trainingCurrentLevelInput.value = getTrainingEntryLevel(entry);
    }
    hideTrainingPokemonSearchResults();
    syncTrainingCalculator();
}

function updateRangeResults(){
    const val = rangeSelect.value;
    const data = ranges[val];
    const variant = document.querySelector('input[name="poke-variant"]:checked')?.value || 'normal';
    if(data){
        const rangeStartLevel = Number.parseInt(val, 10) || 50;
        const totals = calculateTrainingTotals(rangeStartLevel, variant, rangeStartLevel);
        const plateCount = totals.successPlates;
        const failPlateCount = totals.failPlates;
        const failGoldCount = totals.failCoins;
        const blocks = Math.ceil(plateCount / SHINING_PLATE_BLOCK_SIZE);
        const totalInBlocks = blocks * SHINING_PLATE_BLOCK_SIZE;
        const variantLabel = variant === 'shiny' ? t('shiny') : t('normal');
        const requiredCommonPlates = variant === 'shiny' ? totalInBlocks : plateCount;
        const elementItems = requiredCommonPlates * COMMON_PLATE_COST.elementItems;
        const charItems = requiredCommonPlates * COMMON_PLATE_COST.charItems;
        const stones = requiredCommonPlates * COMMON_PLATE_COST.stones;

        if(variant === 'normal'){
            if(commonInput) commonInput.value = plateCount;
            if(shinyInput) shinyInput.value = 0;
            if(shinyResults) shinyResults.innerHTML = '';
            updateCommon();
        } else {
            const shinyVal = blocks * 30;
            if(shinyInput) shinyInput.value = shinyVal;
            if(commonInput) commonInput.value = shinyVal;
            updateShiny();
            updateCommon();
        }

        let html = `<p><strong>${t('pokemonTypeLabel')}:</strong> ${variantLabel}</p>`;
        if(variant === 'normal'){
            html += `<p><strong>${t('commonPlatesLabel')}:</strong> <span class="num" data-value="${plateCount}">${plateCount.toLocaleString()}</span></p>`;
        } else {
            html += `<p><strong>${t('shinyPlatesLabel')}:</strong> <span class="num" data-value="${plateCount}">${plateCount.toLocaleString()}</span></p>`;
            html += `<p><strong>${t('roundedProductionLabel')}:</strong> <span class="num" data-value="${totalInBlocks}">${totalInBlocks.toLocaleString()}</span></p>`;
            html += `<p><strong>${t('commonPlatesLabel')}:</strong> <span class="num" data-value="${requiredCommonPlates}">${requiredCommonPlates.toLocaleString()}</span></p>`;
            html += `<p><strong>${t('shiningStonesLabel')}:</strong> <span class="num" data-value="${blocks}">${blocks.toLocaleString()}</span></p>`;
        }
        html += `<p><strong>${t('goldCoinsLabel')}:</strong> <span class="num" data-value="${totals.coins}">${totals.coins.toLocaleString()}</span></p>`;
        if(failGoldCount > 0){
            html += `<p><strong>${t('goldCoinsLabel')} (F):</strong> <span class="num" data-value="${failGoldCount}">${failGoldCount.toLocaleString()}</span></p>`;
        }
        if(failPlateCount > 0){
            html += `<p><strong>Plates (F):</strong> <span class="num" data-value="${failPlateCount}">${failPlateCount.toLocaleString()}</span></p>`;
        }
        const materialsHtml = t('calcInfoItems')
            .replace('{elementItems}', `<span class="num" data-value="${elementItems}">${elementItems.toLocaleString()}</span>`)
            .replace('{charItems}', `<span class="num" data-value="${charItems}">${charItems.toLocaleString()}</span>`)
            .replace('{stones}', `<span class="num" data-value="${stones}">${stones.toLocaleString()}</span>`);
        html += `<p><strong>${t('materialsForRangeLabel')}:</strong><br>${materialsHtml}</p>`;
        html += `<p><em>${variant === 'normal' ? t('sameQuantityNote') : t('shiningBlockNote')}</em></p>`;
        rangeResults.innerHTML = html;
        animateCalcResult(rangeResults);
    } else {
        rangeResults.innerHTML = '';
    }
}
function animateCalcResult(target){
    if(!target) return;
    if(useGsap){
        gsap.killTweensOf(target);
        gsap.fromTo(target,
            {opacity: 0, y: 10},
            {opacity: 1, y: 0, duration: 0.28, overwrite: 'auto', clearProps: 'opacity,transform', onComplete: ()=> animateNumbersIn(target)}
        );
    } else {
        target.style.opacity = '1';
        target.style.transform = 'translateY(0)';
        animateNumbersIn(target);
    }
}
function animateNumbersIn(target){
    if(!target) return;
    const elems = target.querySelectorAll('.num[data-value]');
    if(!elems.length) return;
    const easeOutCubic = t => 1 - Math.pow(1 - t, 3);
    elems.forEach(el => {
        const final = Number(el.getAttribute('data-value')) || 0;
        if(useGsap && typeof gsap !== 'undefined'){
            const obj = {val: 0};
            gsap.to(obj, {
                val: final,
                duration: 0.7,
                roundProps: 'val',
                onUpdate: function(){
                    el.textContent = obj.val.toLocaleString();
                }
            });
        } else {
            const start = Date.now();
            const duration = 700;
            function tick(){
                const now = Date.now();
                const t = Math.min(1, (now - start) / duration);
                const v = Math.round(easeOutCubic(t) * final);
                el.textContent = v.toLocaleString();
                if(t < 1) requestAnimationFrame(tick);
            }
            tick();
        }
    });
}
function updateCommon(){
    const n = parseInt(commonInput.value) || 0;
    const perPlateElement = COMMON_PLATE_COST.elementItems;
    const perPlateChar = COMMON_PLATE_COST.charItems;
    const perPlateStone = COMMON_PLATE_COST.stones;
    const elementItems = n * perPlateElement;
    const charItems = n * perPlateChar;
    const stones = n * perPlateStone;
    // Montar usando traducoes (apenas visual)
    const header = t('forCommonLabel').replace('{n}', `<span class="num" data-value="${n}">${n.toLocaleString()}</span>`);
    const itemsText = `<span class="num" data-value="${elementItems}">${elementItems.toLocaleString()}</span> itens do elemento (${perPlateElement}×${n}), ` +
                      `<span class="num" data-value="${charItems}">${charItems.toLocaleString()}</span> itens característicos (${perPlateChar}×${n}), ` +
                      `<span class="num" data-value="${stones}">${stones.toLocaleString()}</span> pedra(s) do elemento (${perPlateStone}×${n})`;
    commonResults.innerHTML = `<p>${header}<br>${itemsText}</p>`;
    animateCalcResult(commonResults);
}
function updateShiny(){
    let n = parseInt(shinyInput.value) || 0;
    let html = '';
    if(n % SHINING_PLATE_BLOCK_SIZE !== 0){
        const rounded = Math.ceil(n / SHINING_PLATE_BLOCK_SIZE) * SHINING_PLATE_BLOCK_SIZE;
        html += `<p><em>${t('adjustNote').replace('{rounded}', `<span class="num" data-value="${rounded}">${rounded.toLocaleString()}</span>`)}</em></p>`;
        n = rounded;
    }
    const blocks = Math.ceil(n / SHINING_PLATE_BLOCK_SIZE);
    const commonNeeded = blocks * SHINING_PLATE_BLOCK_SIZE;
    const shiningStones = blocks;
    html += `<p><span class="num" data-value="${n}">${n.toLocaleString()}</span> shining plate(s) requer <span class="num" data-value="${commonNeeded}">${commonNeeded.toLocaleString()}</span> plate(s) comum(ns)` +
            ` e <span class="num" data-value="${shiningStones}">${shiningStones.toLocaleString()}</span> shining stone(s) (em <span class="num" data-value="${blocks}">${blocks.toLocaleString()}</span> bloco(s) de 30).</p>`;
    shinyResults.innerHTML = html;
    animateCalcResult(shinyResults);
}

