function initializeCalculatorPage(){
    if(calculatorPageInitialized){
        ensurePokemonCatalogLoaded()
            .then(() => {
                hydrateTrainingPokemonOptions();
                syncTrainingCalculator();
            })
            .catch(() => {
                if(trainingPokemonSearchInput) trainingPokemonSearchInput.placeholder = 'Catalogo indisponivel no momento';
            });
        return;
    }

    if(trainingInfoToggle && trainingInfoPanel){
        trainingInfoToggle.addEventListener('click', () => {
            const nextHidden = !trainingInfoPanel.hidden ? true : false;
            trainingInfoPanel.hidden = nextHidden;
            trainingInfoToggle.setAttribute('aria-expanded', String(!nextHidden));
        });
    }

    if(trainingPokemonSearchInput){
        trainingPokemonSearchInput.addEventListener('input', () => {
            const value = String(trainingPokemonSearchInput.value || '').trim();
            const key = normalizePokemonSearchText(value);
            trainingSelectedPokemonEntry = key ? trainingPokemonSearchIndex.get(key) || null : null;
            renderTrainingPokemonSearchResults(value);
            syncTrainingCalculator();
        });
        trainingPokemonSearchInput.addEventListener('focus', () => {
            renderTrainingPokemonSearchResults(trainingPokemonSearchInput.value || '');
        });
        trainingPokemonSearchInput.addEventListener('keydown', (event) => {
            if(event.key !== 'Enter') return;
            const firstEntry = getTrainingPokemonSearchResultEntries(trainingPokemonSearchInput.value || '', 1)[0];
            if(!firstEntry) return;
            event.preventDefault();
            applyTrainingPokemonSelection(firstEntry);
        });
        trainingPokemonSearchInput.addEventListener('blur', () => {
            if(trainingPokemonSearchHideTimer) clearTimeout(trainingPokemonSearchHideTimer);
            trainingPokemonSearchHideTimer = setTimeout(hideTrainingPokemonSearchResults, 160);
        });
    }

    if(trainingCurrentLevelInput){
        trainingCurrentLevelInput.addEventListener('input', () => {
            trainingCurrentLevelInput.value = clampTrainingLevel(trainingCurrentLevelInput.value);
            syncTrainingCalculator();
        });
    }
    if(trainingLevelDecreaseBtn){
        trainingLevelDecreaseBtn.addEventListener('click', () => {
            if(!trainingCurrentLevelInput) return;
            trainingCurrentLevelInput.value = clampTrainingLevel(Number(trainingCurrentLevelInput.value || 5) - 1);
            syncTrainingCalculator();
        });
    }
    if(trainingLevelIncreaseBtn){
        trainingLevelIncreaseBtn.addEventListener('click', () => {
            if(!trainingCurrentLevelInput) return;
            trainingCurrentLevelInput.value = clampTrainingLevel(Number(trainingCurrentLevelInput.value || 5) + 1);
            syncTrainingCalculator();
        });
    }

    trainingVariantInputs.forEach(input => {
        input.addEventListener('change', syncTrainingCalculator);
    });

    ensurePokemonCatalogLoaded()
        .then(() => {
            hydrateTrainingPokemonOptions();
            syncTrainingCalculator();
        })
        .catch(() => {
            if(trainingPokemonSearchInput) trainingPokemonSearchInput.placeholder = 'Catalogo indisponivel no momento';
            syncTrainingCalculator();
        });

    syncTrainingCalculator();
    calculatorPageInitialized = true;
}

function formatBoostQuantity(value){
    return (Number(value) || 0).toLocaleString('pt-BR');
}

function normalizeBoostLevel(value){
    const parsed = parseInt(value, 10);
    if(!Number.isFinite(parsed)) return 0;
    return Math.max(0, Math.min(5, parsed));
}

function getBoostAvailablePokemonEntries(){
    const combinedEntries = (Array.isArray(pokemonCatalogEntriesByVariant.default)
        ? pokemonCatalogEntriesByVariant.default
        : []
    ).filter(entry => (
        entry
        && entry.name
        && entry.type1
        && entry.registered !== false
        && (
            !getPokemonEntrySpecialTags(entry).includes('pack')
            || normalizePokemonSearchText(entry.name) === 'ditto'
        )
    ));

    const seen = new Set();
    return combinedEntries
        .filter(entry => {
            const key = `${entry.variant || 'default'}:${entry.id || entry.name}`;
            if(seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((left, right) => left.name.localeCompare(right.name, 'pt-BR'));
}

function refreshBoostPokemonSearchStore(){
    boostPokemonEntries = getBoostAvailablePokemonEntries();
    boostPokemonSearchIndex = new Map();

    boostPokemonEntries.forEach(entry => {
        const searchKey = entry.searchName || normalizePokemonSearchText(entry.name);
        if(searchKey && !boostPokemonSearchIndex.has(searchKey)){
            boostPokemonSearchIndex.set(searchKey, entry);
        }
    });

    return boostPokemonEntries;
}

function clearBoostPokemonSearchHideTimer(){
    if(boostPokemonSearchHideTimer){
        clearTimeout(boostPokemonSearchHideTimer);
        boostPokemonSearchHideTimer = 0;
    }
}

function findBoostMatchingPokemonEntries(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || boostPokemonSearchInput?.value || '');
    if(!normalizedValue) return [];

    return boostPokemonEntries.filter(entry => {
        const searchKey = getBoostPokemonEntrySearchKey(entry);
        return searchKey === normalizedValue || searchKey.includes(normalizedValue);
    });
}

function getBoostPokemonSearchResultEntries(value = '', limit = 8){
    const normalizedValue = normalizePokemonSearchText(value || boostPokemonSearchInput?.value || '');
    return getLimitedPokemonSearchEntries(boostPokemonEntries, normalizedValue, getBoostPokemonEntrySearchKey, limit);
}

function getBoostPokemonEntrySearchKey(entry){
    return entry?.searchName || normalizePokemonSearchText(entry?.name || '');
}

function resolveBoostPokemonEntry(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || boostPokemonSearchInput?.value || '');
    if(!normalizedValue) return null;
    const exactEntry = boostPokemonSearchIndex.get(normalizedValue) || null;
    if(exactEntry) return exactEntry;

    const matchingEntries = findBoostMatchingPokemonEntries(normalizedValue);
    return matchingEntries.length === 1 ? matchingEntries[0] : null;
}

function syncBoostSelectedPokemonEntry(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || boostPokemonSearchInput?.value || '');
    if(!normalizedValue){
        boostSelectedPokemonEntry = null;
        return null;
    }

    if(boostSelectedPokemonEntry && getBoostPokemonEntrySearchKey(boostSelectedPokemonEntry) === normalizedValue){
        return boostSelectedPokemonEntry;
    }

    boostSelectedPokemonEntry = resolveBoostPokemonEntry(normalizedValue);
    return boostSelectedPokemonEntry;
}

function getBoostSelectedPokemonEntry(value = ''){
    const normalizedValue = normalizePokemonSearchText(value || boostPokemonSearchInput?.value || '');
    if(!normalizedValue) return null;

    if(boostSelectedPokemonEntry && getBoostPokemonEntrySearchKey(boostSelectedPokemonEntry) === normalizedValue){
        return boostSelectedPokemonEntry;
    }

    return resolveBoostPokemonEntry(normalizedValue);
}

function getBoostDefaultFormState(){
    return {
        ...BOOST_DEFAULT_STATE
    };
}

function hasBoostSelectedPokemon(state){
    return Boolean(state?.pokemonEntry && state?.type1);
}

function hasBoostSelectedLevel(state){
    return normalizeBoostLevel(state?.bronzeLevel) > normalizeBoostLevel(state?.bronzeCurrentLevel)
        || normalizeBoostLevel(state?.silverLevel) > normalizeBoostLevel(state?.silverCurrentLevel);
}

function getBoostSelectionPromptText(state){
    // Se os novos selects de tipo estiverem presentes, preferir orientar o usuario a escolher um tipo
    if(false && boostType1Select){
        if(!state?.type1) return 'Selecione um elemento para liberar o cálculo.';
        return '';
    }
    if(!boostPokemonEntries.length) return 'Catalogo indisponivel.';
    if(state?.pokemonEntry) return '';
    if(!state?.pokemonName) return 'Selecione um resultado para liberar o calculo.';
    if((state.pokemonMatches || []).length > 1) return 'Escolha uma opcao da lista.';
    return 'Nenhum resultado encontrado.';
}

function renderBoostSelectionPrompt(state){
    if(!boostSelectionPrompt) return;
    const message = getBoostSelectionPromptText(state);
    boostSelectionPrompt.hidden = !message;
    boostSelectionPrompt.textContent = message;
}

function syncBoostCalculatorVisibility(state){
    const hasSelection = hasBoostSelectedPokemon(state);
    const hasSelectedBoost = hasSelection && hasBoostSelectedLevel(state);

    if(boostLayout){
        boostLayout.dataset.hasSelection = hasSelection ? 'true' : 'false';
    }
    if(boostConfigControls){
        boostConfigControls.hidden = !hasSelection;
    }
    if(boostResultsShell){
        boostResultsShell.hidden = !hasSelectedBoost;
    }
    if(boostHeroSummary){
        boostHeroSummary.hidden = !hasSelectedBoost;
    }
    if(boostHelpPanel){
        boostHelpPanel.hidden = !hasSelection;
        if(!hasSelection){
            boostHelpPanel.open = false;
        }
    }
}

function setBoostFormMessage(message = '', tone = 'info'){
    boostLastFormMessage = message;
    if(!boostFormMessage) return;

    if(!message){
        boostFormMessage.hidden = true;
        boostFormMessage.textContent = '';
        boostFormMessage.className = 'boost-message';
        return;
    }

    boostFormMessage.hidden = false;
    boostFormMessage.textContent = message;
    boostFormMessage.className = `boost-message boost-message--${tone}`;
}

function hideBoostPokemonSearchResults(){
    clearBoostPokemonSearchHideTimer();
    const searchField = boostPokemonSearchInput?.closest('.boost-search-panel__field');
    if(searchField){
        searchField.classList.remove('boost-search-panel__field--drop-up');
    }
    if(boostPokemonResults){
        boostPokemonResults.hidden = true;
        boostPokemonResults.replaceChildren();
    }
    if(boostPokemonNoResults){
        boostPokemonNoResults.hidden = true;
    }
}

function syncBoostPokemonSearchResultsDirection(){
    const searchField = boostPokemonSearchInput?.closest('.boost-search-panel__field');
    if(!searchField) return;

    searchField.classList.remove('boost-search-panel__field--drop-up');
    if(searchField.closest('.catch-search-panel')) return;

    const activePanel = !boostPokemonResults?.hidden
        ? boostPokemonResults
        : (!boostPokemonNoResults?.hidden ? boostPokemonNoResults : null);
    if(!activePanel) return;

    const fieldRect = searchField.getBoundingClientRect();
    const panelRect = activePanel.getBoundingClientRect();
    const viewportHeight = window.innerHeight || document.documentElement?.clientHeight || 0;
    const availableBelow = viewportHeight - fieldRect.bottom;
    const availableAbove = fieldRect.top;
    const desiredHeight = Math.min(
        Math.max(panelRect.height, activePanel.scrollHeight || 0),
        viewportHeight * 0.7
    );

    if(availableBelow < desiredHeight && availableAbove > availableBelow){
        searchField.classList.add('boost-search-panel__field--drop-up');
    }
}

function createBoostSearchResultContent(entry){
    const sprite = document.createElement('img');
    sprite.className = 'speedster-search-item-icon boost-search-item-icon boost-search-item-icon--pokemon';
    sprite.src = getPokemonImageSource(entry);
    sprite.alt = entry.name;
    sprite.title = entry.name;
    sprite.loading = 'lazy';
    sprite.decoding = 'async';
    setImageFallback(sprite, POKEMON_IMAGE_PLACEHOLDER);

    const typeIcons = [entry.type1, entry.type2]
        .filter(Boolean)
        .slice(0, 2)
        .map((typeKey) => {
            const img = document.createElement('img');
            img.className = 'speedster-search-item-icon boost-search-item-icon';
            img.src = `icons-type/${typeKey}.png`;
            img.alt = typeKey;
            img.title = getTypeDisplayName(typeKey);
            img.loading = 'lazy';
            img.decoding = 'async';
            return img;
        });

    const moveIcons = (Array.isArray(entry.moveset) ? entry.moveset : [])
        .filter(Boolean)
        .slice(0, 2)
        .map((typeKey) => {
            const img = document.createElement('img');
            img.className = 'speedster-search-item-icon boost-search-item-icon';
            img.src = `icons-type/${typeKey}.png`;
            img.alt = typeKey;
            img.title = `${getTypeDisplayName(typeKey)} move`;
            img.loading = 'lazy';
            img.decoding = 'async';
            return img;
        });

    const name = document.createElement('span');
    name.className = 'boost-search-item-name';
    name.textContent = entry.name;

    const content = document.createElement('div');
    content.className = 'boost-search-item-content';
    content.appendChild(sprite);
    typeIcons.forEach((icon) => content.appendChild(icon));
    content.appendChild(name);
    moveIcons.forEach((icon) => content.appendChild(icon));
    return content;
}

function applyBoostPokemonSearchSelection(entry){
    if(!entry) return;
    boostSelectedPokemonEntry = entry;
    if(boostPokemonSearchInput){
        boostPokemonSearchInput.value = entry.name;
    }

    if(boostType1Select) boostType1Select.value = entry.type1 || '';
    if(boostType2Select) boostType2Select.value = entry.type2 || '';
    boostSelectedTypes = [entry.type1, entry.type2].filter(Boolean);
    hideBoostPokemonSearchResults();
    renderBoostCalculator();
}

function renderBoostPokemonSearchResults(value = '', options = {}){
    const { keepClosed = false } = options;
    if(!boostPokemonResults || !boostPokemonNoResults) return;
    if(keepClosed){
        hideBoostPokemonSearchResults();
        return;
    }

    const normalizedValue = normalizePokemonSearchText(value || boostPokemonSearchInput?.value || '');
    const entries = getBoostPokemonSearchResultEntries(value);

    if(!entries.length){
        boostPokemonResults.hidden = true;
        boostPokemonResults.replaceChildren();
        boostPokemonNoResults.hidden = !normalizedValue;
        window.requestAnimationFrame(syncBoostPokemonSearchResultsDirection);
        return;
    }

    boostPokemonNoResults.hidden = true;
    boostPokemonResults.hidden = false;
    boostPokemonResults.replaceChildren();

    const currentEntry = getBoostSelectedPokemonEntry(value);
    const fragment = document.createDocumentFragment();
    entries.forEach(entry => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'speedster-search-item boost-search-item';
        item.dataset.pokemonName = entry.name;
        item.setAttribute('aria-label', `Selecionar ${entry.name} para calcular o boost.`);
        if(currentEntry && currentEntry.id === entry.id){
            item.dataset.selected = 'true';
        }
        item.appendChild(createBoostSearchResultContent(entry));
        item.addEventListener('click', () => {
            applyBoostPokemonSearchSelection(entry);
        });
        fragment.appendChild(item);
    });

    boostPokemonResults.appendChild(fragment);
    window.requestAnimationFrame(syncBoostPokemonSearchResultsDirection);
}

function hydrateBoostPokemonOptions(){
    if(!boostPokemonSearchInput) return;

    const entries = refreshBoostPokemonSearchStore();
    boostPokemonSearchInput.placeholder = entries.length
        ? 'Digite para buscar'
        : 'Catalogo indisponivel no momento';

    hideBoostPokemonSearchResults();
    boostSelectedPokemonEntry = resolveBoostPokemonEntry(boostPokemonSearchInput.value || '');
    boostPokemonOptionsHydrated = true;
    // Popular selects de tipo, se disponiveis
    try{ hydrateBoostTypeSelects(); }catch(e){}
}

function hydrateBoostTypeSelects(){
    if(!menuTypes || !menuTypes.length) return;
    if(!boostType1Select && !boostType2Select) return;

    const optionsHtml = menuTypes.map(t => `<option value="${t}">${getTypeDisplayName(t)}</option>`).join('');
    if(boostType1Select){
        const prev = boostType1Select.value || '';
        boostType1Select.innerHTML = `<option value="">Selecione o elemento</option>` + optionsHtml;
        if(prev) boostType1Select.value = prev;
    }
    if(boostType2Select){
        const prev2 = boostType2Select.value || '';
        boostType2Select.innerHTML = `<option value="">(Opcional) Segundo elemento</option>` + optionsHtml;
        if(prev2) boostType2Select.value = prev2;
    }
    // Renderizar seletor visual
    try{ renderBoostTypePicker(); }catch(e){}
    // Restaurar estado de selecao a partir dos selects
    boostSelectedTypes = [];
    const s1 = boostType1Select?.value || '';
    const s2 = boostType2Select?.value || '';
    if(s1) boostSelectedTypes.push(s1);
    if(s2 && s2 !== s1) boostSelectedTypes.push(s2);
    updateBoostTypePickerUI();
}

function renderBoostTypePicker(){
    const picker = document.getElementById('boost-type-picker');
    if(!picker || picker.hidden || !menuTypes) return;
    picker.replaceChildren();
    const fragment = document.createDocumentFragment();
    menuTypes.forEach(type => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'boost-type-button';
        btn.dataset.type = type;
        btn.setAttribute('role','option');
        btn.setAttribute('aria-pressed','false');

        const thumb = document.createElement('span');
        thumb.className = 'boost-type-thumb';
        const img = document.createElement('img');
        img.src = `icons-type/${type}.png`;
        img.alt = getTypeDisplayName(type);
        img.loading = 'lazy'; img.decoding = 'async';
        thumb.appendChild(img);

        setTypeToneVariables(btn, type);

        const label = document.createElement('span');
        label.className = 'boost-type-label';
        label.textContent = getTypeDisplayName(type);

        btn.appendChild(thumb);
        btn.appendChild(label);

        btn.addEventListener('click', ()=> toggleBoostTypeSelection(type));
        btn.addEventListener('keydown', (e)=>{ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); btn.click(); } });

        fragment.appendChild(btn);
    });
    picker.appendChild(fragment);
    updateBoostTypePickerUI();
}

function updateBoostTypePickerUI(){
    const picker = document.getElementById('boost-type-picker');
    if(!picker) return;
    const buttons = picker.querySelectorAll('.boost-type-button');
    buttons.forEach(btn => {
        const type = btn.dataset.type;
        const idx = boostSelectedTypes.indexOf(type);
        if(idx !== -1){
            btn.classList.add('boost-type-button--selected');
            btn.setAttribute('aria-pressed','true');
            btn.dataset.order = String(idx+1);
        } else {
            btn.classList.remove('boost-type-button--selected');
            btn.setAttribute('aria-pressed','false');
            delete btn.dataset.order;
        }
    });
}

function toggleBoostTypeSelection(type){
    const idx = boostSelectedTypes.indexOf(type);
    if(idx !== -1){
        boostSelectedTypes.splice(idx,1);
    } else {
        if(boostSelectedTypes.length === 2) boostSelectedTypes.shift();
        boostSelectedTypes.push(type);
    }
    if(boostType1Select) boostType1Select.value = boostSelectedTypes[0] || '';
    if(boostType2Select) boostType2Select.value = boostSelectedTypes[1] || '';
    updateBoostTypePickerUI();
    renderBoostCalculator();
}

function applyBoostFormState(nextState = getBoostDefaultFormState()){
    const state = {
        ...getBoostDefaultFormState(),
        ...nextState
    };

    if(boostPokemonSearchInput){
        boostPokemonSearchInput.value = String(state.pokemonName || '').trim();
    }
    boostSelectedPokemonEntry = resolveBoostPokemonEntry(state.pokemonName || '');
    const resolvedTypes = [boostSelectedPokemonEntry?.type1 || '', boostSelectedPokemonEntry?.type2 || ''];
    if(boostType1Select) boostType1Select.value = resolvedTypes[0] || '';
    if(boostType2Select) boostType2Select.value = resolvedTypes[1] || '';
    boostSelectedTypes = resolvedTypes.filter(Boolean);
    boostShinyInputs.forEach(input => {
        input.checked = input.value === state.shiny;
    });
    if(boostBronzeCurrentLevelSelect) boostBronzeCurrentLevelSelect.value = String(normalizeBoostLevel(state.bronzeCurrentLevel));
    if(boostBronzeLevelSelect) boostBronzeLevelSelect.value = String(normalizeBoostLevel(state.bronzeLevel));
    if(boostSilverCurrentLevelSelect) boostSilverCurrentLevelSelect.value = String(normalizeBoostLevel(state.silverCurrentLevel));
    if(boostSilverLevelSelect) boostSilverLevelSelect.value = String(normalizeBoostLevel(state.silverLevel));
}

function syncBoostSilverAvailability(options = {}){
    if(boostSilverLevelSelect){
        boostSilverLevelSelect.disabled = false;
    }

    if(boostSilverNote){
        boostSilverNote.textContent = '';
        boostSilverNote.hidden = true;
    }

    return true;
}

function getBoostFormState(){
    const pokemonName = String(boostPokemonSearchInput?.value || '').trim();
    const pokemonMatches = findBoostMatchingPokemonEntries(pokemonName);
    const pokemonEntry = getBoostSelectedPokemonEntry(pokemonName);
    const type1 = pokemonEntry?.type1 || '';
    const type2 = pokemonEntry?.type2 || '';

    if(boostType1Select) boostType1Select.value = type1;
    if(boostType2Select) boostType2Select.value = type2;

    return {
        pokemonName,
        pokemonMatches,
        pokemonEntry,
        typeMode: type2 ? 'double' : 'single',
        type1,
        type2,
        shiny: Array.from(boostShinyInputs).find(input => input.checked)?.value === 'yes' ? 'yes' : 'no',
        bronzeCurrentLevel: normalizeBoostLevel(boostBronzeCurrentLevelSelect?.value),
        bronzeLevel: normalizeBoostLevel(boostBronzeLevelSelect?.value),
        silverCurrentLevel: normalizeBoostLevel(boostSilverCurrentLevelSelect?.value),
        silverLevel: normalizeBoostLevel(boostSilverLevelSelect?.value)
    };
}

function validateBoostFormState(state){
    // Se estiver usando os novos selects de tipo, validar com base nos tipos selecionados
    if(false && boostType1Select){
        if(!state.type1){
            return { valid: false, message: 'Selecione um elemento.' };
        }
        return { valid: true, message: '' };
    }

    if(!boostPokemonEntries.length){
        return {
            valid: false,
            message: 'Catalogo indisponivel.'
        };
    }
    if(!state.pokemonName){
        return {
            valid: false,
            message: 'Selecione um Pokemon.'
        };
    }
    if(!state.pokemonEntry){
        if((state.pokemonMatches || []).length > 1){
            return {
                valid: false,
                message: 'Escolha um Pokemon da lista.'
            };
        }
        return {
            valid: false,
            message: 'Pokemon nao encontrado.'
        };
    }
    if(!state.type1){
        return {
            valid: false,
            message: 'Tipo do Pokemon indisponivel.'
        };
    }
    if(normalizeBoostLevel(state.bronzeLevel) < normalizeBoostLevel(state.bronzeCurrentLevel)){
        return {
            valid: false,
            message: 'O Bronze alvo precisa ser igual ou maior que o Bronze atual.'
        };
    }
    if(normalizeBoostLevel(state.silverLevel) < normalizeBoostLevel(state.silverCurrentLevel)){
        return {
            valid: false,
            message: 'O Silver alvo precisa ser igual ou maior que o Silver atual.'
        };
    }
    return { valid: true, message: '' };
}

function renderBoostPokemonMeta(state){
    if(!boostPokemonMeta) return;
    boostPokemonMeta.replaceChildren();

    const entry = state?.pokemonEntry || null;
    const selectedTypes = [];
    if(state?.type1) selectedTypes.push(state.type1);
    if(state?.type2) selectedTypes.push(state.type2);

    if(!hasBoostSelectedPokemon(state)){
        return;
    }

    // Se houver uma entrada completa de Pokemon, renderizar o preview mais rico
    if(entry){

        const typeKeys = [entry.type1, entry.type2].filter(Boolean);
        const moveKeys = (Array.isArray(entry.moveset) ? entry.moveset : [])
            .map(typeKey => normalizePokemonTypeKey(typeKey))
            .filter(Boolean);
        const preview = document.createElement('article');
        preview.className = 'boost-selected-preview';

        const media = document.createElement('div');
        media.className = 'boost-selected-preview__media';

        const mountPokemonFallback = () => {
            if(media.querySelector('.boost-material-card__fallback')) return;
            media.replaceChildren(createBoostMediaFallback(entry.name));
        };

        const sprite = document.createElement('img');
        sprite.src = getPokemonImageSource(entry);
        sprite.alt = entry.name;
        sprite.loading = 'eager';
        sprite.decoding = 'async';
        sprite.addEventListener('error', mountPokemonFallback, { once: true });
        media.appendChild(sprite);

        const header = document.createElement('div');
        header.className = 'boost-selected-preview__header';

        const identity = document.createElement('div');
        identity.className = 'boost-selected-preview__identity';

        const kicker = document.createElement('span');
        kicker.className = 'boost-selected-preview__kicker';
        kicker.textContent = entry.variant === POKEMON_CATALOG_VARIANT_MEGA
            ? 'Selecionado - Mega'
            : 'Selecionado';

        const title = document.createElement('strong');
        title.className = 'boost-selected-preview__title';
        title.textContent = entry.name;

        identity.append(kicker, title);
        header.append(media, identity);

        const groups = document.createElement('div');
        groups.className = 'boost-selected-preview__groups';

        const typeGroup = document.createElement('div');
        typeGroup.className = 'boost-selected-preview__group';

        const typeLabel = document.createElement('span');
        typeLabel.className = 'boost-selected-preview__group-label';
        typeLabel.textContent = 'Tipo';

        const typeChips = document.createElement('div');
        typeChips.className = 'boost-selected-preview__chips';
        typeKeys.forEach(typeKey => {
            typeChips.appendChild(createBoostTypeChip(typeKey));
        });
        typeGroup.append(typeLabel, typeChips);

        const stoneGroup = document.createElement('div');
        stoneGroup.className = 'boost-selected-preview__group';

        const stoneLabel = document.createElement('span');
        stoneLabel.className = 'boost-selected-preview__group-label';
        const usesAceBronzeRule = usesBoostAncientBronzeStone(state);
        const usesBraveBronzeRule = usesBoostBraveBronzeStone(state);
        const usesDittoBronzeRule = isBoostDittoState(state);
        stoneLabel.textContent = usesBraveBronzeRule
            ? 'Brave'
            : (
                usesAceBronzeRule
                    ? (hasBoostSpecialTag(state, 'pre-ace') ? 'Pre Ace' : 'Ace')
                    : (usesDittoBronzeRule ? 'Ditto' : (typeKeys.length > 1 ? 'Stones' : 'Stone'))
            );

        const stoneChips = document.createElement('div');
        stoneChips.className = 'boost-selected-preview__chips';
        if(usesDittoBronzeRule){
        } else if(usesBraveBronzeRule){
            stoneChips.appendChild(createBoostNamedStoneChip('Brave Stone'));
        } else if(usesAceBronzeRule){
            stoneChips.appendChild(createBoostNamedStoneChip('Ancient Stone'));
        } else {
            typeKeys.forEach(typeKey => {
                stoneChips.appendChild(createBoostStoneChip(typeKey));
            });
        }
        stoneGroup.append(stoneLabel, stoneChips);

        const movesetGroup = document.createElement('div');
        movesetGroup.className = 'boost-selected-preview__group';

        const movesetLabel = document.createElement('span');
        movesetLabel.className = 'boost-selected-preview__group-label';
        movesetLabel.textContent = 'Moveset';

        const movesetChips = document.createElement('div');
        movesetChips.className = 'boost-selected-preview__chips';
        if(moveKeys.length){
            moveKeys.forEach(typeKey => {
                movesetChips.appendChild(createBoostMoveChip(typeKey));
            });
        } else {
            movesetChips.appendChild(createBoostTextChip('Nao informado'));
        }
        movesetGroup.append(movesetLabel, movesetChips);

        groups.append(typeGroup, stoneGroup, movesetGroup);
        preview.append(header, groups);
        boostPokemonMeta.appendChild(preview);
    } else {
        // Renderizar um preview simplificado quando o usuario selecionou apenas tipos (sem entrada de Pokemon)
        const preview = document.createElement('article');
        preview.className = 'boost-selected-preview';

        const header = document.createElement('div');
        header.className = 'boost-selected-preview__header';

        const identity = document.createElement('div');
        identity.className = 'boost-selected-preview__identity';

        const kicker = document.createElement('span');
        kicker.className = 'boost-selected-preview__kicker';
        kicker.textContent = 'Selecionado';

        const title = document.createElement('strong');
        title.className = 'boost-selected-preview__title';
        title.textContent = selectedTypes.map(getTypeDisplayName).join(' + ');

        identity.append(kicker, title);
        header.append(identity);

        const groups = document.createElement('div');
        groups.className = 'boost-selected-preview__groups';

        const typeGroup = document.createElement('div');
        typeGroup.className = 'boost-selected-preview__group';
        const typeLabel = document.createElement('span');
        typeLabel.className = 'boost-selected-preview__group-label';
        typeLabel.textContent = 'Tipo';
        const typeChips = document.createElement('div');
        typeChips.className = 'boost-selected-preview__chips';
        selectedTypes.forEach(typeKey => typeChips.appendChild(createBoostTypeChip(typeKey)));
        typeGroup.append(typeLabel, typeChips);

        const stoneGroup = document.createElement('div');
        stoneGroup.className = 'boost-selected-preview__group';
        const stoneLabel = document.createElement('span');
        stoneLabel.className = 'boost-selected-preview__group-label';
        stoneLabel.textContent = selectedTypes.length > 1 ? 'Stones' : 'Stone';
        const stoneChips = document.createElement('div');
        stoneChips.className = 'boost-selected-preview__chips';
        selectedTypes.forEach(typeKey => stoneChips.appendChild(createBoostStoneChip(typeKey)));
        stoneGroup.append(stoneLabel, stoneChips);

        groups.append(typeGroup, stoneGroup);
        preview.append(header, groups);
        boostPokemonMeta.appendChild(preview);
    }
}

function getBoostStoneMetaByType(typeKey = ''){
    const normalizedType = normalizePokemonTypeKey(typeKey);
    const mappedStone = BOOST_TYPE_STONE_META[normalizedType] || null;
    return {
        name: mappedStone?.name || `${getTypeDisplayName(normalizedType)} Stone`,
        image: mappedStone?.image || '',
        typeKey: normalizedType,
        category: 'stone',
        craftable: false
    };
}

function createBoostInlineMedia(label, imageSrc = ''){
    const media = document.createElement('span');
    media.className = 'boost-pokemon-chip__media';

    const mountFallback = () => {
        if(media.querySelector('.boost-material-card__fallback')) return;
        media.replaceChildren(createBoostMediaFallback(label));
    };

    if(imageSrc){
        const image = document.createElement('img');
        image.src = imageSrc;
        image.alt = label;
        image.loading = 'lazy';
        image.decoding = 'async';
        image.addEventListener('error', mountFallback, { once: true });
        media.appendChild(image);
    } else {
        mountFallback();
    }

    return media;
}

function createBoostTypeChip(typeKey){
    const normalizedType = normalizePokemonTypeKey(typeKey);
    const chip = document.createElement('span');
    chip.className = 'boost-pokemon-chip';
    chip.innerHTML = `<img src="icons-type/${normalizedType}.png" alt="" aria-hidden="true" loading="lazy" decoding="async"><span>${getTypeDisplayName(normalizedType)}</span>`;
    setTypeToneVariables(chip, normalizedType);
    return chip;
}

function createBoostMoveChip(typeKey){
    const normalizedType = normalizePokemonTypeKey(typeKey);
    const chip = document.createElement('span');
    chip.className = 'boost-pokemon-chip boost-pokemon-chip--move';
    chip.innerHTML = `<img src="icons-type/${normalizedType}.png" alt="" aria-hidden="true" loading="lazy" decoding="async"><span>${getTypeDisplayName(normalizedType)}</span>`;
    return chip;
}

function createBoostTextChip(label){
    const chip = document.createElement('span');
    chip.className = 'boost-pokemon-chip boost-pokemon-chip--text';
    chip.textContent = label;
    return chip;
}

function createBoostStoneChip(typeKey){
    const stoneMeta = getBoostStoneMetaByType(typeKey);
    const chip = document.createElement('span');
    chip.className = 'boost-pokemon-chip boost-pokemon-chip--stone';

    const label = document.createElement('span');
    label.textContent = stoneMeta.name;

    chip.append(createBoostInlineMedia(stoneMeta.name, stoneMeta.image), label);
    return chip;
}

function createBoostNamedStoneChip(name){
    const materialMeta = getBoostMaterialMeta(name, {
        category: 'stone',
        craftable: false
    });
    const chip = document.createElement('span');
    chip.className = 'boost-pokemon-chip boost-pokemon-chip--stone';

    const label = document.createElement('span');
    label.textContent = name;

    chip.append(createBoostInlineMedia(name, materialMeta.image), label);
    return chip;
}

function getBoostMaterialMeta(name, overrides = {}){
    const namedStoneMeta = BOOST_NAMED_STONE_META[name]
        ? {
            ...BOOST_NAMED_STONE_META[name],
            craftable: false,
            category: 'stone'
        }
        : {};
    const staticMeta = BOOST_STATIC_MATERIAL_META[name]
        ? { ...BOOST_STATIC_MATERIAL_META[name] }
        : { ...namedStoneMeta };
    const typeKey = overrides.typeKey || staticMeta.typeKey || '';
    const stoneMeta = typeKey ? getBoostStoneMetaByType(typeKey) : null;

    if(!staticMeta.image && stoneMeta){
        staticMeta.image = stoneMeta.image;
        staticMeta.craftable = false;
        staticMeta.category = 'stone';
        staticMeta.typeKey = stoneMeta.typeKey;
    }

    return {
        image: '',
        craftable: false,
        category: 'generic',
        typeKey: '',
        ...staticMeta,
        ...overrides,
        typeKey
    };
}

function createBoostMaterialItem(name, quantity, overrides = {}){
    if(!quantity) return null;
    return {
        name,
        quantity,
        ...getBoostMaterialMeta(name, overrides)
    };
}

function createBoostStoneMaterialItem(typeKey, quantity, overrides = {}){
    const stoneMeta = getBoostStoneMetaByType(typeKey);
    return createBoostMaterialItem(stoneMeta.name, quantity, {
        ...stoneMeta,
        ...overrides,
        typeKey: stoneMeta.typeKey
    });
}

function createBoostNamedStoneMaterialItem(name, quantity, overrides = {}){
    return createBoostMaterialItem(name, quantity, {
        craftable: false,
        category: 'stone',
        ...overrides
    });
}

function hasBoostSpecialTag(state, tag){
    const tags = state?.pokemonEntry?.specialTags;
    return Array.isArray(tags) && tags.includes(tag);
}

function usesBoostAncientBronzeStone(state){
    return hasBoostSpecialTag(state, 'ace') || hasBoostSpecialTag(state, 'pre-ace');
}

function usesBoostBraveBronzeStone(state){
    const entry = state?.pokemonEntry;
    if(!entry) return false;
    if(usesBoostAncientBronzeStone(state)) return false;
    const normalizedName = normalizePokemonSearchText(entry.name || state?.pokemonName || '');
    const normalizedPriceLabel = normalizePokemonSearchText(entry.priceLabel || '');
    return entry.roleKey === 'striker'
        || normalizedPriceLabel.endsWith('rush')
        || normalizedName.includes('alolan');
}

function isBoostDittoState(state){
    return normalizePokemonSearchText(state?.pokemonEntry?.name || state?.pokemonName || '') === 'ditto';
}

function getBoostBronzeNormalStoneQuantity(state, options = {}){
    const {
        currentLevel = 0,
        targetLevel = state?.bronzeLevel,
        cumulative = false
    } = options;
    const normalizedLevel = normalizeBoostLevel(targetLevel);
    if(normalizedLevel <= 0) return 0;
    const levelMultiplier = cumulative
        ? getBoostLevelRangeStepSum(currentLevel, normalizedLevel)
        : getBoostLevelDelta(currentLevel, normalizedLevel);
    if(levelMultiplier <= 0) return 0;
    if(state?.typeMode === 'double'){
        return levelMultiplier * BOOST_BRONZE_DOUBLE_STONES_PER_LEVEL * 2;
    }
    return levelMultiplier * BOOST_BRONZE_SINGLE_STONES_PER_LEVEL;
}

function createBoostDittoBronzeStoneItems(targetLevel, options = {}){
    const {
        currentLevel = 0,
        cumulative = false,
        contextLabel = '',
        detail = ''
    } = options;
    const current = normalizeBoostLevel(currentLevel);
    const normalizedLevel = normalizeBoostLevel(targetLevel);
    if(normalizedLevel <= current) return [];

    const levels = cumulative
        ? Array.from({ length: normalizedLevel - current }, (_, index) => current + index + 1)
        : [normalizedLevel];

    return levels.flatMap(stepLevel => {
        const step = BOOST_DITTO_BRONZE_STONE_STEPS[stepLevel];
        if(!step) return [];
        return step.stones.map(name => createBoostNamedStoneMaterialItem(name, step.quantity, {
            detail: detail || `Bronze ${stepLevel} do Ditto.`,
            contextLabel
        }));
    });
}

function createBoostBronzeStoneItems(state, options = {}){
    const {
        currentLevel = 0,
        targetLevel = state?.bronzeLevel,
        cumulative = false,
        contextLabel = '',
        directDetail = ''
    } = options;
    const current = normalizeBoostLevel(currentLevel);
    const normalizedLevel = normalizeBoostLevel(targetLevel);
    if(normalizedLevel <= current) return [];

    if(isBoostDittoState(state)){
        return createBoostDittoBronzeStoneItems(normalizedLevel, {
            currentLevel: current,
            cumulative,
            contextLabel,
            detail: directDetail
        });
    }

    if(usesBoostBraveBronzeStone(state)){
        return [
            createBoostNamedStoneMaterialItem('Brave Stone', getBoostBronzeNormalStoneQuantity(state, { currentLevel: current, targetLevel: normalizedLevel, cumulative }), {
                detail: directDetail || 'Mesma quantidade das stones normais, trocada por Brave Stone.',
                contextLabel
            })
        ];
    }

    if(usesBoostAncientBronzeStone(state)){
        return [
            createBoostMaterialItem('Ancient Stone', getBoostBronzeNormalStoneQuantity(state, { currentLevel: current, targetLevel: normalizedLevel, cumulative }), {
                category: 'ancient',
                detail: directDetail || 'Mesma quantidade das stones normais, trocada por Ancient Stone para Pokemon Ace ou Pre Ace.',
                contextLabel
            })
        ];
    }

    const levelMultiplier = cumulative
        ? getBoostLevelRangeStepSum(current, normalizedLevel)
        : getBoostLevelDelta(current, normalizedLevel);
    if(levelMultiplier <= 0) return [];

    if(state.typeMode === 'double'){
        return [
            createBoostStoneMaterialItem(state.type1, levelMultiplier * BOOST_BRONZE_DOUBLE_STONES_PER_LEVEL, {
                detail: directDetail || `Tipo ${getTypeDisplayName(state.type1)}.`,
                contextLabel
            }),
            createBoostStoneMaterialItem(state.type2, levelMultiplier * BOOST_BRONZE_DOUBLE_STONES_PER_LEVEL, {
                detail: directDetail || `Tipo ${getTypeDisplayName(state.type2)}.`,
                contextLabel
            })
        ];
    }

    return [
        createBoostStoneMaterialItem(state.type1, levelMultiplier * BOOST_BRONZE_SINGLE_STONES_PER_LEVEL, {
            detail: directDetail || `Tipo ${getTypeDisplayName(state.type1)}.`,
            contextLabel
        })
    ];
}

function aggregateBoostMaterialItems(groups = [], options = {}){
    const { asTotal = false } = options;
    const aggregateMap = new Map();

    groups.flat().forEach(item => {
        if(!item || !item.name || !item.quantity) return;
        const existing = aggregateMap.get(item.name);
        if(existing){
            existing.quantity += item.quantity;
            if(!existing.typeKey && item.typeKey){
                existing.typeKey = item.typeKey;
            }
            return;
        }
        aggregateMap.set(item.name, {
            ...item
        });
    });

    const items = Array.from(aggregateMap.values());
    if(!asTotal) return items;

    return items.map(item => ({
        ...item,
        detail: '',
        hideDetail: true,
        contextLabel: getBoostTotalMaterialBadgeText(item)
    }));
}

function getBoostLevelCumulativeStepSum(level){
    const normalizedLevel = normalizeBoostLevel(level);
    return (normalizedLevel * (normalizedLevel + 1)) / 2;
}

function getBoostLevelRangeStepSum(currentLevel, targetLevel){
    const current = normalizeBoostLevel(currentLevel);
    const target = normalizeBoostLevel(targetLevel);
    if(target <= current) return 0;
    return getBoostLevelCumulativeStepSum(target) - getBoostLevelCumulativeStepSum(current);
}

function getBoostLevelDelta(currentLevel, targetLevel){
    return Math.max(0, normalizeBoostLevel(targetLevel) - normalizeBoostLevel(currentLevel));
}

function getBoostBronzeStarQuantity(state, options = {}){
    if(state?.shiny !== 'yes') return 0;
    const {
        currentLevel = state?.bronzeCurrentLevel,
        targetLevel = state?.bronzeLevel
    } = options;
    const current = normalizeBoostLevel(currentLevel);
    const target = normalizeBoostLevel(targetLevel);
    if(target <= current) return 0;

    let total = 0;
    for(let level = current + 1; level <= target; level += 1){
        total += Number(BOOST_BRONZE_STAR_STEPS[level] || 0);
    }
    return total;
}

function getBoostTotalMaterialBadgeText(item){
    const materialCategories = new Set([
        'ancient-shiny',
        'bronze-piece',
        'silver-token',
        'silver-flask'
    ]);
    return materialCategories.has(item?.category) ? 'Material' : 'Total';
}

function sortBoostMaterialItems(items = []){
    const categoryOrder = {
        stone: 0,
        ancient: 1,
        'ancient-shiny': 2,
        bronze: 3,
        'bronze-piece': 4,
        'silver-star': 5,
        'silver-token': 6,
        'silver-piece': 7,
        'silver-flask': 8,
        generic: 20
    };

    return [...items].sort((left, right) => {
        const leftOrder = categoryOrder[left.category] ?? 99;
        const rightOrder = categoryOrder[right.category] ?? 99;
        if(leftOrder !== rightOrder) return leftOrder - rightOrder;
        return left.name.localeCompare(right.name, 'pt-BR');
    });
}

function sortBoostTotalItems(items = []){
    const badgeOrder = {
        Total: 0,
        Material: 1
    };

    return [...sortBoostMaterialItems(items)].sort((left, right) => {
        const leftBadgeOrder = badgeOrder[getBoostTotalMaterialBadgeText(left)] ?? 99;
        const rightBadgeOrder = badgeOrder[getBoostTotalMaterialBadgeText(right)] ?? 99;
        if(leftBadgeOrder !== rightBadgeOrder){
            return leftBadgeOrder - rightBadgeOrder;
        }
        return sortBoostMaterialItems([left, right])[0] === left ? -1 : 1;
    });
}

function calculateBoostTotalDirectItems(state){
    const totalDirectItems = [];
    const bronzeCurrent = normalizeBoostLevel(state.bronzeCurrentLevel);
    const bronzeTarget = normalizeBoostLevel(state.bronzeLevel);
    const silverCurrent = normalizeBoostLevel(state.silverCurrentLevel);
    const silverTarget = normalizeBoostLevel(state.silverLevel);
    const silverStepSum = getBoostLevelRangeStepSum(silverCurrent, silverTarget);

    if(bronzeTarget > bronzeCurrent){
        totalDirectItems.push(...createBoostBronzeStoneItems(state, { currentLevel: bronzeCurrent, targetLevel: bronzeTarget, cumulative: true }));

        if(state.shiny === 'yes'){
            const bronzeStarCount = getBoostBronzeStarQuantity(state, { currentLevel: bronzeCurrent, targetLevel: bronzeTarget });
            totalDirectItems.push(
                createBoostMaterialItem('Bronze Star', bronzeStarCount, {
                    category: 'bronze'
                })
            );
        }
    }

    if(silverTarget > silverCurrent){
        totalDirectItems.push(
            createBoostMaterialItem('Ancient Stone', silverStepSum * BOOST_SILVER_ANCIENT_STONE_PER_LEVEL, {
                category: 'ancient'
            }),
            createBoostMaterialItem('Silver Star', silverStepSum, {
                craftable: true,
                category: 'silver-star'
            })
        );
    }

    return sortBoostMaterialItems(totalDirectItems.filter(Boolean));
}

function calculateBoostTotalCraftItems(state){
    const totalCraftItems = [];
    const silverStepSum = getBoostLevelRangeStepSum(state.silverCurrentLevel, state.silverLevel);
    const totalBronzeStarCount = getBoostBronzeStarQuantity(state);
    const totalSilverStarCount = silverStepSum;
    const totalSilverPieceCount = totalSilverStarCount * (BOOST_SILVER_STAR_RECIPE['Piece of Silver Star'] || 0);
    const totalPieceBronzeFromBronzeStars = totalBronzeStarCount * BOOST_BRONZE_PIECES_PER_STAR;

    if(totalSilverStarCount > 0){
        Object.entries(BOOST_SILVER_STAR_RECIPE).forEach(([name, amount]) => {
            let category = 'generic';
            if(name === 'Silver Flask') category = 'silver-flask';
            if(name === 'Piece of Silver Star') category = 'silver-piece';
            if(name === 'Shining Ancient Stone') category = 'ancient-shiny';
            totalCraftItems.push(
                createBoostMaterialItem(name, amount * totalSilverStarCount, {
                    category
                })
            );
        });
    }

    if(totalSilverPieceCount > 0){
        Object.entries(BOOST_SILVER_PIECE_RECIPE).forEach(([name, amount]) => {
            let category = 'generic';
            if(name === 'Piece of Bronze Star') category = 'bronze-piece';
            if(name === 'Silver Token') category = 'silver-token';
            totalCraftItems.push(
                createBoostMaterialItem(name, amount * totalSilverPieceCount, {
                    category
                })
            );
        });
    }

    if(totalPieceBronzeFromBronzeStars > 0){
        totalCraftItems.push(
            createBoostMaterialItem('Piece of Bronze Star', totalPieceBronzeFromBronzeStars, {
                category: 'bronze-piece'
            })
        );
    }

    return sortBoostMaterialItems(totalCraftItems.filter(Boolean));
}

function calculateBoostMaterials(state){
    const bronzeItems = [];
    const silverItems = [];
    const starCraftItems = [];
    let bronzeStarCraftCount = 0;
    let silverPieceCount = 0;
    const bronzeCurrent = normalizeBoostLevel(state.bronzeCurrentLevel);
    const bronzeTarget = normalizeBoostLevel(state.bronzeLevel);
    const silverCurrent = normalizeBoostLevel(state.silverCurrentLevel);
    const silverTarget = normalizeBoostLevel(state.silverLevel);

    if(bronzeTarget > bronzeCurrent){
        bronzeItems.push(...createBoostBronzeStoneItems(state, { currentLevel: bronzeCurrent, targetLevel: bronzeTarget, cumulative: true, contextLabel: 'Direto' }));

        if(state.shiny === 'yes'){
            const bronzeStarCount = getBoostBronzeStarQuantity(state, { currentLevel: bronzeCurrent, targetLevel: bronzeTarget });
            bronzeItems.push(
                createBoostMaterialItem('Bronze Star', bronzeStarCount, {
                    detail: 'Custo direto do shiny.',
                    contextLabel: 'Direto'
                })
            );
            bronzeStarCraftCount += bronzeStarCount;
        }
    }

    if(silverTarget > silverCurrent){
        const silverStepSum = getBoostLevelRangeStepSum(silverCurrent, silverTarget);
        silverItems.push(
            createBoostMaterialItem('Ancient Stone', silverStepSum * BOOST_SILVER_ANCIENT_STONE_PER_LEVEL, {
                detail: 'Custo direto do Silver.',
                contextLabel: 'Direto'
            }),
            createBoostMaterialItem('Silver Star', silverStepSum, {
                craftable: true,
                category: 'silver-star',
                detail: 'Custo direto do Silver.',
                contextLabel: 'Direto'
            })
        );

        Object.entries(BOOST_SILVER_STAR_RECIPE).forEach(([name, amount]) => {
            let category = 'generic';
            if(name === 'Silver Flask') category = 'silver-flask';
            if(name === 'Piece of Silver Star') category = 'silver-piece';
            if(name === 'Shining Ancient Stone') category = 'ancient-shiny';
            starCraftItems.push(
                createBoostMaterialItem(name, amount * silverStepSum, {
                    category,
                    detail: name === 'Piece of Silver Star'
                        ? 'Item usado no craft da Silver Star.'
                        : 'Receita da Silver Star.',
                    contextLabel: 'Craft'
                })
            );
            if(name === 'Piece of Silver Star'){
                silverPieceCount += amount * silverStepSum;
            }
        });
    }

    if(silverPieceCount > 0){
        Object.entries(BOOST_SILVER_PIECE_RECIPE).forEach(([name, amount]) => {
            let category = 'generic';
            if(name === 'Piece of Bronze Star') category = 'bronze-piece';
            if(name === 'Silver Token') category = 'silver-token';
            starCraftItems.push(
                createBoostMaterialItem(name, amount * silverPieceCount, {
                    category,
                    detail: 'Material da Piece of Silver Star.',
                    contextLabel: 'Craft'
                })
            );
        });
    }

    if(bronzeStarCraftCount > 0){
        starCraftItems.push(
            createBoostMaterialItem('Piece of Bronze Star', bronzeStarCraftCount * BOOST_BRONZE_PIECES_PER_STAR, {
                category: 'bronze-piece',
                detail: 'Craft da Bronze Star.',
                contextLabel: 'Craft'
            })
        );
    }

    const cleanBronzeItems = sortBoostMaterialItems(bronzeItems.filter(Boolean));
    const cleanSilverItems = sortBoostMaterialItems(silverItems.filter(Boolean));
    const cleanStarCraftItems = sortBoostMaterialItems(starCraftItems.filter(Boolean));
    const totalDirectItems = calculateBoostTotalDirectItems(state);
    const totalCraftItems = calculateBoostTotalCraftItems(state);
    const totalItems = sortBoostTotalItems(aggregateBoostMaterialItems([
        totalDirectItems,
        totalCraftItems
    ], { asTotal: true }));

    return {
        bronzeItems: cleanBronzeItems,
        silverItems: cleanSilverItems,
        starCraftItems: cleanStarCraftItems,
        totalItems,
        bronzeStarCount: cleanBronzeItems
            .filter(item => item.name === 'Bronze Star')
            .reduce((sum, item) => sum + item.quantity, 0),
        silverStarCount: cleanSilverItems
            .filter(item => item.name === 'Silver Star')
            .reduce((sum, item) => sum + item.quantity, 0),
        distinctMaterialCount: totalItems.length
    };
}

function getBoostMaterialBadgeText(item){
    if(item.contextLabel) return item.contextLabel;
    return item.craftable ? 'Fabricavel' : 'Item direto';
}

function getBoostMaterialDetailText(item){
    if(item.detail) return item.detail;
    if(item.typeKey) return `Tipo ${getTypeDisplayName(item.typeKey)}.`;
    if(item.name === 'Silver Star') return 'Pode ser fabricada.';
    if(item.name === 'Bronze Star') return 'Pode ser fabricada.';
    return item.craftable ? 'Item craftavel.' : 'Material do calculo.';
}

function createBoostMediaFallback(label){
    const fallback = document.createElement('span');
    fallback.className = 'boost-material-card__fallback';
    fallback.textContent = String(label || 'Sem imagem');
    fallback.title = String(label || 'Sem imagem');
    fallback.setAttribute('aria-hidden', 'true');
    return fallback;
}

function createBoostMaterialCard(item){
    const card = document.createElement('article');
    card.className = 'boost-material-card';
    if(item.category){
        card.dataset.category = item.category;
    }

    const media = document.createElement('div');
    media.className = 'boost-material-card__media';

    const mountFallback = () => {
        if(media.querySelector('.boost-material-card__fallback')) return;
        media.replaceChildren(createBoostMediaFallback(item.name));
    };

    if(item.image){
        const image = document.createElement('img');
        image.src = item.image;
        image.alt = item.name;
        image.loading = 'eager';
        image.decoding = 'async';
        image.addEventListener('error', mountFallback, { once: true });
        media.appendChild(image);
    } else {
        mountFallback();
    }

    const content = document.createElement('div');
    content.className = 'boost-material-card__content';

    const title = document.createElement('strong');
    title.className = 'boost-material-card__title';
    title.textContent = item.name;

    const quantity = document.createElement('span');
    quantity.className = 'boost-material-card__quantity num';
    quantity.dataset.value = String(item.quantity);
    quantity.textContent = formatBoostQuantity(item.quantity);

    const footer = document.createElement('div');
    footer.className = 'boost-material-card__footer';

    const stateBadge = document.createElement('span');
    stateBadge.className = 'boost-material-card__badge';
    stateBadge.textContent = getBoostMaterialBadgeText(item);

    footer.appendChild(stateBadge);
    content.append(title, quantity);
    if(!item.hideDetail){
        const detail = document.createElement('p');
        detail.className = 'boost-material-card__detail';
        detail.textContent = getBoostMaterialDetailText(item);
        content.append(detail);
    }
    content.append(footer);
    card.append(media, content);
    return card;
}

function createBoostEmptyState(title, description){
    const emptyState = document.createElement('div');
    emptyState.className = 'boost-empty-state';

    const strong = document.createElement('strong');
    strong.textContent = title;

    const span = document.createElement('span');
    span.textContent = description;

    emptyState.append(strong, span);
    return emptyState;
}

function renderBoostMaterialGrid(container, items, emptyTitle, emptyDescription){
    if(!container) return;
    container.replaceChildren();

    if(!items.length){
        container.appendChild(createBoostEmptyState(emptyTitle, emptyDescription));
        return;
    }

    const fragment = document.createDocumentFragment();
    items.forEach(item => {
        fragment.appendChild(createBoostMaterialCard(item));
    });
    container.appendChild(fragment);
    animateCalcResult(container);
}

function renderBoostOverview(state, breakdown){
    const naturalTypeCount = [state.type1, state.type2].filter(Boolean).length;
    const bronzeDirectCount = breakdown.bronzeItems.length;
    const craftCount = breakdown.starCraftItems.length;
    const selectedPokemonName = state?.pokemonEntry?.name || 'Pokemon selecionado';
    const selectedTypeLabel = [state.type1, state.type2]
        .filter(Boolean)
        .map(getTypeDisplayName)
        .join(' + ');

    if(boostSummaryTarget){
        boostSummaryTarget.textContent = selectedPokemonName;
    }
    if(boostSummaryFlags){
        boostSummaryFlags.textContent = `${state.shiny === 'yes' ? 'Shiny' : 'Comum'} - ${selectedTypeLabel || `${naturalTypeCount} tipo(s)`} - Bronze ${state.bronzeCurrentLevel} -> ${state.bronzeLevel} - Silver ${state.silverCurrentLevel} -> ${state.silverLevel}`;
    }
    if(!boostOverviewCards) return;

    const cards = [
        {
            label: 'Pokemon',
            value: selectedPokemonName,
            note: selectedTypeLabel || (naturalTypeCount > 1 ? 'Pokemon de 2 tipos' : 'Pokemon de 1 tipo')
        },
        {
            label: 'Bronze',
            value: `${state.bronzeCurrentLevel} -> ${state.bronzeLevel}`,
            note: bronzeDirectCount ? `${formatBoostQuantity(bronzeDirectCount)} material(is) direto(s)` : 'Sem custo direto'
        },
        {
            label: 'Silver',
            value: `${state.silverCurrentLevel} -> ${state.silverLevel}`,
            note: 'Silver disponivel'
        },
        {
            label: 'Total',
            value: `${formatBoostQuantity(breakdown.distinctMaterialCount)} item(ns)`,
            note: craftCount
                ? `${formatBoostQuantity(craftCount)} item(ns) de craft • inclui boosts anteriores`
                : 'Inclui boosts anteriores'
        }
    ];

    const fragment = document.createDocumentFragment();
    cards.forEach(cardData => {
        const card = document.createElement('article');
        card.className = 'boost-overview-card';

        const label = document.createElement('span');
        label.className = 'boost-overview-card__label';
        label.textContent = cardData.label;

        const value = document.createElement('strong');
        value.className = 'boost-overview-card__value';
        value.textContent = cardData.value;

        const note = document.createElement('p');
        note.className = 'boost-overview-card__note';
        note.textContent = cardData.note;

        card.append(label, value, note);
        fragment.appendChild(card);
    });

    boostOverviewCards.replaceChildren(fragment);
    animateCalcResult(boostOverviewCards);
}
function renderBoostBlockedState(state, message){
    const emptyBreakdown = {
        bronzeItems: [],
        silverItems: [],
        starCraftItems: [],
        totalItems: [],
        bronzeStarCount: 0,
        silverStarCount: 0,
        distinctMaterialCount: 0
    };
    renderBoostPokemonMeta(state);
    renderBoostOverview(state, emptyBreakdown);
    renderBoostMaterialGrid(boostBronzeResults, [], 'Calculo indisponivel', message);
    renderBoostMaterialGrid(boostSilverResults, [], 'Calculo indisponivel', message);
    renderBoostMaterialGrid(boostStarResults, [], 'Calculo indisponivel', message);
    renderBoostMaterialGrid(boostTotalResults, [], 'Calculo indisponivel', message);
}
function renderBoostCalculator(options = {}){
    if(!contentBoost) return;
    const { announceSilverReset = false } = options;

    syncBoostSilverAvailability({ announceReset: announceSilverReset });

    const state = getBoostFormState();
    renderBoostSelectionPrompt(state);
    renderBoostPokemonMeta(state);
    syncBoostCalculatorVisibility(state);
    if(!hasBoostSelectedPokemon(state)){
        setBoostFormMessage('', 'info');
        return;
    }
    const validation = validateBoostFormState(state);
    if(!validation.valid){
        setBoostFormMessage(validation.message, 'warning');
        renderBoostBlockedState(state, validation.message);
        return;
    }

    if(announceSilverReset && boostLastFormMessage && boostLastFormMessage.includes('Silver foi resetado')){
        setBoostFormMessage(boostLastFormMessage, 'warning');
    } else {
        setBoostFormMessage('', 'info');
    }

    const breakdown = calculateBoostMaterials(state);
    renderBoostOverview(state, breakdown);
    renderBoostMaterialGrid(
        boostBronzeResults,
        breakdown.bronzeItems,
        state.bronzeLevel > state.bronzeCurrentLevel ? 'Sem materiais de Bronze.' : 'Bronze sem alteracao.',
        state.bronzeLevel > state.bronzeCurrentLevel
            ? 'Nada para mostrar.'
            : 'Escolha um Bronze alvo maior que o Bronze atual.'
    );
    renderBoostMaterialGrid(
        boostSilverResults,
        breakdown.silverItems,
        'Silver sem alteracao.',
        'Escolha um Silver alvo maior que o Silver atual.'
    );
    renderBoostMaterialGrid(
        boostStarResults,
        breakdown.starCraftItems,
        'Sem craft adicional.',
        'Os crafts aparecem aqui quando forem necessarios.'
    );
    renderBoostMaterialGrid(
        boostTotalResults,
        breakdown.totalItems,
        'Sem materiais.',
        'Escolha um alvo maior que o boost atual.'
    );
}
function initializeBoostCalculatorPage(){
    if(!contentBoost) return Promise.resolve(false);
    if(boostPageInitialized){
        return Promise.all([
            ensureTypesDataLoaded(),
            ensurePokemonCatalogLoaded()
        ]).then(() => {
            hydrateBoostPokemonOptions();
            try{ hydrateBoostTypeSelects(); }catch(e){}
            renderBoostCalculator();
            return true;
        }).catch(error => {
            console.error('Boost calculator load failed', error);
            setBoostFormMessage('Nao foi possivel carregar o catalogo da calculadora de boost.', 'warning');
            return false;
        });
    }

    const handleBoostChange = (event) => {
        const shouldAnnounceReset = event?.target === boostBronzeLevelSelect;
        renderBoostCalculator({ announceSilverReset: shouldAnnounceReset });
    };

    boostShinyInputs.forEach(input => input.addEventListener('change', handleBoostChange));
    [boostBronzeCurrentLevelSelect, boostBronzeLevelSelect, boostSilverCurrentLevelSelect, boostSilverLevelSelect]
        .filter(Boolean)
        .forEach(element => {
            element.addEventListener('change', handleBoostChange);
        });

    if(boostType1Select) boostType1Select.addEventListener('change', handleBoostChange);
    if(boostType2Select) boostType2Select.addEventListener('change', handleBoostChange);

    if(boostPokemonSearchInput){
        boostPokemonSearchInput.addEventListener('input', (event) => {
            clearBoostPokemonSearchHideTimer();
            syncBoostSelectedPokemonEntry(event.currentTarget?.value || '');
            renderBoostPokemonSearchResults(event.currentTarget?.value || '');
            handleBoostChange(event);
        });
        boostPokemonSearchInput.addEventListener('focus', (event) => {
            clearBoostPokemonSearchHideTimer();
            renderBoostPokemonSearchResults(event.currentTarget?.value || '');
        });
        boostPokemonSearchInput.addEventListener('blur', () => {
            clearBoostPokemonSearchHideTimer();
            boostPokemonSearchHideTimer = window.setTimeout(() => {
                hideBoostPokemonSearchResults();
            }, 140);
        });
        boostPokemonSearchInput.addEventListener('keydown', (event) => {
            if(event.key === 'Escape'){
                hideBoostPokemonSearchResults();
                return;
            }
            if(event.key !== 'Enter') return;

            const firstEntry = getBoostPokemonSearchResultEntries(boostPokemonSearchInput.value, 1)[0] || null;
            if(!firstEntry) return;

            event.preventDefault();
            applyBoostPokemonSearchSelection(firstEntry);
        });
    }

    window.addEventListener('resize', syncBoostPokemonSearchResultsDirection);

    document.addEventListener('click', (event) => {
        const searchPanel = boostPokemonSearchInput?.closest('.boost-search-panel');
        if(!searchPanel || searchPanel.contains(event.target)) return;
        hideBoostPokemonSearchResults();
    });

    if(boostResetBtn){
        boostResetBtn.addEventListener('click', () => {
            applyBoostFormState(getBoostDefaultFormState());
            hideBoostPokemonSearchResults();
            setBoostFormMessage('', 'info');
            renderBoostCalculator();
        });
    }

    boostPageInitialized = true;

    return Promise.all([
        ensureTypesDataLoaded(),
        ensurePokemonCatalogLoaded()
    ]).then(() => {
        hydrateBoostPokemonOptions();
        try{ hydrateBoostTypeSelects(); }catch(e){}
        applyBoostFormState(getBoostDefaultFormState());
        try{ renderBoostTypePicker(); updateBoostTypePickerUI(); }catch(e){}
        renderBoostCalculator();
        return true;
    }).catch(error => {
        console.error('Boost calculator load failed', error);
        setBoostFormMessage('Nao foi possivel carregar o catalogo da calculadora de boost.', 'warning');
        return false;
    });
}
function updateUrl(options = {}){
    const { historyMode = 'replace' } = options || {};
    const isHomeView = document.body.classList.contains('home-view');
    const params=new URLSearchParams(location.search);
    const pokemonVariant = getCurrentPokemonCatalogVariant();
    const activeBossRouteState = typeof window.getActiveBossRouteState === 'function'
        ? window.getActiveBossRouteState()
        : null;
    const requestedQuickAction = getRequestedQuickActionFromUrl();
    const activeTab = isHomeView ? '' :
                      (contentBoost && !contentBoost.hidden) ? 'boost' :
                      (contentPokemons && !contentPokemons.hidden) ? 'pokemons' :
                      (contentTimes && !contentTimes.hidden) ? 'times' :
                      (contentTeamBuilder && !contentTeamBuilder.hidden) ? 'team-builder' :
                      (contentHuntBuilder && !contentHuntBuilder.hidden) ? 'hunt-builder' :
                      (contentRotomPhone && !contentRotomPhone.hidden) ? 'rotom-phone' :
                      (contentInteractiveMap && !contentInteractiveMap.hidden) ? 'mapa-interativo' :
                      (contentPoliceOperation && !contentPoliceOperation.hidden) ? 'police-operation' :
                      (contentSlowpokeWell && !contentSlowpokeWell.hidden) ? 'slowpoke-well' :
                      (contentLigaPokemon && !contentLigaPokemon.hidden) ? 'liga-pokemon' :
                      (contentHeldFusion && !contentHeldFusion.hidden) ? 'fusao-de-held' :
                      (contentProfessions && !contentProfessions.hidden) ? 'profissoes' :
                      (contentManiacs && !contentManiacs.hidden) ? 'maniacs' :
                      (contentBossesInfo && !contentBossesInfo.hidden) ? 'bosses-info' :
                      tabEffectBtn.classList.contains('active') ? 'effectiveness' :
                      tabFossilsBtn.classList.contains('active') ? 'fossils' :
                      tabCalcBtn.classList.contains('active') ? 'calculator' :
                      tabSpeedstersBtn.classList.contains('active') ? 'bosses' :
                      (tabCommunityBtn && tabCommunityBtn.classList.contains('active')) ? 'youtube' :
                      (tabStreamersBtn && tabStreamersBtn.classList.contains('active')) ? 'streamers' :
                      (tabCatchBtn && tabCatchBtn.classList.contains('active')) ? 'catch' : '';
    if(isHomeView){
        params.delete('types');
        params.delete('tab');
        params.delete('topic');
        params.delete('bossmode');
        params.delete('plan');
        params.delete('variant');
    } else if(activeTab !== 'effectiveness'){
        params.delete('types');
    } else if(currentSelection.length) params.set('types',currentSelection.join(','));
    else if(!(isEffectivenessRouteActive() && !typesDataLoaded && params.has('types'))) params.delete('types');
    params.delete('tab');
    params.delete('bossmode');
    params.delete('quick');
    if(!(activeTab === 'bosses' && getCurrentBossMode() === 'planner')){
        params.delete('plan');
    }
    if(activeTab === 'youtube'){
        if(activeCommunityTopicKey && activeCommunityTopicKey !== 'all') params.set('topic', activeCommunityTopicKey);
        else params.delete('topic');
    } else {
        params.delete('topic');
    }
    const pendingCatchUrlState = activeTab === 'catch'
        && !catchPokemonEntries.length
        && !catchSelectedPokemonEntry
        && Boolean(getCatchRouteMatch()?.routeToken || params.has('pokemon') || params.has('alvo'));
    if(activeTab === 'catch'){
        if(!pendingCatchUrlState){
            params.delete('pokemon');
            params.delete('alvo');
            params.delete('variant');
            params.delete('pokebola');
            params.delete('calcular');
            const catchVariant = getSelectedCatchVariant();
            const catchBall = String(ballSelect?.value || '').trim().toLowerCase();
            if(catchSelectedPokemonEntry && catchVariant){
                params.set('variante', catchVariant);
            } else {
                params.delete('variante');
            }
            if(catchSelectedPokemonEntry && catchBall && catchBall !== 'ultra'){
                params.set('ball', catchBall);
            } else {
                params.delete('ball');
            }
            if(catchSelectedPokemonEntry && catchVariant && isCatchEstimateRendered()){
                params.set('estimativa', '1');
            } else {
                params.delete('estimativa');
            }
        }
    } else {
        params.delete('pokemon');
        params.delete('alvo');
        params.delete('variant');
        params.delete('variante');
        params.delete('ball');
        params.delete('pokebola');
        params.delete('estimativa');
        params.delete('calcular');
    }
    if(activeTab === 'pokemons'){
        syncPokemonCatalogFilterParams(params, pokemonCatalogFilters);
    } else {
        syncPokemonCatalogFilterParams(params, DEFAULT_POKEMON_CATALOG_FILTERS);
    }
    if(activeTab === 'times'){
        syncTeamFilterParams(params, teamFilters);
    } else {
        syncTeamFilterParams(params, DEFAULT_TEAM_FILTERS);
    }
    if(activeTab === 'team-builder'){
        const teamShareValue = getTeamBuilderShareValue();
        if(teamShareValue) params.set(TEAM_BUILDER_SHARE_PARAM, teamShareValue);
        else params.delete(TEAM_BUILDER_SHARE_PARAM);
    } else {
        params.delete(TEAM_BUILDER_SHARE_PARAM);
    }
    if(!pendingCatchUrlState){
        params.delete('variant');
    }
    const query = params.toString();
    // Se o modal de detalhes de Pokemon estiver aberto, preferir o caminho de deep-link do Pokemon
    let routePath = isHomeView ? getRoutePathForTab('home') : getRoutePathForTab(activeTab, getCurrentBossMode());
    if(!isHomeView && activeTab === 'effectiveness' && requestedQuickAction){
        routePath = getQuickActionRoutePath(requestedQuickAction) || routePath;
    }
    try{
        if(!isHomeView && activeTab === 'pokemons'){
            if(pokemonDetailsModal && pokemonDetailsModal.getAttribute('aria-hidden') !== 'true' && activePokemonCatalogEntry){
                routePath = getPokemonDetailRoutePath(activePokemonCatalogEntry, pokemonVariant);
            } else {
                routePath = getPokemonCatalogRoutePath(pokemonCatalogCurrentPage, pokemonVariant);
            }
        } else if(!isHomeView && activeTab === 'mapa-interativo'){
            const activeMapRoute = String(location.pathname || '').match(/\/mapa-interativo\/[a-z0-9][a-z0-9-]*\/?$/i);
            routePath = activeMapRoute ? activeMapRoute[0].replace(/\/+$/, '') : getRoutePathForTab(activeTab);
        } else if(!isHomeView && activeTab === 'catch'){
            const activeCatchMatch = getCatchRouteMatch();
            routePath = catchSelectedPokemonEntry
                ? getCatchRoutePath(catchSelectedPokemonEntry)
                : (activeCatchMatch?.routeToken && !catchPokemonEntries.length
                    ? `/catch/${encodeURIComponent(activeCatchMatch.routeToken)}`
                    : getRoutePathForTab(activeTab));
        } else if(!isHomeView && activeTab === 'times'){
            if(timesDetailsModal && timesDetailsModal.getAttribute('aria-hidden') !== 'true' && activeTeamEntry){
                routePath = getTeamDetailRoutePath(activeTeamEntry) || getRoutePathForTab(activeTab);
            } else {
                routePath = getRoutePathForTab(activeTab);
            }
        } else if(!isHomeView && activeTab === 'maniacs'){
            routePath = getRoutePathForTab(activeTab);
        } else if(!isHomeView && activeTab === 'bosses'){
            const activeBossMode = normalizeBossModeParam(activeBossRouteState?.bossMode || getCurrentBossMode()) || 'hoopa';
            routePath = getRoutePathForTab(activeTab, activeBossMode);
            if(activeBossRouteState?.mapOpen && activeBossRouteState?.bossSlug){
                routePath = `${routePath}/${activeBossRouteState.bossSlug}/mapa`;
            } else if(activeBossRouteState?.videoOpen && activeBossRouteState?.bossSlug){
                routePath = `${routePath}/${activeBossRouteState.bossSlug}/video`;
            } else if(activeBossRouteState?.modalOpen && activeBossRouteState?.bossSlug){
                routePath = `${routePath}/${activeBossRouteState.bossSlug}`;
            } else if(activeBossRouteState?.searchOpen && activeBossRouteState?.searchPath){
                routePath = activeBossRouteState.searchPath;
            } else if(activeBossRouteState?.searchOpen && activeBossRouteState?.searchSlug){
                routePath = `${routePath}/${activeBossRouteState.searchSlug}`;
            }
        }
    }catch(e){}
    const routeHash = activeTab === 'profissoes' && activeProfessionKey
        ? `#${encodeURIComponent(activeProfessionKey)}`
        : '';
    const newUrl = routePath + (query ? `?${query}` : '') + routeHash;
    if(historyMode === 'push'){
        history.pushState(null, '', newUrl);
    } else {
        history.replaceState(null, '', newUrl);
    }
    syncSidebarNavigationState();

    if(currentSelection.length) localStorage.setItem('selectedTypes', currentSelection.join(','));
    else localStorage.removeItem('selectedTypes');
    if(isHomeView) localStorage.setItem('selectedTab', 'home');
    else if(activeTab) localStorage.setItem('selectedTab', activeTab);
}
function initFromUrl(){
    const params=new URLSearchParams(location.search);
    const tparam=params.get('types');
    currentSelection = [];
    if(tparam){
        tparam.split(',').forEach(type=>{
            const normalizedType = normalizePokemonTypeKey(type);
            if(menuTypes.includes(normalizedType) && !currentSelection.includes(normalizedType)){
                currentSelection.push(normalizedType);
            }
        });
    }

    if(!currentSelection.length) {
        const stored = localStorage.getItem('selectedTypes');
        if(stored) {
            stored.split(',').forEach(type=>{
                const normalizedType = normalizePokemonTypeKey(type);
                if(menuTypes.includes(normalizedType) && !currentSelection.includes(normalizedType)){
                    currentSelection.push(normalizedType);
                }
            });
        }
    }
    if(currentSelection.length)renderSelection();
}

