function openQuickActionFromUrl(){
    const action = getRequestedQuickActionFromUrl();
    if(!action) return;
    const triggerMap = {
        commands: commandsBtn,
        'elemental-balls': elementalBallsBtn,
        'full-map': { click: openFullMapVideo },
        fishing: fishingBtn
    };
    const trigger = triggerMap[action];
    if(!trigger) return;
    window.setTimeout(() => {
        try{
            trigger.click();
        }catch(error){
            console.error('Nao foi possivel abrir o atalho rapido', action, error);
        }
    }, 180);
}

openQuickActionFromUrl();

function buildMatrix(){
    const types = menuTypes;
    const rows = types.map(att=>{
        const row = types.map(def=>{
            const raw = computeTypeRawMultiplier(att, [def]);
            return normalizeTypeMatchupMultiplier(raw, att, [def]);
        });
        return row;
    });
    const getMatrixTone = (value) => {
        if(value >= TYPE_SUPER_EFFECTIVE_MULTIPLIER) return 'is-super';
        if(value > 1) return 'is-effective';
        if(value === 0) return 'is-immune';
        if(value < 1) return 'is-resist';
        return 'is-neutral';
    };
    let html = '<table class="types-matrix"><tr><th></th>' + types.map(t=>`<th>${getTypeDisplayName(t)}</th>`).join('') + '</tr>';
    rows.forEach((row,i)=>{
        html += '<tr><th>' + types[i] + '</th>' + row.map(v=>`<td>${v===1?'–':v}</td>`).join('') + '</tr>';
    });
    html = '<table class="types-matrix"><tr><th></th>' + types.map(t=>`<th>${getTypeDisplayName(t)}</th>`).join('') + '</tr>';
    rows.forEach((row,i)=>{
        html += '<tr><th>' + getTypeDisplayName(types[i]) + '</th>' + row.map(v=>`<td class="${getMatrixTone(v)}">${v===1 ? '&ndash;' : formatTypeMultiplierValue(v)}</td>`).join('') + '</tr>';
    });
    html += '</table>';
    matrixBody.innerHTML = html;
}

function clearTypeDataStore(){
    [effectiveness, weaknesses, immunities, resistances].forEach(store => {
        Object.keys(store).forEach(key => delete store[key]);
    });
}

function createTypesLoadErrorMessage(){
    const wrapper = document.createElement('div');
    wrapper.className = 'load-error-message';
    wrapper.setAttribute('role', 'alert');

    const title = document.createElement('strong');
    title.className = 'load-error-title';
    title.textContent = 'Não foi possível carregar os tipos.';

    const description = document.createElement('p');
    description.className = 'load-error-description';
    description.textContent = 'Atualize a página ou tente novamente em instantes.';

    const retryButton = document.createElement('button');
    retryButton.type = 'button';
    retryButton.className = 'load-error-retry';
    retryButton.textContent = 'Tentar novamente';
    retryButton.addEventListener('click', ()=>{ ensureTypesDataLoaded({ force: true }).catch(()=>{}); });

    wrapper.appendChild(title);
    wrapper.appendChild(description);
    wrapper.appendChild(retryButton);
    return wrapper;
}

function showTypesLoadError(error){
    typesDataLoaded = false;
    clearTypeDataStore();
    menuTypes = [];
    currentSelection = [];

    if(connectionsSvg) connectionsSvg.replaceChildren();
    if(chart){
        chart.replaceChildren(createTypesLoadErrorMessage());
    }

    const infoPanel = document.getElementById('info');
    if(infoPanel){
        infoPanel.classList.add('load-error-state');
        infoPanel.textContent = 'Os dados de efetividade estão indisponíveis no momento.';
    }

    const instructions = document.getElementById('instructions');
    if(instructions){
        instructions.textContent = 'Não foi possível carregar os dados de efetividade. Atualize a página ou tente novamente.';
    }

    if(matrixBtn){
        matrixBtn.disabled = true;
        matrixBtn.setAttribute('aria-disabled', 'true');
        matrixBtn.title = 'Tabela indisponível';
    }

    console.error('types.json load failed', error);
}

function resetTypesLoadErrorState(){
    const infoPanel = document.getElementById('info');
    if(infoPanel){
        infoPanel.classList.remove('load-error-state');
        if(!currentSelection.length){
            renderTypeInfoEmptyState();
        }
    }

    if(matrixBtn){
        matrixBtn.disabled = false;
        matrixBtn.removeAttribute('aria-disabled');
        matrixBtn.title = 'Tabela';
    }
}

function populateTypesDatalist(){
    if(!searchInput) return;

    const existing = document.getElementById('types-list');
    if(existing) existing.remove();

    const datalist = document.createElement('datalist');
    datalist.id = 'types-list';
    menuTypes.forEach(type => {
        const option = document.createElement('option');
        option.value = type;
        datalist.appendChild(option);
    });
    document.body.appendChild(datalist);
    searchInput.setAttribute('list', 'types-list');
}

function renderTypesInterfaceFromLoadedData(){
    if(!menuTypes.length) return;
    if(
        contentEffect?.dataset.panelFragment
        && contentEffect.dataset.panelLoaded !== 'true'
    ) return;
    refreshEffectivenessDomReferences();
    if(!chart || !connectionsSvg) return;
    createButtons(searchInput?.value?.trim() || '');
    updateTextContent();
    initFromUrl();
    renderSelection();
    populateTypesDatalist();
}

function applyTypesData(data){
    if(!data || typeof data !== 'object' || typeof data.effectiveness !== 'object' || typeof data.immunities !== 'object'){
        throw new Error('Formato inválido em types.json');
    }

    clearTypeDataStore();
    Object.assign(effectiveness, data.effectiveness);
    Object.assign(immunities, data.immunities);
    Object.assign(resistances, data.resistances || {});

    for(const type in effectiveness){
        weaknesses[type] = [];
    }

    for(const type in effectiveness){
        (effectiveness[type] || []).forEach(target => {
            if(!weaknesses[target]) weaknesses[target] = [];
            weaknesses[target].push(type);
        });
    }

    menuTypes = Object.keys(effectiveness).sort();
    renderTypesInterfaceFromLoadedData();

    if(useGsap){
        const visibleCards = [...document.querySelectorAll('[role="tabpanel"]:not([hidden]) .card')]
            .filter(card=>!card.classList.contains('catch-card'));
        if(visibleCards.length){
            gsap.from(visibleCards, {opacity:0, y:20, stagger:0.1, duration:0.6, clearProps:'opacity,transform'});
        }
    }
}

function loadTypesData(){
    return fetch(TYPES_DATA_URL)
        .then(response => {
            if(!response.ok){
                throw new Error(`Falha ao carregar ${TYPES_DATA_URL} (${response.status})`);
            }
            return response.json();
        })
        .then(data => {
            resetTypesLoadErrorState();
            applyTypesData(data);
            typesDataLoaded = true;
            return true;
        })
        .catch(error => {
            showTypesLoadError(error);
            throw error;
        });
}

function ensureTypesDataLoaded(options = {}){
    const { force = false } = options;
    if(typesDataLoaded && !force) return Promise.resolve(true);
    if(typesDataLoadPromise && !force) return typesDataLoadPromise;

    if(force){
        typesDataLoaded = false;
        typesDataLoadPromise = null;
    }

    showTypesLoadingState();
    typesDataLoadPromise = loadTypesData()
        .finally(() => {
            typesDataLoadPromise = null;
        });

    return typesDataLoadPromise;
}

function ensureBossesPageReady(){
    if(typeof window.setBossMode === 'function' && typeof renderGrid === 'function'){
        return Promise.resolve(true);
    }
    if(bossesPageLoadPromise) return bossesPageLoadPromise;

    renderBossesDeferredState('Carregando catálogo de bosses...');
    ensurePokemonCatalogLoaded()
        .catch(error => {
            console.warn('Pokemon catalog unavailable before bosses load', error);
        });
    Promise.allSettled([
        loadDeferredScript(DEFERRED_LZ_STRING_SCRIPT_SRC, () => typeof window.LZString === 'object'),
        loadDeferredScript(DEFERRED_PAKO_SCRIPT_SRC, () => typeof window.pako === 'object')
    ]).then((results) => {
        if(results.some(result => result.status === 'rejected')){
            console.warn('Compactadores opcionais indisponiveis; Bosses continuara sem compressao de links.');
        }
    });
    bossesPageLoadPromise = loadDeferredScript(
            DEFERRED_BOSSES_SCRIPT_SRC,
            () => typeof window.setBossMode === 'function' && typeof renderGrid === 'function'
        )
        .then(() => {
            if(typeof window.setBossMode !== 'function' || typeof renderGrid !== 'function'){
                throw new Error('bosses.js carregou sem inicializar a página de bosses corretamente.');
            }
            return true;
        }).catch(error => {
            renderBossesDeferredState('Não foi possível carregar os bosses. Tente atualizar a página.', { error: true });
            throw error;
        }).finally(() => {
            bossesPageLoadPromise = null;
        });

    return bossesPageLoadPromise;
}

function showPokemonCatalogLoadingState(variant = getCurrentPokemonCatalogVariant()){
    const variantLabel = getPokemonCatalogSubjectLabel(variant);
    if(pokemonCatalogStatus){
        pokemonCatalogStatus.textContent = normalizePokemonCatalogVariant(variant) === POKEMON_CATALOG_VARIANT_MEGA
            ? 'Carregando catalogo Mega...'
            : 'Carregando catalogo...';
    }
    updatePokemonCatalogPaginationControls(null);
    if(pokemonCardGrid && !pokemonCatalog.length){
        pokemonCardGrid.replaceChildren(createInlineStatusMessage('pokemon-load-pending-message', `Carregando ${variantLabel}...`));
    }
}

function showPokemonCatalogErrorState(message, variant = getCurrentPokemonCatalogVariant()){
    if(pokemonCatalogStatus){
        pokemonCatalogStatus.textContent = 'Nao foi possivel carregar o catalogo agora.';
    }
    updatePokemonCatalogPaginationControls(null);
    if(pokemonCardGrid){
        pokemonCardGrid.replaceChildren(
            createInlineStatusMessage(
                'pokemon-load-error-message',
                message || `Falha ao carregar ${getPokemonCatalogSubjectLabel(variant)}.`
            )
        );
    }
}

function getPokemonCatalogRegistryKey(name){
    return String(name || '')
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '');
}

function getPokemonCatalogGenerationMap(data){
    const rawMap = data && typeof data === 'object' && !Array.isArray(data) && data.generations && typeof data.generations === 'object'
        ? data.generations
        : data;

    if(!rawMap || typeof rawMap !== 'object' || Array.isArray(rawMap)) return {};

    return Object.entries(rawMap).reduce((acc, [key, value]) => {
        const normalizedKey = getPokemonCatalogRegistryKey(key);
        const generation = Number.parseInt(value, 10);
        if(normalizedKey && Number.isFinite(generation) && generation > 0){
            acc[normalizedKey] = generation;
        }
        return acc;
    }, {});
}

function getPokemonCatalogPokedexMap(data){
    const rawMap = data && typeof data === 'object' && !Array.isArray(data) && data.pokedex && typeof data.pokedex === 'object'
        ? data.pokedex
        : data;

    if(!rawMap || typeof rawMap !== 'object' || Array.isArray(rawMap)) return {};

    return Object.entries(rawMap).reduce((acc, [key, value]) => {
        const normalizedKey = getPokemonCatalogRegistryKey(key);
        const dex = Number.parseInt(value, 10);
        if(normalizedKey && Number.isFinite(dex) && dex > 0){
            acc[normalizedKey] = dex;
        }
        return acc;
    }, {});
}

function resolvePokemonCatalogOfficialDex(entry){
    const lookupKey = getPokemonCatalogGenerationLookupKey(entry);
    const mappedDex = Number.parseInt(pokemonCatalogPokedexMap?.[lookupKey], 10);
    if(Number.isFinite(mappedDex) && mappedDex > 0){
        return mappedDex;
    }

    const explicitDex = Number(entry?.dex);
    return Number.isFinite(explicitDex) && explicitDex > 0 ? explicitDex : null;
}

function normalizePokemonImageFileName(fileName){
    const rawFileName = String(fileName || '').trim();
    if(!rawFileName) return '';
    const normalizedKey = rawFileName.toLowerCase();
    return POKEMON_IMAGE_FILE_ALIASES[normalizedKey] || rawFileName;
}

function resolvePokemonImageAssetPath(fileName, generationHint = null){
    const rawFileName = String(fileName || '').trim();
    if(!rawFileName) return '';
    if(rawFileName === POKEMON_IMAGE_PLACEHOLDER || /^[./]/.test(rawFileName) || rawFileName.includes('/')){
        return rawFileName;
    }

    const normalizedFileName = normalizePokemonImageFileName(rawFileName);
    const explicitGeneration = Number.parseInt(generationHint, 10);
    const generation = Number.isFinite(explicitGeneration) && explicitGeneration > 0
        ? explicitGeneration
        : Number.parseInt(
            pokemonCatalogGenerationMap?.[
                getPokemonCatalogRegistryKey(normalizedFileName.replace(/\.[^.]+$/u, ''))
            ],
            10
        );

    return Number.isFinite(generation) && generation > 0
        ? `pokemons/${generation}gen/${normalizedFileName}`
        : `pokemons/${normalizedFileName}`;
}

function getPokemonCatalogGenerationLookupKey(entry){
    const rawKey = getPokemonCatalogRegistryKey(typeof entry === 'string' ? entry : entry?.name);
    if(
        rawKey
        && typeof entry === 'object'
        && entry
        && normalizePokemonCatalogVariant(entry.variant) === POKEMON_CATALOG_VARIANT_MEGA
        && rawKey.startsWith('mega')
    ){
        return rawKey.slice(4) || rawKey;
    }
    return rawKey;
}

function getPokemonCatalogJsonList(data){
    return Array.isArray(data?.pokemon) ? data.pokemon : Array.isArray(data) ? data : [];
}

function fetchPokemonCatalogJson(url){
    const parseResponse = (response) => {
        if(!response.ok){
            throw new Error(`Falha ao carregar ${url} (${response.status})`);
        }
        return response.json();
    };
    return fetch(url, { cache: 'no-store' })
        .then(parseResponse)
        .catch((firstError) => {
            const retryUrl = new URL(url, document.baseURI);
            retryUrl.searchParams.set('_retry', Date.now().toString(36));
            return fetch(retryUrl.href, { cache: 'reload' })
                .then(parseResponse)
                .catch(() => {
                    throw firstError;
                });
        });
}

function loadSharedPokemonGenerationMap(){
    if(pokemonGenerationMapLoadPromise){
        return pokemonGenerationMapLoadPromise;
    }

    pokemonGenerationMapLoadPromise = fetchPokemonCatalogJson(POKEMON_GENERATION_MAP_URL)
        .then(data => getPokemonCatalogGenerationMap(data))
        .catch(error => {
            console.warn('Nao foi possivel carregar pokemons/generations.json.', error);
            return {};
        });

    return pokemonGenerationMapLoadPromise;
}

function loadSharedPokemonPokedexMap(){
    return fetchPokemonCatalogJson(POKEMON_POKEDEX_MAP_URL)
        .then(data => getPokemonCatalogPokedexMap(data))
        .catch(error => {
            console.warn('Nao foi possivel carregar pokemons/pokedex.json.', error);
            return {};
        });
}

function normalizePokemonTypeKey(value){
    const normalized = String(value || '').trim().toLowerCase();
    if(normalized === 'insect') return 'bug';
    if(normalized === 'fighter') return 'fighting';
    if(normalized === 'metal') return 'steel';
    return normalized;
}

function normalizePokemonSearchText(value){
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .trim()
        .toLowerCase();
}

function getLimitedPokemonSearchEntries(entries, normalizedValue, getSearchKey, limit = 8){
    const source = Array.isArray(entries) ? entries : [];
    const normalized = normalizePokemonSearchText(normalizedValue || '');
    const max = Math.max(1, Number(limit) || 8);
    if(!normalized) return source.slice(0, max);

    const exact = [];
    const prefix = [];
    const partial = [];
    for(const entry of source){
        const key = normalizePokemonSearchText(getSearchKey(entry) || '');
        if(!key) continue;
        if(key === normalized){
            exact.push(entry);
        } else if(key.startsWith(normalized)){
            prefix.push(entry);
        } else if(key.includes(normalized) && partial.length < max){
            partial.push(entry);
        }
    }

    return exact.concat(prefix, partial).slice(0, max);
}

function normalizePokemonGenerationFilterValue(value){
    const normalized = Number.parseInt(String(value ?? '').trim(), 10);
    return Number.isFinite(normalized) && normalized > 0 ? String(normalized) : '';
}

function formatPokemonGenerationLabel(value){
    const normalized = normalizePokemonGenerationFilterValue(value);
    return normalized ? `Geracao ${normalized}` : 'Geracao';
}

function normalizePokemonSpecialTagKey(value){
    const normalized = normalizePokemonSearchText(value).replace(/[_\s]+/g, '-');
    if(normalized === 'mega') return 'mega';
    if(normalized === 'lendario' || normalized === 'legendario' || normalized === 'legendary') return 'legendary';
    if(normalized === 'fossil' || normalized === 'fossil-pokemon') return 'fossil';
    if(normalized === 'boss') return 'boss';
    if(normalized === 'ranger') return 'ranger';
    if(normalized === 'maniac') return 'maniac';
    if(normalized === 'impossivel-capturar' || normalized === 'impossivel-de-capturar' || normalized === 'impossivelcapturar') return 'impossivel-capturar';
    if(normalized === 'mewtwo-solo' || normalized === 'mew2-solo') return 'mewtwo-solo';
    if(normalized === 'poke-gift' || normalized === 'pokegift') return 'poke-gift';
    if(normalized === 'pre-ace' || normalized === 'preace') return 'pre-ace';
    if(normalized === 'ace') return 'ace';
    if(normalized === 'saffari' || normalized === 'safari') return 'saffari';
    if(normalized === 'shiny' || normalized === 'brilhante') return 'shiny';
    if(normalized === 'pack' || normalized === 'pacote' || normalized === 'especial' || normalized === 'special') return 'pack';
    return '';
}

function comparePokemonSpecialTagValues(left, right){
    const normalizedLeft = normalizePokemonSpecialTagKey(left);
    const normalizedRight = normalizePokemonSpecialTagKey(right);
    const leftIndex = Object.prototype.hasOwnProperty.call(POKEMON_SPECIAL_TAG_SORT_INDEX, normalizedLeft)
        ? POKEMON_SPECIAL_TAG_SORT_INDEX[normalizedLeft]
        : Number.MAX_SAFE_INTEGER;
    const rightIndex = Object.prototype.hasOwnProperty.call(POKEMON_SPECIAL_TAG_SORT_INDEX, normalizedRight)
        ? POKEMON_SPECIAL_TAG_SORT_INDEX[normalizedRight]
        : Number.MAX_SAFE_INTEGER;
    if(leftIndex !== rightIndex) return leftIndex - rightIndex;
    return normalizedLeft.localeCompare(normalizedRight);
}

function normalizePokemonSpecialTags(values){
    const rawValues = Array.isArray(values)
        ? values
        : (values ? [values] : []);
    return Array.from(new Set(
        rawValues
            .map(normalizePokemonSpecialTagKey)
            .filter(Boolean)
    )).sort(comparePokemonSpecialTagValues);
}

function formatPokemonSpecialTagLabel(value){
    const normalized = normalizePokemonSpecialTagKey(value);
    return POKEMON_SPECIAL_TAG_META[normalized]?.label || normalized || 'Tag';
}

function normalizePokemonSubFunctionKey(value){
    const normalized = normalizePokemonSearchText(value)
        .replace(/[_\s]+/g, '-')
        .replace(/[^a-z0-9-]/g, '')
        .replace(/-+/g, '-')
        .replace(/^-+|-+$/g, '');
    if(!normalized || normalized === 'sem-sub-funcao' || normalized === 'sem-subfuncao') return '';
    return normalized;
}

function formatPokemonSubFunctionLabel(value){
    const normalized = normalizePokemonSubFunctionKey(value);
    if(!normalized) return 'Sub-funcao';
    if(POKEMON_SUB_FUNCTION_META[normalized]?.label) return POKEMON_SUB_FUNCTION_META[normalized].label;
    return normalized
        .split('-')
        .filter(Boolean)
        .map(part => part.charAt(0).toUpperCase() + part.slice(1))
        .join(' ');
}

function normalizePokemonSubFunctions(values){
    const rawValues = Array.isArray(values)
        ? values
        : (values ? String(values).split(',') : []);
    const seenKeys = new Set();
    return rawValues
        .map(value => {
            const key = normalizePokemonSubFunctionKey(value);
            if(!key || seenKeys.has(key)) return null;
            seenKeys.add(key);
            return {
                key,
                label: formatPokemonSubFunctionLabel(key)
            };
        })
        .filter(Boolean);
}

function resolvePokemonCatalogGeneration(entry){
    const explicitGeneration = Number.parseInt(entry?.generation, 10);
    if(Number.isFinite(explicitGeneration) && explicitGeneration > 0){
        return explicitGeneration;
    }

    const lookupKey = getPokemonCatalogGenerationLookupKey(entry);
    const mappedGeneration = Number.parseInt(pokemonCatalogGenerationMap?.[lookupKey], 10);
    return Number.isFinite(mappedGeneration) && mappedGeneration > 0 ? mappedGeneration : null;
}

function normalizePokemonRoleKey(value){
    const normalized = String(value || '')
        .trim()
        .toLowerCase()
        .replace(/[_\s]+/g, '-');
    return POKEMON_ROLE_ALIASES[normalized] || normalized;
}

function isPokemonUnknownLevelLabel(value){
    return /\?\?/.test(String(value || ''));
}

function normalizePokemonLevelFilterValue(level, levelLabel = ''){
    const normalizedLevel = String(level || '').trim().toLowerCase();
    if(normalizedLevel === POKEMON_UNKNOWN_LEVEL_FILTER_VALUE || normalizedLevel === '??'){
        return POKEMON_UNKNOWN_LEVEL_FILTER_VALUE;
    }
    const levelKey = getPokemonCaptureLevelKey(level);
    const normalizedLevelKey = String(levelKey || '').trim().toLowerCase();
    if(normalizedLevelKey) return normalizedLevelKey;
    return isPokemonUnknownLevelLabel(levelLabel) ? POKEMON_UNKNOWN_LEVEL_FILTER_VALUE : '';
}

function getPokemonRoleInfo(value){
    const normalized = normalizePokemonRoleKey(value);
    if(POKEMON_ROLE_META[normalized]){
        return POKEMON_ROLE_META[normalized];
    }
    return {
        key: normalized || 'unknown',
        label: normalized || 'sem função'
    };
}

function hasPokemonVisibleRole(roleValue){
    const roleInfo = typeof roleValue === 'object' && roleValue
        ? getPokemonRoleInfo(roleValue.key || roleValue.label || '')
        : getPokemonRoleInfo(roleValue);
    return Boolean(roleInfo.key && roleInfo.key !== 'unknown');
}

function normalizePokemonRole(value){
    return getPokemonRoleInfo(value).label;
}

function formatPokemonRoleLabel(value){
    const normalized = String(value || '').trim();
    if(!normalized) return 'Sem função';
    return normalized
        .split('-')
        .map(part => part ? part.charAt(0).toUpperCase() + part.slice(1) : '')
        .join('-');
}

function getPokemonRoleAssetSource(roleKey){
    const normalized = String(roleKey || '').trim().toLowerCase();
    return normalized ? `roles/${normalized}.png` : '';
}

function formatPokemonTypeLabel(value){
    const normalized = normalizePokemonTypeKey(value);
    return normalized ? normalized.charAt(0).toUpperCase() + normalized.slice(1) : '—';
}

function formatPokemonLevelLabel(level){
    if(level === 'pre') return 'Pré Ace';
    if(level === 'ace') return 'Ace';
    if(level === POKEMON_UNKNOWN_LEVEL_FILTER_VALUE) return 'Nível ??';
    const numericLevel = Number(level);
    return Number.isFinite(numericLevel) ? `Nível ${numericLevel}` : String(level || 'Nível não informado');
}

function getPokemonEntryLevelLabel(entry){
    const customLabel = String(entry?.levelLabel || '').trim();
    return customLabel || formatPokemonLevelLabel(entry?.level);
}

function getPokemonEntryPriceLabel(entry){
    const customLabel = String(entry?.priceLabel || '').trim();
    if(customLabel) return customLabel;
    return Number(entry?.price) > 0 ? formatPokemonPriceLabel(entry.price) : '';
}

function isPokemonFossilAcquisitionLabel(label){
    const normalized = normalizePokemonSearchText(label).replace(/[^a-z0-9]+/g, '');
    return normalized === 'fossil'
        || normalized === 'fosseis'
        || normalized === 'fossils';
}

function getPokemonEntryAcquisitionLink(entry, priceLabel = getPokemonEntryPriceLabel(entry)){
    const specialTags = getPokemonEntrySpecialTags(entry);
    if(specialTags.includes('fossil') || isPokemonFossilAcquisitionLabel(priceLabel)){
        return {
            label: 'Fossil',
            url: '/fossils'
        };
    }

    const acquisitionUrl = String(entry?.acquisitionUrl || '').trim();
    if(acquisitionUrl && priceLabel){
        return {
            label: priceLabel,
            url: acquisitionUrl
        };
    }

    return null;
}

function getPokemonEntrySpecialTags(entry){
    return Array.isArray(entry?.specialTags) ? entry.specialTags : [];
}

function getPokemonCardSpecialTags(entry){
    const tags = getPokemonEntrySpecialTags(entry);
    const visibleTags = tags.filter(tagKey => tagKey !== 'pre-ace');
    if(entry?.searchName === 'zoroark'){
        return visibleTags.filter(tagKey => tagKey !== 'boss');
    }
    if(entry?.routeSlug === 'rosas-serperior'){
        return visibleTags.filter(tagKey => tagKey !== 'shiny');
    }
    return visibleTags;
}

function getPokemonEntrySubFunctions(entry){
    return Array.isArray(entry?.subFunctions) ? entry.subFunctions : [];
}

function getPokemonEntryShinySubFunctions(entry){
    return Array.isArray(entry?.shinySubFunctions) ? entry.shinySubFunctions : [];
}

function getPokemonEntryAllSubFunctions(entry){
    const seenKeys = new Set();
    return [
        ...getPokemonEntrySubFunctions(entry),
        ...getPokemonEntryShinySubFunctions(entry)
    ].filter((subFunction) => {
        const key = normalizePokemonSubFunctionKey(subFunction?.key ?? subFunction);
        if(!key || seenKeys.has(key)) return false;
        seenKeys.add(key);
        return true;
    });
}

function pokemonEntryMatchesNameFilter(entry, normalizedName){
    if(!normalizedName) return true;
    if(entry.searchName.includes(normalizedName)) return true;
    if(Array.isArray(entry.searchAliases) && entry.searchAliases.some(alias => alias.includes(normalizedName))) return true;
    if(getPokemonEntryShinySubFunctions(entry).length){
        return normalizePokemonSearchText(`Shiny ${entry.name}`).includes(normalizedName);
    }
    return false;
}

function getPokemonEntryPassiveLabel(entry, variant = 'normal'){
    const isShiny = variant === 'shiny';
    const passiveName = String(isShiny ? entry?.shinyPassiveName : entry?.passiveName || '').trim();
    const passiveDescription = String(
        isShiny
            ? entry?.shinyPassiveDescription
            : entry?.passiveDescription || entry?.passiveText || ''
    ).trim();
    if(!passiveName && !passiveDescription) return '';
    if(passiveName && passiveDescription && !passiveDescription.toLowerCase().startsWith(`${passiveName.toLowerCase()}:`)){
        return `${passiveName}: ${passiveDescription}`;
    }
    return passiveDescription || passiveName;
}

function getPokemonTeamInfo(teamKey){
    const normalized = String(teamKey || '').trim().toLowerCase();
    return TEAM_ASSETS[normalized] || {
        label: normalized ? normalized.charAt(0).toUpperCase() + normalized.slice(1) : 'Sem time',
        image: ''
    };
}

function getPokemonImageSource(entry){
    const fileName = String(entry?.image || '').trim();
    if(!fileName) return POKEMON_IMAGE_PLACEHOLDER;
    return resolvePokemonImageAssetPath(fileName, entry?.generation) || POKEMON_IMAGE_PLACEHOLDER;
}

function setImageFallback(imageEl, fallbackSrc = POKEMON_IMAGE_PLACEHOLDER){
    if(!(imageEl instanceof HTMLImageElement)) return;
    imageEl.onerror = () => {
        if(imageEl.dataset.fallbackApplied === 'true') return;
        imageEl.dataset.fallbackApplied = 'true';
        imageEl.src = fallbackSrc;
    };
}

function createPokemonEvolutionNode(){
    return {
        parents: new Set(),
        children: new Set()
    };
}

function ensurePokemonEvolutionGraph(){
    if(pokemonEvolutionGraph) return pokemonEvolutionGraph;

    const graph = new Map();
    const ensureNode = (key) => {
        if(!key) return null;
        if(!graph.has(key)){
            graph.set(key, createPokemonEvolutionNode());
        }
        return graph.get(key);
    };

    POKEMON_EVOLUTION_EDGES.forEach(([parentName, childName]) => {
        const parentKey = getPokemonCatalogRegistryKey(parentName);
        const childKey = getPokemonCatalogRegistryKey(childName);
        if(!parentKey || !childKey) return;

        ensureNode(parentKey).children.add(childKey);
        ensureNode(childKey).parents.add(parentKey);
    });

    pokemonEvolutionGraph = graph;
    return pokemonEvolutionGraph;
}

function comparePokemonEvolutionEntries(left, right){
    const leftDex = Number(left?.dex);
    const rightDex = Number(right?.dex);
    if(Number.isFinite(leftDex) && Number.isFinite(rightDex) && leftDex !== rightDex){
        return leftDex - rightDex;
    }
    return String(left?.name || '').localeCompare(String(right?.name || ''));
}

function getPokemonEvolutionCatalogEntriesByKey(key){
    const normalizedKey = getPokemonCatalogRegistryKey(key);
    if(!normalizedKey) return [];

    return getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT)
        .filter((candidate) => (
            candidate
            && !isMegaPokemonCatalogEntry(candidate)
            && canOpenPokemonCatalogEntry(candidate)
            && getPokemonCatalogRegistryKey(candidate.name) === normalizedKey
        ))
        .sort(comparePokemonEvolutionEntries);
}

function getPokemonEvolutionNeighborEntries(keys = []){
    const seen = new Set();
    const entries = [];

    keys.forEach((key) => {
        getPokemonEvolutionCatalogEntriesByKey(key).forEach((entry) => {
            const entryKey = entry?.id || entry?.routeSlug || entry?.name;
            if(!entryKey || seen.has(entryKey)) return;
            seen.add(entryKey);
            entries.push(entry);
        });
    });

    return entries.sort(comparePokemonEvolutionEntries);
}

function getPokemonMegaBaseRegistryKey(entryOrName){
    const name = String(typeof entryOrName === 'string' ? entryOrName : entryOrName?.name || '').trim();
    if(!/^mega\s+/i.test(name)) return '';
    const baseName = name
        .replace(/^mega\s+/i, '')
        .replace(/\s+[xyz]$/i, '')
        .trim();
    return getPokemonCatalogRegistryKey(baseName);
}

function getPokemonMegaEvolutionEntriesByBaseKey(key){
    const normalizedKey = getPokemonCatalogRegistryKey(key);
    if(!normalizedKey) return [];

    const seen = new Set();
    return getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
        .filter((candidate) => (
            candidate
            && isMegaPokemonCatalogEntry(candidate)
            && canOpenPokemonCatalogEntry(candidate)
            && getPokemonMegaBaseRegistryKey(candidate) === normalizedKey
        ))
        .filter((candidate) => {
            const candidateKey = candidate?.id || candidate?.routeSlug || candidate?.name;
            if(!candidateKey || seen.has(candidateKey)) return false;
            seen.add(candidateKey);
            return true;
        })
        .sort(comparePokemonEvolutionEntries);
}

function getPokemonMegaEvolutionEntriesForKeys(keys = []){
    const seen = new Set();
    const entries = [];

    keys.forEach((key) => {
        getPokemonMegaEvolutionEntriesByBaseKey(key).forEach((entry) => {
            const entryKey = entry?.id || entry?.routeSlug || entry?.name;
            if(!entryKey || seen.has(entryKey)) return;
            seen.add(entryKey);
            entries.push(entry);
        });
    });

    return entries.sort(comparePokemonEvolutionEntries);
}

function getPokemonEvolutionAncestorKeys(key){
    const graph = ensurePokemonEvolutionGraph();
    const normalizedKey = getPokemonCatalogRegistryKey(key);
    if(!normalizedKey) return [];

    const seen = new Set([normalizedKey]);
    const collect = (currentKey) => {
        const node = graph.get(currentKey);
        const parentKeys = Array.from(node?.parents || [])
            .filter(parentKey => parentKey && !seen.has(parentKey))
            .sort((left, right) => comparePokemonEvolutionEntries(
                getPokemonEvolutionCatalogEntriesByKey(left)[0] || { name: left },
                getPokemonEvolutionCatalogEntriesByKey(right)[0] || { name: right }
            ));

        return parentKeys.flatMap((parentKey) => {
            seen.add(parentKey);
            return [...collect(parentKey), parentKey];
        });
    };

    return collect(normalizedKey);
}

function getPokemonEvolutionDescendantKeys(key){
    const graph = ensurePokemonEvolutionGraph();
    const normalizedKey = getPokemonCatalogRegistryKey(key);
    if(!normalizedKey) return [];

    const seen = new Set([normalizedKey]);
    const collect = (currentKey) => {
        const node = graph.get(currentKey);
        const childKeys = Array.from(node?.children || [])
            .filter(childKey => childKey && !seen.has(childKey))
            .sort((left, right) => comparePokemonEvolutionEntries(
                getPokemonEvolutionCatalogEntriesByKey(left)[0] || { name: left },
                getPokemonEvolutionCatalogEntriesByKey(right)[0] || { name: right }
            ));

        return childKeys.flatMap((childKey) => {
            seen.add(childKey);
            return [childKey, ...collect(childKey)];
        });
    };

    return collect(normalizedKey);
}

function getPokemonEvolutionRelations(entry){
    if(!entry){
        return { parents: [], children: [], megas: [] };
    }

    if(isMegaPokemonCatalogEntry(entry)){
        const baseKey = getPokemonMegaBaseRegistryKey(entry);
        const parentKeys = baseKey
            ? [...getPokemonEvolutionAncestorKeys(baseKey), baseKey]
            : [];
        return {
            parents: getPokemonEvolutionNeighborEntries(parentKeys),
            children: [],
            megas: []
        };
    }

    const key = getPokemonCatalogRegistryKey(entry.name);
    const parentKeys = getPokemonEvolutionAncestorKeys(key);
    const childKeys = getPokemonEvolutionDescendantKeys(key);
    const megaKeys = [key, ...childKeys];

    return {
        parents: getPokemonEvolutionNeighborEntries(parentKeys),
        children: getPokemonEvolutionNeighborEntries(childKeys),
        megas: getPokemonMegaEvolutionEntriesForKeys(megaKeys)
    };
}

function formatPokemonEvolutionStageLabel(stage, count = 1){
    if(stage === 'previous') return count > 1 ? 'Pre-evolucoes' : 'Pre-evolucao';
    if(stage === 'next') return count > 1 ? 'Evolucoes' : 'Evolucao';
    if(stage === 'mega') return count > 1 ? 'Mega evolucoes' : 'Mega evolucao';
    return 'Atual';
}

function createPokemonMegaEvolutionMark(modifier = 'card'){
    const mark = document.createElement('span');
    mark.className = `pokemon-evolution-mega-mark pokemon-evolution-mega-mark--${modifier}`;
    mark.setAttribute('aria-hidden', 'true');

    const icon = document.createElement('img');
    icon.src = POKEMON_MEGA_SYMBOL_IMAGE;
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    icon.onerror = () => {
        mark.hidden = true;
    };

    mark.appendChild(icon);
    return mark;
}

function createPokemonEvolutionCard(entry, stage, options = {}){
    const { current = false } = options;
    const isMegaEntry = isMegaPokemonCatalogEntry(entry);
    const card = document.createElement(current ? 'article' : 'button');
    card.className = 'pokemon-evolution-card';
    card.dataset.stage = stage;
    card.dataset.variant = normalizePokemonCatalogVariant(entry?.variant);

    if(current){
        card.setAttribute('aria-current', 'step');
        card.tabIndex = -1;
    } else {
        card.type = 'button';
        card.addEventListener('click', () => {
            navigatePokemonDetailsFromEvolution(entry);
        });
    }

    const media = document.createElement('span');
    media.className = 'pokemon-evolution-card__media';

    const image = document.createElement('img');
    image.src = getPokemonImageSource(entry);
    image.alt = `Imagem de ${entry.name}`;
    image.loading = 'lazy';
    image.decoding = 'async';
    setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
    media.appendChild(image);

    const copy = document.createElement('span');
    copy.className = 'pokemon-evolution-card__copy';

    const label = document.createElement('span');
    label.className = 'pokemon-evolution-card__label';
    label.textContent = getPokemonEntryLevelLabel(entry);

    const name = document.createElement('strong');
    name.className = 'pokemon-evolution-card__name';
    name.textContent = entry.name;

    copy.append(label, name);
    card.append(media, copy);
    if(isMegaEntry){
        card.appendChild(createPokemonMegaEvolutionMark('card'));
    }
    return card;
}

function createPokemonEvolutionStage(stage, entries = [], options = {}){
    const { currentEntry = null } = options;
    const stageEl = document.createElement('div');
    stageEl.className = 'pokemon-evolution-nav__stage';
    stageEl.dataset.stage = stage;

    const label = document.createElement('span');
    label.className = 'pokemon-evolution-nav__stage-label';
    if(stage === 'mega'){
        label.append(createPokemonMegaEvolutionMark('stage'), document.createTextNode(formatPokemonEvolutionStageLabel(stage, entries.length)));
    } else {
        label.textContent = formatPokemonEvolutionStageLabel(stage, entries.length);
    }

    const list = document.createElement('div');
    list.className = 'pokemon-evolution-nav__stage-list';
    entries.forEach((entry) => {
        list.appendChild(createPokemonEvolutionCard(entry, stage, {
            current: currentEntry === entry
        }));
    });

    stageEl.append(label, list);
    return stageEl;
}

function replacePokemonDetailsModalRoute(entry){
    const detailRoutePath = getPokemonDetailRoutePath(entry, entry?.variant);
    const routeToken = getPokemonDetailRouteToken(entry);
    if(!detailRoutePath || !routeToken) return;

    try{
        history.replaceState({ tab: 'pokemons', pokemonRouteToken: routeToken }, '', detailRoutePath);
    }catch(error){}
}

function navigatePokemonDetailsFromEvolution(entry){
    if(!canOpenPokemonCatalogEntry(entry)) return;
    if(!pokemonDetailsModal || pokemonDetailsModal.getAttribute('aria-hidden') === 'true'){
        openPokemonDetailsModal(entry, { pushState: true });
        return;
    }

    renderPokemonDetailsModal(entry);
    replacePokemonDetailsModalRoute(entry);

    const currentCard = pokemonDetailsEvolution?.querySelector('[aria-current="step"]');
    if(currentCard instanceof HTMLElement){
        try { currentCard.focus({ preventScroll: true }); } catch(error) {}
    }
}

function renderPokemonEvolutionNavigation(entry){
    if(!(pokemonDetailsEvolutionSection instanceof HTMLElement) || !(pokemonDetailsEvolution instanceof HTMLElement)){
        return;
    }

    const { parents, children, megas } = getPokemonEvolutionRelations(entry);
    if(!parents.length && !children.length && !megas.length){
        pokemonDetailsEvolutionSection.hidden = true;
        pokemonDetailsEvolution.replaceChildren();
        return;
    }

    const track = document.createElement('div');
    track.className = 'pokemon-evolution-nav__track';
    const baseStageEntries = [...parents, entry, ...children];
    const baseStageColumnByKey = new Map(
        baseStageEntries.map((stageEntry, index) => [
            getPokemonCatalogRegistryKey(stageEntry?.name),
            index + 1
        ])
    );
    const alignedMegaNames = new Set(['mega gardevoir', 'mega gallade']);

    parents.forEach((parentEntry) => {
        track.appendChild(createPokemonEvolutionStage('previous', [parentEntry]));
    });
    track.appendChild(createPokemonEvolutionStage('current', [entry], { currentEntry: entry }));
    children.forEach((childEntry) => {
        track.appendChild(createPokemonEvolutionStage('next', [childEntry]));
    });
    megas.forEach((megaEntry) => {
        const megaStage = createPokemonEvolutionStage('mega', [megaEntry]);
        const normalizedMegaName = normalizePokemonSearchText(megaEntry?.name);
        const megaBaseKey = getPokemonMegaBaseRegistryKey(megaEntry);
        const baseColumn = baseStageColumnByKey.get(megaBaseKey);
        if(alignedMegaNames.has(normalizedMegaName) && baseColumn){
            const isCurrentBase = getPokemonCatalogRegistryKey(entry?.name) === megaBaseKey;
            megaStage.classList.add('pokemon-evolution-nav__stage--aligned-mega');
            megaStage.style.setProperty('--pokemon-evolution-base-column', String(baseColumn + (isCurrentBase ? 1 : 0)));
            megaStage.style.setProperty('--pokemon-evolution-base-row', isCurrentBase ? '1' : '2');
        }
        track.appendChild(megaStage);
    });

    pokemonDetailsEvolutionSection.hidden = false;
    pokemonDetailsEvolution.replaceChildren(track);
}

function createPokemonTokenRow(types = [], options = {}){
    const row = document.createElement('span');
    row.className = 'pokemon-token-row';
    types.forEach(type => {
        row.appendChild(createPokemonTypeToken(type, options));
    });
    return row;
}

function createPokemonSubFunctionToken(subFunction){
    const key = normalizePokemonSubFunctionKey(
        typeof subFunction === 'object' && subFunction ? subFunction.key : subFunction
    );
    const label = String(
        typeof subFunction === 'object' && subFunction ? subFunction.label : ''
    ).trim() || formatPokemonSubFunctionLabel(key);
    const token = document.createElement('span');
    token.className = 'pokemon-sub-function-token';
    token.dataset.subFunction = key || 'custom';
    token.textContent = label;
    return token;
}

function createPokemonSubFunctionTokenRow(subFunctions = []){
    const row = document.createElement('span');
    row.className = 'pokemon-token-row pokemon-sub-function-token-row';
    (Array.isArray(subFunctions) ? subFunctions : []).forEach(subFunction => {
        row.appendChild(createPokemonSubFunctionToken(subFunction));
    });
    return row;
}

function comparePokemonLevelFilterValues(left, right){
    const normalizedLeft = String(left || '').trim().toLowerCase();
    const normalizedRight = String(right || '').trim().toLowerCase();
    const leftIndex = Object.prototype.hasOwnProperty.call(POKEMON_LEVEL_FILTER_SORT_INDEX, normalizedLeft)
        ? POKEMON_LEVEL_FILTER_SORT_INDEX[normalizedLeft]
        : Number.MAX_SAFE_INTEGER;
    const rightIndex = Object.prototype.hasOwnProperty.call(POKEMON_LEVEL_FILTER_SORT_INDEX, normalizedRight)
        ? POKEMON_LEVEL_FILTER_SORT_INDEX[normalizedRight]
        : Number.MAX_SAFE_INTEGER;

    if(leftIndex !== rightIndex) return leftIndex - rightIndex;
    return normalizedLeft.localeCompare(normalizedRight);
}

function createPokemonFilterSelectOption(value, label){
    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    return option;
}

function populatePokemonFilterSelect(selectEl, options = [], placeholder = 'Todos', selectedValue = ''){
    if(!(selectEl instanceof HTMLSelectElement)) return;

    const fragment = document.createDocumentFragment();
    fragment.appendChild(createPokemonFilterSelectOption('', placeholder));
    options.forEach((option) => {
        fragment.appendChild(createPokemonFilterSelectOption(option.value, option.label));
    });

    selectEl.replaceChildren(fragment);
    const nextValue = String(selectedValue || '');
    const hasSelectedValue = Array.from(selectEl.options).some(option => option.value === nextValue);
    selectEl.value = hasSelectedValue ? nextValue : '';
}

function normalizePokemonCatalogFiltersInput(filters = DEFAULT_POKEMON_CATALOG_FILTERS){
    return {
        name: String(filters?.name || '').trim(),
        role: normalizePokemonRoleKey(filters?.role || ''),
        subFunction: normalizePokemonSubFunctionKey(filters?.subFunction || ''),
        clan: String(filters?.clan || '').trim().toLowerCase(),
        level: normalizePokemonLevelFilterValue(filters?.level || ''),
        generation: normalizePokemonGenerationFilterValue(filters?.generation || ''),
        specialTag: normalizePokemonSpecialTagKey(filters?.specialTag || ''),
        type1: normalizePokemonTypeKey(filters?.type1 || ''),
        type2: String(filters?.type2 || '').trim() === POKEMON_FILTER_TYPE2_NONE_VALUE
            ? POKEMON_FILTER_TYPE2_NONE_VALUE
            : normalizePokemonTypeKey(filters?.type2 || ''),
        moveset: normalizePokemonTypeKey(filters?.moveset || '')
    };
}

function getPokemonCatalogFiltersFromUrl(search = location.search){
    try{
        const params = new URLSearchParams(search);
        return normalizePokemonCatalogFiltersInput({
            name: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.name) || '',
            role: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.role) || '',
            subFunction: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.subFunction) || '',
            clan: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.clan) || '',
            level: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.level) || '',
            generation: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.generation) || '',
            specialTag: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.specialTag) || '',
            type1: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.type1) || '',
            type2: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.type2) || '',
            moveset: params.get(POKEMON_CATALOG_FILTER_QUERY_KEYS.moveset) || ''
        });
    }catch(error){
        return { ...DEFAULT_POKEMON_CATALOG_FILTERS };
    }
}

function syncPokemonCatalogFilterParams(params, filters = pokemonCatalogFilters){
    if(!(params instanceof URLSearchParams)) return params;

    const normalizedFilters = normalizePokemonCatalogFiltersInput(filters);
    Object.entries(POKEMON_CATALOG_FILTER_QUERY_KEYS).forEach(([filterKey, paramKey]) => {
        const value = String(normalizedFilters?.[filterKey] || '').trim();
        if(value){
            params.set(paramKey, value);
        } else {
            params.delete(paramKey);
        }
    });
    return params;
}

function buildPokemonCatalogFilterUrl(filters = pokemonCatalogFilters, options = {}){
    const {
        variant = getCurrentPokemonCatalogVariant(),
        page = 1,
        absolute = false
    } = options;
    const params = syncPokemonCatalogFilterParams(new URLSearchParams(), filters);
    const routePath = getPokemonCatalogRoutePath(page, variant);
    const relativeUrl = routePath + (params.toString() ? `?${params}` : '');
    return absolute ? new URL(relativeUrl, document.baseURI).href : relativeUrl;
}

function getPokemonCatalogFilterDisplayLabel(filterKey, value){
    const normalizedValue = String(value || '').trim();
    switch(filterKey){
        case 'role':
            return formatPokemonRoleLabel(normalizePokemonRoleKey(normalizedValue));
        case 'subFunction':
            return formatPokemonSubFunctionLabel(normalizedValue);
        case 'clan':
            return getPokemonTeamInfo(normalizedValue).label;
        case 'level':
            return formatPokemonLevelLabel(normalizedValue);
        case 'generation':
            return formatPokemonGenerationLabel(normalizedValue);
        case 'specialTag':
            return formatPokemonSpecialTagLabel(normalizedValue);
        case 'type1':
        case 'moveset':
            return formatPokemonTypeLabel(normalizedValue);
        case 'type2':
            return normalizedValue === POKEMON_FILTER_TYPE2_NONE_VALUE
                ? 'Sem tipo 2'
                : formatPokemonTypeLabel(normalizedValue);
        case 'name':
        default:
            return normalizedValue;
    }
}

function getPokemonCatalogFilterVisualKind(filterKey, value){
    if(filterKey === 'role') return 'role';
    if(filterKey === 'clan') return 'team';
    if(filterKey === 'type1' || filterKey === 'moveset') return 'type';
    if(filterKey === 'type2'){
        return String(value || '').trim() === POKEMON_FILTER_TYPE2_NONE_VALUE ? 'empty' : 'type';
    }
    return 'text';
}

function createPokemonFilterVisual(kind, value, label, options = {}){
    const {
        compact = false,
        muted = false
    } = options;
    const visual = document.createElement('span');
    visual.className = 'pokemon-filter-visual';
    if(compact) visual.classList.add('pokemon-filter-visual--compact');
    if(muted) visual.classList.add('pokemon-filter-visual--muted');
    visual.dataset.kind = String(kind || 'text').trim().toLowerCase() || 'text';

    let iconSrc = '';
    if(kind === 'role'){
        iconSrc = getPokemonRoleAssetSource(value);
    } else if(kind === 'team'){
        iconSrc = getPokemonTeamInfo(value).image;
    } else if(kind === 'type'){
        const normalizedType = normalizePokemonTypeKey(value);
        if(normalizedType){
            iconSrc = `icons-type/${normalizedType}.png`;
        }
    }

    if(iconSrc){
        const icon = document.createElement('img');
        icon.className = 'pokemon-filter-visual__icon';
        icon.src = iconSrc;
        icon.alt = '';
        icon.loading = 'lazy';
        icon.decoding = 'async';
        setImageFallback(icon, POKEMON_IMAGE_PLACEHOLDER);
        visual.appendChild(icon);
    } else if(kind === 'empty'){
        const emptyIcon = document.createElement('span');
        emptyIcon.className = 'pokemon-filter-visual__icon pokemon-filter-visual__icon--empty';
        emptyIcon.setAttribute('aria-hidden', 'true');
        emptyIcon.textContent = 'Ø';
        visual.appendChild(emptyIcon);
    }

    const text = document.createElement('span');
    text.className = 'pokemon-filter-visual__label';
    text.textContent = String(label || '').trim();
    visual.appendChild(text);

    return visual;
}

function closePokemonFilterDropdown(controller = activePokemonFilterDropdownController, options = {}){
    const { restoreFocus = false } = options;
    if(!controller || !(controller.menu instanceof HTMLElement) || !(controller.trigger instanceof HTMLButtonElement)) return;
    controller.menu.hidden = true;
    controller.wrapper.classList.remove('is-open');
    controller.trigger.setAttribute('aria-expanded', 'false');
    if(restoreFocus){
        try{ controller.trigger.focus({ preventScroll: true }); }catch(error){}
    }
    if(activePokemonFilterDropdownController === controller){
        activePokemonFilterDropdownController = null;
    }
}

function openPokemonFilterDropdown(controller){
    if(!controller || !(controller.menu instanceof HTMLElement) || !(controller.trigger instanceof HTMLButtonElement)) return;
    if(activePokemonFilterDropdownController && activePokemonFilterDropdownController !== controller){
        closePokemonFilterDropdown(activePokemonFilterDropdownController);
    }
    controller.menu.hidden = false;
    controller.wrapper.classList.add('is-open');
    controller.trigger.setAttribute('aria-expanded', 'true');
    activePokemonFilterDropdownController = controller;
}

function togglePokemonFilterDropdown(controller){
    if(!controller) return;
    if(activePokemonFilterDropdownController === controller && !controller.menu.hidden){
        closePokemonFilterDropdown(controller, { restoreFocus: true });
        return;
    }
    openPokemonFilterDropdown(controller);
}

function ensurePokemonFilterUiListeners(){
    if(pokemonFilterUiListenersBound) return;

    document.addEventListener('click', (event) => {
        if(!activePokemonFilterDropdownController) return;
        if(activePokemonFilterDropdownController.wrapper.contains(event.target)) return;
        closePokemonFilterDropdown(activePokemonFilterDropdownController);
    });

    document.addEventListener('keydown', (event) => {
        if(event.key === 'Escape' && activePokemonFilterDropdownController){
            event.preventDefault();
            closePokemonFilterDropdown(activePokemonFilterDropdownController, { restoreFocus: true });
        }
    });

    pokemonFilterUiListenersBound = true;
}

function createPokemonDecoratedFilterController(selectEl, config = {}){
    if(!(selectEl instanceof HTMLSelectElement)) return null;
    if(pokemonDecoratedFilterControllers.has(selectEl.id)){
        return pokemonDecoratedFilterControllers.get(selectEl.id);
    }

    const wrapper = document.createElement('div');
    wrapper.className = 'pokemon-filter-select';
    wrapper.dataset.kind = config.kind || 'text';

    const trigger = document.createElement('button');
    trigger.type = 'button';
    trigger.className = 'pokemon-filter-select__trigger';
    trigger.setAttribute('aria-haspopup', 'listbox');
    trigger.setAttribute('aria-expanded', 'false');
    trigger.setAttribute('aria-controls', `${selectEl.id}-menu`);

    const triggerCopy = document.createElement('span');
    triggerCopy.className = 'pokemon-filter-select__trigger-copy';
    trigger.appendChild(triggerCopy);

    const caret = document.createElement('span');
    caret.className = 'pokemon-filter-select__caret';
    caret.setAttribute('aria-hidden', 'true');
    caret.textContent = '⌄';
    trigger.appendChild(caret);

    const menu = document.createElement('div');
    menu.className = 'pokemon-filter-select__menu';
    menu.id = `${selectEl.id}-menu`;
    menu.setAttribute('role', 'listbox');
    menu.hidden = true;

    wrapper.append(trigger, menu);
    selectEl.insertAdjacentElement('afterend', wrapper);
    selectEl.classList.add('pokemon-filter-native-select');
    selectEl.tabIndex = -1;
    selectEl.setAttribute('aria-hidden', 'true');

    const field = selectEl.closest('.pokemon-filter-field');
    if(field){
        field.classList.add('pokemon-filter-field--decorated');
    }

    const controller = { selectEl, wrapper, trigger, triggerCopy, menu, config };
    pokemonDecoratedFilterControllers.set(selectEl.id, controller);

    trigger.addEventListener('click', (event) => {
        event.preventDefault();
        togglePokemonFilterDropdown(controller);
    });

    trigger.addEventListener('keydown', (event) => {
        if(event.key !== 'ArrowDown' && event.key !== 'Enter' && event.key !== ' '){
            return;
        }
        event.preventDefault();
        openPokemonFilterDropdown(controller);
        const selectedOption = menu.querySelector('.pokemon-filter-select__option.is-selected') || menu.querySelector('.pokemon-filter-select__option');
        if(selectedOption instanceof HTMLButtonElement){
            selectedOption.focus({ preventScroll: true });
        }
    });

    selectEl.addEventListener('change', () => {
        syncPokemonDecoratedFilterController(selectEl);
    });

    return controller;
}

function syncPokemonDecoratedFilterController(selectEl){
    if(!(selectEl instanceof HTMLSelectElement)) return;
    const config = POKEMON_DECORATED_FILTER_SELECTS[selectEl.id];
    if(!config) return;

    const controller = createPokemonDecoratedFilterController(selectEl, config);
    if(!controller) return;

    const selectedOption = selectEl.options[selectEl.selectedIndex] || selectEl.options[0] || null;
    const selectedValue = String(selectEl.value || '');
    const selectedLabel = selectedOption ? selectedOption.textContent : config.placeholder || 'Todos';
    const selectedKind = selectedValue ? getPokemonCatalogFilterVisualKind(
        selectEl.id === 'pokemon-filter-moveset'
            ? 'moveset'
            : selectEl.id === 'pokemon-filter-type1'
                ? 'type1'
                : selectEl.id === 'pokemon-filter-type2'
                    ? 'type2'
                    : selectEl.id === 'pokemon-filter-clan'
                        ? 'clan'
                        : 'role',
        selectedValue
    ) : 'text';

    controller.triggerCopy.replaceChildren(
        createPokemonFilterVisual(
            selectedKind,
            selectedValue,
            selectedLabel || config.placeholder || 'Todos',
            { muted: !selectedValue }
        )
    );

    const fragment = document.createDocumentFragment();
    Array.from(selectEl.options).forEach((option) => {
        const optionButton = document.createElement('button');
        optionButton.type = 'button';
        optionButton.className = 'pokemon-filter-select__option';
        optionButton.setAttribute('role', 'option');
        optionButton.dataset.value = option.value;
        optionButton.setAttribute('aria-selected', option.value === selectedValue ? 'true' : 'false');
        if(option.value === selectedValue){
            optionButton.classList.add('is-selected');
        }

        const filterKey = selectEl.id === 'pokemon-filter-moveset'
            ? 'moveset'
            : selectEl.id === 'pokemon-filter-type1'
                ? 'type1'
                : selectEl.id === 'pokemon-filter-type2'
                    ? 'type2'
                    : selectEl.id === 'pokemon-filter-clan'
                        ? 'clan'
                        : 'role';
        const visualKind = option.value ? getPokemonCatalogFilterVisualKind(filterKey, option.value) : 'text';
        optionButton.appendChild(
            createPokemonFilterVisual(
                visualKind,
                option.value,
                option.textContent || config.placeholder || 'Todos',
                { muted: !option.value }
            )
        );

        optionButton.addEventListener('click', () => {
            selectEl.value = option.value;
            selectEl.dispatchEvent(new Event('change', { bubbles: true }));
            closePokemonFilterDropdown(controller, { restoreFocus: true });
        });

        optionButton.addEventListener('keydown', (event) => {
            if(event.key === 'Escape'){
                event.preventDefault();
                closePokemonFilterDropdown(controller, { restoreFocus: true });
            }
        });

        fragment.appendChild(optionButton);
    });

    controller.menu.replaceChildren(fragment);
    controller.trigger.disabled = Boolean(selectEl.disabled);
}

function initializePokemonDecoratedFilterControls(){
    ensurePokemonFilterUiListeners();
    Object.entries(POKEMON_DECORATED_FILTER_SELECTS).forEach(([selectId, config]) => {
        const selectEl = document.getElementById(selectId);
        if(!(selectEl instanceof HTMLSelectElement)) return;
        createPokemonDecoratedFilterController(selectEl, config);
        syncPokemonDecoratedFilterController(selectEl);
    });
}

function getPokemonCatalogActiveFilterEntries(filters = pokemonCatalogFilters){
    const normalizedFilters = normalizePokemonCatalogFiltersInput(filters);
    return Object.entries(normalizedFilters)
        .filter(([, value]) => Boolean(value))
        .map(([key, value]) => ({
            key,
            value,
            title: POKEMON_FILTER_SHARE_LABELS[key] || key,
            label: getPokemonCatalogFilterDisplayLabel(key, value),
            kind: getPokemonCatalogFilterVisualKind(key, value)
        }));
}

function renderPokemonFilterShareLinks(filters = pokemonCatalogFilters){
    if(!(pokemonFilterShareLinks instanceof HTMLElement)) return;

    const activeFilters = getPokemonCatalogActiveFilterEntries(filters);
    if(!activeFilters.length){
        pokemonFilterShareLinks.hidden = true;
        pokemonFilterShareLinks.replaceChildren();
        return;
    }

    const currentVariant = getCurrentPokemonCatalogVariant();
    const list = document.createElement('div');
    list.className = 'pokemon-filter-share-links__list';

    activeFilters.forEach((entry) => {
        const link = document.createElement('a');
        link.className = 'pokemon-filter-share-link pokemon-filter-share-link-card';
        link.href = buildPokemonCatalogFilterUrl(
            { [entry.key]: entry.value },
            { variant: currentVariant, page: 1 }
        );
        link.title = `Abrir filtro ${entry.title}: ${entry.label}`;

        const visual = createPokemonFilterVisual(entry.kind, entry.value, entry.label, { compact: true });
        link.appendChild(visual);

        const meta = document.createElement('span');
        meta.className = 'pokemon-filter-share-link__meta';
        meta.textContent = entry.title;
        link.appendChild(meta);

        list.appendChild(link);
    });

    pokemonFilterShareLinks.hidden = false;
    pokemonFilterShareLinks.replaceChildren(list);
}

function readPokemonCatalogFiltersFromDom(){
    return normalizePokemonCatalogFiltersInput({
        name: String(pokemonFilterNameInput?.value || '').trim(),
        role: pokemonFilterRoleSelect?.value || '',
        subFunction: pokemonFilterSubFunctionSelect?.value || '',
        clan: pokemonFilterClanSelect?.value || '',
        level: pokemonFilterLevelSelect?.value || '',
        generation: pokemonFilterGenerationSelect?.value || '',
        specialTag: pokemonFilterTagSelect?.value || '',
        type1: pokemonFilterType1Select?.value || '',
        type2: pokemonFilterType2Select?.value || '',
        moveset: pokemonFilterMovesetSelect?.value || ''
    });
}

function writePokemonCatalogFiltersToDom(filters = DEFAULT_POKEMON_CATALOG_FILTERS){
    const normalizedFilters = normalizePokemonCatalogFiltersInput(filters);
    if(pokemonFilterNameInput){
        pokemonFilterNameInput.value = normalizedFilters.name;
    }
    const selectEntries = [
        [pokemonFilterRoleSelect, normalizedFilters.role],
        [pokemonFilterSubFunctionSelect, normalizedFilters.subFunction],
        [pokemonFilterClanSelect, normalizedFilters.clan],
        [pokemonFilterLevelSelect, normalizedFilters.level],
        [pokemonFilterGenerationSelect, normalizedFilters.generation],
        [pokemonFilterTagSelect, normalizedFilters.specialTag],
        [pokemonFilterType1Select, normalizedFilters.type1],
        [pokemonFilterType2Select, normalizedFilters.type2],
        [pokemonFilterMovesetSelect, normalizedFilters.moveset]
    ];
    selectEntries.forEach(([selectEl, value]) => {
        if(selectEl instanceof HTMLSelectElement){
            selectEl.value = String(value || '');
        }
    });
    [
        pokemonFilterRoleSelect,
        pokemonFilterClanSelect,
        pokemonFilterType1Select,
        pokemonFilterType2Select,
        pokemonFilterMovesetSelect
    ].forEach((selectEl) => {
        syncPokemonDecoratedFilterController(selectEl);
    });
    renderPokemonFilterShareLinks(normalizedFilters);
}

function resetPokemonCatalogFilters(){
    if(pokemonCatalogRenderFrame){
        cancelAnimationFrame(pokemonCatalogRenderFrame);
        pokemonCatalogRenderFrame = null;
    }
    pokemonCatalogFilters = { ...DEFAULT_POKEMON_CATALOG_FILTERS };
    pendingPokemonCatalogRouteFilters = null;
    resetPokemonCatalogPage();
    writePokemonCatalogFiltersToDom(pokemonCatalogFilters);
}

function hasPokemonCatalogActiveFilters(filters = pokemonCatalogFilters){
    return Object.values(filters || {}).some(value => Boolean(value));
}

function getVisiblePokemonCatalogEntries(entries = pokemonCatalog){
    return (Array.isArray(entries) ? entries : []).filter((entry) => {
        if(!entry) return false;
        if(entry.catalogHidden) return false;
        return isMegaPokemonCatalogEntry(entry) || entry.registered !== false;
    });
}

function canOpenPokemonCatalogEntry(entry){
    if(!entry) return false;
    return isMegaPokemonCatalogEntry(entry) || entry.registered !== false;
}

function getFilteredPokemonCatalogEntries(filters = pokemonCatalogFilters){
    const normalizedName = normalizePokemonSearchText(filters?.name || '');

    return getVisiblePokemonCatalogEntries().filter((entry) => {
        if(!pokemonEntryMatchesNameFilter(entry, normalizedName)) return false;
        if(filters?.role && entry.roleKey !== filters.role) return false;
        if(filters?.subFunction && !getPokemonEntryAllSubFunctions(entry).some(subFunction => subFunction.key === filters.subFunction)) return false;
        if(filters?.clan && entry.team !== filters.clan) return false;
        if(filters?.level && entry.levelKey !== filters.level) return false;
        if(filters?.generation && entry.generationKey !== filters.generation) return false;
        if(filters?.specialTag && !getPokemonEntrySpecialTags(entry).includes(filters.specialTag)) return false;
        if(filters?.type1 && entry.type1 !== filters.type1) return false;
        if(filters?.type2 === POKEMON_FILTER_TYPE2_NONE_VALUE && entry.type2) return false;
        if(filters?.type2 && filters.type2 !== POKEMON_FILTER_TYPE2_NONE_VALUE && entry.type2 !== filters.type2) return false;
        if(filters?.moveset && !entry.moveset.includes(filters.moveset)) return false;
        return true;
    });
}

function resetPokemonCatalogPage(){
    pokemonCatalogCurrentPage = 1;
}

function getPokemonCatalogPaginationState(entries = []){
    const safeEntries = Array.isArray(entries) ? entries : [];
    const totalEntries = safeEntries.length;
    const totalPages = Math.max(1, Math.ceil(totalEntries / POKEMON_CATALOG_PAGE_SIZE));

    if(pokemonCatalogCurrentPage < 1){
        pokemonCatalogCurrentPage = 1;
    } else if(pokemonCatalogCurrentPage > totalPages){
        pokemonCatalogCurrentPage = totalPages;
    }

    const currentPage = pokemonCatalogCurrentPage;
    const startIndex = totalEntries ? (currentPage - 1) * POKEMON_CATALOG_PAGE_SIZE : 0;
    const endIndex = Math.min(startIndex + POKEMON_CATALOG_PAGE_SIZE, totalEntries);

    return {
        entries: safeEntries.slice(startIndex, endIndex),
        totalEntries,
        totalPages,
        currentPage,
        startIndex,
        endIndex,
        shouldPaginate: totalEntries > POKEMON_CATALOG_PAGE_SIZE
    };
}

function updatePokemonCatalogPaginationControls(paginationState){
    const paginationBlocks = [
        pokemonCatalogPagination,
        pokemonCatalogPaginationBottom
    ].filter(Boolean);
    const prevButtons = [
        pokemonCatalogPrevPageBtn,
        pokemonCatalogPrevPageBottomBtn
    ].filter(Boolean);
    const nextButtons = [
        pokemonCatalogNextPageBtn,
        pokemonCatalogNextPageBottomBtn
    ].filter(Boolean);
    const pageIndicators = [
        pokemonCatalogPageIndicator,
        pokemonCatalogPageIndicatorBottom
    ].filter(Boolean);

    if(!paginationBlocks.length) return;

    const hasPagination = Boolean(
        paginationState
        && paginationState.totalEntries
        && paginationState.totalPages > 1
        && paginationState.shouldPaginate
    );

    paginationBlocks.forEach((block) => {
        block.hidden = !hasPagination;
    });

    if(!hasPagination){
        pageIndicators.forEach((indicator) => {
            indicator.textContent = 'Pagina 1 de 1';
        });
        prevButtons.forEach((button) => {
            button.disabled = true;
        });
        nextButtons.forEach((button) => {
            button.disabled = true;
        });
        return;
    }

    pageIndicators.forEach((indicator) => {
        indicator.textContent = `Pagina ${paginationState.currentPage} de ${paginationState.totalPages} • ${paginationState.startIndex + 1}-${paginationState.endIndex} de ${paginationState.totalEntries}`;
    });
    prevButtons.forEach((button) => {
        button.disabled = paginationState.currentPage <= 1;
    });
    nextButtons.forEach((button) => {
        button.disabled = paginationState.currentPage >= paginationState.totalPages;
    });
}

function goToPokemonCatalogPage(page){
    const filteredEntries = getFilteredPokemonCatalogEntries();
    const totalPages = Math.max(1, Math.ceil(filteredEntries.length / POKEMON_CATALOG_PAGE_SIZE));
    const normalizedPage = Math.min(Math.max(Number.parseInt(page, 10) || 1, 1), totalPages);
    if(normalizedPage === pokemonCatalogCurrentPage) return;
    pokemonCatalogCurrentPage = normalizedPage;
    renderPokemonCatalog({ historyMode: 'push' });
}

function updatePokemonCatalogStatus(totalCount, visibleCount, filters = pokemonCatalogFilters){
    if(!pokemonCatalogStatus) return;

    if(!totalCount){
        pokemonCatalogStatus.textContent = 'Nenhum pokemon disponivel ainda.';
        return;
    }

    if(!hasPokemonCatalogActiveFilters(filters)){
        pokemonCatalogStatus.textContent = `${totalCount} pokemons disponiveis.`;
        return;
    }

    if(!visibleCount){
        pokemonCatalogStatus.textContent = 'Nenhum resultado encontrado com os filtros atuais.';
        return;
    }

    pokemonCatalogStatus.textContent = `${visibleCount} de ${totalCount} pokemons exibidos.`;
}

function schedulePokemonCatalogRender(){
    if(!pokemonCatalogLoaded) return;

    if(pokemonCatalogRenderFrame){
        cancelAnimationFrame(pokemonCatalogRenderFrame);
    }

    pokemonCatalogRenderFrame = requestAnimationFrame(() => {
        pokemonCatalogRenderFrame = null;
        renderPokemonCatalog();
    });
}

function populatePokemonFilterControls(){
    const currentFilters = pendingPokemonCatalogRouteFilters
        ? normalizePokemonCatalogFiltersInput(pendingPokemonCatalogRouteFilters)
        : readPokemonCatalogFiltersFromDom();
    const visibleEntries = getVisiblePokemonCatalogEntries();

    if(pokemonFilterNameInput){
        pokemonFilterNameInput.value = currentFilters.name;
    }

    populatePokemonFilterSelect(
        pokemonFilterRoleSelect,
        POKEMON_ROLE_ORDER.map(roleKey => ({ value: roleKey, label: roleKey })),
        'Todas',
        currentFilters.role
    );

    populatePokemonFilterSelect(
        pokemonFilterSubFunctionSelect,
        POKEMON_SUB_FUNCTION_FILTER_OPTIONS.map(subFunctionKey => ({
            value: subFunctionKey,
            label: formatPokemonSubFunctionLabel(subFunctionKey)
        })),
        'Todas',
        currentFilters.subFunction
    );

    populatePokemonFilterSelect(
        pokemonFilterClanSelect,
        Object.entries(TEAM_ASSETS).map(([teamKey, teamInfo]) => ({ value: teamKey, label: teamInfo.label })),
        'Todos',
        currentFilters.clan
    );

    const levelOptions = Array.from(new Set(
        visibleEntries
            .map(entry => entry.levelKey)
            .filter(Boolean)
    ))
        .filter(levelKey => !POKEMON_LEVEL_FILTER_HIDDEN_OPTIONS.has(levelKey))
        .sort(comparePokemonLevelFilterValues)
        .map(levelKey => ({ value: levelKey, label: formatPokemonLevelLabel(levelKey) }));

    populatePokemonFilterSelect(
        pokemonFilterLevelSelect,
        levelOptions,
        'Todos',
        currentFilters.level
    );

    const generationOptions = Array.from(new Set(
        visibleEntries
            .map(entry => entry.generationKey)
            .filter(Boolean)
    ))
        .sort((left, right) => Number(left) - Number(right))
        .map(generationKey => ({ value: generationKey, label: formatPokemonGenerationLabel(generationKey) }));

    populatePokemonFilterSelect(
        pokemonFilterGenerationSelect,
        generationOptions,
        'Todas',
        currentFilters.generation
    );

    const specialTagOptions = Array.from(new Set(
        visibleEntries.flatMap(entry => getPokemonEntrySpecialTags(entry))
    ))
        .filter(tagKey => tagKey !== 'shiny')
        .sort(comparePokemonSpecialTagValues)
        .map(tagKey => ({ value: tagKey, label: formatPokemonSpecialTagLabel(tagKey) }));

    populatePokemonFilterSelect(
        pokemonFilterTagSelect,
        specialTagOptions,
        'Todas',
        currentFilters.specialTag
    );

    const type1Options = Array.from(new Set(
        visibleEntries
            .map(entry => entry.type1)
            .filter(Boolean)
    ))
        .sort((left, right) => left.localeCompare(right))
        .map(type => ({ value: type, label: formatPokemonTypeLabel(type) }));

    populatePokemonFilterSelect(
        pokemonFilterType1Select,
        type1Options,
        'Todos',
        currentFilters.type1
    );

    const type2Options = Array.from(new Set(
        visibleEntries
            .map(entry => entry.type2)
            .filter(Boolean)
    ))
        .sort((left, right) => left.localeCompare(right))
        .map(type => ({ value: type, label: formatPokemonTypeLabel(type) }));

    if(visibleEntries.some(entry => !entry.type2)){
        type2Options.unshift({ value: POKEMON_FILTER_TYPE2_NONE_VALUE, label: 'Sem tipo 2' });
    }

    populatePokemonFilterSelect(
        pokemonFilterType2Select,
        type2Options,
        'Todos',
        currentFilters.type2
    );

    const movesetOptions = Array.from(new Set(
        visibleEntries.flatMap(entry => entry.moveset || [])
    ))
        .sort((left, right) => left.localeCompare(right))
        .map(type => ({ value: type, label: formatPokemonTypeLabel(type) }));

    populatePokemonFilterSelect(
        pokemonFilterMovesetSelect,
        movesetOptions,
        'Todos',
        currentFilters.moveset
    );

    pendingPokemonCatalogRouteFilters = null;
    writePokemonCatalogFiltersToDom(currentFilters);
    pokemonCatalogFilters = readPokemonCatalogFiltersFromDom();
    renderPokemonFilterShareLinks(pokemonCatalogFilters);
}

function syncPokemonCatalogFiltersFromInputs(){
    pokemonCatalogFilters = readPokemonCatalogFiltersFromDom();
    resetPokemonCatalogPage();
    renderPokemonFilterShareLinks(pokemonCatalogFilters);
    schedulePokemonCatalogRender();
}

function clearPokemonCatalogFilters(){
    resetPokemonCatalogFilters();
    if(pokemonCatalogLoaded){
        renderPokemonCatalog();
    }
}

function initializePokemonCatalogPagination(){
    if(pokemonCatalogPaginationInitialized) return;

    [
        pokemonCatalogPrevPageBtn,
        pokemonCatalogPrevPageBottomBtn
    ].filter(Boolean).forEach((button) => {
        button.addEventListener('click', () => {
            goToPokemonCatalogPage(pokemonCatalogCurrentPage - 1);
        });
    });

    [
        pokemonCatalogNextPageBtn,
        pokemonCatalogNextPageBottomBtn
    ].filter(Boolean).forEach((button) => {
        button.addEventListener('click', () => {
            goToPokemonCatalogPage(pokemonCatalogCurrentPage + 1);
        });
    });

    pokemonCatalogPaginationInitialized = true;
}

function initializePokemonCatalogFilters(){
    if(pokemonCatalogFiltersInitialized) return;

    initializePokemonDecoratedFilterControls();

    const filterControls = [
        pokemonFilterNameInput,
        pokemonFilterRoleSelect,
        pokemonFilterSubFunctionSelect,
        pokemonFilterClanSelect,
        pokemonFilterLevelSelect,
        pokemonFilterGenerationSelect,
        pokemonFilterTagSelect,
        pokemonFilterType1Select,
        pokemonFilterType2Select,
        pokemonFilterMovesetSelect
    ].filter(Boolean);

    filterControls.forEach((control) => {
        const eventName = control instanceof HTMLInputElement ? 'input' : 'change';
        control.addEventListener(eventName, syncPokemonCatalogFiltersFromInputs);
    });

    if(pokemonFilterClearBtn){
        pokemonFilterClearBtn.addEventListener('click', clearPokemonCatalogFilters);
    }

    pokemonCatalogFilters = readPokemonCatalogFiltersFromDom();
    renderPokemonFilterShareLinks(pokemonCatalogFilters);
    pokemonCatalogFiltersInitialized = true;
}

function createPokemonTypeToken(typeKey, options = {}){
    const { labelPrefix = '', compact = false } = options;
    const normalizedType = normalizePokemonTypeKey(typeKey);
    const token = document.createElement('span');
    token.className = 'pokemon-type-token' + (compact ? ' pokemon-type-token--compact' : '');
    token.dataset.type = normalizedType;
    setTypeToneVariables(token, normalizedType);

    const icon = document.createElement('img');
    icon.src = `icons-type/${normalizedType}.png`;
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    setImageFallback(icon, POKEMON_IMAGE_PLACEHOLDER);

    token.appendChild(icon);

    if(!compact){
        const text = document.createElement('span');
        text.textContent = labelPrefix ? `${labelPrefix}${formatPokemonTypeLabel(normalizedType)}` : formatPokemonTypeLabel(normalizedType);
        token.appendChild(text);
    } else {
        token.setAttribute('aria-label', labelPrefix ? `${labelPrefix}${formatPokemonTypeLabel(normalizedType)}` : formatPokemonTypeLabel(normalizedType));
    }

    return token;
}

function createPokemonTeamBadge(teamKey, options = {}){
    const { labelOverride = '' } = options;
    const teamInfo = getPokemonTeamInfo(teamKey);
    const badge = document.createElement('span');
    badge.className = 'pokemon-team-badge';
    badge.dataset.team = String(teamKey || '').trim().toLowerCase();

    if(teamInfo.image && !labelOverride){
        const icon = document.createElement('img');
        icon.src = teamInfo.image;
        icon.alt = '';
        icon.loading = 'lazy';
        icon.decoding = 'async';
        badge.appendChild(icon);
    }

    const text = document.createElement('span');
    text.textContent = String(labelOverride || teamInfo.label).trim() || 'Sem time';
    badge.appendChild(text);
    return badge;
}

function createPokemonSpecialTagBadge(tagKey, options = {}){
    const { labelOverride = '' } = options;
    const normalized = normalizePokemonSpecialTagKey(tagKey);
    const badge = document.createElement('span');
    badge.className = 'pokemon-special-tag-badge';
    badge.dataset.tag = normalized || 'custom';
    badge.textContent = String(labelOverride || formatPokemonSpecialTagLabel(normalized)).trim();
    return badge;
}

function createPokemonNaturalShinyBadge(){
    const badge = document.createElement('span');
    badge.className = 'pokemon-natural-shiny-badge';
    badge.textContent = '✨ Shiny';
    badge.title = 'Shiny por natureza';
    badge.setAttribute('aria-label', 'Shiny por natureza');
    return badge;
}

function shouldShowPokemonNaturalShinyBadgeOnCard(entry){
    return Boolean(entry?.naturalShiny && !getPokemonEntrySpecialTags(entry).includes('pack'));
}

function createPokemonFieldCard(label, value){
    const card = document.createElement('article');
    card.className = 'pokemon-detail-card';

    const eyebrow = document.createElement('span');
    eyebrow.className = 'pokemon-detail-card__label';
    eyebrow.textContent = label;

    const content = document.createElement('strong');
    content.className = 'pokemon-detail-card__value';
    if(value instanceof Node){
        content.appendChild(value);
    } else {
        content.textContent = value;
    }

    card.append(eyebrow, content);
    return card;
}

function createPokemonRoleBadge(roleValue, options = {}){
    const { compact = false, modal = false } = options;
    const roleInfo = typeof roleValue === 'object' && roleValue
        ? roleValue
        : getPokemonRoleInfo(roleValue);
    const badge = document.createElement('span');
    badge.className = 'pokemon-role-badge';
    if(compact) badge.classList.add('pokemon-role-badge--compact');
    if(modal) badge.classList.add('pokemon-role-badge--modal');
    badge.dataset.role = roleInfo.key || 'unknown';

    const icon = document.createElement('img');
    icon.className = 'pokemon-role-badge__icon';
    icon.src = getPokemonRoleAssetSource(roleInfo.key);
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    icon.onerror = () => {
        icon.hidden = true;
    };

    const label = document.createElement('span');
    label.className = 'pokemon-role-badge__label';
    label.textContent = formatPokemonRoleLabel(roleInfo.label);

    badge.append(icon, label);
    return badge;
}

function createPokemonRespawnMapButton(entry, options = {}){
    const { modal = false } = options;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'pokemon-respawn-map-btn';
    if(modal) button.classList.add('pokemon-respawn-map-btn--modal');
    button.setAttribute('aria-label', `Mostrar respawns de ${entry.name} no mapa interativo`);
    button.title = 'Mostrar respawns no mapa';
    button.textContent = '🗺️';
    button.addEventListener('click', async event => {
        event.preventDefault();
        event.stopPropagation();
        if(button.disabled) return;
        button.disabled = true;
        button.setAttribute('aria-busy', 'true');
        try{
            await openInteractiveMapPokemonRespawns(entry, { trigger: button });
        }finally{
            button.disabled = false;
            button.removeAttribute('aria-busy');
        }
    });
    return button;
}

function createPokemonPassiveBadge(entry, options = {}){
    const { variant = 'normal' } = options;
    const isShiny = variant === 'shiny';
    const passiveLabel = getPokemonEntryPassiveLabel(entry, variant);
    if(!passiveLabel) return null;

    const badge = document.createElement('span');
    badge.className = 'pokemon-passive-badge';
    badge.tabIndex = 0;
    badge.setAttribute('aria-label', `${isShiny ? 'Passiva Shiny' : 'Passiva'}: ${passiveLabel}`);

    const mark = document.createElement('span');
    mark.className = 'pokemon-passive-badge__mark';
    mark.textContent = '!';

    const label = document.createElement('span');
    label.className = 'pokemon-passive-badge__label';
    label.textContent = isShiny ? 'Passiva Shiny' : 'Passiva';

    const tooltip = document.createElement('span');
    tooltip.className = 'pokemon-passive-badge__tooltip';
    tooltip.textContent = passiveLabel;

    badge.append(mark, label, tooltip);
    return badge;
}

function setPokemonDetailsModalTheme(entry){
    if(!(pokemonDetailsContent instanceof HTMLElement)){
        return;
    }

    const naturalTypes = Array.isArray(entry?.naturalElements) ? entry.naturalElements : [];
    const primaryType = normalizePokemonTypeKey(entry?.type1 || naturalTypes[0] || '');
    const secondaryFallback = naturalTypes.find((type) => normalizePokemonTypeKey(type) && normalizePokemonTypeKey(type) !== primaryType) || '';
    const secondaryType = normalizePokemonTypeKey(entry?.type2 || secondaryFallback || primaryType || '');
    const primaryColor = primaryType ? getTypeColor(primaryType) : '#68d7ff';
    const secondaryColor = secondaryType ? getTypeColor(secondaryType) : primaryColor;

    pokemonDetailsContent.dataset.primaryType = primaryType || 'unknown';
    pokemonDetailsContent.dataset.secondaryType = secondaryType || primaryType || 'unknown';
    pokemonDetailsContent.style.setProperty('--pokemon-detail-primary', primaryColor);
    pokemonDetailsContent.style.setProperty('--pokemon-detail-primary-rgb', hexToRgb(primaryColor));
    pokemonDetailsContent.style.setProperty('--pokemon-detail-secondary', secondaryColor);
    pokemonDetailsContent.style.setProperty('--pokemon-detail-secondary-rgb', hexToRgb(secondaryColor));
}

function createPokemonBallCard(ballConfig, averageValue, caption){
    const card = document.createElement('article');
    card.className = 'pokemon-ball-card';

    const media = document.createElement('span');
    media.className = 'pokemon-ball-card__media';

    const icon = document.createElement('img');
    icon.src = ballConfig?.key ? getBallPreviewImageSrc(ballConfig.key) : BALL_IMAGE_FALLBACK;
    icon.alt = '';
    icon.loading = 'lazy';
    icon.decoding = 'async';
    setImageFallback(icon, BALL_IMAGE_FALLBACK);
    media.appendChild(icon);

    const body = document.createElement('span');
    body.className = 'pokemon-ball-card__body';

    const title = document.createElement('strong');
    title.className = 'pokemon-ball-card__title';
    title.textContent = ballConfig?.label || 'Pokébola';

    const value = document.createElement('span');
    value.className = 'pokemon-ball-card__value';
    value.textContent = Number.isFinite(averageValue) ? `${averageValue} em m\u00e9dia` : 'Sem m\u00e9dia';

    const note = document.createElement('span');
    note.className = 'pokemon-ball-card__note';
    note.textContent = caption;

    body.append(title, value, note);
    card.append(media, body);
    return card;
}

function getPokemonCaptureLevelKey(level){
    const numericLevel = Number(level);
    if(Number.isFinite(numericLevel)) return numericLevel;
    const normalized = String(level || '').trim().toLowerCase();
    return normalized || 0;
}

function getPokemonShinyCaptureLevelKey(entry){
    const specialTags = Array.isArray(entry?.specialTags) ? entry.specialTags : [];
    if(specialTags.includes('ace')) return 'ace';
    if(specialTags.includes('pre-ace')) return 'pre';
    if(isPokemonHuntAceSourceEntry(entry)) return 'ace';
    if(isPokemonHuntPreAceEntry(entry)) return 'pre';
    return getPokemonCaptureLevelKey(entry?.level);
}

function isMegaPokemonCatalogEntry(entry){
    return normalizePokemonCatalogVariant(entry?.variant) === POKEMON_CATALOG_VARIANT_MEGA;
}

function getPokemonNormalCaptureAverageForBall(entry, ballKey){
    const normalizedBallKey = getCatchRequirementBallKey(ballKey);
    const ballPrice = Number(ballPrices?.[normalizedBallKey] || 0);
    const pokemonPrice = Number(entry?.price || 0);
    if(!ballPrice || !pokemonPrice) return 0;
    return Math.ceil(pokemonPrice / ballPrice);
}

function isPokemonCaptureVariantAvailable(entry, variant){
    if(isMegaPokemonCatalogEntry(entry)) return false;
    if(getPokemonEntrySpecialTags(entry).includes('pack')) return false;
    if(variant === 'normal') return entry?.normalCaptureAvailable !== false;
    if(variant === 'shiny') return entry?.shinyCaptureAvailable !== false;
    return false;
}

function getPokemonCaptureAverageForBall(level, variant, ballKey){
    const levelKey = getPokemonCaptureLevelKey(level);
    const requirementBall = getCatchRequirementBallKey(ballKey);
    const options = computeRequired(levelKey, variant) || [];

    const explicitOption = options.find((option) => (
        option
        && typeof option === 'object'
        && typeof option[requirementBall] === 'number'
        && option[requirementBall] > 0
    ));
    if(explicitOption){
        return Number(explicitOption[requirementBall] || 0);
    }

    const fallbackOption = options.find((option) => getCatchRequiredAmount(option, ballKey, variant) > 0);
    return fallbackOption ? Number(getCatchRequiredAmount(fallbackOption, ballKey, variant) || 0) : 0;
}

function forEachTeamHuntSourceName(callback){
    if(!teamsCatalogLoaded || !Array.isArray(teamsCatalog) || typeof callback !== 'function') return;

    const collectHuntSource = (entity) => {
        const sourceName = String(entity?.name || '').trim();
        if(!sourceName || entity?.sourceHuntName) return;
        getTeamHuntPreEvolutionSourceNames(sourceName).forEach(callback);
    };

    teamsCatalog.forEach((team) => {
        (Array.isArray(team?.hunts) ? team.hunts : []).forEach(collectHuntSource);
        (Array.isArray(team?.alternativeHunts) ? team.alternativeHunts : []).forEach(collectHuntSource);
    });
}

function getPokemonHuntAceSourceKeySet(){
    if(!teamsCatalogLoaded || !Array.isArray(teamsCatalog)) return new Set();
    if(pokemonHuntAceSourceKeys instanceof Set) return pokemonHuntAceSourceKeys;

    const sourceKeys = new Set();
    forEachTeamHuntSourceName((sourceName) => {
        const key = getPokemonCatalogRegistryKey(sourceName);
        if(key) sourceKeys.add(key);
    });

    pokemonHuntAceSourceKeys = sourceKeys;
    return pokemonHuntAceSourceKeys;
}

function isPokemonHuntAceSourceEntry(entry){
    const key = getPokemonCatalogRegistryKey(entry?.name);
    return !!key && getPokemonHuntAceSourceKeySet().has(key);
}

function getPokemonHuntPreAceStageMap(){
    if(!teamsCatalogLoaded || !Array.isArray(teamsCatalog)) return new Map();
    if(pokemonHuntPreAceStageByKey instanceof Map) return pokemonHuntPreAceStageByKey;

    const stageByKey = new Map();
    forEachTeamHuntSourceName((sourceName) => {
        getTeamHuntPreEvolutionEntries(sourceName).forEach((preEvolution, index) => {
            const key = getPokemonCatalogRegistryKey(preEvolution?.name);
            const stage = Math.min(index + 1, 2);
            if(!key || !stage) return;
            stageByKey.set(key, Math.max(Number(stageByKey.get(key) || 0), stage));
        });
    });

    pokemonHuntPreAceStageByKey = stageByKey;
    return pokemonHuntPreAceStageByKey;
}

function getPokemonHuntPreAceEvolutionStage(entry){
    const key = getPokemonCatalogRegistryKey(entry?.name);
    if(!key) return 0;
    return Number(getPokemonHuntPreAceStageMap().get(key) || 0);
}

function isPokemonHuntPreAceEntry(entry){
    if(Array.isArray(entry?.specialTags) && entry.specialTags.includes('pre-ace')) return true;
    return getPokemonHuntPreAceEvolutionStage(entry) > 0;
}

function getPokemonHuntPreAceShinyAverageForBall(entry, ballKey){
    if(!isPokemonHuntPreAceEntry(entry)) return 0;
    return getPokemonCaptureAverageForBall('pre', 'shiny', ballKey);
}

function getPokemonAverageValueForVariant(entry, variant, ballKey){
    if(!isPokemonCaptureVariantAvailable(entry, variant)) return 0;
    if(variant === 'normal') return getPokemonNormalCaptureAverageForBall(entry, ballKey);
    if(variant === 'shiny'){
        const levelForRequirements = getPokemonShinyCaptureLevelKey(entry);
        return levelForRequirements ? getPokemonCaptureAverageForBall(levelForRequirements, variant, ballKey) : 0;
    }
    return 0;
}

function isPokemonNormalCaptureBallAllowed(entry, ballKey){
    const allowedBalls = Array.isArray(entry?.normalCaptureBalls) ? entry.normalCaptureBalls : [];
    if(!allowedBalls.length) return true;
    const rawBallKey = String(ballKey || '').trim().toLowerCase();
    if(allowedBalls.includes(rawBallKey)) return true;
    const requirementBallKey = getCatchRequirementBallKey(rawBallKey);
    return requirementBallKey !== rawBallKey && allowedBalls.includes(requirementBallKey);
}

function isPokemonSafariBallValue(value){
    const normalized = String(value || '').trim().toLowerCase();
    return normalized === 'safari' || normalized === 'saffari';
}

function normalizePokemonNormalCaptureBalls(values, specialTags = []){
    const normalizedBalls = Array.from(new Set(
        (Array.isArray(values) ? values : [])
            .map(value => {
                const normalized = String(value || '').trim().toLowerCase();
                return normalized === 'saffari' ? 'safari' : normalized;
            })
            .filter(value => catchBallOrder.includes(value) || value === 'elemental')
    ));
    const isSafariCapture = normalizedBalls.some(isPokemonSafariBallValue)
        || normalizePokemonSpecialTags(specialTags).includes('saffari');
    if(isSafariCapture){
        return ['story', 'safari', 'elemental'];
    }
    return normalizedBalls;
}

function isPokemonSafariCaptureEntry(entry){
    return isPokemonNormalCaptureBallAllowed(entry, 'safari')
        && Array.isArray(entry?.normalCaptureBalls)
        && entry.normalCaptureBalls.some(isPokemonSafariBallValue);
}

function shouldDisplayPokemonSafariAverageLabel(entry){
    return getPokemonEntrySpecialTags(entry).some(tagKey => normalizePokemonSpecialTagKey(tagKey) === 'saffari')
        || isPokemonSafariCaptureEntry(entry);
}

function buildPokemonAverageCards(entry, variant){
    const cards = [];
    const appendBallCard = (ball, caption = variant === 'shiny' ? 'Shiny' : 'Normal') => {
        if(variant === 'normal' && !isPokemonNormalCaptureBallAllowed(entry, ball.key)) return;
        cards.push(createPokemonBallCard(
            ball,
            getPokemonAverageValueForVariant(entry, variant, ball.key),
            caption
        ));
    };

    appendBallCard({ key: 'ultra', label: 'Ultra Ball' });
    appendBallCard({ key: 'story', label: 'Story Ball' });
    if(variant === 'normal' && isPokemonSafariCaptureEntry(entry)){
        appendBallCard({ key: 'safari', label: 'Safari Ball' });
    }

    const elementalOptions = getPokemonElementalBallOptions(entry?.naturalElements || []);
    if(elementalOptions.length){
        elementalOptions.forEach((ball) => {
            appendBallCard(
                ball,
                `${variant === 'shiny' ? 'Shiny' : 'Normal'} \u2022 ${getPokemonElementalBallTypeLabel(ball.key, entry?.naturalElements || [])}`
            );
        });
        return cards;
    }

    appendBallCard({ key: 'elemental', label: 'Ball Elemental' });
    return cards;
}

function getPokemonAverageDescription(entry, variant){
    if(variant === 'normal'){
        if(entry?.normalCaptureNote) return entry.normalCaptureNote;
        if(isMegaPokemonCatalogEntry(entry)) return 'Mega nao pode ser capturado.';
        if(entry?.normalCaptureAvailable === false) return 'Nao pode ser capturado no momento.';
        if(isPokemonSafariCaptureEntry(entry)) return 'Captura apenas com Safari Ball, Story Ball e Elemental Balls.';
        return 'Preco do Pokemon dividido pelo preco da Ultra, Story e Elemental Ball.';
    }
    if(entry?.shinyCaptureNote) return entry.shinyCaptureNote;
    if(isMegaPokemonCatalogEntry(entry)) return 'Mega nao pode ser capturado.';
    if(entry?.shinyCaptureAvailable === false) return 'Versao shiny nao pode ser capturada.';
    return 'Use Ultra Ball, Story Ball e as Elemental Balls do(s) tipo(s).';
}

function createPokemonAverageGroup(titleText, descriptionText, cards = []){
    const group = document.createElement('section');
    group.className = 'pokemon-average-group';

    const header = document.createElement('div');
    header.className = 'pokemon-average-group__head';

    const title = document.createElement('h4');
    title.className = 'pokemon-average-group__title';
    title.textContent = titleText;

    const description = document.createElement('p');
    description.className = 'pokemon-average-group__description';
    description.textContent = descriptionText;

    header.append(title, description);
    group.appendChild(header);

    const grid = document.createElement('div');
    grid.className = 'pokemon-average-group__grid';
    cards.forEach((card) => {
        grid.appendChild(card);
    });

    group.appendChild(grid);
    return group;
}

function getPokemonElementalBallOptions(types = []){
    const seen = new Set();
    return types
        .map(type => ELEMENTAL_BALL_TYPE_MAP[normalizePokemonTypeKey(type)] || null)
        .filter(ball => {
            if(!ball || seen.has(ball.key)) return false;
            seen.add(ball.key);
            return true;
        });
}

function getPokemonElementalBallTypeLabel(ballKey, types = []){
    const matchingType = types.find(type => (ELEMENTAL_BALL_TYPE_MAP[normalizePokemonTypeKey(type)] || {}).key === ballKey);
    return matchingType ? formatPokemonTypeLabel(matchingType) : 'Elemento';
}

function getPokemonTypeMultiplier(attackingType, defendingTypes = []){
    const normalizedDefendingTypes = defendingTypes
        .map(normalizePokemonTypeKey)
        .filter(Boolean);
    const rawMultiplier = computeTypeRawMultiplier(attackingType, normalizedDefendingTypes);
    return normalizeTypeMatchupMultiplier(rawMultiplier, attackingType, normalizedDefendingTypes);
}

function getPokemonWeaknesses(types = []){
    const attackTypes = menuTypes.length ? menuTypes : Object.keys(effectiveness);
    return attackTypes
        .map(type => ({
            type,
            multiplier: getPokemonTypeMultiplier(type, types)
        }))
        .filter(entry => entry.multiplier > 1)
        .sort((left, right) => right.multiplier - left.multiplier || left.type.localeCompare(right.type));
}

function normalizePokemonCatalogEntry(entry, index){
    if(!entry || typeof entry !== 'object') return null;

    const name = String(entry.name || '').trim();
    if(!name) return null;

    const slug = String(entry.slug || name)
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '') || `pokemon-${index + 1}`;

    const primaryType = normalizePokemonTypeKey(entry.type1 || entry.primaryType || '');
    const secondaryType = normalizePokemonTypeKey(entry.type2 || entry.secondaryType || '');
    const naturalElements = Array.from(new Set(
        (Array.isArray(entry.naturalElements) && entry.naturalElements.length ? entry.naturalElements : [primaryType, secondaryType])
            .map(normalizePokemonTypeKey)
            .filter(Boolean)
    ));
    const moveset = Array.from(new Set(
        (Array.isArray(entry.moveset) ? entry.moveset : [entry.moveset])
            .map(normalizePokemonTypeKey)
            .filter(Boolean)
    ));

    const roleInfo = getPokemonRoleInfo(entry.role);
    const officialDex = resolvePokemonCatalogOfficialDex(entry);
    const hasImage = Object.prototype.hasOwnProperty.call(entry, 'image');
    const generation = resolvePokemonCatalogGeneration(entry);
    const baseSpecialTags = normalizePokemonSpecialTags(
        entry.specialTags
        ?? entry.tags
        ?? entry.specialTag
    );
    const normalCaptureBalls = normalizePokemonNormalCaptureBalls(entry.normalCaptureBalls, baseSpecialTags);
    const specialTags = normalizePokemonSpecialTags([
        ...baseSpecialTags,
        ...(normalCaptureBalls.some(isPokemonSafariBallValue) ? ['saffari'] : [])
    ]);
    const subFunctions = normalizePokemonSubFunctions(
        entry.subFunctions
        ?? entry.subFunction
        ?? entry.subFuncao
        ?? entry.subfuncoes
    );
    const shinySubFunctions = normalizePokemonSubFunctions(
        entry.shinySubFunctions
        ?? entry.shinySubFunction
        ?? entry.shinySubFuncao
        ?? entry.shinySubfuncoes
    );
    const searchAliases = Array.from(new Set(
        [
            ...(Array.isArray(entry.searchAliases) ? entry.searchAliases : []),
            ...(Array.isArray(entry.aliases) ? entry.aliases : []),
            ...(Array.isArray(entry.searchTerms) ? entry.searchTerms : [])
        ]
            .map(normalizePokemonSearchText)
            .filter(Boolean)
    ));

    return {
        id: slug,
        routeSlug: slug,
        dex: officialDex,
        routeToken: String(entry.routeToken || entry.pokedexToken || '').trim().toLowerCase(),
        name,
        searchName: normalizePokemonSearchText(name),
        searchAliases,
        role: roleInfo.label,
        roleKey: roleInfo.key,
        level: entry.level,
        levelKey: normalizePokemonLevelFilterValue(entry.level, entry.levelLabel),
        generation,
        generationKey: normalizePokemonGenerationFilterValue(generation),
        type1: primaryType,
        type2: secondaryType,
        naturalElements,
        moveset,
        team: String(entry.team || '').trim().toLowerCase(),
        image: hasImage ? String(entry.image || '').trim() : `${slug}.png`,
        price: Number(entry.price ?? entry.preco ?? 0) || 0,
        priceLabel: String(entry.priceLabel || '').trim(),
        acquisitionUrl: String(entry.acquisitionUrl || '').trim(),
        levelLabel: String(entry.levelLabel || '').trim(),
        movesetLabel: String(entry.movesetLabel || '').trim(),
        teamLabel: String(entry.teamLabel || '').trim(),
        normalCaptureAvailable: entry.normalCaptureAvailable !== false,
        normalCaptureNote: String(entry.normalCaptureNote || '').trim(),
        normalCaptureBalls,
        registered: entry.registered !== false,
        shinyCaptureAvailable: entry.shinyCaptureAvailable !== false,
        shinyCaptureNote: String(entry.shinyCaptureNote || '').trim(),
        naturalShiny: entry.naturalShiny === true,
        catalogHidden: entry.catalogHidden === true || entry.hidden === true,
        specialTags,
        subFunctions,
        shinySubFunctions,
        passiveName: String(entry.passiveName || '').trim(),
        passiveDescription: String(entry.passiveDescription || '').trim(),
        passiveText: String(entry.passiveText || '').trim(),
        shinyPassiveName: String(entry.shinyPassiveName || '').trim(),
        shinyPassiveDescription: String(entry.shinyPassiveDescription || '').trim(),
        passiveSuperEffectiveTypes: Array.from(new Set(
            (Array.isArray(entry.passiveSuperEffectiveTypes) ? entry.passiveSuperEffectiveTypes : [])
                .map(normalizePokemonTypeKey)
                .filter(Boolean)
        )),
        shinyPassiveSuperEffectiveTypes: Array.from(new Set(
            (Array.isArray(entry.shinyPassiveSuperEffectiveTypes) ? entry.shinyPassiveSuperEffectiveTypes : [])
                .map(normalizePokemonTypeKey)
                .filter(Boolean)
        )),
        defenseByBossType: entry.defenseByBossType && typeof entry.defenseByBossType === 'object'
            ? { ...entry.defenseByBossType }
            : {},
        defenseDamageFactorByBossType: entry.defenseDamageFactorByBossType && typeof entry.defenseDamageFactorByBossType === 'object'
            ? { ...entry.defenseDamageFactorByBossType }
            : {},
        variant: normalizePokemonCatalogVariant(entry.variant)
    };
}

function buildMegaPokemonCatalogEntries(rawMegaEntries = [], registeredEntries = []){
    const registeredKeys = new Set(
        (registeredEntries || [])
            .map(entry => getPokemonCatalogRegistryKey(entry?.name))
            .filter(Boolean)
    );
    const seenMegaKeys = new Set();

    return (rawMegaEntries || [])
        .map((entry, index) => normalizePokemonCatalogEntry({
            ...entry,
            dex: null,
            image: Object.prototype.hasOwnProperty.call(entry || {}, 'image') ? entry.image : '',
            level: entry?.level || 'ace',
            moveset: Array.isArray(entry?.moveset) && entry.moveset.length
                ? entry.moveset
                : [entry?.type1, entry?.type2].filter(Boolean),
            registered: false,
            normalCaptureAvailable: false,
            normalCaptureNote: entry?.normalCaptureNote || 'Mega nao pode ser capturado.',
            shinyCaptureAvailable: false,
            shinyCaptureNote: entry?.shinyCaptureNote || 'Mega nao pode ser capturado.',
            specialTags: [
                ...(Array.isArray(entry?.specialTags) ? entry.specialTags : []),
                'mega'
            ],
            variant: POKEMON_CATALOG_VARIANT_MEGA
        }, index))
        .filter((entry) => {
            if(!entry) return false;
            const registryKey = getPokemonCatalogRegistryKey(entry.name);
            if(!registryKey || registeredKeys.has(registryKey) || seenMegaKeys.has(registryKey)) return false;
            seenMegaKeys.add(registryKey);
            return true;
        });
}

function getPokemonCatalogAttachedFormBaseKey(entry){
    if(isMegaPokemonCatalogEntry(entry)){
        return getPokemonMegaBaseRegistryKey(entry);
    }

    const name = String(entry?.name || '').trim();
    if(!name || /^mewtwo$/i.test(name) || !/two$/i.test(name)) return '';
    return getPokemonCatalogRegistryKey(name.replace(/two$/i, ''));
}

function formatPokemonPokedexRouteNumber(dex){
    const numericDex = Number(dex);
    return Number.isFinite(numericDex) && numericDex > 0
        ? String(numericDex).padStart(3, '0')
        : '';
}

function getPokemonCatalogRouteFallbackToken(entry){
    return String(entry?.routeSlug || entry?.id || '')
        .trim()
        .toLowerCase();
}

function getPokemonCatalogFormPriority(entry){
    const name = normalizePokemonSearchText(entry?.name);
    if(!name) return 100;
    if(/^mega\s+/.test(name)) return 80;
    if(/\btwo$/.test(name) || /'s\b/.test(String(entry?.name || '').toLowerCase())) return 70;
    if(/^alolan\s+/.test(name)) return 50;
    if(/\b(gorging|full-belly|hangry|hero|dusk|midnight|midday|amped|low key|meteor|core|curly|droopy|stretchy)\b/.test(name)) return 40;
    if(/\b(male|female|plant|sandy|trash|west|east|sword form|shield form)\b/.test(name)) return 35;
    return 0;
}

function getPokemonMegaRouteSuffix(entry){
    const name = String(entry?.name || '').trim();
    const variantMatch = name.match(/\s+([xyz])$/i);
    return variantMatch ? `m${variantMatch[1].toLowerCase()}` : 'm';
}

function assignPokemonCatalogRouteTokens(normalEntries = [], megaEntries = []){
    const usedTokens = new Set();
    const assignUniqueToken = (entry, preferredToken) => {
        const fallbackToken = getPokemonCatalogRouteFallbackToken(entry);
        const baseToken = String(preferredToken || fallbackToken || '').trim().toLowerCase();
        if(!baseToken) return;

        let routeToken = baseToken;
        let suffix = 2;
        while(usedTokens.has(routeToken)){
            routeToken = `${baseToken}-${suffix}`;
            suffix += 1;
        }
        usedTokens.add(routeToken);
        entry.routeToken = routeToken;
    };

    const normalGroupsByDex = new Map();
    normalEntries.forEach((entry, index) => {
        const dex = Number(entry?.dex);
        if(Number.isFinite(dex) && dex > 0){
            if(!normalGroupsByDex.has(dex)) normalGroupsByDex.set(dex, []);
            normalGroupsByDex.get(dex).push({ entry, index });
            return;
        }
        assignUniqueToken(entry, entry?.routeToken);
    });

    Array.from(normalGroupsByDex.keys())
        .sort((left, right) => left - right)
        .forEach((dex) => {
            const baseToken = formatPokemonPokedexRouteNumber(dex);
            const group = normalGroupsByDex.get(dex)
                .sort((left, right) => (
                    getPokemonCatalogFormPriority(left.entry) - getPokemonCatalogFormPriority(right.entry)
                    || left.index - right.index
                ));
            group.forEach(({ entry }, formIndex) => {
                assignUniqueToken(entry, formIndex === 0 ? baseToken : `${baseToken}-${formIndex}`);
            });
        });

    megaEntries
        .slice()
        .sort((left, right) => (
            Number(left?.dex || Number.MAX_SAFE_INTEGER) - Number(right?.dex || Number.MAX_SAFE_INTEGER)
            || String(left?.name || '').localeCompare(String(right?.name || ''), 'pt-BR')
        ))
        .forEach((entry) => {
            const baseToken = formatPokemonPokedexRouteNumber(entry?.dex);
            const megaToken = baseToken ? `${baseToken}-${getPokemonMegaRouteSuffix(entry)}` : '';
            assignUniqueToken(entry, megaToken || entry?.routeToken);
        });
}

function getPokemonCatalogSortNumber(entry){
    const dex = Number(entry?.dex);
    return Number.isFinite(dex) && dex > 0 ? dex : Number.MAX_SAFE_INTEGER;
}

function comparePokemonCatalogPokedexOrder(left, right){
    return getPokemonCatalogSortNumber(left) - getPokemonCatalogSortNumber(right)
        || getPokemonCatalogFormPriority(left) - getPokemonCatalogFormPriority(right)
        || String(left?.routeToken || '').localeCompare(String(right?.routeToken || ''), 'pt-BR')
        || String(left?.name || '').localeCompare(String(right?.name || ''), 'pt-BR');
}

function orderPokemonCatalogByEvolution(normalEntries = [], megaEntries = []){
    const normalList = Array.isArray(normalEntries) ? normalEntries : [];
    const megaList = Array.isArray(megaEntries) ? megaEntries : [];
    const sourceIndexByEntry = new Map(normalList.map((entry, index) => [entry, index]));
    const baseEntries = normalList.filter(entry => !getPokemonCatalogAttachedFormBaseKey(entry));
    const baseEntryByKey = new Map(
        baseEntries
            .map(entry => [getPokemonCatalogRegistryKey(entry?.name), entry])
            .filter(([key]) => Boolean(key))
    );
    const attachedEntriesByBaseKey = new Map();
    const unattachedEntries = [];

    [...megaList, ...normalList.filter(entry => getPokemonCatalogAttachedFormBaseKey(entry))]
        .forEach((entry) => {
            const baseKey = getPokemonCatalogAttachedFormBaseKey(entry);
            if(!baseKey || !baseEntryByKey.has(baseKey)){
                unattachedEntries.push(entry);
                return;
            }
            if(!attachedEntriesByBaseKey.has(baseKey)){
                attachedEntriesByBaseKey.set(baseKey, []);
            }
            attachedEntriesByBaseKey.get(baseKey).push(entry);
        });

    const childrenByKey = new Map();
    const parentsByKey = new Map();
    const undirectedNeighborsByKey = new Map();
    const ensureKey = (key) => {
        if(!childrenByKey.has(key)) childrenByKey.set(key, new Set());
        if(!parentsByKey.has(key)) parentsByKey.set(key, new Set());
        if(!undirectedNeighborsByKey.has(key)) undirectedNeighborsByKey.set(key, new Set());
    };

    baseEntryByKey.forEach((entry, key) => ensureKey(key));
    POKEMON_EVOLUTION_EDGES.forEach(([parentName, childName]) => {
        const parentKey = getPokemonCatalogRegistryKey(parentName);
        const childKey = getPokemonCatalogRegistryKey(childName);
        if(!baseEntryByKey.has(parentKey) || !baseEntryByKey.has(childKey)) return;
        ensureKey(parentKey);
        ensureKey(childKey);
        childrenByKey.get(parentKey).add(childKey);
        parentsByKey.get(childKey).add(parentKey);
        undirectedNeighborsByKey.get(parentKey).add(childKey);
        undirectedNeighborsByKey.get(childKey).add(parentKey);
    });

    const entrySourceIndex = key => sourceIndexByEntry.get(baseEntryByKey.get(key)) ?? Number.MAX_SAFE_INTEGER;
    const compareFamilyKeys = (left, right) => (
        comparePokemonCatalogPokedexOrder(baseEntryByKey.get(left), baseEntryByKey.get(right))
        || entrySourceIndex(left) - entrySourceIndex(right)
    );
    const visitedKeys = new Set();
    const families = [];

    baseEntries.forEach((entry) => {
        const startKey = getPokemonCatalogRegistryKey(entry?.name);
        if(!startKey || visitedKeys.has(startKey)) return;

        const familyKeys = [];
        const pendingKeys = [startKey];
        visitedKeys.add(startKey);
        while(pendingKeys.length){
            const key = pendingKeys.shift();
            familyKeys.push(key);
            Array.from(undirectedNeighborsByKey.get(key) || [])
                .sort(compareFamilyKeys)
                .forEach((neighborKey) => {
                    if(visitedKeys.has(neighborKey)) return;
                    visitedKeys.add(neighborKey);
                    pendingKeys.push(neighborKey);
                });
        }

        const familyKeySet = new Set(familyKeys);
        const pendingParentCount = new Map(
            familyKeys.map(key => [
                key,
                Array.from(parentsByKey.get(key) || []).filter(parentKey => familyKeySet.has(parentKey)).length
            ])
        );
        const readyKeys = familyKeys
            .filter(key => pendingParentCount.get(key) === 0)
            .sort(compareFamilyKeys);
        const orderedKeys = [];

        while(readyKeys.length){
            const key = readyKeys.shift();
            orderedKeys.push(key);
            Array.from(childrenByKey.get(key) || [])
                .filter(childKey => familyKeySet.has(childKey))
                .sort(compareFamilyKeys)
                .forEach((childKey) => {
                    const remainingParents = (pendingParentCount.get(childKey) || 0) - 1;
                    pendingParentCount.set(childKey, remainingParents);
                    if(remainingParents === 0){
                        readyKeys.push(childKey);
                        readyKeys.sort(compareFamilyKeys);
                    }
                });
        }

        familyKeys
            .filter(key => !orderedKeys.includes(key))
            .sort(compareFamilyKeys)
            .forEach(key => orderedKeys.push(key));

        families.push({
            sortNumber: Math.min(...familyKeys.map(key => getPokemonCatalogSortNumber(baseEntryByKey.get(key)))),
            sourceIndex: Math.min(...familyKeys.map(entrySourceIndex)),
            keys: orderedKeys
        });
    });

    families.sort((left, right) => (
        left.sortNumber - right.sortNumber
        || left.sourceIndex - right.sourceIndex
    ));
    const orderedEntries = [];
    families.forEach((family) => {
        family.keys.forEach((key) => {
            const entry = baseEntryByKey.get(key);
            if(entry) orderedEntries.push(entry);
            (attachedEntriesByBaseKey.get(key) || [])
                .slice()
                .sort(comparePokemonCatalogPokedexOrder)
                .forEach(attachedEntry => orderedEntries.push(attachedEntry));
        });
    });
    unattachedEntries
        .slice()
        .sort(comparePokemonCatalogPokedexOrder)
        .forEach(entry => orderedEntries.push(entry));
    return orderedEntries;
}

function applyPokemonCatalogVariant(variant = POKEMON_CATALOG_VARIANT_DEFAULT, options = {}){
    const { resetFilters = false } = options;
    const normalizedVariant = setCurrentPokemonCatalogVariant(variant);
    const variantChanged = activePokemonCatalogVariant !== normalizedVariant;
    activePokemonCatalogVariant = normalizedVariant;
    pokemonCatalog = normalizedVariant === POKEMON_CATALOG_VARIANT_DEFAULT
        ? orderPokemonCatalogByEvolution(
            getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_DEFAULT),
            getPokemonCatalogEntriesForVariant(POKEMON_CATALOG_VARIANT_MEGA)
        )
        : getPokemonCatalogEntriesForVariant(normalizedVariant);
    if(pokemonCardGrid){
        pokemonCardGrid.setAttribute('aria-label', 'Lista de pokemons');
    }

    if(resetFilters || variantChanged){
        resetPokemonCatalogFilters();
    } else {
        updatePokemonCatalogPaginationControls(null);
    }

    populatePokemonFilterControls();
    return normalizedVariant;
}

function renderPokemonCatalog(options = {}){
    const { animate = false, historyMode = 'replace' } = options;
    if(!pokemonCardGrid) return;
    const visibleEntries = getVisiblePokemonCatalogEntries();

    if(!visibleEntries.length){
        updatePokemonCatalogStatus(0, 0);
        updatePokemonCatalogPaginationControls(null);
        pokemonCardGrid.replaceChildren(
            createInlineStatusMessage(
                'pokemon-empty-message',
                'Adicione itens nos catalogos de pokemon para preencher esta pagina.'
            )
        );
        if(contentPokemons && !contentPokemons.hidden){
            updateUrl({ historyMode });
        }
        return;
    }

    const filteredEntries = getFilteredPokemonCatalogEntries();
    updatePokemonCatalogStatus(visibleEntries.length, filteredEntries.length);

    if(!filteredEntries.length){
        updatePokemonCatalogPaginationControls(null);
        pokemonCardGrid.replaceChildren(createInlineStatusMessage('pokemon-no-results-message', 'Nenhum resultado encontrado. Ajuste ou limpe os filtros para continuar.'));
        if(contentPokemons && !contentPokemons.hidden){
            updateUrl({ historyMode });
        }
        return;
    }

    const paginationState = getPokemonCatalogPaginationState(filteredEntries);
    updatePokemonCatalogPaginationControls(paginationState);

    const fragment = document.createDocumentFragment();
    paginationState.entries.forEach((entry) => {
        const hasRole = hasPokemonVisibleRole({ key: entry.roleKey, label: entry.role });
        const specialTags = getPokemonCardSpecialTags(entry);
        const card = document.createElement('article');
        card.className = 'pokemon-entry-card';
        setTypeToneVariables(card, entry.type1 || entry.naturalElements?.[0] || '');
        if(specialTags.includes('mewtwo-solo') && !POKEMON_STANDARD_CARD_IMAGE_ENTRIES.has(entry.searchName)){
            card.classList.add('pokemon-entry-card--mewtwo-solo');
        }
        card.setAttribute('role', 'listitem');
        // Expor o id da entrada no DOM para estilos direcionados
        card.dataset.pokemonId = entry.id;
        const ariaLabelParts = [entry.name];
        if(hasRole) ariaLabelParts.push(entry.role);
        ariaLabelParts.push(getPokemonEntryLevelLabel(entry));
        if(shouldShowPokemonNaturalShinyBadgeOnCard(entry)) ariaLabelParts.push('Shiny por natureza');
        specialTags.forEach((tagKey) => ariaLabelParts.push(formatPokemonSpecialTagLabel(tagKey)));
        card.setAttribute('aria-label', `${ariaLabelParts.join(', ')}.`);

        const detailsTrigger = document.createElement('button');
        detailsTrigger.type = 'button';
        detailsTrigger.className = 'pokemon-entry-card__details-trigger';
        detailsTrigger.setAttribute('aria-label', `Abrir detalhes de ${entry.name}`);
        detailsTrigger.addEventListener('click', () => {
            openPokemonDetailsModal(entry, { pushState: true });
        });

        const header = document.createElement('div');
        header.className = 'pokemon-entry-card__header';

        const titleWrap = document.createElement('div');
        titleWrap.className = 'pokemon-entry-card__title-wrap';

        const title = document.createElement('strong');
        title.className = 'pokemon-entry-card__title';
        title.textContent = entry.name;

        const metaRow = document.createElement('span');
        metaRow.className = 'pokemon-entry-card__meta-row';

        const level = document.createElement('span');
        level.className = 'pokemon-entry-card__level';
        level.textContent = getPokemonEntryLevelLabel(entry);
        metaRow.appendChild(level);
        if(shouldShowPokemonNaturalShinyBadgeOnCard(entry)){
            metaRow.appendChild(createPokemonNaturalShinyBadge());
        }
        specialTags.forEach((tagKey) => {
            metaRow.appendChild(createPokemonSpecialTagBadge(tagKey, {
                labelOverride: tagKey === 'mewtwo-solo' ? 'Mewtwo' : ''
            }));
        });

        titleWrap.append(title, metaRow);

        const headerActions = document.createElement('div');
        headerActions.className = 'pokemon-entry-card__header-actions';
        headerActions.appendChild(createPokemonRespawnMapButton(entry));
        if(hasRole){
            headerActions.appendChild(createPokemonRoleBadge({ key: entry.roleKey, label: entry.role }, { compact: true }));
        }
        header.append(titleWrap, headerActions);

        const media = document.createElement('div');
        media.className = 'pokemon-entry-card__media';

        const image = document.createElement('img');
        image.src = getPokemonImageSource(entry);
        image.alt = `Imagem de ${entry.name}`;
        image.loading = 'lazy';
        image.decoding = 'async';
        setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
        media.appendChild(image);

        const sections = document.createElement('div');
        sections.className = 'pokemon-entry-card__sections';

        const movesetBlock = document.createElement('div');
        movesetBlock.className = 'pokemon-entry-card__block';
        const movesetLabel = document.createElement('span');
        movesetLabel.className = 'pokemon-entry-card__label';
        movesetLabel.textContent = 'Moveset';
        const movesetRow = document.createElement('div');
        movesetRow.className = 'pokemon-token-row';
        if(entry.moveset.length){
            // Se houver multiplos tipos de moveset, mostrar apenas icones na horizontal (compacto)
            if(entry.moveset.length > 1){
                entry.moveset.forEach(type => movesetRow.appendChild(createPokemonTypeToken(type, { compact: true })));
                movesetRow.classList.add('pokemon-token-row--icons');
            } else {
                entry.moveset.forEach(type => movesetRow.appendChild(createPokemonTypeToken(type)));
            }
        } else {
            const movesetHint = document.createElement('span');
            movesetHint.className = 'pokemon-entry-card__hint';
            movesetHint.textContent = entry.movesetLabel || 'Não informado';
            movesetRow.appendChild(movesetHint);
        }
        movesetBlock.append(movesetLabel, movesetRow);

        const elementsBlock = document.createElement('div');
        elementsBlock.className = 'pokemon-entry-card__block';
        const elementsLabel = document.createElement('span');
        elementsLabel.className = 'pokemon-entry-card__label';
        elementsLabel.textContent = 'Tipos';
        const elementsRow = document.createElement('div');
        elementsRow.className = 'pokemon-token-row';
        entry.naturalElements.forEach(type => elementsRow.appendChild(createPokemonTypeToken(type)));
        elementsBlock.append(elementsLabel, elementsRow);

        // Mostrar Tipos a esquerda e Moveset a direita para uma ordem de leitura mais natural
        sections.append(elementsBlock, movesetBlock);

        const footer = document.createElement('div');
        footer.className = 'pokemon-entry-card__footer';
        footer.appendChild(createPokemonTeamBadge(entry.team, { labelOverride: entry.teamLabel }));

        // Rotulo 'Detalhes' removido por pedido de UI; clique no card abre o modal de detalhes

        card.append(detailsTrigger, header, media, sections, footer);

        fragment.appendChild(card);
    });

    pokemonCardGrid.replaceChildren(fragment);
    if(contentPokemons && !contentPokemons.hidden){
        updateUrl({ historyMode });
    }

    if(useGsap && animate && contentPokemons && !contentPokemons.hidden){
        const cards = pokemonCardGrid.querySelectorAll('.pokemon-entry-card');
        if(cards.length){
            gsap.from(cards, { opacity: 0, y: 18, duration: 0.45, stagger: 0.06, clearProps: 'opacity,transform' });
        }
    }
}

function loadPokemonCatalog(){
    return Promise.all([
        fetchPokemonCatalogJson(POKEMON_CATALOG_URL),
        fetchPokemonCatalogJson(POKEMON_MEGA_CATALOG_URL).catch(error => {
            console.warn('Catalogo Mega indisponivel; carregando catalogo principal.', error);
            return { pokemon: [] };
        }),
        loadSharedPokemonGenerationMap(),
        loadSharedPokemonPokedexMap()
    ])
        .then(([registeredData, megaData, generationMap, pokedexMap]) => {
            pokemonCatalogGenerationMap = generationMap;
            pokemonCatalogPokedexMap = pokedexMap;
            const registeredEntries = getPokemonCatalogJsonList(registeredData)
                .map((entry, index) => normalizePokemonCatalogEntry(entry, index))
                .filter(Boolean);
            const megaEntries = buildMegaPokemonCatalogEntries(
                getPokemonCatalogJsonList(megaData),
                registeredEntries
            );
            assignPokemonCatalogRouteTokens(registeredEntries, megaEntries);

            pokemonCatalogEntriesByVariant = {
                default: registeredEntries,
                mega: megaEntries.slice().sort(comparePokemonCatalogPokedexOrder)
            };
            pokemonCatalogLoaded = true;
            huntBuilderTargetEntriesCache = null;
            applyPokemonCatalogVariant(getCurrentPokemonCatalogVariant(), { resetFilters: false });
            return true;
        })
        .catch(error => {
            showPokemonCatalogErrorState(
                'Nao foi possivel carregar os catalogos de pokemon. Verifique pokemons/pokemons.json e pokemons/mega-pokemons.json.',
                getCurrentPokemonCatalogVariant()
            );
            throw error;
        });
}

function ensurePokemonCatalogLoaded(options = {}){
    const { force = false } = options;
    if(pokemonCatalogLoaded && !force) return Promise.resolve(true);
    if(pokemonCatalogLoadPromise && !force) return pokemonCatalogLoadPromise;

    if(force){
        pokemonCatalogLoaded = false;
        pokemonCatalogLoadPromise = null;
        huntBuilderTargetEntriesCache = null;
    }

    showPokemonCatalogLoadingState();
    pokemonCatalogLoadPromise = loadPokemonCatalog()
        .finally(() => {
            pokemonCatalogLoadPromise = null;
        });

    return pokemonCatalogLoadPromise;
}

function resetPokemonBossUsageSection(){
    if(pokemonDetailsBossUsage){
        pokemonDetailsBossUsage.replaceChildren();
    }
    if(pokemonDetailsBossUsageSection){
        pokemonDetailsBossUsageSection.hidden = true;
    }
}

function ensurePokemonBossUsageDataReady(){
    if(typeof window.getPokemonBossUsages === 'function') return Promise.resolve(true);
    return ensureBossesPageReady().then(() => {
        if(typeof window.getPokemonBossUsages !== 'function'){
            throw new Error('bosses.js carregou sem expor os usos por Pokemon.');
        }
        return true;
    });
}

function createPokemonBossUsageSubject(entry){
    if(!entry || typeof entry !== 'object') return entry;

    const passiveTypes = new Set([
        ...(Array.isArray(entry.passiveSuperEffectiveTypes) ? entry.passiveSuperEffectiveTypes : []),
        ...(Array.isArray(entry.shinyPassiveSuperEffectiveTypes) ? entry.shinyPassiveSuperEffectiveTypes : [])
    ].map(normalizePokemonTypeKey).filter(Boolean));

    if(typeof getTimesOffensivePassiveMeta === 'function'){
        const offensivePassiveMeta = getTimesOffensivePassiveMeta(entry, 'all');
        (offensivePassiveMeta.types || []).forEach(type => {
            const normalizedType = normalizePokemonTypeKey(type);
            if(normalizedType) passiveTypes.add(normalizedType);
        });

        if(offensivePassiveMeta.all){
            (menuTypes.length ? menuTypes : Object.keys(effectiveness)).forEach(type => {
                const normalizedType = normalizePokemonTypeKey(type);
                if(normalizedType) passiveTypes.add(normalizedType);
            });
        }
    }

    return {
        ...entry,
        passiveSuperEffectiveTypes: Array.from(passiveTypes)
    };
}

function shouldShowPokemonBossUsageEmptyState(entry){
    return ['speedster', 'defender', 'supporter'].includes(String(entry?.roleKey || '').trim().toLowerCase());
}

function openPokemonBossUsageLink(usage){
    if(!usage || !usage.mode || !usage.bossSlug){
        return;
    }

    ensureBossesPageReady()
        .then(() => {
            if(typeof window.setBossMode === 'function'){
                window.setBossMode(usage.mode, { syncUrl: false, render: false });
            }

            const opened = typeof window.openBossModalByRouteSlug === 'function'
                ? window.openBossModalByRouteSlug(usage.mode, usage.bossSlug, {
                    pushState: false,
                    skipRouteSync: true,
                    renderBossGrid: false,
                    overlayParent: 'pokemon'
                })
                : false;

            if(!opened){
                console.warn('Nao foi possivel abrir o boss indicado no modal do Pokemon.', usage);
            }
        })
        .catch((error) => {
            console.error('Nao foi possivel carregar o modal de boss indicado pelo Pokemon.', error);
        });
}

function formatPokemonBossUsageScoreValue(value){
    return typeof value === 'number' && Number.isFinite(value)
        ? value.toFixed(2)
        : '-';
}

function createPokemonBossUsageCard(usage){
    const card = document.createElement('a');
    card.className = 'pokemon-boss-usage-card';
    card.href = usage?.url || '#';
    card.dataset.bossMode = usage?.mode || '';
    card.dataset.bossSlug = usage?.bossSlug || '';
    card.dataset.tier = usage?.tier || 'seminformacao';
    card.setAttribute('aria-label', `Abrir ${usage?.bossName || 'boss'} em ${usage?.contentLabel || 'Bosses'}`);

    const media = document.createElement('span');
    media.className = 'pokemon-boss-usage-card__media';

    const image = document.createElement('img');
    image.src = usage?.image || POKEMON_IMAGE_PLACEHOLDER;
    image.alt = '';
    image.loading = 'lazy';
    image.decoding = 'async';
    setImageFallback(image, POKEMON_IMAGE_PLACEHOLDER);
    media.appendChild(image);

    const body = document.createElement('span');
    body.className = 'pokemon-boss-usage-card__body';

    const title = document.createElement('strong');
    title.className = 'pokemon-boss-usage-card__title';
    title.textContent = usage?.bossName || 'Boss';

    const meta = document.createElement('span');
    meta.className = 'pokemon-boss-usage-card__meta';
    const metaParts = [
        usage?.clanLabel,
        usage?.roleLabel,
        usage?.groupTitle,
        usage?.tierLabel
    ].filter(Boolean);
    meta.textContent = metaParts.join(' - ');

    const score = document.createElement('span');
    score.className = 'pokemon-boss-usage-card__score';
    score.title = 'ATK e DEF calculados contra este boss.';

    const atk = document.createElement('span');
    atk.className = 'pokemon-boss-usage-card__score-item pokemon-boss-usage-card__score-item--atk';
    atk.textContent = `ATK ${formatPokemonBossUsageScoreValue(usage?.offenseScore)}`;

    const def = document.createElement('span');
    def.className = 'pokemon-boss-usage-card__score-item pokemon-boss-usage-card__score-item--def';
    def.textContent = `DEF ${formatPokemonBossUsageScoreValue(usage?.defenseScore)}`;

    score.append(atk, def);

    body.append(title, meta, score);
    card.append(media, body);
    card.addEventListener('click', (event) => {
        event.preventDefault();
        openPokemonBossUsageLink(usage);
    });
    return card;
}

function groupPokemonBossUsagesByContent(usages = []){
    const groups = [];
    const groupMap = new Map();

    usages.forEach((usage) => {
        const key = usage?.mode || usage?.contentLabel || 'bosses';
        if(!groupMap.has(key)){
            const group = {
                key,
                label: usage?.contentLabel || usage?.shortContentLabel || 'Bosses',
                items: []
            };
            groupMap.set(key, group);
            groups.push(group);
        }
        groupMap.get(key).items.push(usage);
    });

    return groups;
}

function createPokemonBossUsageGroup(group){
    const section = document.createElement('section');
    section.className = 'pokemon-boss-usage-group';
    section.dataset.bossContent = group?.key || '';

    const header = document.createElement('div');
    header.className = 'pokemon-boss-usage-group__head';

    const title = document.createElement('strong');
    title.className = 'pokemon-boss-usage-group__title';
    title.textContent = group?.label || 'Bosses';

    const count = document.createElement('span');
    count.className = 'pokemon-boss-usage-group__count';
    const amount = Array.isArray(group?.items) ? group.items.length : 0;
    count.textContent = amount === 1 ? '1 uso' : `${amount} usos`;

    header.append(title, count);

    const list = document.createElement('div');
    list.className = 'pokemon-boss-usage-list';
    (group?.items || []).forEach((usage) => {
        list.appendChild(createPokemonBossUsageCard(usage));
    });

    section.append(header, list);
    return section;
}

function renderPokemonBossUsageSection(entry){
    const renderToken = ++pokemonBossUsageRenderToken;
    resetPokemonBossUsageSection();

    if(!entry || !pokemonDetailsBossUsageSection || !pokemonDetailsBossUsage) return;

    ensurePokemonBossUsageDataReady()
        .then(() => {
            if(renderToken !== pokemonBossUsageRenderToken || activePokemonCatalogEntry !== entry) return;

            const usages = typeof window.getPokemonBossUsages === 'function'
                ? window.getPokemonBossUsages(createPokemonBossUsageSubject(entry))
                : [];
            if(!Array.isArray(usages) || !usages.length){
                if(shouldShowPokemonBossUsageEmptyState(entry)){
                    const summary = document.createElement('p');
                    summary.className = 'pokemon-boss-usage__summary';
                    summary.textContent = 'Nenhum uso bom ou maior em boss foi encontrado.';
                    pokemonDetailsBossUsage.replaceChildren(summary);
                    pokemonDetailsBossUsageSection.hidden = false;
                    return;
                }

                resetPokemonBossUsageSection();
                return;
            }

            const summary = document.createElement('p');
            summary.className = 'pokemon-boss-usage__summary';
            summary.textContent = usages.length === 1
                ? '1 uso em boss.'
                : `${usages.length} usos em bosses.`;

            const groups = document.createElement('div');
            groups.className = 'pokemon-boss-usage-groups';
            groupPokemonBossUsagesByContent(usages).forEach((group) => {
                groups.appendChild(createPokemonBossUsageGroup(group));
            });

            pokemonDetailsBossUsage.replaceChildren(summary, groups);
            pokemonDetailsBossUsageSection.hidden = false;
        })
        .catch((error) => {
            if(renderToken === pokemonBossUsageRenderToken){
                resetPokemonBossUsageSection();
            }
            console.error('Nao foi possivel carregar usos do Pokemon em bosses.', error);
        });
}

function renderPokemonDetailsAverages(entry){
    if(!pokemonDetailsAverages) return;

    const averageFragment = document.createDocumentFragment();
    averageFragment.append(
        createPokemonAverageGroup(
            'Pokémon Normal',
            getPokemonAverageDescription(entry, 'normal'),
            buildPokemonAverageCards(entry, 'normal')
        ),
        createPokemonAverageGroup(
            'Pokémon Shiny',
            getPokemonAverageDescription(entry, 'shiny'),
            buildPokemonAverageCards(entry, 'shiny')
        )
    );
    pokemonDetailsAverages.replaceChildren(averageFragment);
}

function refreshPokemonDetailsAveragesWhenTeamsLoaded(entry){
    if(teamsCatalogLoaded || !entry) return;
    const entryKey = getPokemonCatalogRegistryKey(entry.name);
    if(!entryKey) return;

    ensureTeamsCatalogLoaded()
        .then(() => {
            const activeKey = getPokemonCatalogRegistryKey(activePokemonCatalogEntry?.name);
            if(
                activeKey === entryKey
                && pokemonDetailsModal
                && pokemonDetailsModal.getAttribute('aria-hidden') !== 'true'
            ){
                renderPokemonDetailsAverages(activePokemonCatalogEntry || entry);
            }
        })
        .catch((error) => {
            console.error('Nao foi possivel carregar hunts para medias de captura.', error);
        });
}

function renderPokemonDetailsModal(entry){
    if(!entry || !pokemonDetailsModal) return;
    const hasRole = hasPokemonVisibleRole({ key: entry.roleKey, label: entry.role });
    const specialTags = getPokemonEntrySpecialTags(entry);
    const visibleSpecialTags = specialTags.filter(tagKey => tagKey !== 'pre-ace');
    const subFunctions = getPokemonEntrySubFunctions(entry);

    activePokemonCatalogEntry = entry;
    setPokemonDetailsModalTheme(entry);

    if(pokemonDetailsImage){
        pokemonDetailsImage.dataset.fallbackApplied = 'false';
        pokemonDetailsImage.src = getPokemonImageSource(entry);
        pokemonDetailsImage.alt = `Imagem de ${entry.name}`;
        setImageFallback(pokemonDetailsImage, POKEMON_IMAGE_PLACEHOLDER);
    }
    if(pokemonDetailsRole){
        pokemonDetailsRole.replaceChildren();
        pokemonDetailsRole.hidden = true;
    }
    if(pokemonDetailsTitle) pokemonDetailsTitle.textContent = entry.name;
    if(pokemonDetailsSubtitle){
        // Deixar subtitulo vazio; o nivel e exibido no campo do lado direito
        pokemonDetailsSubtitle.textContent = '';
    }
    if(pokemonDetailsAveragesKicker){
        const priceLabel = getPokemonEntryPriceLabel(entry);
        const acquisitionLink = getPokemonEntryAcquisitionLink(entry, priceLabel);
        pokemonDetailsAveragesKicker.replaceChildren(document.createTextNode('Médias'));

        const appendKickerSeparator = () => {
            pokemonDetailsAveragesKicker.appendChild(document.createTextNode(' • '));
        };

        if(priceLabel || acquisitionLink){
            appendKickerSeparator();
            if(acquisitionLink){
                const link = document.createElement('a');
                link.className = 'pokemon-acquisition-link';
                link.href = acquisitionLink.url;
                link.textContent = acquisitionLink.label;
                pokemonDetailsAveragesKicker.appendChild(link);
            } else {
                pokemonDetailsAveragesKicker.appendChild(document.createTextNode(priceLabel));
            }
        }
        if(shouldDisplayPokemonSafariAverageLabel(entry)){
            appendKickerSeparator();
            pokemonDetailsAveragesKicker.appendChild(document.createTextNode('Saffari'));
        }
    }

    if(pokemonDetailsMeta){
        const metaFragment = document.createDocumentFragment();
        metaFragment.appendChild(createPokemonTeamBadge(entry.team, { labelOverride: entry.teamLabel }));
        if(entry.type1){
            metaFragment.appendChild(createPokemonTypeToken(entry.type1, { labelPrefix: 'Tipo 1 • ' }));
        }
        if(entry.type2){
            metaFragment.appendChild(createPokemonTypeToken(entry.type2, { labelPrefix: 'Tipo 2 • ' }));
        }
        if(hasRole){
            metaFragment.appendChild(createPokemonRoleBadge({ key: entry.roleKey, label: entry.role }, { modal: true }));
        }
        const passiveBadge = createPokemonPassiveBadge(entry);
        if(passiveBadge){
            metaFragment.appendChild(passiveBadge);
        }
        const shinyPassiveBadge = createPokemonPassiveBadge(entry, { variant: 'shiny' });
        if(shinyPassiveBadge){
            metaFragment.appendChild(shinyPassiveBadge);
        }
        pokemonDetailsMeta.replaceChildren(metaFragment);
    }

    renderPokemonEvolutionNavigation(entry);
    renderPokemonBossUsageSection(entry);

    if(pokemonDetailsInfo){
        const infoFragment = document.createDocumentFragment();
        const shinySubFunctions = getPokemonEntryShinySubFunctions(entry);
        const levelMeta = document.createElement('span');
        levelMeta.className = 'pokemon-level-meta-row';
        const levelText = document.createElement('span');
        levelText.textContent = getPokemonEntryLevelLabel(entry);

        // Badges sob o texto de nivel (shiny / tags especiais)
        const badgesWrap = document.createElement('span');
        badgesWrap.className = 'pokemon-level-meta-row__badges';
        if(entry.naturalShiny){
            badgesWrap.appendChild(createPokemonNaturalShinyBadge());
        }
        visibleSpecialTags.forEach((tagKey) => {
            badgesWrap.appendChild(createPokemonSpecialTagBadge(tagKey));
        });

        levelMeta.append(levelText, badgesWrap);

        infoFragment.append(
            createPokemonFieldCard('Tipo 1', entry.type1 ? createPokemonTypeToken(entry.type1) : 'Não informado'),
            createPokemonFieldCard('Tipo 2', entry.type2 ? createPokemonTypeToken(entry.type2) : 'Não possui'),
            createPokemonFieldCard('Moveset', entry.moveset.length ? createPokemonTokenRow(entry.moveset) : (entry.movesetLabel || 'Não informado')),
            createPokemonFieldCard('Sub-função', subFunctions.length ? createPokemonSubFunctionTokenRow(subFunctions) : 'Não possui'),
            createPokemonFieldCard('Nível', levelMeta),
            createPokemonFieldCard('Localização', createPokemonRespawnMapButton(entry, { modal: true }))
        );
        if(shinySubFunctions.length){
            infoFragment.appendChild(
                createPokemonFieldCard('Sub-funcao Shiny', createPokemonSubFunctionTokenRow(shinySubFunctions))
            );
        }
        pokemonDetailsInfo.replaceChildren(infoFragment);
    }

    if(pokemonDetailsAverages){
        const averageFragment = document.createDocumentFragment();
        averageFragment.append(
            createPokemonAverageGroup(
                'Pokémon Normal',
                getPokemonAverageDescription(entry, 'normal'),
                buildPokemonAverageCards(entry, 'normal')
            ),
            createPokemonAverageGroup(
                'Pokémon Shiny',
                getPokemonAverageDescription(entry, 'shiny'),
                buildPokemonAverageCards(entry, 'shiny')
            )
        );
        pokemonDetailsAverages.replaceChildren(averageFragment);
    }

    refreshPokemonDetailsAveragesWhenTeamsLoaded(entry);

    if(pokemonDetailsWeaknesses){
        const weaknessEntries = getPokemonWeaknesses(entry.naturalElements);
        if(!weaknessEntries.length){
            const empty = document.createElement('span');
            empty.className = 'pokemon-weakness-empty';
            empty.textContent = 'Sem fraquezas cadastradas no momento.';
            pokemonDetailsWeaknesses.replaceChildren(empty);
        } else {
            const weaknessFragment = document.createDocumentFragment();
            weaknessEntries.forEach((weakness) => {
                const pill = document.createElement('span');
                pill.className = 'pokemon-weakness-pill';
                setTypeToneVariables(pill, weakness.type);
                pill.classList.add(
                    weakness.multiplier >= TYPE_SUPER_EFFECTIVE_MULTIPLIER
                        ? 'pokemon-weakness-pill--super'
                        : 'pokemon-weakness-pill--effective'
                );

                const icon = document.createElement('img');
                icon.src = `icons-type/${weakness.type}.png`;
                icon.alt = '';
                icon.loading = 'lazy';
                icon.decoding = 'async';
                setImageFallback(icon, POKEMON_IMAGE_PLACEHOLDER);

                const text = document.createElement('span');
                text.textContent = `${formatPokemonTypeLabel(weakness.type)} ${formatTypeMultiplierValue(weakness.multiplier)}`;

                pill.append(icon, text);
                weaknessFragment.appendChild(pill);
            });
            pokemonDetailsWeaknesses.replaceChildren(weaknessFragment);
        }
    }
}
function getPokemonModalRestoreFallbackUrl(){
    return buildPokemonCatalogFilterUrl(pokemonCatalogFilters, {
        variant: getCurrentPokemonCatalogVariant(),
        page: pokemonCatalogCurrentPage
    });
}

function hidePokemonDetailsModalUi(){
    if(!pokemonDetailsModal) return;
    pokemonDetailsModal.setAttribute('aria-hidden', 'true');
    syncBasicModalPageState();

    if(pokemonDetailsKeyHandler){
        document.removeEventListener('keydown', pokemonDetailsKeyHandler);
        pokemonDetailsKeyHandler = null;
    }

    if(pokemonDetailsLastFocus instanceof HTMLElement && pokemonDetailsLastFocus.isConnected){
        try { pokemonDetailsLastFocus.focus({ preventScroll: true }); } catch(error) {}
    }
    pokemonDetailsLastFocus = null;
}

function openPokemonDetailsModal(entry, options = {}){
    const { pushState = true } = options || {};
    if(!pokemonDetailsModal || !canOpenPokemonCatalogEntry(entry)) return;
    const previousUrl = getCurrentHistoryUrl();

    renderPokemonDetailsModal(entry);
    pokemonDetailsLastFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    pokemonDetailsModal.setAttribute('aria-hidden', 'false');
    syncBasicModalPageState();

    const closeBtn = pokemonDetailsModal.querySelector('.modal-close');
    if(closeBtn instanceof HTMLElement){
        try { closeBtn.focus({ preventScroll: true }); } catch(error) {}
    }

    if(pokemonDetailsKeyHandler){
        document.removeEventListener('keydown', pokemonDetailsKeyHandler);
    }
    pokemonDetailsKeyHandler = (event) => {
        if(event.key === 'Escape') closePokemonDetailsModal();
    };
    document.addEventListener('keydown', pokemonDetailsKeyHandler);

    // Gerenciar historico para deep-link
    const detailRoutePath = getPokemonDetailRoutePath(entry);
    if(pushState && detailRoutePath){
        try{
            pokemonModalRestoreUrl = getPokemonDetailRouteMatch(location.pathname)
                ? getPokemonModalRestoreFallbackUrl()
                : previousUrl;
            history.pushState({ tab: 'pokemons', pokemonRouteToken: getPokemonDetailRouteToken(entry) }, '', detailRoutePath);
            pokemonModalHistoryPushed = true;
        }catch(e){
            pokemonModalHistoryPushed = false;
            pokemonModalRestoreUrl = getPokemonModalRestoreFallbackUrl();
        }
    } else {
        pokemonModalHistoryPushed = false;
        pokemonModalRestoreUrl = getPokemonModalRestoreFallbackUrl();
    }
}

window.openPokemonDetailsModalByName = async function(name){
    await Promise.all([
        ensureTypesDataLoaded(),
        ensurePokemonCatalogLoaded()
    ]);
    const entry = getPokemonCatalogEntryByName(name);
    if(!entry || !canOpenPokemonCatalogEntry(entry)) return false;
    openPokemonDetailsModal(entry, { pushState: true });
    return true;
};

function closePokemonDetailsModal(options = {}){
    const { viaPopstate = false } = options || {};
    if(!pokemonDetailsModal) return;

    // Se este fechamento e resultado de navegacao no historico, apenas atualizar a UI
    if(viaPopstate){
        hidePokemonDetailsModalUi();
        pokemonModalHistoryPushed = false;
        pokemonModalRestoreUrl = '';
        return;
    }

    const restoreUrl = pokemonModalRestoreUrl || getPokemonModalRestoreFallbackUrl();
    hidePokemonDetailsModalUi();
    pokemonModalHistoryPushed = false;
    pokemonModalRestoreUrl = '';
    if(getPokemonDetailRouteMatch(location.pathname)){
        try{
            history.replaceState({ tab: 'pokemons' }, '', restoreUrl);
        }catch(error){
            updateUrl({ historyMode: 'replace' });
        }
    }
}

initializeSidebarNavigation();
initializeGlobalSearch();

// Sincronizar abertura/fechamento do modal com o historico do navegador (voltar/avancar)
window.addEventListener('popstate', () => {
    const pathname = String(location.pathname || '');
    const detailMatch = getPokemonDetailRouteMatch(pathname);
    const requestedPokemonCatalogPage = getRequestedPokemonCatalogPageFromPath(pathname);
    const requestedPokemonFilters = getPokemonCatalogFiltersFromUrl();
    const requestedTeamFilters = getTeamFiltersFromUrl();
    const isPokemonCatalogRoute = isPokemonCatalogPathname(pathname);
    const requestedTeamRoute = getTeamRouteMatch(pathname);
    const isTeamCatalogRoute = isTeamCatalogPathname(pathname);
    const requestedManiacsMapRoute = getManiacsMapRouteMatch(pathname);
    const isManiacsRoute = /\/maniacs(?:\/|$)/i.test(pathname);
    const requestedBossRoute = getBossRouteMatch(pathname);
    const isCatchRoute = /\/catch(?:\/|$)/i.test(pathname);
    if(detailMatch){
        const requestedVariant = getPokemonCatalogVariantFromUrl();
        if(!pokemonCatalogLoaded){
            ensurePokemonCatalogLoaded().then(() => {
                const entry = findPokemonCatalogEntryByRouteToken(detailMatch.routeToken, requestedVariant);
                if(canOpenPokemonCatalogEntry(entry)){
                    openPokemonDetailsModal(entry, { pushState: false });
                }
            }).catch(console.error);
        } else {
            const entry = findPokemonCatalogEntryByRouteToken(detailMatch.routeToken, requestedVariant);
            if(canOpenPokemonCatalogEntry(entry)){
                openPokemonDetailsModal(entry, { pushState: false });
            }
        }
    } else {
        // Caminho nao aponta mais para um Pokemon; fechar modal se estiver aberto
        if(pokemonDetailsModal && pokemonDetailsModal.getAttribute('aria-hidden') !== 'true'){
            closePokemonDetailsModal({ viaPopstate: true });
        }
        if(isPokemonCatalogRoute){
            const requestedVariant = getPokemonCatalogVariantFromUrl();
            const requestedPage = requestedPokemonCatalogPage == null
                ? 1
                : requestedPokemonCatalogPage;
            if(contentPokemons && !contentPokemons.hidden && pokemonCatalogLoaded){
                pendingPokemonCatalogRouteFilters = requestedPokemonFilters;
                pokemonCatalogFilters = normalizePokemonCatalogFiltersInput(requestedPokemonFilters);
                applyPokemonCatalogVariant(requestedVariant, {
                    resetFilters: false
                });
                pokemonCatalogCurrentPage = requestedPage;
                renderPokemonCatalog();
            } else {
                showPokemons(requestedVariant, {
                    requestedPage,
                    requestedFilters: requestedPokemonFilters
                });
            }
        }
    }

    if(requestedTeamRoute){
        const requestedTeamSlug = requestedTeamRoute.teamSlug;
        const openRequestedTeam = () => {
            applyTeamFiltersInput(requestedTeamFilters);
            if(teamsCatalogLoaded){
                renderTeamsCatalog();
            }
            const opened = openTeamDetailsByRouteSlug(requestedTeamSlug, { pushState: false });
            if(!opened){
                updateUrl({ historyMode: 'replace' });
            }
        };
        if(contentTimes && !contentTimes.hidden && teamsCatalogLoaded){
            openRequestedTeam();
        } else {
            showTimes({
                requestedTeamSlug,
                requestedFilters: requestedTeamFilters
            });
        }
    } else {
        if(timesDetailsModal && timesDetailsModal.getAttribute('aria-hidden') !== 'true'){
            closeTeamDetailsModal({ viaPopstate: true });
        }
        if(isTeamCatalogRoute && contentTimes && !contentTimes.hidden){
            applyTeamFiltersInput(requestedTeamFilters);
            if(teamsCatalogLoaded){
                renderTeamsCatalog();
            }
        } else if(isTeamCatalogRoute){
            showTimes({ requestedFilters: requestedTeamFilters });
        }
    }

    if(isCatchRoute){
        const applyCatchRoute = () => {
            applyCatchUrlState({ updateHistory: false });
        };
        if(contentCatch && !contentCatch.hidden){
            ensurePokemonCatalogLoaded().then(applyCatchRoute).catch(console.error);
        } else {
            showCatch();
            ensurePokemonCatalogLoaded().then(applyCatchRoute).catch(console.error);
        }
    }

    if(requestedManiacsMapRoute){
        const requestedLocationSlug = requestedManiacsMapRoute.locationSlug;
        if(contentManiacs && !contentManiacs.hidden){
            const opened = openManiacsLocationByRouteSlug(requestedLocationSlug, { pushState: false });
            if(!opened){
                closeManiacsLocationModal({ viaPopstate: true });
                updateUrl({ historyMode: 'replace' });
            }
        } else {
            showManiacs({ requestedLocationSlug });
        }
    } else if(isManiacsRoute){
        if(contentManiacs && !contentManiacs.hidden){
            closeManiacsLocationModal({ viaPopstate: true });
        } else {
            showManiacs();
        }
    } else {
        closeManiacsLocationModal({ viaPopstate: true });
    }

    if(requestedBossRoute){
        const requestedBossMode = normalizeBossModeParam(requestedBossRoute.bossMode) || 'hoopa';
        const requestedBossSlug = String(requestedBossRoute.bossSlug || '').trim().toLowerCase();
        if(contentSpeedsters && !contentSpeedsters.hidden && typeof window.setBossMode === 'function' && typeof renderGrid === 'function'){
            window.setBossMode(requestedBossMode);
            if(requestedBossSlug){
                let opened = false;
                if(!requestedBossRoute.searchView && typeof window.openBossModalByRouteSlug === 'function'){
                    opened = window.openBossModalByRouteSlug(requestedBossMode, requestedBossSlug, { pushState: false });
                }
                if(opened && requestedBossRoute.mapView && typeof window.openBossLocationByRouteSlug === 'function'){
                    window.openBossLocationByRouteSlug(requestedBossMode, requestedBossSlug, { pushState: false });
                } else if(typeof window.closeBossLocationOverlay === 'function'){
                    window.closeBossLocationOverlay({ skipHistory: true, skipRouteRestore: true });
                }
                if(opened && requestedBossRoute.videoView && typeof window.openBossTutorialByRouteSlug === 'function'){
                    window.openBossTutorialByRouteSlug(requestedBossMode, requestedBossSlug, { pushState: false });
                } else if(typeof window.closeBossTutorialModal === 'function'){
                    window.closeBossTutorialModal({ skipRouteRestore: true, skipFocusRestore: true });
                }
                if(!opened && !requestedBossRoute.mapView && !requestedBossRoute.videoView && typeof window.openSpeedsterSearchResultByRouteSlug === 'function'){
                    opened = window.openSpeedsterSearchResultByRouteSlug(requestedBossMode, requestedBossSlug, { pushState: false });
                }
                if(!opened && typeof window.closeBossModal === 'function'){
                    window.closeBossModal({ skipHistory: true });
                    updateUrl();
                }
            } else if(((typeof window.isBossModalOpen === 'function' && window.isBossModalOpen()) || (typeof window.isBossSearchResultModalOpen === 'function' && window.isBossSearchResultModalOpen())) && typeof window.closeBossModal === 'function'){
                if(typeof window.closeBossLocationOverlay === 'function'){
                    window.closeBossLocationOverlay({ skipHistory: true, skipRouteRestore: true });
                }
                if(typeof window.closeBossTutorialModal === 'function'){
                    window.closeBossTutorialModal({ skipRouteRestore: true, skipFocusRestore: true });
                }
                window.closeBossModal({ skipHistory: true });
                updateUrl();
            } else if(typeof window.closeBossLocationOverlay === 'function'){
                window.closeBossLocationOverlay({ skipHistory: true, skipRouteRestore: true });
            }
            if(typeof window.closeBossTutorialModal === 'function' && !(requestedBossSlug && requestedBossRoute.videoView)){
                window.closeBossTutorialModal({ skipRouteRestore: true, skipFocusRestore: true });
            }
        } else {
            showSpeedsters(requestedBossMode);
        }
    } else {
        if(typeof window.closeBossLocationOverlay === 'function'){
            window.closeBossLocationOverlay({ skipHistory: true, skipRouteRestore: true });
        }
        if(typeof window.closeBossTutorialModal === 'function'){
            window.closeBossTutorialModal({ skipRouteRestore: true, skipFocusRestore: true });
        }
        const bossModalOpen = typeof window.isBossModalOpen === 'function' && window.isBossModalOpen();
        const bossSearchModalOpen = typeof window.isBossSearchResultModalOpen === 'function' && window.isBossSearchResultModalOpen();
        if((bossModalOpen || bossSearchModalOpen) && typeof window.closeBossModal === 'function'){
            window.closeBossModal({ skipHistory: true });
        }
    }

    syncSidebarNavigationState();
});

// Inicializador do vídeo de treinamento — abre modal de vídeo do site (estilo Hoopa tutorials)
function initTrainingVideo(){
    // Funcao auxiliar para abrir o modal com seguranca
    const openModal = (videoId) => {
        if(!videoId) return;
        if(typeof openSiteYouTubeModal === 'function'){
            openSiteYouTubeModal({ videoId: videoId, title: 'Tutorial de Treinamento' });
        } else if(typeof window.openSiteYouTubeModal === 'function'){
            window.openSiteYouTubeModal({ videoId: videoId, title: 'Tutorial de Treinamento' });
        }
    };

    // Anexar handlers ao wrapper para que cliques na imagem, badge ou botao abram o modal.
    document.querySelectorAll('.training-video-wrapper').forEach(wrapper => {
        if(!wrapper) return;
        // Evitar dupla inicializacao
        if(wrapper.dataset.trainingInit === '1') return;
        wrapper.dataset.trainingInit = '1';

        // Tornar o wrapper focavel por teclado para acessibilidade (Enter / Space)
        if(!wrapper.hasAttribute('tabindex')) wrapper.setAttribute('tabindex', '0');

        wrapper.addEventListener('click', (e) => {
            // Permitir cliques em qualquer lugar dentro do wrapper (imagem, badge, legenda, botao)
            const videoId = wrapper.dataset.videoId || wrapper.getAttribute('data-video-id');
            openModal(videoId);
        });

        wrapper.addEventListener('keydown', (e) => {
            if(e.key === 'Enter' || e.key === ' '){
                e.preventDefault();
                const videoId = wrapper.dataset.videoId || wrapper.getAttribute('data-video-id');
                openModal(videoId);
            }
        });
    });
}

// Recurso de Pascoa removido
